def page(title, content, active='', share_image=''):
    user=current_user()
    if title=='Emergency Resources':
        emergency_logo=f'''<img src="{EMERGENCY_LOGO_DATA_URI}" alt="Galaxy Eve" style="display:block;width:96px;max-width:24vw;height:auto;margin:0 0 12px;object-fit:contain">'''
        content=content.replace('<div class="hero"><span class="badge heart">PUBLIC RESOURCE SEARCH</span>',f'<div class="hero">{emergency_logo}<span class="badge heart">PUBLIC RESOURCE SEARCH</span>',1)
        qr_image_pattern=r'''<img src="([^"]+)" alt="QR code for the public Emergency Resources page" style="width:260px;max-width:100%;height:auto">'''
        def branded_emergency_qr(match):
            return f'''<svg role="img" aria-label="QR code for the public Emergency Resources page with the Galaxy Eve logo" viewBox="0 0 260 260" width="260" height="260" style="display:block;width:260px;max-width:100%;height:auto" xmlns="http://www.w3.org/2000/svg"><defs><clipPath id="emergencyQrLogoClip"><circle cx="130" cy="130" r="26"/></clipPath></defs><image href="{match.group(1)}" x="0" y="0" width="260" height="260"/><circle cx="130" cy="130" r="30" fill="#fff"/><image href="{EMERGENCY_LOGO_DATA_URI}" x="104" y="104" width="52" height="52" preserveAspectRatio="xMidYMid slice" clip-path="url(#emergencyQrLogoClip)"/></svg>'''
        content=re.sub(qr_image_pattern,branded_emergency_qr,content,count=1)
    elif title=='Home':
        community_support_logo=f'''<img src="{EMERGENCY_LOGO_DATA_URI}" alt="Galaxy Eve" style="display:block;width:96px;max-width:24vw;height:auto;margin:0 0 12px;object-fit:contain">'''
        content=content.replace('<article class="card paid"><span class="badge heart">PUBLIC COMMUNITY SUPPORT</span>',f'<article class="card paid">{community_support_logo}<span class="badge heart">PUBLIC COMMUNITY SUPPORT</span>',1)
    content='''<style>.topin{min-height:94px}.logo{width:72px!important;height:72px!important}@media(max-width:820px){.topin{min-height:78px}.logo{width:62px!important;height:62px!important}}</style>'''+content
    content+='''<script>if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('/service-worker.js',{scope:'/'}).catch(()=>{}))}</script>'''
    if user:
        content=content+_global_autosave_script()
    return render_template_string(BASE, title=title, content=content, active=active, user=user, share_image=share_image)

