    response=send_file(io.BytesIO(base64.b64decode(icon_uri.split(',',1)[1])),mimetype='image/png',download_name=f'seasons-within-{size}.png')
    response.headers['Cache-Control']='public, max-age=31536000, immutable'
    return response

