@app.route('/service-worker.js')
def pwa_service_worker():
    script='''const CACHE='tsw-pwa-shell-v1';const SHELL=['/offline','/pwa-icon-192.png','/pwa-icon-512.png'];self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting()))});self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()))});self.addEventListener('fetch',event=>{const request=event.request;if(request.method!=='GET')return;const url=new URL(request.url);if(url.origin!==location.origin)return;if(request.mode==='navigate'){event.respondWith(fetch(request).catch(()=>caches.match('/offline')));return}if(SHELL.includes(url.pathname)){event.respondWith(caches.match(request).then(hit=>hit||fetch(request)));}});'''
    response=app.response_class(script,mimetype='application/javascript')
    response.headers['Cache-Control']='no-cache, no-store, must-revalidate'
    response.headers['Service-Worker-Allowed']='/'
    return response

def _persist_uploaded_file(file_name, user_id, content_type='application/octet-stream'):
    """Keep a database copy so Render deploys cannot erase member media."""
    path=UPLOAD_DIR/file_name
    if not path.exists():
        return
    data=path.read_bytes()
    conn=db()
    try:
        conn.execute('''INSERT INTO stored_files(file_name,user_id,content_type,file_data,created_at)
                        VALUES(?,?,?,?,?)
                        ON CONFLICT(file_name) DO UPDATE SET user_id=excluded.user_id,
                        content_type=excluded.content_type,file_data=excluded.file_data''',
                     (file_name,user_id,content_type or 'application/octet-stream',data,now()))
        conn.commit()
    finally:
        conn.close()

def _send_persistent_upload(file_name):
    path=UPLOAD_DIR/file_name
    if path.exists():
        return send_from_directory(UPLOAD_DIR,file_name)
    conn=db()
    try:
        row=conn.execute('SELECT content_type,file_data FROM stored_files WHERE file_name=?',(file_name,)).fetchone()
    finally:
        conn.close()
    if not row:
        abort(404)
    raw=row['file_data']
    if isinstance(raw,memoryview):
        raw=raw.tobytes()
    return send_file(io.BytesIO(bytes(raw)),mimetype=row['content_type'] or 'application/octet-stream',download_name=file_name)


def save_community_media(file_storage, user_id):
    if not file_storage or not getattr(file_storage, 'filename', ''):
        return '', ''
    name = secure_filename(file_storage.filename)
    ext = Path(name).suffix.lower()
    image_ext = {'.jpg','.jpeg','.png','.gif','.webp'}
    video_ext = {'.mp4','.mov','.webm','.m4v'}
    if ext not in image_ext | video_ext:
        return '', ''
    stamp = datetime.utcnow().strftime('%Y%m%d%H%M%S%f')
    stored = f'u{user_id}_{stamp}{ext}'
    file_storage.save(UPLOAD_DIR / stored)
    _persist_uploaded_file(stored,user_id,getattr(file_storage,'mimetype','application/octet-stream'))
    return stored, ('video' if ext in video_ext else 'image')


def community_media_html(post):
    name = post['media_name'] if 'media_name' in post.keys() else ''
    kind = post['media_type'] if 'media_type' in post.keys() else ''
    if not name:
        return ''
    src = url_for('community_media', filename=name)
    if kind == 'video':
        return f'<video class="media" controls preload="metadata" style="width:100%;max-height:520px"><source src="{src}"></video>'
    if 'source_gallery_media_id' in post.keys() and post['source_gallery_media_id']:
        return f'<img src="{src}" alt="Public Journal photo" style="display:block;width:auto;max-width:100%;height:auto;max-height:none;object-fit:contain;margin:14px auto;border-radius:16px">'
    return f'<img class="media" src="{src}" alt="Community post media" style="width:100%;max-height:520px;object-fit:cover">'


def journal_category_for_public(category):
    return category if category in JOURNAL_CATEGORIES else 'Reflection'


def public_journal_cards(member_id, viewer_id=None):
    conn=db()
    posts=conn.execute('SELECT p.*,u.name FROM community_posts p JOIN users u ON u.id=p.user_id WHERE p.user_id=? ORDER BY p.id DESC',(member_id,)).fetchall()
    gifts=conn.execute('''SELECT g.*,t.label,t.emoji,u.name sender_name
                          FROM member_virtual_gifts g
                          JOIN virtual_gift_types t ON t.id=g.gift_type_id
                          JOIN users u ON u.id=g.sender_id
                          WHERE g.recipient_id=? AND g.public_shared_at IS NOT NULL
                          ORDER BY g.public_shared_at DESC,g.id DESC''',(member_id,)).fetchall()
    conn.close()
    if not posts and not gifts:
        return '<div class="empty"><h3>No Public Journal entries yet</h3></div>'
    cards=[]
    for g in gifts:
        remove=(f'''<form method="post" action="{url_for('unshare_virtual_gift',gift_id=g['id'])}" style="display:inline"><button class="out danger" type="submit">Remove from Public Journal</button></form>''' if viewer_id==member_id else '')
        private_entry=(f'''<a class="out" href="{url_for('message_member',recipient_id=member_id,origin='Public Gift',gift_id=g['id'])}">Send Private Entry</a>''' if viewer_id and viewer_id!=member_id else '')
        sender=(f'''<p class="muted">Gift from {html.escape(g['sender_name'])}</p>''' if ('public_show_sender' in g.keys() and g['public_show_sender']) else '')
        caption=html.escape(g['journal_caption'] or '').replace(chr(10),'<br>') if 'journal_caption' in g.keys() else ''
        cards.append(f'''<article class="card"><span class="badge heart">GIFT SHARED BY THIS MEMBER</span><h3>{g['emoji']} {html.escape(g['label'])}</h3>{sender}<p>{caption}</p><p class="muted small">Shared {g['public_shared_at']}</p><div class="actions">{private_entry}{remove}</div></article>''')
    for p in posts:
        message=f'<a class="out" href="{url_for("message_member",recipient_id=p["user_id"],origin="Community",post_id=p["id"])}">Send Private Journal Entry</a>' if viewer_id and viewer_id!=p['user_id'] else ''
        if viewer_id == p['user_id']:
            controls=message+f'<a class="out" href="{url_for("community_post_edit",post_id=p["id"])}">Edit Post</a><form method="post" action="{url_for("community_post_delete",post_id=p["id"])}" style="display:inline"><button class="out danger" type="submit">Delete Post</button></form>'
        else:
            controls=message
        cards.append(f'<article class="card"><span class="badge">{p["category"]}</span><h3>{p["title"]}</h3><p class="muted small">{p["created_at"]}</p><p>{p["body"]}</p>{community_media_html(p)}<div class="actions">{controls}</div></article>')
    return ''.join(cards)


@app.route('/community-media/<path:filename>')
@login_required
def community_media(filename):
    return _send_persistent_upload(filename)



BUSINESS_IMAGE_EXT={'.jpg','.jpeg','.png','.gif','.webp'}
BUSINESS_VIDEO_EXT={'.mp4','.mov','.webm','.m4v'}

def _store_business_upload(file_storage, business_id, kind, allowed_exts):
    if not file_storage or not getattr(file_storage,'filename',''):
        return ''
    name=secure_filename(file_storage.filename)
    ext=Path(name).suffix.lower()
    if ext not in allowed_exts:
        return ''
    stamp=datetime.utcnow().strftime('%Y%m%d%H%M%S%f')
    stored=f'b{business_id}_{kind}_{stamp}{ext}'
    file_storage.save(UPLOAD_DIR/stored)
    conn=db()
    try:
        owner=conn.execute('SELECT owner_id FROM businesses WHERE id=?',(business_id,)).fetchone()
    finally:
        conn.close()
    if owner:
        _persist_uploaded_file(stored,owner['owner_id'],getattr(file_storage,'mimetype','application/octet-stream'))
    return stored

def _video_duration_seconds(path):
    ffprobe=shutil.which('ffprobe')
    if not ffprobe:
        return None
    try:
        result=subprocess.run([ffprobe,'-v','error','-show_entries','format=duration','-of','default=noprint_wrappers=1:nokey=1',str(path)],capture_output=True,text=True,timeout=20)
        return float(result.stdout.strip()) if result.returncode==0 and result.stdout.strip() else None
    except Exception:
        return None

def business_media_src(name):
    return url_for('business_media_file',filename=name) if name else ''

