def _planet_positions_at_utc(dt):
    # Internal factual planetary positions for a supplied UTC moment.
    try:
        import swisseph as swe
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=timezone.utc)
        z=dt.astimezone(timezone.utc)
        jd=swe.julday(z.year,z.month,z.day,z.hour+z.minute/60+z.second/3600)
        ids={'Sun':swe.SUN,'Moon':swe.MOON,'Mercury':swe.MERCURY,'Venus':swe.VENUS,
             'Mars':swe.MARS,'Jupiter':swe.JUPITER,'Saturn':swe.SATURN}
        planets={}
        for name,pid in ids.items():
            lon=float(swe.calc_ut(jd,pid)[0][0])%360
            sign,degree=_sign_from_longitude(lon)
            planets[name]={'longitude':round(lon,3),'sign':sign,'degree':degree}
        return planets
    except Exception:
        return {}


def _current_moon_sign_period(current_sky=None,at_utc=None):
    """Find the real Moon-sign ingress interval; never use a fixed 2.5-day timer."""
    at_utc=at_utc or datetime.now(timezone.utc)
    if at_utc.tzinfo is None: at_utc=at_utc.replace(tzinfo=timezone.utc)
    at_utc=at_utc.astimezone(timezone.utc)
    sky=current_sky or current_sky_data()
    moon=((sky or {}).get('planets') or {}).get('Moon') or {}
    try: current_lon=float(moon.get('longitude'))%360.0
    except (TypeError,ValueError):
        positions=_planet_positions_at_utc(at_utc); moon=positions.get('Moon') or {}
        try: current_lon=float(moon.get('longitude'))%360.0
        except (TypeError,ValueError): return {'ready':False,'reason':'Current Moon position is unavailable.'}
    sign,degree=_sign_from_longitude(current_lon); sign_index=int(current_lon//30)
    def moon_index(moment):
        placement=(_planet_positions_at_utc(moment).get('Moon') or {})
        try: return int((float(placement.get('longitude'))%360.0)//30)
        except (TypeError,ValueError): return None
    # Step only to bracket the astronomical crossings; the stored transition is
    # refined by bisection and is not based on an assumed sign duration.
    inside=at_utc; outside=None
    for step in range(1,49):
        candidate=at_utc-timedelta(hours=3*step); idx=moon_index(candidate)
        if idx is None: break
        if idx!=sign_index: outside=candidate; break
        inside=candidate
    started=None
    if outside is not None:
        lo,hi=outside,inside
        for _ in range(24):
            mid=lo+(hi-lo)/2
            if moon_index(mid)==sign_index: hi=mid
            else: lo=mid
        started=hi.replace(microsecond=0)
    inside=at_utc; outside=None
    for step in range(1,49):
        candidate=at_utc+timedelta(hours=3*step); idx=moon_index(candidate)
        if idx is None: break
        if idx!=sign_index: outside=candidate; break
        inside=candidate
    ends=None
    if outside is not None:
        lo,hi=inside,outside
        for _ in range(24):
            mid=lo+(hi-lo)/2
            if moon_index(mid)==sign_index: lo=mid
            else: hi=mid
        ends=hi.replace(microsecond=0)
    started_text=(started.isoformat().replace('+00:00','Z') if started else at_utc.strftime('%Y-%m-%d')+'Z')
    return {'ready':True,'period_key':f'moon-sign:{sign}:{started_text}','moon_sign':sign,'moon_degree':degree,'moon_longitude':round(current_lon,4),'started_utc':started_text,'ends_utc':ends.isoformat().replace('+00:00','Z') if ends else '','calculation':'actual Moon longitude and refined zodiac-boundary crossing'}

def _current_lunar_cycle_chart(current_sky=None):
    # Locate the most recent Sun/lunar conjunction and calculate its full sky.
    sky=current_sky or current_sky_data()
    planets=(sky or {}).get('planets') or {}
    sun=(planets.get('Sun') or {}).get('longitude')
    lunar=(planets.get('Moon') or {}).get('longitude')
    now_utc=datetime.now(timezone.utc)
    try:
        phase=(float(lunar)-float(sun))%360
    except Exception:
        phase=0.0
    relative_speed=12.19075
    guess=now_utc-timedelta(days=phase/relative_speed)
    refined=False
    for _ in range(10):
        at=_planet_positions_at_utc(guess)
        if not at:
            break
        s=(at.get('Sun') or {}).get('longitude')
        m=(at.get('Moon') or {}).get('longitude')
        if s is None or m is None:
            break
        signed=((float(m)-float(s)+180)%360)-180
        guess=guess-timedelta(days=signed/relative_speed)
        refined=True
        if abs(signed)<0.0005:
            break
    cycle_planets=_planet_positions_at_utc(guess) if refined else {}
    cycle_id=(guess.astimezone(timezone.utc).strftime('%Y-%m-%dT%H:%MZ') if cycle_planets else 'approx-'+guess.astimezone(timezone.utc).strftime('%Y-%m-%d'))
    # Find the next beginning-of-cycle conjunction from the previous one. This is
    # internal astronomical timing; member-facing copy continues to use Lunar Cycle.
    next_guess=guess+timedelta(days=29.530588)
    next_refined=False
    for _ in range(10):
        at=_planet_positions_at_utc(next_guess)
        if not at: break
        s=(at.get('Sun') or {}).get('longitude'); m=(at.get('Moon') or {}).get('longitude')
        if s is None or m is None: break
        signed=((float(m)-float(s)+180)%360)-180
        next_guess=next_guess-timedelta(days=signed/relative_speed)
        next_refined=True
        if abs(signed)<0.0005: break
    return {
        'cycle_id':cycle_id,
        'started_utc':guess.astimezone(timezone.utc).replace(microsecond=0).isoformat().replace('+00:00','Z'),
        'next_started_utc':next_guess.astimezone(timezone.utc).replace(microsecond=0).isoformat().replace('+00:00','Z') if next_refined else '',
        'planets':cycle_planets,
        'source':'Swiss Ephemeris lunar-cycle chart' if cycle_planets else 'lunar-cycle estimate from current factual sky',
        'exact_chart':bool(cycle_planets),
    }

def _journal_theme_counts(rows):
    combined=' '.join(
        f"{r['title'] or ''} {r['category'] or ''} {r['body'] or ''}".lower()
        for r in rows
    )
    counts={}
    for theme,needles in JOURNAL_THEME_KEYWORDS.items():
        score=sum(combined.count(n.lower()) for n in needles)
        if score:
            counts[theme]=score
    return dict(sorted(counts.items(),key=lambda kv:(-kv[1],kv[0])))

def _journal_chunk_fallback(chunk_text):
    low=chunk_text.lower()
    scored=[]
    for theme,needles in JOURNAL_THEME_KEYWORDS.items():
        score=sum(low.count(n.lower()) for n in needles)
        if score:
            scored.append((score,theme))
    scored.sort(reverse=True)
    themes=', '.join(t for _,t in scored[:5]) or 'personal reflection and ongoing life decisions'
    return f"This portion of the Journal repeatedly touches {themes}. Treat those as background themes rather than quotations."

def _all_journal_context(user_id):
    # Every private Journal entry belonging to this member participates.
    conn=db()
    rows=conn.execute(
        '''SELECT id,title,body,category,created_at,updated_at
           FROM journal_entries WHERE user_id=? ORDER BY id ASC''',
        (user_id,)
    ).fetchall()
    conn.close()

    if not rows:
        return {
            'entry_count':0,
            'history_fingerprint':hashlib.sha256(b'empty-journal').hexdigest(),
            'theme_counts':{},
            'history_for_reflection':'',
            'privacy':'Use only for this member’s own private personalization; never expose entries to another member.'
        }

    serialized=[]
    h=hashlib.sha256()
    category_counts=Counter()
    for r in rows:
        entry=(
            f"ENTRY {r['id']}\n"
            f"DATE: {r['created_at'] or ''}\n"
            f"CATEGORY: {r['category'] or ''}\n"
            f"TITLE: {r['title'] or ''}\n"
            f"BODY:\n{r['body'] or ''}\n"
        )
        serialized.append(entry)
        h.update(entry.encode('utf-8','ignore'))
        category_counts[r['category'] or 'Journal Entry']+=1

    full_history='\n---\n'.join(serialized)
    theme_counts=_journal_theme_counts(rows)

    if len(full_history)<=70000:
        history_for_reflection=full_history
        compression='full Journal history supplied'
    else:
        summaries=[]
        chunk=[]
        size=0
        for entry in serialized:
            if chunk and size+len(entry)>18000:
                chunk_text='\n---\n'.join(chunk)
                prompt='''Privately summarize this portion of one member’s Journal for use in that member’s own Conscious Coordination reflection.
Use every entry in the supplied chunk. Identify recurring themes, meaningful changes, unresolved questions, decisions, relationship/business/wellness patterns and signs of growth.
Do not diagnose. Do not quote identifying details. Do not address the member directly. Return a compact evidence summary only.
JOURNAL CHUNK:
'''+chunk_text
                summaries.append(_openai_text(prompt) or _journal_chunk_fallback(chunk_text))
                chunk=[entry]
                size=len(entry)
            else:
                chunk.append(entry)
                size+=len(entry)
        if chunk:
            chunk_text='\n---\n'.join(chunk)
            prompt='''Privately summarize this portion of one member’s Journal for use in that member’s own Conscious Coordination reflection.
Use every entry in the supplied chunk. Identify recurring themes, meaningful changes, unresolved questions, decisions, relationship/business/wellness patterns and signs of growth.
Do not diagnose. Do not quote identifying details. Do not address the member directly. Return a compact evidence summary only.
JOURNAL CHUNK:
'''+chunk_text
            summaries.append(_openai_text(prompt) or _journal_chunk_fallback(chunk_text))
        history_for_reflection='\n\n'.join(f'Journal history segment {i+1}: {s}' for i,s in enumerate(summaries))
        compression='all Journal entries processed in chronological chunks'

    return {
        'entry_count':len(rows),
        'first_entry_at':rows[0]['created_at'] or '',
        'latest_entry_at':rows[-1]['created_at'] or '',
        'category_counts':dict(category_counts),
        'theme_counts':theme_counts,
        'history_fingerprint':h.hexdigest(),
        'history_for_reflection':history_for_reflection,
        'compression':compression,
        'privacy':'Use only for this member’s own private personalization; never expose entries to another member.'
    }

def _cc_journal_evidence_packet(journal_context):
    """Return only structured private themes for report generation.

    Raw Journal bodies stay in the Journal store.  Report writers receive theme
    strength/relevance and a continuity fingerprint, never a dump of entries.
    """
    journal_context=journal_context or {}
    counts=journal_context.get('theme_counts') or {}
    maximum=max([float(v or 0) for v in counts.values()] or [1.0])
    strengths={k:round(min(1.0,float(v or 0)/maximum),3) for k,v in counts.items() if float(v or 0)>0}
    ranked=[k for k,_ in sorted(strengths.items(),key=lambda kv:(-kv[1],kv[0]))[:8]]
    return {
        'entry_count':int(journal_context.get('entry_count',0) or 0),
        'history_fingerprint':journal_context.get('history_fingerprint',''),
        'current_themes':ranked,
        'theme_strength':strengths,
        'theme_counts':{k:counts.get(k,0) for k in ranked},
        'privacy':'Owner-private structured themes only. Never quote or expose Journal entries.'
    }


