        conn.execute('''INSERT INTO astrology_reflections(user_id,reflection_type,period_key,payload,created_at)
                        VALUES(?,?,?,?,?) ON CONFLICT(user_id,reflection_type,period_key)
                        DO UPDATE SET payload=excluded.payload,created_at=excluded.created_at''',
                     (user_id,reflection_type,period_key,json.dumps(payload,default=str),now()))
