def _lunar_season_scores(ctx):
    scores={'Spring':0.0,'Summer':0.0,'Autumn':0.0,'Winter':0.0}
    journal=(ctx.get('journal_history') or {}).get('theme_counts') or {}
    theme_weights={
        'creativity':{'Spring':3,'Summer':2},
        'confidence/direction':{'Spring':3,'Summer':2},
        'business':{'Spring':2,'Summer':2},
        'communication':{'Summer':2,'Spring':1},
        'relationships':{'Summer':4},
        'family':{'Summer':1,'Winter':2},
        'boundaries':{'Autumn':4},
        'conflict/repair':{'Autumn':4,'Winter':1},
        'money/resources':{'Autumn':2,'Winter':1},
        'grief/change':{'Autumn':3,'Winter':3},
        'rest/regulation':{'Winter':5},
        'health/wellness':{'Winter':3,'Spring':1},
    }
    for theme,count in journal.items():
        for season,weight in theme_weights.get(theme,{}).items():
            scores[season]+=min(float(count),8.0)*weight

    profile=ctx.get('profile') or {}
    intentions=' '.join(str(profile.get(k,'') or '') for k in ('coordination_types','seeking','business_style','retreat_style','values_text')).lower()
    if any(w in intentions for w in ('new','begin','create','growth','business','opportunity')):
        scores['Spring']+=4
    if any(w in intentions for w in ('love','relationship','friendship','community','connection','social')):
        scores['Summer']+=4
    if any(w in intentions for w in ('boundary','repair','clarity','simplify','reflection')):
        scores['Autumn']+=4
    if any(w in intentions for w in ('rest','quiet','slow','private','healing','restore')):
        scores['Winter']+=4


    retreat_text=' '.join(
        ' '.join(str(r.get(k,'') or '') for k in ('retreat_type','season','wellness','meaning'))
        for r in (ctx.get('previous_retreat_interests') or [])
    ).lower()
    if any(w in retreat_text for w in ('renewal','new beginning','creative','intention')):
        scores['Spring']+=2
    if any(w in retreat_text for w in ('couples','connection','community','adventure','social')):
        scores['Summer']+=2
    if any(w in retreat_text for w in ('boundary','reflection','release','transition','gratitude')):
        scores['Autumn']+=2
    if any(w in retreat_text for w in ('rest','restore','quiet','reiki','meditation')):
        scores['Winter']+=2

    current=ctx.get('current_sky') or {}
    anchor=((current.get('planets') or {}).get('Moon') or {}).get('sign','')
    tie_break={
        'Aries':'Spring','Taurus':'Spring','Gemini':'Spring',
        'Cancer':'Summer','Leo':'Summer',
        'Virgo':'Autumn','Libra':'Autumn','Scorpio':'Autumn',
        'Sagittarius':'Winter','Capricorn':'Winter','Aquarius':'Winter','Pisces':'Winter',
    }.get(anchor)
    if tie_break:
        scores[tie_break]+=1.25

    return scores

def _lunar_season_for_context(ctx):
    scores=_lunar_season_scores(ctx)
    # Stable tie-break order prevents random season changes for identical evidence.
    order=['Spring','Summer','Autumn','Winter']
    return max(order,key=lambda s:(scores[s],-order.index(s)))

def _quiet_theme_sentence(ctx,season,variant=0):
    themes=list(((ctx.get('journal_history') or {}).get('theme_counts') or {}).keys())
    season_info=LUNAR_SEASONS[season]
    seed=int(hashlib.sha256(
        f"{ctx.get('member_id','')}|{season}|{(ctx.get('lunar_cycle_chart') or {}).get('cycle_id','')}|{variant}".encode()
    ).hexdigest()[:10],16)
    if themes:
        primary=themes[seed%len(themes)].replace('/',' and ')
        options=[
            f"One pattern worth noticing is how {primary} is changing the choices that deserve your attention now.",
            f"Pay closer attention to the way {primary} shows up when you are deciding what deserves energy and what can wait.",
            f"This may be a useful period to explore how {primary} connects with the pace, boundaries, or direction you want now.",
        ]
        return options[(seed//7)%len(options)]
    options=[
        f"This may be a useful period to explore {season_info['themes'][seed%len(season_info['themes'])]} without forcing an immediate conclusion.",
        f"Consider observing where {season_info['themes'][(seed//5)%len(season_info['themes'])]} would create a more intentional next step.",
        f"You may want to pay closer attention to {season_info['themes'][(seed//11)%len(season_info['themes'])]} and what it asks you to choose more consciously.",
    ]
    return options[(seed//13)%len(options)]

def _lunar_season_report_fallback(ctx,season,variant=0):
    info=LUNAR_SEASONS[season]
    insights=_behavioral_insights(ctx.get('profile') or {})
    seed=int(hashlib.sha256(
        f"season-report|{ctx.get('member_id','')}|{season}|{(ctx.get('journal_history') or {}).get('history_fingerprint','')}|{variant}".encode()
    ).hexdigest()[:12],16)
    attention=[
        _quiet_theme_sentence(ctx,season,variant),
        insights.get('communication') or "Notice where clearer language would reduce guesswork.",
        insights.get('boundaries') or "Notice which expectations need to be made explicit before they become pressure.",
        insights.get('business') or "Let pace, capacity, and follow-through matter as much as possibility.",
        insights.get('connection') or "Notice whether care and attention are being expressed in a form that can actually be received.",
    ]
    start=seed%len(attention)
    chosen=[attention[start],attention[(start+2)%len(attention)],attention[(start+3)%len(attention)]]
    support=(insights.get('practice') or f"Choose one gentle {info['wellness'][seed%len(info['wellness'])]} practice and use it to create space before the next important response.")
    questions=[
        "What deserves more of my energy because it still feels aligned after the urgency settles?",
        "Where would a slower, clearer choice change the pattern I keep repeating?",
        "What am I ready to approach differently without needing to force the entire outcome?",
        "Which choice would feel more intentional if I stopped trying to manage every possible reaction?",
    ]
    question=questions[(seed//17)%len(questions)]
    coordination=(
        f"Your current Conscious Coordination places emphasis on {info['themes'][(seed//19)%len(info['themes'])]} "
        f"while asking for enough awareness to keep familiar reactions from making the decision automatically. "
        f"{insights.get('repair') or insights.get('trust') or 'Let consistency between what you value, what you communicate, and what you do become the measure of progress.'}"
    )
    return (
        f"♡ Your Lunar Season Within\n\n"
        f"Your Current Season: {season.upper()} — {info['subtitle']}\n\n"
        f"What Deserves Your Attention\n\n{chosen[0]} {chosen[1]}\n\n"
        f"What You May Be Noticing\n\n{chosen[2]}\n\n"
        f"Your Conscious Coordination\n\n{coordination}\n\n"
        f"What May Support You\n\n{support}\n\n"
        f"A Question to Carry With You\n\n{question}"
    )

def _meditation_fallback(ctx,season,minutes,variant=0):
    info=LUNAR_SEASONS[season]
    seed=int(hashlib.sha256(
        f"meditation|{ctx.get('member_id','')}|{season}|{minutes}|{(ctx.get('journal_history') or {}).get('history_fingerprint','')}|{variant}".encode()
    ).hexdigest()[:12],16)
    focus=info['themes'][seed%len(info['themes'])]
    support=info['themes'][(seed//7)%len(info['themes'])]
    title_options=[
        f"Making Space for {focus.title()}",
        f"Returning to {support.title()}",
        f"A {season} Practice for Clearer Attention",
        f"Listening for the Next Intentional Step",
    ]
    title=title_options[(seed//11)%len(title_options)]
    pauses=max(2,int(minutes))
    script=(
        f"Your Meditation: {title}\n\n"
        f"Give yourself permission to be here for about {minutes} minutes. Settle into a position that feels supported. "
        "Let your hands rest easily. If closing your eyes feels comfortable, allow them to close; otherwise soften your gaze.\n\n"
        "Begin by noticing the surface underneath you. Feel the places where your body is already being held. "
        "Take a slow breath in, and let the exhale be a little longer than the inhale. Repeat that without forcing the breath.\n\n"
        f"As you settle, bring gentle attention to {focus}. You do not have to solve anything. Notice what your body does when this part of life comes to mind. "
        "Where do you tighten? Where do you soften? What changes when you allow the question to be present without immediately answering it?\n\n"
        f"Imagine the qualities of your {season} season creating enough room for {support}. Let the image be simple: light, water, trees, warmth, open space, or another natural image that feels calming to you. "
        "With each exhale, release the need to reach the conclusion before you have heard yourself clearly.\n\n"
        "Now ask quietly: What deserves my attention? What can wait? What would feel more intentional than automatic? "
        "Let the answers come as words, sensations, images, or even silence.\n\n"
        f"For the remaining time, return to your breath whenever the mind moves ahead. You have about {pauses} gentle minutes of practice available; there is no need to fill them with thought.\n\n"
        "To close, feel the surface beneath you again. Notice one thing you want to carry forward: a boundary, a question, a small action, or simply a steadier pace. "
        "Take one final slow breath and let your closing intention be: I can move with awareness without forcing certainty."
    )
    return script

def _reiki_reflection_for(ctx,season):
    themes=list(((ctx.get('journal_history') or {}).get('theme_counts') or {}).keys())
    if 'communication' in themes:
        focus='Communication'
    elif 'relationships' in themes or 'family' in themes:
        focus='Heart'
    elif 'confidence/direction' in themes or 'business' in themes:
        focus='Confidence'
    elif 'rest/regulation' in themes or 'health/wellness' in themes:
        focus='Rest'
    elif 'boundaries' in themes or 'conflict/repair' in themes:
        focus='Grounding'
    else:
        focus={'Spring':'Confidence','Summer':'Heart','Autumn':'Grounding','Winter':'Rest'}[season]
    duration={'Spring':'10–15 minutes','Summer':'10–15 minutes','Autumn':'15–20 minutes','Winter':'15–20 minutes'}[season]
    intentions={
        'Grounding':'I can stay present while deciding what belongs with me and what does not.',
        'Heart':'I can remain open to connection without abandoning clarity or reciprocity.',
        'Rest':'I can allow restoration to be part of how I move forward.',
        'Confidence':'I can choose a direction without requiring perfect certainty first.',
        'Communication':'I can make room for curiosity, clarity, and direct conversation.',
        'Reflection':'I can notice what is true now without forcing an immediate answer.',
    }
    return {'focus':focus,'duration':duration,'intention':intentions.get(focus,intentions['Reflection'])}

def _spoken_reflection_fallback(ctx,season,report,variant=0):
    info=LUNAR_SEASONS[season]
    seed=int(hashlib.sha256(
        f"spoken|{ctx.get('member_id','')}|{season}|{(ctx.get('journal_history') or {}).get('history_fingerprint','')}|{variant}".encode()
    ).hexdigest()[:10],16)
    openings=[
        f"Welcome to your Conscious Coordination reflection. Your current Lunar Season Within is {season}, a season centered on {info['subtitle'].lower()}.",
        f"This is your Conscious Coordination listening reflection. Right now, your symbolic season is {season}, bringing attention toward {info['themes'][seed%len(info['themes'])]}.",
        f"Take a comfortable breath and arrive here. Your current Season Within is {season}, with an invitation to notice {info['themes'][(seed//7)%len(info['themes'])]}.",
    ]
    middle=_quiet_theme_sentence(ctx,season,variant)
    return (
        f"{openings[seed%len(openings)]} {middle} "
        "You do not need to turn this into a prediction or a demand. Use it as a way to notice what is asking for clearer attention. "
        "As you listen, consider where a familiar response is still useful and where a more deliberate choice would fit the situation better. "
        "Let the next step be small enough to be real: a conversation, a boundary, a period of rest, a written intention, or one practical decision. "
        "When you are ready, move into your meditation and let the nature sounds give you space between thoughts rather than something else to accomplish."
    )

def _support_tags_for_context(ctx,season):
    """Derive member support needs first; business lookup remains deterministic."""
    profile=(ctx or {}).get('profile') or {}
    journal=((ctx or {}).get('journal_history') or {}).get('theme_counts') or {}
    practices={str(x).lower() for x in ((ctx or {}).get('wellness_practices') or [])}
    text=' '.join(str(profile.get(k,'') or '') for k in ('overwhelmed','regulate','other_emotions','communication','conflict_style','repair','boundaries','trust','lifestyle','retreat_style','seeking')).lower()
    tags=[]
    def add(*vals):
        for v in vals:
            if v and v not in tags: tags.append(v)

    # Direct self-reported regulation/environment preferences.
    if any(x in text for x in ('quiet time','homebody','quiet / restorative','need time before','space')): add('quiet','low stimulation','rest')
    if 'nature' in text or 'nature' in practices: add('nature','grounding')
    if any(x in text for x in ('movement','fitness','yoga')) or 'movement' in practices: add('movement','restorative movement')
    if 'breath' in text or 'meditation' in practices: add('meditation','breathwork')
    if 'music' in text or 'creative' in text: add('creative expression','sound')
    if any(x in text for x in ('talk','communication','direct','written')): add('communication','reflection')
    if 'boundary' in text or journal.get('boundaries'): add('boundaries','grounding')
    if journal.get('rest/regulation') or journal.get('health/wellness'): add('rest','grounding','low stimulation')
    if journal.get('communication'): add('communication','reflection')
    if journal.get('relationships') or journal.get('family'): add('connection','social support')
    if journal.get('confidence/direction') or journal.get('business'): add('decision clarity','reflection')
    if any(x in practices for x in ('reiki','energy work')): add('reiki','grounding')

    # The symbolic season can refine, but never replace, the individualized evidence.
    seasonal={
        'Spring':['creative expression','nature','movement','reflection'],
        'Summer':['connection','movement','nature','creative expression'],
        'Autumn':['grounding','reflection','restorative movement','nature'],
        'Winter':['rest','quiet','low stimulation','meditation'],
    }
    for tag in seasonal.get(season,[]):
        if len(tags)<10: add(tag)
    return tags[:12]


def _hosted_business_matches(ctx,season,limit=6):
    tags=_support_tags_for_context(ctx,season)
    if not tags:
        return []
    synonyms={
        'quiet':['quiet','restorative','private','calm','relax','meditation'],
        'low stimulation':['quiet','restorative','gentle','meditation','relax'],
        'rest':['rest','restorative','relax','massage','meditation','reiki'],
        'nature':['nature','outdoor','forest','lake','garden','trail','water'],
        'grounding':['grounding','reiki','meditation','breath','nature','somatic'],
        'movement':['movement','yoga','fitness','pilates','dance','stretch'],
        'restorative movement':['restorative','gentle yoga','yin','stretch','mindful movement','yoga'],
        'meditation':['meditation','mindfulness','breath','sound bath','sound healing'],
        'breathwork':['breathwork','breathing','breath'],
        'creative expression':['creative','art','music','writing','journal','creator'],
        'sound':['sound','music','sound bath','sound healing'],
        'communication':['communication','coaching','relationship','counseling','facilitation'],
        'reflection':['reflection','journal','coaching','meditation','mindfulness'],
        'boundaries':['boundary','boundaries','coaching','communication'],
        'connection':['community','group','relationship','couples','connection'],
        'social support':['community','group','support','circle','connection'],
        'decision clarity':['coaching','clarity','planning','strategy','reflection'],
        'reiki':['reiki','energy work','energy healing'],
    }
    conn=db()
    try:
        rows=conn.execute('SELECT * FROM businesses WHERE active=1 ORDER BY id DESC').fetchall()
    finally:
        conn.close()
    ranked=[]
    for b in rows:
        hay=' '.join(str(b[k] or '') for k in ('name','category','tagline','description','offers','features','location','retreat_service_area','retreat_delivery_mode','retreat_travel_radius','retreat_price_range','retreat_group_size','retreat_availability','retreat_accessibility','retreat_booking_requirements') if k in b.keys()).lower()
        matched=[]; score=0
        for tag in tags:
            words=synonyms.get(tag,[tag])
            if any(word in hay for word in words):
                matched.append(tag); score+=2
        # Retreat participation is helpful for Retreat-focused recommendations, but ordinary
        # network recommendations may still show a relevant active Hosted App.
        if season and 'retreat_participating' in b.keys() and b['retreat_participating']:
            score+=1
        if matched:
            ranked.append((score,b,matched[:4]))
    ranked.sort(key=lambda x:(-x[0],x[1]['name'].lower()))
    return ranked[:limit]

def _lunar_sound_player_html(season,minutes,audio_key=''):
    minutes=minutes if minutes in (5,10,15) else 5
    reflection_url=url_for('conscious_coordination_audio',kind='reflection',minutes=minutes,v=audio_key)
    meditation_url=url_for('conscious_coordination_audio',kind='meditation',minutes=minutes,v=audio_key)
    reflection_script_url=url_for('lunar_listening_script',kind='reflection',minutes=minutes)
    meditation_script_url=url_for('lunar_listening_script',kind='meditation',minutes=minutes)
    nature_src=html.escape(MEDITATION_NATURE_AUDIO,quote=True)
    bowl_src=html.escape(MEDITATION_BOWL_AUDIO,quote=True)
    nature_tag=f'<audio id="season-nature" preload="metadata" loop src="{nature_src}"></audio>' if nature_src else '<audio id="season-nature" preload="none"></audio>'
    bowl_tag=f'<audio id="season-bowl" preload="metadata" src="{bowl_src}"></audio>' if bowl_src else '<audio id="season-bowl" preload="none"></audio>'
    ambience_note=('A professionally curated meditation soundscape is mixed quietly beneath the guidance.' if nature_src else 'No unreviewed background recording is played. A curated meditation soundscape can be configured without changing the member experience.')
    nature_button=('<button class="out" type="button" onclick="seasonAudioStart(\'nature\')">🌿 Nature Soundscape</button>' if nature_src else '')
    return f'''
    <article class="card" id="listen">
      <span class="badge heart">🎧 LISTEN TO MY CONSCIOUS COORDINATION</span>
      <h2>Listen to My Reflection</h2>
      <p class="muted">Soft, calm narration speaks the meaning of your personalized report naturally instead of reading the page word-for-word. {ambience_note}</p>
      <div class="chips"><a class="chip" href="?minutes=5#listen">5 min</a><a class="chip" href="?minutes=10#listen">10 min</a><a class="chip" href="?minutes=15#listen">15 min</a></div>
      <div class="actions">
        <button class="btn" type="button" onclick="seasonAudioStart('reflection')">▶ Listen to My Reflection</button>
        <button class="btn" type="button" onclick="seasonAudioStart('meditation')">▶ Guided Meditation</button>
        {nature_button}
        <button class="out" type="button" onclick="seasonAudioPause()">⏸ Pause</button>
        <button class="out" type="button" onclick="seasonAudioRestart()">↻ Restart</button>
      </div>
      <p><b id="season-audio-time">00:00 / {minutes:02d}:00</b></p>
      {nature_tag}{bowl_tag}<audio id="season-voice" preload="none"></audio>
      <p class="muted small" id="season-audio-status">Narration uses an AI-generated voice. If server audio is unavailable, the same saved listening script will play through this browser’s voice service.</p>
    </article>
    <script>
    (function(){{
      const totalSeconds={minutes*60}; const hasNature={str(bool(nature_src)).lower()}; const hasBowl={str(bool(bowl_src)).lower()};
      const voiceUrls={{meditation:{json.dumps(meditation_url)},reflection:{json.dumps(reflection_url)}}};
      const scriptUrls={{meditation:{json.dumps(meditation_script_url)},reflection:{json.dumps(reflection_script_url)}}};
      let elapsed=0,timer=null,active=false;
      const nature=()=>document.getElementById('season-nature'); const bowl=()=>document.getElementById('season-bowl'); const voice=()=>document.getElementById('season-voice');
      function draw(){{const e=Math.min(elapsed,totalSeconds);const mm=String(Math.floor(e/60)).padStart(2,'0');const ss=String(e%60).padStart(2,'0');const tm=String(Math.floor(totalSeconds/60)).padStart(2,'0');document.getElementById('season-audio-time').textContent=mm+':'+ss+' / '+tm+':00';}}
      function stopTimer(){{if(timer)clearInterval(timer);timer=null;}}
      window.seasonAudioPause=function(){{active=false;stopTimer();voice().pause();if(hasNature)nature().pause();if(hasBowl)bowl().pause();}};
      window.seasonAudioRestart=function(){{window.seasonAudioPause();elapsed=0;voice().currentTime=0;if(hasNature)nature().currentTime=0;if(hasBowl)bowl().currentTime=0;draw();}};
      window.seasonAudioStart=function(mode){{window.seasonAudioPause();active=true;voice().volume=1.0;if(hasNature){{nature().volume=0.10;nature().play().catch(()=>{{}});}}if(hasBowl){{bowl().volume=0.07;bowl().currentTime=0;bowl().play().catch(()=>{{}});}}if(mode==='meditation'||mode==='reflection'){{voice().src=voiceUrls[mode];voice().play().catch(()=>{{active=false;stopTimer();speakListeningScript(scriptUrls[mode],document.getElementById('season-audio-status'));}});}}timer=setInterval(()=>{{if(!active)return;elapsed++;draw();if(elapsed>=totalSeconds){{active=false;stopTimer();voice().pause();if(hasNature)nature().pause();}}}},1000);draw();}};
      draw();
    }})();
    </script>
    '''

def _lunar_season_experience(user_id,minutes=5):
    # Legacy adapter: all callers receive the single Moon-sign-transition
    # reflection. The former monthly narration/Reiki collection is retired.
    return _current_lunar_sign_experience(user_id)
    minutes=minutes if minutes in (5,10,15) else 5
    ctx=_reflection_context(user_id)
    ctx['behavioral_insights']=_behavioral_insights(ctx.get('profile') or {})
    monthly_snapshot=_personal_monthly_coordination_snapshot(user_id)
    season=(monthly_snapshot.get('current_season') if monthly_snapshot.get('ready') else None) or _lunar_season_for_context(ctx)
    ctx['lunar_season']=season
    ctx['monthly_coordination_snapshot']={
        'lunar_cycle_id':monthly_snapshot.get('lunar_cycle_id'),
        'current_season':monthly_snapshot.get('current_season'),
        'season_scores':monthly_snapshot.get('season_scores',{}),
        'overall_coordination':monthly_snapshot.get('overall_coordination'),
        'planetary':{k:{'coordination_score':v.get('coordination_score'),'activation_score':v.get('activation_score')} for k,v in (monthly_snapshot.get('planetary') or {}).items()},
        'calculation_note':monthly_snapshot.get('calculation_note','')
    }
    journal=ctx.get('journal_history') or {}
    cycle=(ctx.get('lunar_cycle_chart') or {}).get('cycle_id') or datetime.utcnow().strftime('%Y-%m')
    fingerprint_packet={
        'cycle':cycle,
        'natal_planets':{k:{'longitude':v.get('longitude'),'sign':v.get('sign'),'house':v.get('house')} for k,v in ((ctx.get('chart') or {}).get('planets') or {}).items()},
        'natal_aspects':(ctx.get('chart') or {}).get('aspects',[]),
        'current_planets':{k:{'longitude':v.get('longitude'),'sign':v.get('sign')} for k,v in ((ctx.get('current_sky') or {}).get('planets') or {}).items()},
        'current_aspects':ctx.get('current_to_natal_aspects',[])[:16],
        'behavioral_profile':ctx.get('psychology_context',{}),
        'behavioral_insights':ctx.get('behavioral_insights',{}),
        'wellness_practices':ctx.get('wellness_practices',[]),
        'journal_history_fingerprint':journal.get('history_fingerprint',''),
        'engine_version':REFLECTION_ENGINE_VERSION,
    }
    context_fingerprint=hashlib.sha256(json.dumps(fingerprint_packet,sort_keys=True,default=str).encode('utf-8')).hexdigest()
    base_period=f'{cycle}|monthly-v{CC_ENGINE_VERSION}'
    meditation_period=f'{base_period}|m:{minutes}'

    data=dict(ctx)
    data['selected_lunar_season']=season
    data['season_definition']=LUNAR_SEASONS[season]

    def cached_payload(reflection_type,period_key):
        conn=db()
        try:
            row=conn.execute(
                'SELECT payload FROM astrology_reflections WHERE user_id=? AND reflection_type=? AND period_key=?',
                (user_id,reflection_type,period_key)
            ).fetchone()
        finally:
            conn.close()
        if not row:
            return None
        try:
            payload=json.loads(row['payload'])
        except Exception:
            return None
        return payload if payload.get('engine_version')==REFLECTION_ENGINE_VERSION else None

    def save_payload(reflection_type,period_key,payload):
        conn=db()
        conn.execute(
            '''INSERT INTO astrology_reflections(user_id,reflection_type,period_key,payload,created_at)
               VALUES(?,?,?,?,?)
               ON CONFLICT(user_id,reflection_type,period_key)
               DO UPDATE SET payload=excluded.payload,created_at=excluded.created_at''',
            (user_id,reflection_type,period_key,json.dumps(payload),now())
        )
        conn.commit()
        conn.close()

    report_cached=cached_payload('lunar_season_report',base_period)
    if report_cached:
        report=report_cached.get('text','')
    else:
        report_instruction=LUNAR_SEASON_MASTER_INSTRUCTION+f'''
Create the WRITTEN member experience now.
The selected symbolic season is {season}. Do not explain how it was selected and do not choose a different season.
Silently synthesize the calculated Lunar-cycle evidence, psychological patterns and structured current-life themes without identifying Journal material as the source.
Never mention missing information, internal evidence, profile fields, databases, scores, degrees, aspect mechanics, or how the reflection was generated.
Keep the written reflection focused, personal and specific rather than technical or generic.
Because My Journal supplies the section heading, do not repeat “Your Lunar Season Within” or the current-season title. This is the Lunar-cycle report; do not create the separate daily “What Deserves Your Attention” entry here.
Return ONLY valid JSON with keys: core_theme, psychological_interpretation, current_coordination, grounding_direction, emotional_coordination, communication_reflection, wellness_invitation, journal_question, wellness_tags. wellness_tags must be a short JSON array of strings.
'''
        report=''; structured_report=None
        for attempt in range(6):
            seed=_unique_generation_seed(user_id,'lunar_season_report',base_period,journal,attempt)
            obj=_openai_structured(report_instruction+f'\nInternal composition seed (never print): {seed}.\nEVIDENCE:\n'+json.dumps(data,default=str),'lunar_cycle_coordination',CC_LUNAR_REPORT_JSON_SCHEMA) or _cc_parse_json_object(_openai_text(report_instruction+f'\nInternal composition seed (never print): {seed}.\nEVIDENCE:\n'+json.dumps(data,default=str)))
            if not obj: continue
            candidate=_cc_format_lunar_cycle_report(obj)
            if not _cc_report_quality_ok(candidate): continue
            duplicate,_=_reading_similarity_status(candidate)
            if duplicate: continue
            if _register_unique_reading(user_id,'lunar_season_report',base_period,candidate):
                report=candidate; structured_report=obj; break
        if not report:
            report=_lunar_season_report_fallback(ctx,season,0)
            structured_report={'fallback':True}
            _register_unique_reading(user_id,'lunar_season_report',base_period,report)
        save_payload('lunar_season_report',base_period,{
            'engine_version':REFLECTION_ENGINE_VERSION,
            'text':report,
            'structured_sections':structured_report,
            'season':season
        })
        digest=hashlib.sha256(_normalize_report_text(report).encode()).hexdigest()
        conn=db()
        conn.execute('''INSERT INTO coordination_reports(user_id,other_user_id,report_type,period_key,report_version,written_report,spoken_script,audio_reference,evidence_summary,privacy_scope,context_fingerprint,normalized_text_hash,created_at,updated_at)
            VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(user_id,other_user_id,report_type,period_key) DO UPDATE SET written_report=excluded.written_report,evidence_summary=excluded.evidence_summary,context_fingerprint=excluded.context_fingerprint,normalized_text_hash=excluded.normalized_text_hash,updated_at=excluded.updated_at''',
            (user_id,0,'current_season_lunar_cycle',base_period,1,report,'','',json.dumps({'season':season,'structured_sections':structured_report},default=str),'owner-private',context_fingerprint,digest,now(),now()))
        conn.commit(); conn.close()

    spoken_cached=cached_payload('lunar_season_spoken',base_period)
    if spoken_cached:
        spoken=spoken_cached.get('text','')
    else:
        spoken_instruction=LUNAR_SEASON_MASTER_INSTRUCTION+f'''
Create ONLY the separate spoken narration for "Listen to My Conscious Coordination."
The current symbolic season is {season}.
Do not read the written reflection word-for-word and do not announce headings.
Carry the same core meaning in warm conversational language written specifically for listening.
Keep the narration concise enough to leave quiet space for the nature soundscape.
Never mention internal data sources, Journal history, technical astrology, missing information, or generation process.
'''
        spoken_data=dict(data)
        spoken_data['written_reflection_for_context_only']=report
        try:
            spoken,_=_generate_unique_reflection(
                user_id,'lunar_season_spoken',base_period,spoken_instruction,spoken_data,
                lambda variant:_spoken_reflection_fallback(ctx,season,report,variant)
            )
        except RuntimeError:
            spoken=_spoken_reflection_fallback(ctx,season,report,99)
        save_payload('lunar_season_spoken',base_period,{
            'engine_version':REFLECTION_ENGINE_VERSION,
            'text':spoken,
            'season':season
        })
        conn=db(); conn.execute('UPDATE coordination_reports SET spoken_script=?,audio_reference=?,updated_at=? WHERE user_id=? AND other_user_id=0 AND report_type=? AND period_key=?',(spoken,'lunar-season-audio:'+hashlib.sha256((base_period+'|'+spoken).encode()).hexdigest()[:16],now(),user_id,'current_season_lunar_cycle',base_period)); conn.commit(); conn.close()

    meditation_cached=cached_payload('lunar_season_meditation',meditation_period)
    if meditation_cached:
        meditation=meditation_cached.get('text','')
    else:
        meditation_data=dict(data)
        meditation_data['requested_meditation_minutes']=minutes
        meditation_instruction=LUNAR_SEASON_MASTER_INSTRUCTION+f'''
Create ONLY the personalized guided meditation for this member’s {season} Lunar Season Within.
The full practice lasts {minutes} minutes, but DO NOT fill all {minutes} minutes with talking.
Create gentle guidance followed by intentional quiet periods carried by the nature soundscape.
For 5 minutes, keep spoken guidance roughly 1.5–2.5 minutes.
For 10 minutes, keep spoken guidance roughly 2–3 minutes.
For 15 minutes, keep spoken guidance roughly 2.5–4 minutes.
Use natural pauses and a calm closing intention.
Do not announce technical headings while speaking.
Never mention Journal data, astrology mechanics, data availability, profile fields, databases, or how the meditation was generated.
'''
        try:
            meditation,_=_generate_unique_reflection(
                user_id,'lunar_season_meditation',meditation_period,meditation_instruction,meditation_data,
                lambda variant:_meditation_fallback(ctx,season,minutes,variant)
            )
        except RuntimeError:
            meditation=_meditation_fallback(ctx,season,minutes,99)
        save_payload('lunar_season_meditation',meditation_period,{
            'engine_version':REFLECTION_ENGINE_VERSION,
            'text':meditation,
            'season':season,
            'minutes':minutes
        })
        meditation_digest=hashlib.sha256(_normalize_report_text(meditation).encode()).hexdigest()
        meditation_fingerprint=hashlib.sha256((context_fingerprint+'|meditation|'+str(minutes)).encode()).hexdigest()
        conn=db()
        try:
            conn.execute('''INSERT INTO coordination_reports(user_id,other_user_id,report_type,period_key,report_version,written_report,spoken_script,audio_reference,evidence_summary,privacy_scope,context_fingerprint,normalized_text_hash,created_at,updated_at)
                VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(user_id,other_user_id,report_type,period_key) DO UPDATE SET spoken_script=excluded.spoken_script,evidence_summary=excluded.evidence_summary,context_fingerprint=excluded.context_fingerprint,normalized_text_hash=excluded.normalized_text_hash,updated_at=excluded.updated_at''',
                (user_id,0,'lunar_season_meditation',meditation_period,1,'',meditation,'',json.dumps({'season':season,'minutes':minutes},default=str),'owner-private',meditation_fingerprint,meditation_digest,now(),now()))
            conn.commit()
        finally:
            conn.close()

    reiki=_reiki_reflection_for(ctx,season)
    return {
        'engine_version':REFLECTION_ENGINE_VERSION,
        'season':season,
        'season_subtitle':LUNAR_SEASONS[season]['subtitle'],
        'report':report,
        'meditation':meditation,
        'meditation_minutes':minutes,
        'reiki':reiki,
        'spoken':spoken,
        'period_key':base_period,
        'audio_key':hashlib.sha256(base_period.encode('utf-8')).hexdigest()[:12],
        'lunar_cycle':ctx.get('lunar_cycle_chart',{}),
        'journal_history_fingerprint':journal.get('history_fingerprint',''),
    }

def _current_lunar_sign_experience(user_id):
    """One active written reflection and meditation for the real Moon-sign period."""
    ctx=_reflection_context(user_id)
    sky=ctx.get('current_sky') or current_sky_data()
    period=_current_moon_sign_period(sky)
    if not period.get('ready'): return period
    chart=ctx.get('chart') or {}; cp=ctx.get('profile') or {}
    journal=_cc_journal_evidence_packet(ctx.get('journal_history') or {})
    moon=((sky.get('planets') or {}).get('Moon') or {})
    contacts=[]
    for planet in ('Moon','Sun','Mercury','Venus','Mars'):
        natal=((chart.get('planets') or {}).get(planet) or {})
        if natal.get('longitude') is None: continue
        aspect=_cc_detect_aspect(moon.get('longitude'),natal.get('longitude'))
        if aspect:
            contacts.append({'natal_planet':planet,'natal_sign':natal.get('sign'),'relationship':aspect})
    rising=chart.get('rising') or chart.get('ascendant') or {}
    if rising.get('longitude') is not None:
        aspect=_cc_detect_aspect(moon.get('longitude'),rising.get('longitude'))
        if aspect: contacts.append({'natal_planet':'Rising','natal_sign':rising.get('sign'),'relationship':aspect})
    ctx['current_moon_period']=period
    season=_lunar_season_for_context(ctx); info=LUNAR_SEASONS[season]
    evidence={
        'current_moon':{'sign':period['moon_sign'],'degree':period['moon_degree'],'longitude':period['moon_longitude'],'period_started_utc':period['started_utc'],'period_ends_utc':period['ends_utc']},
        'meaningful_natal_correspondence':contacts,
        'natal_personality':{'Sun':(chart.get('planets') or {}).get('Sun'),'Moon':(chart.get('planets') or {}).get('Moon'),'Rising':rising or None,'Mercury':(chart.get('planets') or {}).get('Mercury'),'Venus':(chart.get('planets') or {}).get('Venus'),'Mars':(chart.get('planets') or {}).get('Mars')},
        'journal_themes':journal,
        'psychological_context':_profile_psychology_context(cp),
        'behavioral_inferences':_behavioral_insights(cp),
        'selected_symbolic_season':{'name':season,'subtitle':info['subtitle']},
        'privacy':'Journal entries are private. Use only structured themes; never quote, repeat or identify an entry.'
    }
    period_key=period['period_key']+f'|v{REFLECTION_ENGINE_VERSION}'
    def load(reflection_type):
        conn=db(); row=conn.execute('SELECT payload FROM astrology_reflections WHERE user_id=? AND reflection_type=? AND period_key=?',(user_id,reflection_type,period_key)).fetchone(); conn.close()
        if not row: return None
        try: return json.loads(row['payload'])
        except Exception: return None
    def save(reflection_type,payload):
        conn=db(); conn.execute('''INSERT INTO astrology_reflections(user_id,reflection_type,period_key,payload,created_at) VALUES(?,?,?,?,?) ON CONFLICT(user_id,reflection_type,period_key) DO UPDATE SET payload=excluded.payload,created_at=excluded.created_at''',(user_id,reflection_type,period_key,json.dumps(payload,default=str),now())); conn.commit(); conn.close()
    cached=load('lunar_sign_reflection') or {}
    # A deterministic fallback is never treated as the completed AI report.
    # When generation was temporarily unavailable, later requests retry for the
    # same Moon-sign period instead of preserving fallback copy until ingress.
    report=(cached.get('text') or '').strip() if cached.get('ai_generated') is True else ''
    if not report:
        prompt='''Write one professional Lunar Season Reflection for the exact Moon-sign period in the evidence. Synthesize the current Moon, only meaningful natal correspondence, stable personality context and structured private Journal themes. Do not quote or repeat Journal language and never say “your Journal says.” Do not expose degrees, aspects, algorithms, scores or data sources. Do not write a generic zodiac forecast or diagnose. Use possibility language. Write two or three cohesive paragraphs, then a final bold-style text heading “What deserves attention:” followed by one specific practical focus. The selected symbolic Season Within is supplied; do not choose another or base it on the outdoor calendar. Return only the reflection text.\nEVIDENCE:\n'''+json.dumps(evidence,default=str)
        report=''
        for attempt in range(3):
            candidate=(_openai_text(prompt+f'\nINTERNAL GENERATION ATTEMPT: {attempt+1}. Do not mention this attempt.') or '').strip()
            if len(candidate)>=500 and 'what deserves attention' in candidate.lower():
                report=candidate
                break
        ai_generated=bool(report)
        if not ai_generated:
            themes=journal.get('current_themes') or ['attention and recovery']; primary=themes[0].replace('/',' and ')
            tone=SIGN_BEHAVIORAL_TONES.get(period['moon_sign'],{})
            insight=_behavioral_insights(cp)
            report=(f"This lunar period may be useful for noticing how {primary} is affecting the pace at which you respond, decide, or take responsibility. The current Moon emphasis supports {tone.get('strength','closer attention to what is emotionally active')}, while the more important question is how that emphasis meets the patterns you already carry rather than what the sign is supposed to mean for everyone.\n\n"
                    f"{insight.get('communication','Clarity may become easier when expectations are made explicit instead of assumed.')} Give reactions enough room to become specific before deciding which concern requires action. {tone.get('question','What needs awareness before the next response?')}\n\nWhat deserves attention: Notice where {primary} has quietly become harder to carry because the need, boundary, or next decision has not yet been named clearly.")
        save('lunar_sign_reflection',{'engine_version':REFLECTION_ENGINE_VERSION,'text':report,'ai_generated':ai_generated,'season':season,'period':period,'evidence_fingerprint':hashlib.sha256(json.dumps(evidence,sort_keys=True,default=str).encode()).hexdigest()})
        # Preserve reflection history inside the existing private Journal without
        # creating duplicate entries on later page loads.
        title=f"Lunar Season Reflection — {period['moon_sign']} — {period['started_utc']}"
        conn=db(); exists=conn.execute('SELECT id FROM journal_entries WHERE user_id=? AND title=?',(user_id,title)).fetchone()
        if not exists: conn.execute('INSERT INTO journal_entries(user_id,title,body,category,shared_copy,created_at,updated_at) VALUES(?,?,?,?,0,?,?)',(user_id,title,report,'Conscious Coordination',now(),now()))
        elif ai_generated: conn.execute('UPDATE journal_entries SET body=?,updated_at=? WHERE id=? AND user_id=?',(report,now(),exists['id'],user_id))
        conn.commit(); conn.close()
    meditation_cached=load('lunar_sign_meditation') or {}
    meditation=(meditation_cached.get('text') or '').strip()
    if not meditation:
        meditation_prompt='''Write one short, personalized, written meditation connected only to the supplied Lunar Season Reflection. Use the current Moon theme, natal context, structured Journal themes and regulation preferences. Include settling physically, breathing, a simple awareness practice, quiet reflection and a closing intention appropriate to the actual reflection. Do not diagnose, promise healing, mention chakras, quote Journal entries, expose astrology mechanics, or write audio/narration directions. Return only the written practice.\nREFLECTION:\n'''+report+'\nEVIDENCE:\n'+json.dumps(evidence,default=str)
        meditation=(_openai_text(meditation_prompt) or '').strip()
        if not meditation:
            practice=_behavioral_insights(cp).get('practice','Take a slow breath and allow the first urgency to settle before choosing a response.')
            meditation=f"Find a position that feels supported and let your breathing become slower without forcing it. {practice}\n\nAs you breathe, notice the concern that has been asking for the most attention. You do not need to solve it during this practice. Name the need, boundary, or responsibility underneath it, then allow a few quiet breaths before deciding what belongs to you now.\n\nClose with this intention: I can create enough space to recognize what matters and respond without carrying more than is mine."
        save('lunar_sign_meditation',{'engine_version':REFLECTION_ENGINE_VERSION,'text':meditation,'season':season,'period':period})
    return {'ready':True,'engine_version':REFLECTION_ENGINE_VERSION,'season':season,'season_subtitle':info['subtitle'],'report':report,'meditation':meditation,'period':period,'period_key':period_key}


def _hosted_business_recommendations_html(ctx,season):
    ranked=_hosted_business_matches(ctx,season)
    if not ranked:
        return '''<article class="card"><span class="badge">🌿 EXPERIENCES WITHIN YOUR NETWORK</span><h2>Recommended for Your Season</h2><p class="muted">Matching active Hosted Business Apps will appear here when services in the network correspond to this reflection.</p></article>'''
    cards=[]
    for score,b,hits in ranked:
        why=', '.join(hits)
        cards.append(
            f'''<article class="card appcard"><span class="badge gold">RECOMMENDED FOR YOUR SEASON</span>
            <h3>{html.escape(b['name'])}</h3>
            <p><b>{html.escape(b['owner_title'] or b['category'] or 'Hosted Wellness Business')}</b></p>
            <p class="muted">{html.escape(b['location'] or '')}</p>
            <p>This Hosted App corresponds to this reflection through {html.escape(why)}.</p>
            <a class="out" href="{url_for('business_app',business_id=b['id'])}">Open Hosted App</a></article>'''
        )
    return f'''<div class="topspace"><span class="badge">🌿 EXPERIENCES WITHIN YOUR NETWORK</span><h2>Recommended for Your Season</h2><p class="muted">Only active Hosted Business Apps whose actual offerings correspond to this reflection are shown.</p></div><div class="grid">{''.join(cards)}</div>'''

def _reflection_context(user_id):
    conn=db()
    u=conn.execute('SELECT * FROM users WHERE id=?',(user_id,)).fetchone()
    cp=conn.execute('SELECT * FROM connection_profiles WHERE user_id=?',(user_id,)).fetchone()
    retreat_rows=conn.execute(
        '''SELECT retreat_type,season,wellness,meaning,preferred_dates
           FROM retreats WHERE user_id=? ORDER BY id DESC''',
        (user_id,)
    ).fetchall()
    conn.close()
    chart=member_chart_data(u)
    sky=current_sky_data()
    lunar_cycle=_current_lunar_cycle_chart(sky)
    profile=dict(cp) if cp else {}
    current_aspects=_chart_sky_aspects(chart,sky) if chart.get('ready') else []
    cycle_aspects=_chart_sky_aspects(chart,lunar_cycle) if chart.get('ready') and lunar_cycle.get('planets') else []
    journal_history=_cc_journal_evidence_packet(_all_journal_context(user_id))
    return {
        'engine_version':REFLECTION_ENGINE_VERSION,
        'member':u['name'],
        'member_id':user_id,
        'intentions':(cp['coordination_types'] if cp else '') or 'General wellness',
        'profile':profile,
        'psychology_context':_profile_psychology_context(profile),
        'wellness_practices':_member_wellness_practices(profile),
        'previous_retreat_interests':[dict(r) for r in retreat_rows],
        'chart':chart if chart.get('ready') else {'ready':False},
        'current_sky':sky,
        'current_to_natal_aspects':current_aspects,
        'lunar_cycle_chart':lunar_cycle,
        'lunar_cycle_to_natal_aspects':cycle_aspects,
        'lunar_reflection_theme':_moon_reflection_theme(lunar_cycle if lunar_cycle.get('planets') else sky),
        'journal_history':journal_history,
    }





def _fallback_coordination_reflection(ctx,kind,variant=0):
    profile=ctx.get('profile') or {}
    insights=_behavioral_insights(profile)
    practices=ctx.get('wellness_practices') or []
    journal=ctx.get('journal_history') or {}
    themes=list((journal.get('theme_counts') or {}).keys())
    lunar_cycle=ctx.get('lunar_cycle_chart') or {}
    cycle_planets=lunar_cycle.get('planets') or {}
    cycle_anchor=(cycle_planets.get('Sun') or {}).get('sign','')
    tone=SIGN_BEHAVIORAL_TONES.get(cycle_anchor,{})
    intentions=(ctx.get('intentions') or '').lower()

    seed_material='|'.join([
        str(ctx.get('member_id','')),
        str(kind),
        str(lunar_cycle.get('cycle_id','')),
        str(journal.get('history_fingerprint','')),
        str(variant),
    ])
    seed=int(hashlib.sha256(seed_material.encode('utf-8')).hexdigest()[:12],16)

    candidates=[
        insights.get('communication'),
        insights.get('boundaries'),
        insights.get('repair'),
        insights.get('trust'),
        insights.get('connection'),
        insights.get('business'),
    ]
    candidates=[c for c in candidates if c] or [
        "Give yourself enough space to notice what still matters after the first emotional reaction settles."
    ]

    focus=candidates[seed%len(candidates)]
    if 'business' in intentions and insights.get('business'):
        lived=insights['business']
    elif any(x in intentions for x in ('love','dating','relationship')) and insights.get('connection'):
        lived=insights['connection']
    else:
        lived=candidates[(seed//7)%len(candidates)]

    if themes:
        primary=themes[seed%len(themes)].replace('/',' and ')
        secondary=themes[(seed//11)%len(themes)].replace('/',' and ') if len(themes)>1 else ''
        noticing=f"One pattern worth noticing is how {primary} is influencing what deserves your attention now."
        if secondary and secondary!=primary:
            noticing+=f" Pay attention to where {secondary} intersects with that pattern rather than treating them as separate concerns."
    else:
        noticing=(
            "Pay attention to the difference between the first reaction and the choice that still feels aligned after you have had enough space to think clearly."
        )

    cycle_sentence=''
    if tone:
        cycle_sentence=(
            f"The current lunar reflection cycle places additional attention on {tone.get('strength','how you are meeting the present')}. "
            f"Notice whether {tone.get('watch','the first reaction is moving faster than your deeper priorities')}."
        )

    practice=insights.get('practice') or "Use a brief regulation pause before an important response."
    if practices:
        first=practices[seed%len(practices)]
        practice_options={
            'meditation':"Use a short meditation before the next important decision. Let the body settle, then separate what is known, what is assumed, and what still matters.",
            'nature':"Take time outside without rehearsing the problem. When your attention widens, return to the decision and notice what remains important without the immediate pressure.",
            'movement':"Use movement to lower activation before deciding or confronting. Revisit the issue when the body is no longer carrying the whole argument.",
            'quiet time':"Take deliberate quiet time before responding. Name the one need or decision that actually requires words instead of rehearsing every possible outcome.",
            'journaling':"Write four short lines: what happened, what you felt, what you assumed, and what you want to do next. Let the differences between those lines give you information.",
            'rest':"If depletion is increasing urgency, protect enough rest to revisit the decision with a steadier nervous system.",
        }
        practice=practice_options.get(first,practice)

    questions=[
        tone.get('question') if tone else '',
        "What would be different if I responded to the present situation instead of to the memory of a similar one?",
        "Which part of this situation needs action, and which part needs understanding before action?",
        "What choice would still feel aligned after the strongest emotion has softened?",
    ]
    questions=[q for q in questions if q]
    reflection=questions[(seed//17)%len(questions)]

    title="Your Current Lunar Reflection" if kind=='monthly' else "Your Focus Right Now"

    return (
        f"{title}\n\n{focus} {cycle_sentence}\n\n"
        f"What You May Be Noticing\n\n{noticing} {lived}\n\n"
        f"What May Support You\n\n{practice}\n\n"
        f"Something to Notice\n\n{tone.get('watch','Notice whether urgency, assumption, or an old expectation is deciding before the present facts are clear.')}\n\n"
        f"A Question to Carry With You\n\n{reflection}"
    )




def get_astrology_reflection(user_id,kind):
    # Daily reflections change by date. The longer reflection changes at each
    # factual lunar-cycle boundary rather than on an arbitrary calendar month.
    if kind=='daily':
        period=datetime.utcnow().strftime('%Y-%m-%d')
    else:
        cycle_probe=_current_lunar_cycle_chart(current_sky_data())
        period=cycle_probe.get('cycle_id') or datetime.utcnow().strftime('%Y-%m')

    conn=db()
    row=conn.execute(
        'SELECT payload FROM astrology_reflections WHERE user_id=? AND reflection_type=? AND period_key=?',
        (user_id,kind,period)
    ).fetchone()
    if row:
        cached=json.loads(row['payload'])
        cached_text=(cached.get('text') or '')
        if (
            cached.get('engine_version')==REFLECTION_ENGINE_VERSION
            and 'Complete your birth date' not in cached_text
            and 'temporarily unavailable' not in cached_text
        ):
            conn.close()
            return cached
    conn.close()

    ctx=_reflection_context(user_id)
    ctx['behavioral_insights']=_behavioral_insights(ctx.get('profile') or {})
    mode='DAILY' if kind=='daily' else 'CURRENT LUNAR CYCLE'

    instruction=f'''
Write a personalized {mode} CONSCIOUS COORDINATION reflection.

This reading must be newly composed for this member and this exact reflection context. The member’s complete Journal history is private internal evidence and must be meaningfully considered together with the factual birth chart, the current sky, the current lunar-cycle chart, relevant chart connections, Conscious Coordination profile and actual wellness practices.

IMPORTANT PRIVACY:
- Use all supplied Journal history as background evidence.
- Do not quote private Journal passages.
- Do not expose dates, names or identifying Journal details unless the member explicitly asks for them.
- Never make one member’s private Journal evidence available in another member’s report.

PUBLIC LANGUAGE:
- Brand the experience as Conscious Coordination.
- If the cycle itself must be named, say "current lunar reflection cycle" or "lunar cycle."
- Do not use technical lunar-event names as member-facing wording.
- Do not explain technical transit/aspect terminology, degrees or chart mechanics.

The calculated chart, current sky, current lunar-cycle chart, aspects, questionnaire answers and Journal history are INTERNAL EVIDENCE. Do not show your work.

Never tell the member what information the system did or did not have. Never say that there is not enough Journal history, that the reflection is based on available data, that a profile or database says something, or explain which internal source produced a conclusion. Silently synthesize the evidence into the reflection itself.

The member-facing response must NOT:
- list planetary degrees;
- list several natal placements;
- explain aspect names/orbs;
- repeat long lists of questionnaire selections;
- recite or quote Journal entries;
- read like a generic horoscope;
- reuse stock Sun, lunar, sign or wellness paragraphs;
- repeat a prior member’s reading or a prior day/cycle reading.

The reflection should primarily answer:
1. What pattern deserves attention in this exact cycle/day?
2. Which long-running Journal themes are relevant now, and what appears to be changing?
3. How might this show up in a real conversation, relationship, business decision or wellness choice?
4. What should the member watch for?
5. What concrete action or real regulation practice would help?
6. What question would move the reflection forward instead of repeating an old answer?

Use the actual lunar-cycle chart as a changing timing layer. A new lunar cycle must produce a newly generated reading even though the natal chart remains the same.

For relationship themes, translate the evidence into useful communication, trust, affection, conflict, repair or boundary guidance.
For business themes, translate it into useful guidance about pace, resources, commitments, clarity, collaboration or decision-making.
For wellness themes, connect the member’s real regulation practice to the actual behavioral pattern.

Write with these headings:
- Your Focus Right Now
- What You May Be Noticing
- What May Support You
- Something to Notice
- A Question to Carry With You

Keep it practical, psychologically thoughtful, non-diagnostic and non-deterministic.
'''

    reading_type='daily_reflection' if kind=='daily' else 'lunar_cycle_reflection'
    fallback_factory=lambda variant: _fallback_coordination_reflection(ctx,kind,variant)
    try:
        output,ai_generated=_generate_unique_reflection(
            user_id,reading_type,period,instruction,ctx,fallback_factory
        )
    except RuntimeError:
        return {'text':'Your individualized Conscious Coordination reflection is temporarily unavailable. Please try again shortly.','ai_generated':False,'engine_version':REFLECTION_ENGINE_VERSION,'chart_ready':bool(ctx.get('chart',{}).get('ready')),'current_sky':ctx.get('current_sky',{}),'lunar_cycle':ctx.get('lunar_cycle_chart',{}),'temporary_unavailable':True}

    payload={
        'text':output,
        'ai_generated':bool(ai_generated),
        'engine_version':REFLECTION_ENGINE_VERSION,
        'chart_ready':bool(ctx.get('chart',{}).get('ready')),
        'current_sky':ctx.get('current_sky',{}),
        'lunar_cycle':ctx.get('lunar_cycle_chart',{}),
        'aspects_used':ctx.get('current_to_natal_aspects',[])[:4],
        'lunar_cycle_aspects_used':ctx.get('lunar_cycle_to_natal_aspects',[])[:4],
        'journal_entry_count':(ctx.get('journal_history') or {}).get('entry_count',0),
        'journal_history_fingerprint':(ctx.get('journal_history') or {}).get('history_fingerprint',''),
        'wellness_practices':ctx.get('wellness_practices',[])
    }
    conn=db()
    conn.execute(
        '''INSERT INTO astrology_reflections(user_id,reflection_type,period_key,payload,created_at)
           VALUES(?,?,?,?,?)
           ON CONFLICT(user_id,reflection_type,period_key)
           DO UPDATE SET payload=excluded.payload,created_at=excluded.created_at''',
        (user_id,kind,period,json.dumps(payload),now())
    )
    conn.commit()
    conn.close()
    return payload

def ensure_free_coordination_notifications(user_id):
    day=datetime.utcnow().strftime('%Y-%m-%d')
    lunar_cycle=_current_lunar_cycle_chart(current_sky_data())
    cycle_key=lunar_cycle.get('cycle_id') or datetime.utcnow().strftime('%Y-%m')
    conn=db()
    cycle_run=conn.execute(
        'SELECT 1 FROM coordination_alert_runs WHERE user_id=? AND run_type=? AND period_key=?',
        (user_id,'lunar_reflection',cycle_key)
    ).fetchone()
    matchrun=conn.execute(
        'SELECT 1 FROM coordination_alert_runs WHERE user_id=? AND run_type=? AND period_key=?',
        (user_id,'matches',day)
    ).fetchone()
    me=conn.execute('SELECT * FROM connection_profiles WHERE user_id=?',(user_id,)).fetchone()
    others=conn.execute('SELECT user_id FROM connection_profiles WHERE opted_in=1 AND user_id<>?',(user_id,)).fetchall()
    conn.close()

    if not cycle_run:
        notify(
            user_id,
            'Conscious Coordination Reflection',
            'Your new lunar-cycle Conscious Coordination reflection is ready.',
            url_for('monthly_coordination_reflection')
        )
        conn=db()
        conn.execute(
            '''INSERT INTO coordination_alert_runs(user_id,run_type,period_key,created_at)
               VALUES(?,?,?,?) ON CONFLICT(user_id,run_type,period_key)
               DO UPDATE SET created_at=excluded.created_at''',
            (user_id,'lunar_reflection',cycle_key,now())
        )
        conn.commit()
        conn.close()

    if not matchrun and me:
        mytypes=_split_choices(me['coordination_types'])
        candidates=[]
        for r in others:
            conn=db()
            other=conn.execute('SELECT coordination_types FROM connection_profiles WHERE user_id=?',(r['user_id'],)).fetchone()
            name=conn.execute('SELECT name FROM users WHERE id=?',(r['user_id'],)).fetchone()
            conn.close()
            if other and (_split_choices(other['coordination_types']) & mytypes):
                c=basic_compatibility(user_id,r['user_id'],'general')
                if c.get('score') is not None:
                    candidates.append((c['score'],r['user_id'],name['name']))
        for score,oid,name in sorted(candidates,reverse=True)[:3]:
            if score>=45:
                notify(user_id,'New Conscious Coordination Match',name+' shares compatible intentions with you. Open their profile to explore the connection.',url_for('connection_profile',user_id=oid))
        conn=db()
        conn.execute(
            '''INSERT INTO coordination_alert_runs(user_id,run_type,period_key,created_at)
               VALUES(?,?,?,?) ON CONFLICT(user_id,run_type,period_key)
               DO UPDATE SET created_at=excluded.created_at''',
            (user_id,'matches',day,now())
        )
        conn.commit()
        conn.close()

