def _home_business_module_map(rows):
    ids=[b['id'] for b in rows]
    result={bid:set() for bid in ids}
    if not ids: return result
    marks=','.join('?' for _ in ids); conn=db()
    media=conn.execute(f'SELECT business_id,media_kind FROM business_media WHERE business_id IN ({marks})',ids).fetchall()
    content=conn.execute(f'SELECT business_id,content_type FROM hosted_app_content WHERE published=1 AND business_id IN ({marks})',ids).fetchall()
    events=conn.execute(f"SELECT business_id,event_type FROM business_calendar WHERE booking_status<>'Cancelled' AND business_id IN ({marks})",ids).fetchall(); conn.close()
    for row in media: result[row['business_id']].add('videos' if row['media_kind']=='video' else 'gallery' if row['media_kind']=='gallery' else '')
    for row in content: result[row['business_id']].add(row['content_type'])
    for row in events:
        typ=(row['event_type'] or '').lower()
        result[row['business_id']].add('classes' if typ in {'class','program'} else 'courses' if typ=='course' else 'retreats' if typ=='retreat' else 'booking' if typ in {'availability','appointment'} else 'events' if typ!='blocked / unavailable' else '')
    return result

def regular_business_cards(rows,home_swipe=False,module_map=None,business_actions=None):
    if not rows:
        return '<div class="empty"><h3>Businesses will appear here as they join</h3></div>'
    cards=[]
    for b in rows:
        logo=business_media_src(b['logo_name']) if 'logo_name' in b.keys() and b['logo_name'] else ''
        media=f'<img src="{logo}" alt="{html.escape(b["name"],quote=True)} profile image" style="width:100%;height:100%;object-fit:contain;object-position:center">' if logo else f'<div class="avatar" style="width:90px;height:90px">{initials(b["name"])}</div>'
        shortcuts=''
        if home_swipe:
            enabled=set(_module_list(b)); selected=[key for key in _module_order(b) if key in enabled]
            labels=dict(HOSTED_APP_MODULES)
            shortcuts='<div class="chips">'+''.join(f'<a class="chip" href="{url_for("business_app",business_id=b["id"])}#{key}">{html.escape(labels.get(key,key.title()))}</a>' for key in selected if key in labels)+'</div>' if selected else ''
        description=(b['description'] or b['tagline'] or '')[:320]
        action=(business_actions or {}).get(b['id'],'')
        cards.append(f'''<article class="card appcard{' home-business-card' if home_swipe else ''}" id="business-app-{b['id']}" {'data-home-business-card' if home_swipe else ''}><div class="media">{media}</div><div class="body"><span class="badge">Hosted App</span><h2>{html.escape(b['name'])}</h2><p><b>{html.escape(b['owner_title'] or b['category'])}</b></p><p class="muted">{html.escape(b['location'] or '')}</p>{f'<p>{html.escape(description)}</p>' if description else ''}{shortcuts}<div class="actions"><a class="btn" href="{url_for('business_app',business_id=b['id'])}">View Full App</a>{action}</div></div></article>''')
    return ''.join(cards)



def _affiliate_code_for(user_id, create=False):
    conn=db()
    try:
        row=conn.execute('SELECT referral_code FROM affiliate_profiles WHERE user_id=?',(user_id,)).fetchone()
        if row:
            return row['referral_code']
        if not create:
            return ''
        alphabet=string.ascii_uppercase+string.digits
        for _ in range(20):
            code=''.join(secrets.choice(alphabet) for _ in range(8))
            try:
                conn.execute('INSERT INTO affiliate_profiles(user_id,referral_code,created_at) VALUES(?,?,?)',(user_id,code,now()))
                conn.commit()
                return code
            except DB_INTEGRITY_ERRORS:
                continue
        return ''
    finally:
        conn.close()

def _affiliate_summary(user):
    conn=db()
    rows=conn.execute('''SELECT ar.created_at referral_date,u.id,u.name,u.email,u.conscious_paid
                         FROM affiliate_referrals ar
                         JOIN users u ON u.id=ar.referred_user_id
                         WHERE ar.referrer_id=?
                         ORDER BY ar.id''',(user['id'],)).fetchall()
    conn.close()

    referrer_active=bool(user['conscious_paid'] or user['is_admin'])
    active=[r for r in rows if bool(r['conscious_paid'])] if referrer_active else []
    inactive=[r for r in rows if not bool(r['conscious_paid']) or not referrer_active]
    active_count=len(active)
    recurring=(2+(active_count-1)) if active_count else 0
    return {
        'rows':rows,
        'active':active,
        'inactive':inactive,
        'active_count':active_count,
        'inactive_count':len(inactive),
        'recurring':recurring,
        'referrer_active':referrer_active,
    }

