def _emergency_verified_local_results(city,state,county,categories):
    city_key=(city or '').strip().lower(); state_key=(state or '').strip().lower()
    county_key=(county or '').strip().lower().removesuffix(' county')
    wanted=set(categories)
    rows=[]
    for provider in EMERGENCY_VERIFIED_LOCAL_PROVIDERS:
        area_match=bool((city_key and city_key in provider['cities']) or (county_key and county_key in provider['counties']))
        if not area_match or state_key not in provider['states'] or not wanted.intersection(provider['categories']): continue
        rows.append({k:v for k,v in provider.items() if k not in ('cities','counties','states','categories')})
    return rows

def _emergency_categories_for_need(need,selected):
    selected=[x for x in selected if x in EMERGENCY_RESOURCE_CATEGORIES]
    lower=(need or '').lower(); keywords={
        'shelter':('shelter','homeless','evict','housing','rent','domestic violence','place to stay'),
        'food':('food','hungry','meal','pantry','groceries'), 'clothing':('clothes','clothing','shoes','coat'),
        'utilities':('electric','utility','utilities','water bill','gas bill','shutoff'),
        'financial':('money','financial','grant','cash','bill','deposit'),
        'health':('health','doctor','medical','mental','crisis','suicide','therapy','prescription'),
        'family':('child','baby','diaper','parent','family','daycare'),
        'transportation':('transport','bus','ride','gas card'), 'employment':('job','work','resume','career','employment'),
        'community':('church','nonprofit','charity','community')}
    for category,terms in keywords.items():
        if any(term in lower for term in terms) and category not in selected: selected.append(category)
    if not selected: selected=['other']
    # AI is used only as a constrained need classifier. It never supplies
    # organizations, contact information, eligibility or availability.
    if need and OPENAI_API_KEY:
        allowed=','.join(EMERGENCY_RESOURCE_CATEGORIES)
        prompt=f'''Classify this U.S. emergency-resource request into one or more of these exact category keys only: {allowed}. Return a comma-separated list and nothing else. Request: {need[:1000]}'''
        try:
            for value in re.split(r'[,\s]+',(_openai_text(prompt) or '').lower()):
                if value in EMERGENCY_RESOURCE_CATEGORIES and value not in selected: selected.append(value)
        except Exception: pass
    return selected[:4]

def _emergency_directory_resources(categories):
    rows=[]
    def add(name,kind,url,phone='',note='Use the official directory to search by location.'):
        if not any(x['url']==url for x in rows): rows.append({'name':name,'kind':kind,'url':url,'phone':phone,'location':'United States','address':'','eligibility':'Eligibility and current availability must be confirmed with the program.','hours':'','how_to_apply':note,'verification':'Verified','verified_at':'Official directory','snippet':note})
    add('211 — Local Community Resources','Community & emergency assistance','https://www.211.org/','211','Call 211 or use the official directory for nearby help.')
    if 'shelter' in categories: add('HUD Find Shelter','Shelter, food, health and clothing resources','https://www.hud.gov/findshelter','','Search the official HUD directory by location.'); add('National Domestic Violence Hotline','Domestic violence safety support','https://www.thehotline.org/','800-799-7233','Call, chat or text START to 88788. Use a safer device if your internet use may be monitored.')
    if 'food' in categories: add('Feeding America Food Bank Finder','Food banks and pantries','https://www.feedingamerica.org/find-your-local-foodbank','','Enter a ZIP code in the official food-bank finder.')
    if 'health' in categories: add('HRSA Find a Health Center','Community health centers','https://findahealthcenter.hrsa.gov/','','Search the official federal health-center directory.'); add('988 Suicide & Crisis Lifeline','Mental health or suicide crisis support','https://988lifeline.org/','988','Call or text 988, or use the official chat service.')
    if 'utilities' in categories: add('LIHEAP Local Office Search','Home energy assistance','https://liheapch.acf.hhs.gov/search-tool/','','Find the state, territory or tribal LIHEAP office serving your area.')
    if 'employment' in categories: add('CareerOneStop Local Help','Employment and workforce services','https://www.careeronestop.org/LocalHelp/local-help.aspx','','Use the U.S. Department of Labor sponsored local-help finder.')
    if 'financial' in categories or 'family' in categories: add('USA.gov Benefit Finder','Government benefits and assistance','https://www.usa.gov/benefit-finder','','Answer the official questionnaire to identify programs that may apply.')
    return rows

def _trusted_emergency_domain(url):
    try: host=(urllib.parse.urlparse(url).hostname or '').lower().removeprefix('www.')
    except Exception: return False
    trusted=('211.org','hud.gov','feedingamerica.org','hrsa.gov','acf.hhs.gov','usa.gov','thehotline.org','988lifeline.org','careeronestop.org')
    return host.endswith('.gov') or any(host==x or host.endswith('.'+x) for x in trusted)

def _emergency_is_directory(url,title=''):
    try: host=(urllib.parse.urlparse(url).hostname or '').lower().removeprefix('www.')
    except Exception: host=''
    directory_hosts=('211.org','findhelp.org','auntbertha.com','yelp.com','yellowpages.com','foodpantries.org','homelessshelterdirectory.org','needhelppayingbills.com','facebook.com','mapquest.com')
    directory_words=('directory','resource finder','search results','find help near you','list of pantries','near me')
    return any(host==x or host.endswith('.'+x) for x in directory_hosts) or any(x in (title or '').lower() for x in directory_words)

def _emergency_geocode(city,state,county,zip_code):
    query=', '.join(x for x in (city,county,state,zip_code,'United States') if x)
    try:
        params=urllib.parse.urlencode({'q':query,'format':'jsonv2','limit':1,'countrycodes':'us'})
        req=urllib.request.Request('https://nominatim.openstreetmap.org/search?'+params,headers={'User-Agent':'TheSeasonsWithin/1.0 (contact: e.reed81@gmail.com)','Accept':'application/json'})
        with urllib.request.urlopen(req,timeout=10) as response: data=json.loads(response.read().decode('utf-8'))
        return (float(data[0]['lat']),float(data[0]['lon'])) if data else None
    except Exception: return None

def _emergency_open_map_results(city,state,county,zip_code,categories,assistance_for='',shelter_type=''):
    """Keyless nearby-provider discovery from structured OpenStreetMap tags."""
    coords=_emergency_geocode(city,state,county,zip_code)
    if not coords: return []
    selectors={
        'food':['["amenity"="food_bank"]','["social_facility"="food_bank"]','["social_facility:for"~"food",i]'],
        'shelter':['["social_facility"="shelter"]','["social_facility"="temporary_shelter"]','["amenity"="social_facility"]["social_facility"~"shelter",i]'],
        'clothing':['["social_facility"="clothing_bank"]','["social_facility:for"~"clothing",i]','["clothes"="free"]'],
        'health':['["amenity"="clinic"]','["healthcare"="community_health_centre"]','["amenity"="social_facility"]["social_facility:for"~"mental_health",i]'],
        'family':['["amenity"="social_facility"]["social_facility:for"~"child|family",i]','["community_centre:for"~"child|family",i]'],
        'employment':['["office"="employment_agency"]','["social_facility:for"~"unemployed",i]'],
        'community':['["amenity"="social_facility"]','["amenity"="community_centre"]'],
        'transportation':['["social_facility:for"~"transport",i]'],
        'utilities':['["social_facility:for"~"utility|financial",i]'],
        'financial':['["social_facility:for"~"financial|homeless|low_income",i]'],
        'other':['["amenity"="social_facility"]']}
    clauses=[]
    for category in categories:
        for selector in selectors.get(category,[]): clauses.append(f'nwr(around:30000,{coords[0]},{coords[1]}){selector};')
    if not clauses: return []
    query='[out:json][timeout:25];('+''.join(clauses)+');out center tags;'
    try:
        req=urllib.request.Request('https://overpass-api.de/api/interpreter',data=urllib.parse.urlencode({'data':query}).encode(),headers={'User-Agent':'TheSeasonsWithin/1.0 (contact: e.reed81@gmail.com)','Content-Type':'application/x-www-form-urlencoded'},method='POST')
        with urllib.request.urlopen(req,timeout=35) as response: payload=json.loads(response.read().decode('utf-8'))
    except Exception: return []
    rows=[]
    for element in payload.get('elements',[]):
        tags=element.get('tags') or {}; name=_clean_text(tags.get('name') or tags.get('operator'))
        if not name: continue
        lat=element.get('lat') or (element.get('center') or {}).get('lat'); lon=element.get('lon') or (element.get('center') or {}).get('lon')
        website=_clean_text(tags.get('contact:website') or tags.get('website') or tags.get('url'))
        if website and not website.startswith(('http://','https://')): website='https://'+website
        osm_type=element.get('type','node'); osm_id=element.get('id'); map_url=f'https://www.openstreetmap.org/{osm_type}/{osm_id}'
        phone=_clean_text(tags.get('contact:phone') or tags.get('phone')); email=_clean_text(tags.get('contact:email') or tags.get('email'))
        street=' '.join(x for x in (_clean_text(tags.get('addr:housenumber')),_clean_text(tags.get('addr:street'))) if x)
        address=', '.join(x for x in (street,_clean_text(tags.get('addr:city')),_clean_text(tags.get('addr:state')),_clean_text(tags.get('addr:postcode'))) if x)
        mapped_city=_clean_text(tags.get('addr:city') or tags.get('contact:city')).lower()
        mapped_zip=_clean_text(tags.get('addr:postcode') or tags.get('contact:postcode')).lower()
        mapped_county=_clean_text(tags.get('addr:county')).lower().removesuffix(' county')
        wanted_city=(city or '').lower(); wanted_zip=(zip_code or '').lower(); wanted_county=(county or '').lower().removesuffix(' county')
        # A mapped place is displayed only when its structured locality matches
        # the area the member entered. Missing locality tags are not enough.
        if wanted_city or wanted_zip:
            if not ((wanted_city and mapped_city==wanted_city) or (wanted_zip and mapped_zip==wanted_zip)): continue
        elif wanted_county and mapped_county!=wanted_county:
            continue
        facility=_clean_text(tags.get('social_facility') or tags.get('amenity') or tags.get('healthcare') or 'Community resource').replace('_',' ').title()
        religious=bool(tags.get('religion') or tags.get('denomination')); kind=('Church / faith-based provider — ' if religious else 'Nearby direct provider — ')+facility
        distance=math.hypot((float(lat)-coords[0])*69 if lat else 99,(float(lon)-coords[1])*54 if lon else 99)
        serves=_clean_text(tags.get('social_facility:for') or tags.get('social_facility:for:gender')).lower()
        shelter_key=(shelter_type or '').lower()
        if 'shelter' in categories and serves:
            if shelter_key=='men' and any(x in serves for x in ('women','female')) and not any(x in serves for x in ('men','male','all')): continue
            if shelter_key=='women' and any(x in serves for x in ('men','male')) and not any(x in serves for x in ('women','female','all')): continue
            if shelter_key in ('family','parents_children') and any(x in serves for x in ('men','male','women','female')) and not any(x in serves for x in ('family','children','parent','all')): continue
        rows.append({'name':name,'kind':kind,'url':website,'map_url':map_url,'phone':phone,'email':email,'location':' '.join(x for x in (city,state) if x),'address':address,'eligibility':'Not published in the mapped record. Contact the provider directly.','hours':_clean_text(tags.get('opening_hours')),'how_to_apply':'Contact the provider directly to confirm the requested service, eligibility, hours and current availability.','verification':'Information may have changed','verified_at':'Structured local map listing; confirm directly','snippet':f'Listed as a nearby {facility.lower()}. Contact the provider to confirm services, eligibility and current availability.','local_score':140-max(0,distance),'latitude':lat,'longitude':lon})
    unique={}
    for row in sorted(rows,key=lambda x:x['local_score'],reverse=True): unique.setdefault((row['name'].lower(),row['address'].lower()),row)
    return list(unique.values())[:25]

def _emergency_search_plan(city,state,county,zip_code,categories,need,assistance_for='',shelter_type=''):
    """Build locality-first passes across actual community-provider types."""
    city_place=' '.join(x for x in (city,state) if x).strip()
    county_name=(county+' County' if county and 'county' not in county.lower() else county).strip()
    county_place=' '.join(x for x in (county_name,state) if x).strip()
    places=[('City',city_place),('ZIP',' '.join(x for x in (zip_code,state) if x).strip()),('County',county_place),('State',state)]
    unique_places=[]; seen_places=set()
    for level,place in places:
        key=place.lower()
        if place and key not in seen_places: seen_places.add(key); unique_places.append((level,place))
    provider_terms={
        'shelter':['emergency shelter transitional housing direct assistance','eviction prevention rent assistance housing nonprofit','domestic violence shelter services'],
        'food':['food pantry emergency groceries','church food pantry community meals','nonprofit food assistance free groceries','community food distribution','food bank pantry hours','school family food program'],
        'clothing':['clothing closet free clothing program','church clothing pantry','nonprofit clothing assistance','work clothing program','school district family resource center clothing assistance'],
        'utilities':['utility shutoff assistance community action agency','church emergency utility assistance','county energy water assistance'],
        'financial':['emergency financial assistance nonprofit','rent deposit assistance community action agency','church family emergency assistance'],
        'health':['community health center low cost care','community mental health crisis services','nonprofit wellness assistance'],
        'family':['family resource center diapers baby supplies','school district family assistance program','nonprofit children family emergency help'],
        'transportation':['transportation assistance nonprofit bus passes','medical transportation community program','community action transportation help'],
        'employment':['workforce center job training','work clothing program nonprofit','school community career resource center'],
        'community':['community action agency emergency assistance','church assistance program food clothing rent','neighborhood nonprofit family resource center'],
        'other':['community emergency assistance nonprofit','community action agency assistance','church community help program']}
    plan=[]
    def add(level,place,focus,provider_type):
        if place and focus: plan.append({'level':level,'place':place,'provider_type':provider_type,'query':f'{place} {focus} official contact address phone hours -site:211.org -site:findhelp.org -site:yelp.com -directory'})
    # The exact need receives the first city and county passes.
    if need:
        for level,place in unique_places[:3]: add(level,place,need[:180]+' direct assistance','Direct local provider')
        for level,place in unique_places[:3]:
            add(level,place,need[:140]+' local nonprofit direct phone intake','Local nonprofit')
            add(level,place,need[:140]+' church faith based direct assistance contact','Church / faith-based direct provider')
    if 'shelter' in categories:
        shelter_focus={
            'men':['men emergency shelter','homeless shelter for men','transitional housing for men'],
            'women':['women emergency shelter','women transitional housing','women housing nonprofit'],
            'family':['family emergency shelter','family emergency housing','family transitional housing'],
            'parents_children':['shelter parents with children','family emergency housing children','family transitional housing'],
            'youth':['youth emergency shelter','runaway homeless youth shelter','youth transitional housing'],
            'any':['emergency shelter intake','emergency housing program','local housing nonprofit'],
            'unsure':['coordinated entry emergency shelter','emergency housing program','local housing nonprofit']}.get(shelter_type,[])
        if assistance_for in ('self_children','family') and shelter_type not in ('family','parents_children'):
            shelter_focus=['family emergency shelter','shelter parents with children','family transitional housing']+shelter_focus
        for index,focus in enumerate(shelter_focus):
            level,place=unique_places[min(index,len(unique_places)-1)]
            add(level,place,focus+' accepts appropriate household official','Local shelter / housing provider')
        for level,place in unique_places[:3]:
            add(level,place,'church faith based nonprofit emergency shelter housing direct assistance','Church / faith-based direct provider')
            add(level,place,'local nonprofit emergency housing shelter intake direct assistance','Local nonprofit')
    for category in categories:
        terms=provider_terms.get(category,provider_terms['other'])
        for index,focus in enumerate(terms):
            level,place=unique_places[min(index,len(unique_places)-1)]
            add(level,place,focus,('Church / faith-based' if 'church' in focus else 'School / family resource center' if 'school' in focus else 'Local organization'))
        if county_place: add('County',county_place,EMERGENCY_RESOURCE_CATEGORIES[category][2]+' county program','County program')
    unique=[]; seen=set()
    for item in plan:
        key=re.sub(r'\W+',' ',item['query'].lower()).strip()
        if key not in seen: seen.add(key); unique.append(item)
    return unique[:30]

def _emergency_contact_fields(text):
    text=re.sub(r'\s+',' ',text or '')
    phone=_published_field(text,[r'((?:\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4})'])
    email=_published_field(text,[r'([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})'])
    address=_published_field(text,[r'(\d{1,6}\s+[A-Z0-9][A-Z0-9 .#\-]{2,80}\s(?:Street|St\.?|Avenue|Ave\.?|Road|Rd\.?|Boulevard|Blvd\.?|Drive|Dr\.?|Lane|Ln\.?|Highway|Hwy\.?|Way|Court|Ct\.?)[^.;|]{0,90}\b[A-Z]{2}\s+\d{5}(?:-\d{4})?)'])
    hours=_published_field(text,[r'((?:hours|open)\s*[:\-]\s*(?:Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday|Mon|Tue|Wed|Thu|Fri|Sat|Sun)[^.;]{3,240})'])
    apply=_published_field(text,[r'((?:how to apply|request assistance|to receive help|appointments?|intake)\s*[:\-]?\s*[^.;]{15,350})'])
    eligibility=_published_field(text,[r'((?:eligibility|eligible|who qualifies|requirements?)\s*[:\-]?\s*[^.;]{15,350})'])
    return {'phone':phone,'email':email,'address':address,'hours':hours,'how_to_apply':apply,'eligibility':eligibility}

def _emergency_relevance(text,city,state,county,zip_code,categories):
    lower=(text or '').lower(); score=0
    if city and city.lower() in lower: score+=45
    if zip_code and zip_code.lower() in lower: score+=40
    if county and county.lower().removesuffix(' county') in lower: score+=28
    if state and state.lower() in lower: score+=12
    requested=' '.join(EMERGENCY_RESOURCE_CATEGORIES[x][2] for x in categories if x in EMERGENCY_RESOURCE_CATEGORIES).lower()
    score+=min(28,sum(3 for word in set(re.findall(r'[a-z]{4,}',requested)) if word in lower))
    if any(x in lower for x in ('pantry','shelter','assistance','community center','resource center','nonprofit','church','food bank','clothing closet','community action')): score+=18
    return score

def _emergency_location_matches(text,city,county,zip_code):
    """Require positive local evidence; state-level relevance alone is never local enough."""
    lower=(text or '').lower()
    city_key=(city or '').strip().lower()
    zip_key=(zip_code or '').strip().lower()
    county_key=(county or '').strip().lower().removesuffix(' county')
    if city_key or zip_key:
        city_match=bool(city_key and re.search(r'(?<![a-z])'+re.escape(city_key)+r'(?![a-z])',lower))
        zip_match=bool(zip_key and re.search(r'(?<!\d)'+re.escape(zip_key)+r'(?!\d)',lower))
        return city_match or zip_match
    if county_key:
        return bool(re.search(r'(?<![a-z])'+re.escape(county_key)+r'(?:\s+county)?(?![a-z])',lower))
    return False

def _emergency_live_results(city,state,county,zip_code,categories,need,assistance_for='',shelter_type=''):
    place=' '.join(x for x in (city,county,state,zip_code) if x).strip()
    rows=_emergency_verified_local_results(city,state,county,categories)
    rows.extend(_emergency_open_map_results(city,state,county,zip_code,categories,assistance_for,shelter_type))
    errors=[]; plan=_emergency_search_plan(city,state,county,zip_code,categories,need,assistance_for,shelter_type)
    traditional_web=bool(os.environ.get('BRAVE_SEARCH_API_KEY','').strip() or os.environ.get('BING_SEARCH_API_KEY','').strip() or (os.environ.get('GOOGLE_CSE_API_KEY','').strip() and os.environ.get('GOOGLE_CSE_ID','').strip()))
    search_jobs=plan[:24]
    search_function=_configured_funding_web_search
    if not traditional_web and OPENAI_API_KEY:
        combined='\n'.join(f"- {item['query']}" for item in plan)
        search_jobs=[{'level':'City','place':place,'provider_type':'Verified local direct provider','query':combined}]
        search_function=lambda query,count: (_openai_emergency_web_search(query,15),'OpenAI web search')
    elif not traditional_web:
        search_jobs=plan[:9]
        search_function=_keyless_emergency_web_search
    with ThreadPoolExecutor(max_workers=min(6,len(search_jobs))) as pool:
        futures={pool.submit(search_function,item['query'],10):item for item in search_jobs}
        for future in as_completed(futures):
            query_meta=futures[future]
            try:
                found,provider=future.result()
                for item in found:
                    url=_clean_text(item.get('url')); title=_clean_text(item.get('title')); snippet=_clean_text(item.get('description'))
                    if not url or not title or not url.startswith('https://'): continue
                    if _emergency_is_directory(url,title): continue
                    page_text=_safe_public_page_text(url)
                    if not page_text and not _trusted_emergency_domain(url): continue
                    evidence=(title+' '+snippet+' '+page_text[:70000]); relevance=_emergency_relevance(evidence,city,state,county,zip_code,categories)
                    if not _emergency_location_matches(evidence,city,county,zip_code): continue
                    # A local organization must be geographically relevant and
                    # publicly describe assistance. Search ranking alone is not proof.
                    assistance=bool(re.search(r'\b(help|assist|service|program|pantry|shelter|meal|clothing|housing|utility|health|transport|employment|resource)\w*\b',evidence,re.I))
                    if relevance<30 or not assistance: continue
                    contact=_emergency_contact_fields(evidence); trusted=_trusted_emergency_domain(url)
                    direct=bool(contact['phone'] or contact['email'] or contact['address'])
                    status='Verified' if (trusted or (page_text and direct and assistance)) else 'Information may have changed'
                    score=relevance+(24 if direct else 0)+(12 if trusted else 0)+(8 if query_meta['level']=='City' else 5 if query_meta['level']=='ZIP' else 2 if query_meta['level']=='County' else 0)
                    rows.append({'name':title[:180],'kind':query_meta['provider_type'],'url':url,'phone':contact['phone'],'email':contact['email'],'location':query_meta['place'],'address':contact['address'],'eligibility':contact['eligibility'] or 'Eligibility requirements may apply. Contact the program to confirm eligibility and current availability.','hours':contact['hours'],'how_to_apply':contact['how_to_apply'] or 'Call or visit the organization’s official website to request assistance and confirm current availability.','verification':status,'verified_at':now()[:10] if status=='Verified' else 'Confirm before relying on this information','snippet':snippet[:700],'local_score':score})
            except Exception as exc: errors.append(type(exc).__name__)
    unique={}
    for row in sorted(rows,key=lambda x:x.get('local_score',0),reverse=True): unique.setdefault(row['url'].lower().rstrip('/'),row)
    return list(unique.values())[:30],('Some local search passes could not be completed; every displayed provider was still checked against its public page.' if errors else f'Deep local search reviewed {len(search_jobs)} locality and provider-type searches and checked discovered organization pages.')

def _emergency_resource_cards(rows):
    cards=[]
    for row in rows:
        phone=re.sub(r'[^0-9+]','',row.get('phone','')); email=row.get('email',''); address=row.get('address','')
        phone_action=f'''<a class="btn" href="tel:{phone}">📞 Call for Assistance</a>''' if phone else ''
        email_action=f'''<a class="out" href="mailto:{html.escape(email,quote=True)}">Email</a>''' if email else ''
        directions_query=' '.join(x for x in (row.get('name',''),address,row.get('location','')) if x)
        directions=row.get('map_url') or ('https://www.google.com/maps/search/?'+urllib.parse.urlencode({'api':'1','query':directions_query}))
        saved_payload=html.escape(json.dumps({'name':row.get('name',''),'kind':row.get('kind',''),'url':row.get('url',''),'phone':row.get('phone',''),'email':email,'address':address,'location':row.get('location','')},separators=(',',':')),quote=True)
        status_class='gold' if row['verification']=='Verified' else ''
        website_action=f'''<a class="btn" href="{html.escape(row['url'],quote=True)}" target="_blank" rel="noopener noreferrer">🌐 Visit Official Website</a>''' if row.get('url') else ''
        cards.append(f'''<article class="card"><span class="badge {status_class}">{html.escape(row['verification'])}</span><h3>{html.escape(row['name'])}</h3><p><b>{html.escape(row['kind'])}</b></p>{f'<p><b>📞 Phone:</b> <a href="tel:{phone}">{html.escape(row["phone"])}</a></p>' if phone else '<p class="muted"><b>📞 Phone:</b> No direct number verified in the available source.</p>'}{f'<p><b>🌐 Official Website:</b> <a href="{html.escape(row["url"],quote=True)}" target="_blank" rel="noopener noreferrer">Open organization website</a></p>' if row.get('url') else '<p class="muted"><b>🌐 Official Website:</b> No official organization website verified.</p>'}{f'<p><b>📍 Address:</b> {html.escape(address)}</p>' if address else f'<p><b>📍 Area:</b> {html.escape(row.get("location", ""))}</p>'}{f'<p><b>✉️ Email:</b> {html.escape(email)}</p>' if email else ''}{f'<p><b>🕐 Hours:</b> {html.escape(row["hours"])}</p>' if row.get('hours') else '<p class="muted"><b>🕐 Hours:</b> Call to confirm.</p>'}{f'<p>{html.escape(row["snippet"])}</p>' if row.get('snippet') else ''}<p class="muted"><b>Eligibility:</b> {html.escape(row['eligibility'])}</p><p><b>How to get assistance:</b> {html.escape(row['how_to_apply'])}</p><div class="actions">{phone_action}{website_action}<a class="out" href="{html.escape(directions,quote=True)}" target="_blank" rel="noopener noreferrer">📍 Directions</a>{email_action}<button class="out" type="button" data-save-emergency="{saved_payload}">Save Resource</button></div><p class="muted small">Availability may change. Please call the organization to confirm that assistance is currently available.</p></article>''')
    return ''.join(cards)

@app.route('/emergency-resources',methods=['GET','POST'])
def emergency_resources():
    values={k:(request.form.get(k,'').strip()[:160] if request.method=='POST' else request.args.get(k,'').strip()[:160]) for k in ('city','state','county','zip','need','assistance_for','shelter_type')}
    if values['county'].lower() in {values['city'].lower(),values['state'].lower()}:
        values['county']=''
    if values['assistance_for'] not in ('self','self_children','family','other'): values['assistance_for']='self'
    if values['shelter_type'] not in ('men','women','family','parents_children','youth','any','unsure'): values['shelter_type']=''
    selected=request.form.getlist('category') if request.method=='POST' else request.args.getlist('category')
    categories=_emergency_categories_for_need(values['need'],selected) if (request.method=='POST' or any(values.values()) or selected) else []
    local_results=[]; directory_results=[]; search_note=''
    if request.method=='POST':
        if not (values['state'] and (values['city'] or values['county'] or values['zip'])):
            flash('Enter a state and at least a city, county or ZIP code so resources can be searched in the correct area.','error')
        else:
            local_results,search_note=_emergency_live_results(values['city'],values['state'],values['county'],values['zip'],categories,values['need'],values['assistance_for'],values['shelter_type']); directory_results=_emergency_directory_resources(categories)
    category_html=''.join(f'''<label class="fact" style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="category" value="{key}" {'checked' if key in categories else ''}> <span>{icon} {html.escape(label)}</span></label>''' for key,(icon,label,terms) in EMERGENCY_RESOURCE_CATEGORIES.items())
    assistance_html=''.join(f'''<option value="{key}" {'selected' if values['assistance_for']==key else ''}>{label}</option>''' for key,label in (('self','Myself'),('self_children','Myself and my children'),('family','My family'),('other','Another person')))
    shelter_html=''.join(f'''<option value="{key}" {'selected' if values['shelter_type']==key else ''}>{label}</option>''' for key,label in (('', 'Select one'),('men',"Men's shelter"),('women',"Women's shelter"),('family','Family shelter'),('parents_children','Shelter for parents with children'),('youth','Youth shelter'),('any','Any appropriate shelter'),('unsure',"I'm not sure")))
    category_html+=f'''</div><div class="topspace"><label><b>Who are you looking for assistance for?</b><select class="input" name="assistance_for">{assistance_html}</select></label><div data-shelter-question {'hidden' if 'shelter' not in categories else ''}><label><b>What type of shelter are you looking for?</b><select class="input" name="shelter_type">{shelter_html}</select></label></div></div><div><script>(()=>{{const shelter=document.querySelector('input[name="category"][value="shelter"]'),question=document.querySelector('[data-shelter-question]');if(!shelter||!question)return;const sync=()=>question.hidden=!shelter.checked;shelter.addEventListener('change',sync);sync()}})();</script>'''
    local_html=f'''<section class="topspace"><h2>Local Resources Found</h2>{f'<p class="muted">{html.escape(search_note)}</p>' if search_note else ''}{f'<div class="grid">{_emergency_resource_cards(local_results)}</div>' if local_results else '<div class="empty"><h3>No direct local provider could be verified in this search.</h3><p>Try a nearby city, county name, ZIP code, or a more specific description. The referral resources below can also help locate currently operating programs.</p></div>'}<p class="muted small">Actual providers are ranked by city, ZIP and county relevance. Details and availability can change, so contact each provider directly before traveling.</p></section>''' if request.method=='POST' and values['state'] else ''
    directory_html=f'''<section class="topspace"><h2>Additional Referral and Government Resources</h2><p class="muted">These are backup options after the local-provider search—not substitutes for it.</p><div class="grid">{_emergency_resource_cards(directory_results)}</div></section>''' if directory_results else ''
    result_html=local_html+directory_html
    if request.method=='POST' and result_html:
        result_html=f'''<div data-emergency-search-results>{result_html}</div><script>(()=>{{const results=document.querySelector('[data-emergency-search-results]'),form=document.querySelector('form.card[method="post"]');if(results&&form)form.before(results)}})();</script>'''
    direct_url=(APP_BASE_URL or request.url_root.rstrip('/'))+url_for('emergency_resources'); qr='https://api.qrserver.com/v1/create-qr-code/?'+urllib.parse.urlencode({'size':'260x260','ecc':'H','data':direct_url})
    return page('Emergency Resources',f'''<div class="hero"><span class="badge heart">PUBLIC RESOURCE SEARCH</span><h1>Emergency Resources</h1><p>Whatever you may be going through, let’s help you find resources that may be available in your community.</p><p><b>If you are in immediate danger or experiencing a life-threatening emergency, call <a href="tel:911">911</a>. If you are experiencing a mental health or suicide crisis in the U.S., call or text <a href="tel:988">988</a>.</b></p></div><form class="card" method="post"><h2>What do you need help with?</h2><div class="grid">{category_html}</div><label><b>Describe what you need</b></label><textarea class="input" name="need" placeholder="For example: I need help paying my electric bill in Detroit.">{html.escape(values['need'])}</textarea><p class="muted small">The assistant uses this only to identify search categories. Organizations and program facts come from verifiable public sources.</p><h2>Where are you located?</h2><div class="grid"><label><b>City</b><input class="input" name="city" value="{html.escape(values['city'],quote=True)}"></label><label><b>State</b><input class="input" name="state" value="{html.escape(values['state'],quote=True)}" required></label><label><b>County</b><input class="input" name="county" value="{html.escape(values['county'],quote=True)}"></label><label><b>ZIP Code</b><input class="input" name="zip" inputmode="numeric" value="{html.escape(values['zip'],quote=True)}"></label></div><button class="btn">Deep Local Search</button></form>{result_html}<section class="topspace" id="saved-emergency-resources" hidden><h2>Saved Resources on This Device</h2><p class="muted">Saved only in this browser. No member account or private app data is used.</p><div class="grid" data-saved-emergency-list></div><button class="out" type="button" data-clear-emergency>Clear Saved Resources</button></section><article class="card topspace" id="qr-code"><h2>Emergency Resources QR Code</h2><p class="muted">Scan to open this public search page. No membership or login is required.</p><img src="{html.escape(qr,quote=True)}" alt="QR code for the public Emergency Resources page" style="width:260px;max-width:100%;height:auto"><p><a class="out" href="{html.escape(qr,quote=True)}" target="_blank" rel="noopener">Open / Save QR Code</a></p><p class="muted small">Direct page: {html.escape(direct_url)}</p></article><script>(()=>{{const key='tsw_emergency_saved_resources_v1',section=document.querySelector('#saved-emergency-resources'),list=document.querySelector('[data-saved-emergency-list]');const read=()=>{{try{{return JSON.parse(localStorage.getItem(key)||'[]')}}catch(e){{return[]}}}};function draw(){{const rows=read();section.hidden=!rows.length;list.innerHTML='';rows.forEach((r,i)=>{{const card=document.createElement('article');card.className='card';const h=document.createElement('h3');h.textContent=r.name||'Saved Resource';const p=document.createElement('p');p.textContent=[r.kind,r.address||r.location,r.phone].filter(Boolean).join(' • ');const a=document.createElement('a');a.className='out';a.href=r.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Open Resource';const remove=document.createElement('button');remove.className='out danger';remove.type='button';remove.textContent='Remove';remove.onclick=()=>{{const next=read();next.splice(i,1);localStorage.setItem(key,JSON.stringify(next));draw()}};card.append(h,p,a,remove);list.append(card)}})}}document.querySelectorAll('[data-save-emergency]').forEach(button=>button.addEventListener('click',()=>{{let item;try{{item=JSON.parse(button.dataset.saveEmergency)}}catch(e){{return}}const rows=read();if(!rows.some(x=>x.url===item.url))rows.push(item);localStorage.setItem(key,JSON.stringify(rows));button.textContent='Saved';draw()}}));document.querySelector('[data-clear-emergency]').addEventListener('click',()=>{{localStorage.removeItem(key);draw()}});draw()}})();</script>''','home')

@app.route('/join', methods=['GET','POST'])


def join():
    referral_code=(request.form.get('referral_code') or request.args.get('ref') or '').strip().upper()
    referrer=None
    if referral_code:
        conn=db()
        referrer=conn.execute('''SELECT u.id,u.name FROM affiliate_profiles ap
                                 JOIN users u ON u.id=ap.user_id
                                 WHERE upper(ap.referral_code)=?''',(referral_code,)).fetchone()
        conn.close()

    if request.method=='POST':
        participation=request.form.get('participation','business')
        wants_coordination=participation in {'coordination','both'}
        name=request.form.get('name','').strip()
        email=request.form.get('email','').strip().lower()
        password=request.form.get('password','')
        dob=request.form.get('dob','').strip()
        birth_time=request.form.get('birth_time','').strip()
        birth_city=request.form.get('birth_city','').strip()
        birth_region=request.form.get('birth_region','').strip()
        birth_country=request.form.get('birth_country','').strip()
        time_unknown=1 if request.form.get('birth_time_unknown') and not birth_time else 0
        exact=1 if request.form.get('exact_time') and birth_time else 0
        adult=1 if request.form.get('adult') else 0

        if not name or not email or len(password)<8:
            flash('Name, email, and a password of at least 8 characters are required.','error')
        elif wants_coordination and (not dob or not birth_city or not birth_country or not adult):
            flash('Conscious Coordination requires birth date, birth city, country, and confirmation that you are at least 18.','error')
        elif wants_coordination and not birth_time and not time_unknown:
            flash('Enter your birth time, or choose “I do not know my birth time.”','error')
        else:
            conn=db()
            try:
                cur=conn.execute('''INSERT INTO users(name,email,password_hash,dob,adult_confirmed,birth_time,birth_city,birth_region,birth_country,exact_time,birth_time_unknown,created_at)
                                    VALUES(?,?,?,?,?,?,?,?,?,?,?,?)''',
                                 (name,email,generate_password_hash(password),dob,adult,birth_time,birth_city,birth_region,birth_country,exact,time_unknown,now()))
                new_user_id=cur.lastrowid
                if referrer and referrer['id']!=new_user_id:
                    conn.execute('''INSERT INTO affiliate_referrals(referrer_id,referred_user_id,created_at)
                                    VALUES(?,?,?) ON CONFLICT DO NOTHING''',(referrer['id'],new_user_id,now()))
                conn.commit()
                session['user_id']=new_user_id
                verification=_issue_email_verification(new_user_id,force=True)
                delivered=bool(verification and verification.get('delivered'))
                if referrer and delivered:
                    flash(f'Your account is ready. You joined through {referrer["name"]}’s Earn While You Grow link. We sent your email verification. Your private setup can save while you verify.','success')
                elif delivered:
                    flash('Your account is ready. We sent your email verification. Your private setup can save while you verify.','success')
                else:
                    flash('Your account and private setup are saved, but the verification email could not be delivered. Please use Resend Code after email delivery is configured.','error')
                return redirect(url_for('edit_profile') if wants_coordination else url_for('business_dashboard'))
            except DB_INTEGRITY_ERRORS:
                flash('An account with that email already exists. Use Login or Forgot Password.','error')
            finally:
                conn.close()

    referral_note=''
    if referrer:
        referral_note=f'''<article class="card paid"><span class="badge gold">EARN WHILE YOU GROW COMMUNITY</span>
        <p>You are joining through <b>{html.escape(referrer['name'])}</b>’s personal Seasons Within referral link.</p>
        <p class="muted small">This records that member as your direct referrer. Joining does not require you to purchase an upgrade.</p></article>'''

    return page('Join Free',f'''<div class="hero"><span class="badge">JOIN FREE</span><h1>Create Your Account</h1>
    <p class="muted">Choose business-only participation without a personal Conscious Coordination profile, or opt into Conscious Coordination if you are 18 or older.</p></div>
    {referral_note}
    <form class="card" method="post">
    <input type="hidden" name="referral_code" value="{html.escape(referral_code,quote=True)}">
    <label><b>Name</b></label><input class="input" name="name" required>
    <label><b>Email</b></label><input class="input" type="email" name="email" required>
    <label><b>Password</b></label><input class="input" type="password" name="password" minlength="8" required>
    <label><b>How will you participate?</b></label><select class="input" name="participation" id="participation"><option value="business">Business only / Hosted Business App</option><option value="coordination">Conscious Coordination</option><option value="both">Business and Conscious Coordination</option></select>
    <div id="coordination-join-fields"><h2>Conscious Coordination Information</h2><p class="muted">Only required if you choose Conscious Coordination. You may add it later.</p>
    <label><b>Birth Date</b></label><input class="input" type="date" name="dob">
    <label><b>Birth Time</b></label><input class="input" type="time" name="birth_time">
    <div class="fact"><label><input type="checkbox" name="exact_time"> Exact birth time is known</label><br>
    <label><input type="checkbox" name="birth_time_unknown"> I do not know my birth time</label></div>
    <label><b>Birth City</b></label><input class="input" name="birth_city">
    <label><b>State / Province</b></label><input class="input" name="birth_region">
    <label><b>Country</b></label><input class="input" name="birth_country">
    <label><input type="checkbox" name="adult"> I confirm I am 18 or older.</label></div>
    <div class="actions"><button class="btn">Create My Account</button><a class="out" href="{url_for('login')}">I Already Have an Account</a></div>
    </form><script>(()=>{{const choice=document.querySelector('#participation'),fields=document.querySelector('#coordination-join-fields');function sync(){{fields.hidden=choice.value==='business'}}choice.addEventListener('change',sync);sync()}})();</script>''')

@app.route('/login', methods=['GET','POST'])
def login():
    if request.method=='POST':
        email=request.form.get('email','').strip().lower()
        password=request.form.get('password','')
        remember=bool(request.form.get('remember'))
        conn=db(); u=conn.execute('SELECT * FROM users WHERE lower(email)=lower(?)',(email,)).fetchone(); conn.close()
        if u and not _row_value(u,'account_deleted_at','') and check_password_hash(u['password_hash'],password):
            session.clear(); session['user_id']=u['id']; session.permanent=remember
            flash('Welcome back. Your existing account and saved information are loaded.','success')
            destination=_safe_next_url(request.args.get('next'))
            if _row_value(u,'personal_profile_disabled',0):
                destination=url_for('settings')
                flash('Your personal profile is disabled. Reactivate it in Settings when you are ready.','info')
            if not u['email_verified']:
                return redirect(url_for('verify_email',next=destination))
            response=redirect(destination)
            if request.form.get('trust_device'):
                response=_set_trusted_cookie(response,u['id'])
            else:
                _trusted_device_for(u['id'])
            return response
        flash('Email or password did not match. Use the email already on your account, or choose Forgot Password.','error')
    content=f'''<div class="hero"><span class="badge">MEMBER LOGIN</span><h1>Welcome Back</h1><p class="muted">Log back into the same account to keep your profile, Journal, posts, business information and Conscious Coordination history.</p></div><form class="card" method="post" data-no-autosave="1"><label><b>Email on your account</b></label><input class="input" type="email" name="email" required autocomplete="email"><label><b>Password</b></label><input class="input" type="password" name="password" required autocomplete="current-password"><label><input type="checkbox" name="remember" value="1"> Remember Me on this browser for 30 days</label><label><input type="checkbox" name="trust_device" value="1"> Trust this device for 60 days</label><p class="muted small">A trusted device never replaces your password or initial email verification.</p><div class="actions"><button class="btn">Login</button><a class="out" href="{url_for('forgot_password')}">Forgot Password</a><a class="out" href="{url_for('join')}">Create Free Account</a></div></form>'''
    return page('Login',content)

@app.route('/verify-email',methods=['GET','POST'])
@login_required
def verify_email():
    u=current_user(); destination=_safe_next_url(request.values.get('next'))
    if u['email_verified']:
        flash('Your email is already verified.','success')
        return redirect(destination)
    if request.method=='POST':
        code=re.sub(r'\D','',request.form.get('code',''))[:6]
        conn=db()
        try:
            row=conn.execute('''SELECT * FROM email_verification_tokens
                WHERE user_id=? AND used_at IS NULL ORDER BY id DESC LIMIT 1''',(u['id'],)).fetchone()
            valid=False; reason='invalid'
            if not row: reason='missing'
            elif _dt(row['locked_until']) and _dt(row['locked_until'])>datetime.utcnow(): reason='locked'
            elif not _dt(row['expires_at']) or _dt(row['expires_at'])<datetime.utcnow(): reason='expired'
            elif row['attempts']>=5: reason='locked'
            elif len(code)==6 and check_password_hash(row['code_hash'],code): valid=True
            if valid:
                _mark_email_verified(conn,u['id'],row['id']); conn.commit()
            else:
                if row and reason=='invalid':
                    attempts=int(row['attempts'] or 0)+1
                    lock=(datetime.utcnow()+timedelta(minutes=15)).replace(microsecond=0).isoformat()+'Z' if attempts>=5 else None
                    conn.execute('UPDATE email_verification_tokens SET attempts=?,locked_until=? WHERE id=?',(attempts,lock,row['id'])); conn.commit()
        finally: conn.close()
        if valid:
            _security_event(u['id'],'email_verified','six_digit_code')
            flash('✓ Email Verified. Welcome to The Seasons Within.','success')
            response=redirect(destination)
            if request.form.get('trust_device'): response=_set_trusted_cookie(response,u['id'])
            return response
        _security_event(u['id'],'verification_failed',reason)
        messages={'locked':'Too many attempts. Request a new code or try again later.','expired':'That code expired. Request a new one.','missing':'Request a verification email first.'}
        flash(messages.get(reason,'That code did not match. Please try again.'),'error')
    conn=db(); active=conn.execute('SELECT id FROM email_verification_tokens WHERE user_id=? AND used_at IS NULL ORDER BY id DESC LIMIT 1',(u['id'],)).fetchone(); conn.close()
    if not active: _issue_email_verification(u['id'],force=True)
    content=f'''<div class="hero"><span class="badge">EMAIL VERIFICATION</span><h1>Verify Your Email</h1>
    <p class="muted">We sent a one-tap verification link and six-digit code to <b>{html.escape(_masked_email(u['email']))}</b>.</p></div>
    <form method="post" class="card" data-no-autosave="1"><input type="hidden" name="next" value="{html.escape(destination,quote=True)}">
    <label><b>Enter verification code</b></label><input class="input" name="code" autocomplete="one-time-code" inputmode="numeric" pattern="[0-9]{{6}}" maxlength="6" placeholder="482193" required>
    <label><input type="checkbox" name="trust_device" value="1"> Trust this device after verification</label>
    <div class="actions"><button class="btn">Verify Email</button></div></form>
    <form method="post" action="{url_for('resend_verification')}" class="card" data-no-autosave="1"><button class="out">Resend Code</button><p class="muted small">For security, resends are limited to one every 45 seconds.</p></form>'''
    return page('Verify Email',content)

@app.route('/verify-email/link/<token>')
def verify_email_link(token):
    digest=hashlib.sha256((token or '').encode()).hexdigest(); conn=db()
    try:
        row=conn.execute('SELECT * FROM email_verification_tokens WHERE link_token_hash=?',(digest,)).fetchone()
        valid=bool(row and not row['used_at'] and _dt(row['expires_at']) and _dt(row['expires_at'])>=datetime.utcnow())
        if valid:
            _mark_email_verified(conn,row['user_id'],row['id']); conn.commit()
    finally: conn.close()
    if not valid:
        return page('Verify Email','''<div class="hero"><h1>This verification link is no longer valid</h1><p class="muted">Sign in and request a new verification email.</p><a class="btn" href="/login">Sign In</a></div>'''),400
    _security_event(row['user_id'],'email_verified','one_tap_link')
    if session.get('user_id')==row['user_id']:
        flash('✓ Email Verified. Welcome to The Seasons Within.','success')
        return redirect(url_for('profile'))
    flash('✓ Email verified. Sign in to continue with your saved account.','success')
    return redirect(url_for('login'))

