    galaxy_business=conn.execute("SELECT b.* FROM businesses b JOIN users owner ON owner.id=b.owner_id WHERE b.active=1 AND lower(owner.name)=lower('Galaxy Eve') ORDER BY b.id LIMIT 1").fetchone()
    posts=conn.execute('''SELECT p.*,u.name FROM community_posts p JOIN users u ON u.id=p.user_id
                          WHERE lower(u.name)<>lower('Galaxy Eve')
                          ORDER BY p.id DESC LIMIT 50''').fetchall()
    conn.close()

    galaxy_feature=''
    if galaxy_user:
        galaxy_actions=[f'<a class="btn" href="{url_for("member_profile",user_id=galaxy_user["id"])}">View Galaxy Eve Public Journal</a>',
                        f'<a class="out" href="{url_for("message_member",recipient_id=galaxy_user["id"],origin="Community")}">Message Galaxy Eve</a>']
        if galaxy_business:
            galaxy_actions.append(f'<a class="out" href="{url_for("business_app",business_id=galaxy_business["id"])}">Open Hosted App</a>')
        galaxy_feature=f'''<article class="card paid"><div class="post"><div class="avatar">GE</div><div><span class="badge gold">GALAXY EVE • FEATURED CREATOR</span><h2>Galaxy Eve</h2><p class="muted small">Conscious Coordinator • Content Creator</p><p>Creator experiences, prompts, events, Retreat invitations and Community posts appear under Galaxy Eve’s own identity.</p><div class="actions">{''.join(galaxy_actions)}</div></div></div></article>'''

    cards=[]
    for p in posts:
        message=f'<a class="out" href="{url_for("message_member",recipient_id=p["user_id"],origin="Community",post_id=p["id"])}">Send Message</a>'
        controls=message+(f'<a class="out" href="{url_for("community_post_edit",post_id=p["id"])}">Edit Post</a><form method="post" action="{url_for("community_post_delete",post_id=p["id"])}" style="display:inline"><button class="out danger" type="submit">Delete Post</button></form>' if p['user_id']==u['id'] else '')
        author_badge='<span class="badge gold">GALAXY EVE</span>' if p['name'].strip().lower()=='galaxy eve' else f'<span class="badge">{html.escape(p["category"])}</span>'
        cards.append(f'''<article class="card"><div class="post"><div class="avatar">{initials(p['name'])}</div><div style="width:100%">{author_badge}<h3 style="margin:6px 0">{html.escape(p['title'])}</h3><p class="muted small"><a class="out" href="{url_for('member_profile',user_id=p['user_id'])}">{html.escape(p['name'])}</a> • {p['created_at']}</p><p>{html.escape(p['body'])}</p>{community_media_html(p)}<div class="actions">{controls}</div></div></div></article>''')
