@app.route('/journal', methods=['GET','POST'])
@login_required


def journal():
    u=current_user(); conn=db()
    cp=conn.execute('SELECT * FROM connection_profiles WHERE user_id=?',(u['id'],)).fetchone()
    conn.close()
    community_ready=conscious_coordination_ready(u,cp)
    categories=['Reflection','Private Journal Entries','Business','Retreat','Conscious Coordination']
    selected=request.args.get('category','All')
    prefill_category=request.args.get('category','Private Journal Entries')
    prefill_title=request.args.get('title','')
    prefill_prompt=request.args.get('prompt','')
    if request.method=='POST':
        title=request.form.get('title','').strip()
        body=request.form.get('body','').strip()
        category=request.form.get('category','Private Journal Entries')
        if category not in categories: category='Private Journal Entries'
        shared=community_ready and request.form.get('visibility')=='community'
        media_name,media_type=save_community_media(request.files.get('media'),u['id'])
        if title and (body or media_name):
            conn=db()
            if shared:
                conn.execute('INSERT INTO community_posts(user_id,title,category,body,media_name,media_type,created_at) VALUES(?,?,?,?,?,?,?)',
                             (u['id'],title,journal_category_for_public(category),body,media_name,media_type,now()))
            else:
                conn.execute('INSERT INTO journal_entries(user_id,title,body,category,shared_copy,source_post_id,media_name,media_type,created_at,updated_at) VALUES(?,?,?,?,0,NULL,?,?,?,?)',
                             (u['id'],title,body,category,media_name,media_type,now(),now()))
            conn.commit(); conn.close()
            _clear_page_drafts(u['id'],request.path)
            flash('Posted to Community.' if shared else 'Journal entry saved privately.','success')
            return redirect(url_for('community') if shared else url_for('journal',category=category))
    conn=db()
    entries=conn.execute('SELECT * FROM journal_entries WHERE user_id=? ORDER BY id DESC',(u['id'],)).fetchall()
    conn.close()
    if selected!='All':
        entries=[e for e in entries if e['category']==selected or (selected=='Private Journal Entries' and e['category']=='Journal Entry')]
    filter_html=''.join('<a class="chip" href="{}">{}</a>'.format(url_for('journal',category=c),c) for c in ['All']+categories)
    opts=''.join('<option value="{}" {}>{}</option>'.format(
        c,'selected' if c==prefill_category else '',
        'Reflections' if c=='Reflection' else 'Retreats' if c=='Retreat' else c) for c in categories)
    cards=[]
    for e in entries:
        media=''
        if 'media_name' in e.keys() and e['media_name']:
            src=url_for('community_media',filename=e['media_name'])
            media=(f'<video controls playsinline style="width:100%;border-radius:16px" src="{src}"></video>' if e['media_type']=='video' else f'<img src="{src}" alt="{html.escape(e["title"],quote=True)}" style="width:100%;max-height:620px;object-fit:contain;border-radius:16px">')
        elif e['source_post_id']:
            conn=db(); linked=conn.execute('SELECT media_name,media_type FROM community_posts WHERE id=?',(e['source_post_id'],)).fetchone(); conn.close()
            if linked and linked['media_name']:
                src=url_for('community_media',filename=linked['media_name']); media=(f'<video controls playsinline style="width:100%;border-radius:16px" src="{src}"></video>' if linked['media_type']=='video' else f'<img src="{src}" alt="{html.escape(e["title"],quote=True)}" style="width:100%;max-height:620px;object-fit:contain;border-radius:16px">')
        cards.append('<article class="card"><span class="badge">{}</span><h3>{}</h3>{}<p>{}</p><p class="muted small">PRIVATE - {}</p><div class="actions"><a class="out" href="{}">Edit</a><form method="post" action="{}" style="display:inline"><button class="out danger" type="submit">Delete</button></form></div></article>'.format(
            html.escape('Private Journal Entries' if e['category']=='Journal Entry' else e['category']).upper(),
            html.escape(e['title']),media,html.escape(e['body']),
            e['created_at'],url_for('journal_entry_edit',entry_id=e['id']),url_for('journal_entry_delete',entry_id=e['id'])))
    cards_html=''.join(cards) or '<div class="empty"><h3>No journal entries here yet</h3><p class="muted">Your private writing will stay organized here.</p></div>'
    prompt_html=f'<div class="fact"><small>Reflection prompt / context</small>{html.escape(prefill_prompt).replace(chr(10),"<br>")}</div>' if prefill_prompt else ''
    visibility_options='<option value="private" selected>Keep Private</option>'
    visibility_note=''
    if community_ready:
        visibility_options+='<option value="community">Share a Copy to Community</option>'
    else:
        visibility_note='<p class="muted small">Community sharing becomes available after your profile is complete.</p>'
    content=f'''<div class="hero"><span class="badge">MY JOURNAL</span><h1>My Private Journal</h1><p class="muted">One journal. Private by default.</p><div class="actions"><a class="btn" href="#new-entry">Private Journal Entry</a><a class="out" href="{url_for('astrology_reflections')}">Conscious Coordination Reflections</a><a class="out" href="{url_for('conscious_community')}">My Conscious Community</a><a class="out" href="{url_for('inbox')}">Journal Inbox</a></div></div>
    <form class="card" id="new-entry" method="post" enctype="multipart/form-data"><h2>Journal Entry</h2><label><b>File this entry under</b></label><select class="input" name="category">{opts}</select>
    <input class="input" name="title" value="{html.escape(prefill_title,quote=True)}" placeholder="Entry title" required>{prompt_html}
    <textarea class="input" name="body" placeholder="Write your private journal entry..." required></textarea>
    <label><b>Attach a Photo</b></label><input class="input" type="file" name="media" accept="image/*">
    <label><b>Visibility</b></label><select class="input" name="visibility">{visibility_options}</select>{visibility_note}<button class="btn">Save Entry</button></form>
    <article class="card"><h3>My Entries</h3><div class="chips">{filter_html}</div></article>{cards_html}'''
    return page('My Journal',content,'more')

@app.route('/journal/entry/<int:entry_id>/edit', methods=['GET','POST'])
@login_required
def journal_entry_edit(entry_id):
    u=current_user(); conn=db(); e=conn.execute('SELECT * FROM journal_entries WHERE id=? AND user_id=?',(entry_id,u['id'])).fetchone(); conn.close()
    if not e: abort(404)
    if request.method=='POST':
        title=request.form.get('title','').strip() or e['title']; category=journal_category_for_public(request.form.get('category',e['category'])); body=request.form.get('body','').strip()
        if body:
            conn=db(); conn.execute('UPDATE journal_entries SET title=?,category=?,body=?,updated_at=? WHERE id=? AND user_id=?',(title,category,body,now(),entry_id,u['id']))
            if e['source_post_id']: conn.execute('UPDATE community_posts SET title=?,category=?,body=? WHERE id=? AND user_id=?',(title,category,body,e['source_post_id'],u['id']))
            conn.commit(); conn.close(); flash('Journal entry updated.','success'); return redirect(url_for('journal',section=category))
    opts=''.join(f'<option {"selected" if e["category"]==c else ""}>{c}</option>' for c in JOURNAL_CATEGORIES)
    return page('Edit Journal Entry',f'''<div class="hero"><span class="badge">MY JOURNAL</span><h1>Edit Entry</h1></div><form class="card" method="post"><input class="input" name="title" value="{e['title']}" required><select class="input" name="category">{opts}</select><textarea class="input" name="body" required>{e['body']}</textarea><button class="btn">Save Changes</button><a class="out" href="{url_for('journal',section=e['category'])}">Cancel</a></form>''','more')

@app.route('/journal/entry/<int:entry_id>/delete', methods=['POST'])
@login_required
def journal_entry_delete(entry_id):
    u=current_user(); conn=db(); e=conn.execute('SELECT * FROM journal_entries WHERE id=? AND user_id=?',(entry_id,u['id'])).fetchone()
    if not e: conn.close(); abort(404)
    if e['source_post_id']:
        p=conn.execute('SELECT media_name FROM community_posts WHERE id=? AND user_id=?',(e['source_post_id'],u['id'])).fetchone(); preserve_media=bool(p and p['media_name'] and conn.execute('SELECT 1 FROM coordination_media WHERE user_id=? AND file_name=? LIMIT 1',(u['id'],p['media_name'])).fetchone()); conn.execute('DELETE FROM community_posts WHERE id=? AND user_id=?',(e['source_post_id'],u['id']))
        if p and p['media_name'] and not preserve_media:
            try: (UPLOAD_DIR / p['media_name']).unlink(missing_ok=True)
            except Exception: pass
    conn.execute('DELETE FROM journal_entries WHERE id=? AND user_id=?',(entry_id,u['id'])); conn.commit(); conn.close(); flash('Journal entry deleted.','success'); return redirect(url_for('journal',section=e['category']))

@app.route('/conscious-coordination/profile/<int:user_id>/experience-invitation',methods=['GET','POST'])
@login_required
def experience_invitation(user_id):
    u=current_user()
    if _member_blocked(u['id'],user_id): abort(404)
    if not has_full_access(u):
        flash('Upgrade your membership to use private Conscious Coordination interactions.','info')
        return redirect(url_for('membership'))
    if user_id==u['id']: abort(400)
    conn=db(); recipient=conn.execute('SELECT * FROM users WHERE id=?',(user_id,)).fetchone(); businesses=conn.execute('SELECT id,name,category,location FROM businesses WHERE active=1 ORDER BY name').fetchall()
    if not recipient: conn.close(); abort(404)
    if request.method=='POST':
        activity=request.form.get('activity','').strip(); proposed_date=request.form.get('proposed_date','').strip(); proposed_time=request.form.get('proposed_time','').strip(); mode=request.form.get('experience_mode','In Person'); note=request.form.get('note','').strip(); virtual_link=request.form.get('virtual_link','').strip(); business_id=request.form.get('business_id',type=int)
        if mode not in {'In Person','Virtual / Zoom'}: mode='In Person'
        if business_id and not conn.execute('SELECT id FROM businesses WHERE id=? AND active=1',(business_id,)).fetchone(): business_id=None
        if activity and proposed_date and proposed_time:
            duplicate=conn.execute("SELECT id FROM member_experience_invitations WHERE sender_id=? AND recipient_id=? AND proposed_date=? AND proposed_time=? AND status='Pending'",(u['id'],user_id,proposed_date,proposed_time)).fetchone()
            if duplicate:
                conn.close(); flash('That invitation is already waiting for a response.','info'); return redirect(url_for('inbox'))
            cur=conn.execute('''INSERT INTO member_experience_invitations(sender_id,recipient_id,activity,proposed_date,proposed_time,experience_mode,virtual_link,note,business_id,status,created_at) VALUES(?,?,?,?,?,?,?,?,?,'Pending',?)''',(u['id'],user_id,activity,proposed_date,proposed_time,mode,virtual_link if mode=='Virtual / Zoom' else '',note,business_id,now()))
            invite_id=cur.lastrowid; conn.commit(); conn.close(); notify(user_id,'Will You Go Out With Me?',f'{u["name"]} sent you a private experience invitation.',url_for('inbox')); flash('Your private invitation was sent to their Journal Inbox.','success'); return redirect(url_for('connection_profile',user_id=user_id))
    conn.close()
    business_options='<option value="">No business selected</option>'+''.join(f'<option value="{b["id"]}">{html.escape(b["name"])} — {html.escape(b["category"] or "Wellness")}</option>' for b in businesses)
    return page('Will You Go Out With Me?',f'''<div class="hero"><span class="badge heart">PRIVATE EXPERIENCE INVITATION</span><h1>Will You Go Out With Me?</h1><p class="muted">Invite {html.escape(recipient['name'])} to a virtual or in-person wellness experience. This goes only to their Journal Inbox.</p></div><form class="card" method="post"><label><b>Activity or experience</b></label><input class="input" name="activity" placeholder="Yoga class, nature walk, meditation, creative experience..." required><div class="grid"><label><b>Proposed date</b><input class="input" type="date" name="proposed_date" required></label><label><b>Proposed time</b><input class="input" type="time" name="proposed_time" required></label></div><label><b>Format</b></label><select class="input" name="experience_mode"><option>In Person</option><option>Virtual / Zoom</option></select><label><b>Virtual / Zoom link, if already available</b></label><input class="input" type="url" name="virtual_link" placeholder="https://..."><label><b>Suggested Seasons Within wellness app</b></label><select class="input" name="business_id">{business_options}</select><label><b>Optional note</b></label><textarea class="input" name="note"></textarea><button class="btn">Send Invitation</button></form>''','coordination')

@app.route('/experience-invitation/<int:invitation_id>/<decision>',methods=['POST'])
@login_required
def experience_invitation_respond(invitation_id,decision):
    if decision not in {'yes','no'}: abort(400)
    u=current_user()
    if not has_full_access(u):
        flash('Upgrade your membership to access private Conscious Coordination interactions.','info')
        return redirect(url_for('membership'))
    conn=db(); row=conn.execute('SELECT * FROM member_experience_invitations WHERE id=? AND recipient_id=? AND status=?',(invitation_id,u['id'],'Pending')).fetchone()
    if not row: conn.close(); abort(404)
    if decision=='yes':
        conflict=conn.execute("""SELECT id FROM member_experience_invitations WHERE id<>? AND status='Accepted' AND proposed_date=? AND proposed_time=? AND (sender_id IN (?,?) OR recipient_id IN (?,?)) LIMIT 1""",(invitation_id,row['proposed_date'],row['proposed_time'],row['sender_id'],row['recipient_id'],row['sender_id'],row['recipient_id'])).fetchone()
        if conflict:
            conn.close(); flash('That time now conflicts with another accepted experience. Coordinate another time before accepting.','error'); return redirect(url_for('inbox'))
    status='Accepted' if decision=='yes' else 'Declined'; conn.execute('UPDATE member_experience_invitations SET status=?,responded_at=? WHERE id=?',(status,now(),invitation_id)); conn.commit(); conn.close()
    destination=url_for('experience_invitation_plan',invitation_id=invitation_id) if decision=='yes' else url_for('inbox')
    notify(row['sender_id'],f'Experience Invitation {status}',f'{u["name"]} responded {"YES" if decision=="yes" else "NO"} to your invitation.',destination)
    flash('Invitation accepted. You can now plan your shared experience.' if decision=='yes' else 'Invitation declined.','success'); return redirect(destination)

@app.route('/experience-invitation/<int:invitation_id>/calendar.ics')
@login_required
def experience_invitation_calendar(invitation_id):
    u=current_user()
    if not has_full_access(u):
        flash('Upgrade your membership to access private Conscious Coordination interactions.','info')
        return redirect(url_for('membership'))
    conn=db(); row=conn.execute("SELECT * FROM member_experience_invitations WHERE id=? AND status='Accepted' AND (sender_id=? OR recipient_id=?)",(invitation_id,u['id'],u['id'])).fetchone(); conn.close()
    if not row: abort(404)
    try: start=datetime.fromisoformat(row['proposed_date']+'T'+row['proposed_time']); end=start+timedelta(hours=1)
    except Exception: abort(400)
    def stamp(value): return value.strftime('%Y%m%dT%H%M%S')
    description=(row['experience_mode']+' '+(row['virtual_link'] or '')+' '+(row['note'] or '')).strip().replace('\\n',' ')
    data=f'''BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//The Seasons Within//Experience Invitation//EN\r\nBEGIN:VEVENT\r\nUID:seasons-invitation-{invitation_id}@theseasonswithin\r\nDTSTART:{stamp(start)}\r\nDTEND:{stamp(end)}\r\nSUMMARY:{row['activity']}\r\nDESCRIPTION:{description}\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n'''
    return send_file(io.BytesIO(data.encode('utf-8')),mimetype='text/calendar',as_attachment=True,download_name=f'seasons-within-invitation-{invitation_id}.ics')

@app.route('/experience-invitation/<int:invitation_id>/plan')
@login_required
def experience_invitation_plan(invitation_id):
    if not has_full_access(current_user()):
        flash('Upgrade your membership to access private Conscious Coordination interactions.','info')
        return redirect(url_for('membership'))
    u=current_user(); conn=db()
    row=conn.execute('''SELECT i.*,s.name sender_name,r.name recipient_name,b.name business_name,b.category business_category,b.location business_location
        FROM member_experience_invitations i JOIN users s ON s.id=i.sender_id JOIN users r ON r.id=i.recipient_id
        LEFT JOIN businesses b ON b.id=i.business_id
        WHERE i.id=? AND i.status='Accepted' AND (i.sender_id=? OR i.recipient_id=?)''',(invitation_id,u['id'],u['id'])).fetchone()
    if not row: conn.close(); abort(404)
    words={x for x in re.findall(r'[a-z0-9]+',(row['activity'] or '').lower()) if len(x)>2}
    businesses=conn.execute('SELECT id,name,category,location,description,offers,features FROM businesses WHERE active=1 ORDER BY updated_at DESC,id DESC LIMIT 60').fetchall(); conn.close()
    ranked=[]
    for b in businesses:
        hay=' '.join(str(b[k] or '') for k in ('name','category','location','description','offers','features')).lower()
        score=sum(1 for word in words if word in hay)
        if score or b['id']==row['business_id']: ranked.append((score+(10 if b['id']==row['business_id'] else 0),b))
    ranked.sort(key=lambda item:(-item[0],(item[1]['name'] or '').lower()))
    suggestions=''.join(f'''<article class="card"><span class="badge">SEASONS WITHIN EXPERIENCE</span><h3>{html.escape(b['name'])}</h3><p class="muted">{html.escape(b['category'] or 'Wellness')} • {html.escape(b['location'] or 'Location available in app')}</p><a class="out" href="{url_for('business_app',business_id=b['id'])}">View Hosted Business App</a></article>''' for _,b in ranked[:4]) or '<div class="empty"><p class="muted">No published Seasons Within business currently matches this selected experience. Nothing has been invented.</p></div>'
    pair=basic_compatibility(row['sender_id'],row['recipient_id'],'general')
    if pair.get('ready'):
        coordination=f'''<p>Based on your shared coordination, here are some experiences that may complement this connection.</p><p>Your current strongest coordination area is <b>{html.escape(str(pair.get('strength') or 'shared understanding'))}</b>. The area to approach with additional awareness is <b>{html.escape(str(pair.get('difference') or 'pacing and expectations'))}</b>. Keep the plan mutual: confirm the activity, timing, boundaries and preferred format together.</p>'''
    else:
        coordination='<p>Choose an experience, pace and setting that both members explicitly agree to. More profile information may support deeper Conscious Coordination suggestions later.</p>'
    try:
        start=datetime.fromisoformat(row['proposed_date']+'T'+row['proposed_time']); end=start+timedelta(hours=1)
        google_dates=start.strftime('%Y%m%dT%H%M%S')+'/'+end.strftime('%Y%m%dT%H%M%S')
    except Exception: google_dates=''
    google_url='https://calendar.google.com/calendar/render?'+urllib.parse.urlencode({'action':'TEMPLATE','text':row['activity'],'dates':google_dates,'details':((row['experience_mode'] or '')+' '+(row['virtual_link'] or '')+' '+(row['note'] or '')).strip()}) if google_dates else ''
    google=f'''<label class="fact"><input type="checkbox" data-google-calendar> Add to my Google Calendar</label><p data-google-calendar-link hidden><a class="out" href="{html.escape(google_url,quote=True)}" target="_blank" rel="noopener">Continue to Google Calendar</a></p><script>(()=>{{const box=document.querySelector('[data-google-calendar]'),link=document.querySelector('[data-google-calendar-link]');if(box&&link)box.addEventListener('change',()=>link.hidden=!box.checked);}})();</script>''' if google_url else '<p class="muted">Google Calendar can be used after a valid date and time are selected.</p>'
    virtual=f'<p><a class="out" href="{html.escape(row["virtual_link"],quote=True)}" target="_blank" rel="noopener">Open Virtual / Zoom Meeting</a></p>' if row['virtual_link'] else ''
    return page('Plan Our Experience',f'''<div class="hero"><span class="badge heart">PRIVATE TWO-PERSON PLANNING</span><h1>Plan Our Experience</h1><p class="muted">Private between {html.escape(row['sender_name'])} and {html.escape(row['recipient_name'])}. Nothing here is posted to the public wall.</p></div><article class="card"><h2>{html.escape(row['activity'])}</h2><p><b>Agreed date:</b> {html.escape(row['proposed_date'])} at {html.escape(row['proposed_time'])}</p><p><b>Format:</b> {html.escape(row['experience_mode'])}</p>{f'<p>{html.escape(row["note"])}</p>' if row['note'] else ''}{virtual}<div class="actions"><a class="btn" href="{url_for('experience_invitation_calendar',invitation_id=invitation_id)}">Add to The Seasons Within Calendar</a></div>{google}</article><article class="card"><span class="badge">CONSCIOUS COORDINATION BETWEEN YOU</span><h2>Ideas for Your Shared Experience</h2>{coordination}</article><div class="topspace"><h2>Suggested Experiences</h2><p class="muted">Only real published Hosted Business Apps matching the selected activity are shown.</p></div><div class="grid">{suggestions}</div>''','coordination')

@app.route('/inbox')
@login_required
def inbox():
    u=current_user(); category=request.args.get('category','All'); focus=request.args.get('message_id',type=int); saved_view=request.args.get('view')=='saved'
    conn=db()
    unread=conn.execute('SELECT COUNT(*) n FROM messages WHERE recipient_id=? AND read_at IS NULL',(u['id'],)).fetchone()['n']
    msgs=conn.execute('''SELECT m.*,s.name sender_name,r.name recipient_name,gt.label gift_label,gt.emoji gift_emoji
                         FROM messages m
                         JOIN users s ON s.id=m.sender_id
                         JOIN users r ON r.id=m.recipient_id
                         LEFT JOIN member_virtual_gifts vg ON vg.id=m.gift_id
                         LEFT JOIN virtual_gift_types gt ON gt.id=vg.gift_type_id
                         WHERE m.recipient_id=? AND COALESCE(m.recipient_deleted,0)=0 AND COALESCE(m.recipient_saved,0)=? ORDER BY m.id DESC''',(u['id'],1 if saved_view else 0)).fetchall()
    sender_ids=sorted({m['sender_id'] for m in msgs})
    community_requests=conn.execute('''SELECT r.*,s.name sender_name FROM conscious_community_requests r JOIN users s ON s.id=r.sender_user_id WHERE r.receiver_user_id=? AND r.status='Pending' ORDER BY r.id DESC''',(u['id'],)).fetchall()
    experience_invites=conn.execute('''SELECT i.*,s.name sender_name,b.name business_name FROM member_experience_invitations i
        JOIN users s ON s.id=i.sender_id LEFT JOIN businesses b ON b.id=i.business_id
        WHERE i.recipient_id=? ORDER BY i.id DESC''',(u['id'],)).fetchall()
    hosted_businesses=conn.execute('''SELECT id,name,logo_name FROM businesses
        WHERE owner_id=? AND active=1 ORDER BY updated_at DESC,id DESC''',(u['id'],)).fetchall()
    retreat_host_requests=conn.execute('''SELECT r.*,b.name business_name
        FROM retreat_host_requests r JOIN businesses b ON b.id=r.business_id
        WHERE b.owner_id=? AND COALESCE(r.inbox_deleted,0)=0 AND COALESCE(r.inbox_saved,0)=? ORDER BY r.id DESC''',(u['id'],1 if saved_view else 0)).fetchall()
    sender_photos={}
    if sender_ids:
        placeholders=','.join('?' for _ in sender_ids)
        rows=conn.execute(f'''SELECT user_id,file_name,crop_data FROM coordination_media
                              WHERE media_role='profile' AND media_type='image' AND user_id IN ({placeholders})
                              ORDER BY id DESC''',sender_ids).fetchall()
        for row in rows:
            sender_photos.setdefault(row['user_id'],row)
    conn.close()
    if category!='All' and category in JOURNAL_CATEGORIES: msgs=[m for m in msgs if m['category']==category]
    cards=[]
    for m in msgs:
        photo=sender_photos.get(m['sender_id'])
        sender_avatar=(f'''<img class="avatar" src="{url_for('community_media',filename=photo['file_name'])}" alt="{html.escape(m['sender_name'],quote=True)}" style="object-fit:cover;{_crop_css(photo['crop_data'])}">''' if photo else f'''<div class="avatar" aria-label="{html.escape(m['sender_name'],quote=True)}">{initials(m['sender_name'])}</div>''')
        reply=f'<a class="out" href="{url_for("message_member",recipient_id=m["sender_id"],origin="Reply",subject=m["subject"],post_id=m["source_post_id"] if m["source_post_id"] else None)}">Reply</a>' if m['recipient_id']==u['id'] else ''
        dates=f'<p><b>Preferred Dates:</b> {m["preferred_dates"]}</p>' if 'preferred_dates' in m.keys() and m['preferred_dates'] else ''
        season=f'<p><b>Season:</b> {m["season"]}</p>' if 'season' in m.keys() and m['season'] else ''
        anchor=f' id="message-{m["id"]}"'; highlight=' style="outline:3px solid #ead7ad"' if focus==m['id'] else ''
        unread_badge='<span class="badge gold">NEW</span>' if m['recipient_id']==u['id'] and 'read_at' in m.keys() and not m['read_at'] else ''
        open_action=f'<a class="btn" href="{url_for("inbox_read",message_id=m["id"])}">Open Message</a>' if m['recipient_id']==u['id'] and 'read_at' in m.keys() and not m['read_at'] else ''
        coordination_profile_action=f'<a class="out" href="{url_for("connection_profile",user_id=m["sender_id"])}">View Coordination Profile</a>' if m['category']=='Conscious Coordination' and m['sender_id']!=u['id'] else ''
        gift_context=(f'''<p class="muted small"><b>About gift:</b> {m['gift_emoji']} {html.escape(m['gift_label'])}</p>''' if m['gift_label'] else '')
        save=(f'''<form method="post" action="{url_for('inbox_save',message_id=m['id'])}" style="display:inline"><button class="out" type="submit">Save</button></form>''' if m['category']=='Business' and not saved_view else '')
        delete=f'''<form method="post" action="{url_for('inbox_delete',message_id=m['id'])}" style="display:inline" onsubmit="return confirm('Remove this item from your inbox?')"><button class="out danger" type="submit">Delete</button></form>'''
        cards.append(f'''<article class="card"{anchor}{highlight}><div class="post">{sender_avatar}<div>{unread_badge}{'<span class="badge gold">SAVED</span>' if saved_view else ''}<span class="badge">{m["category"]}</span><h3>{m["subject"]}</h3><p class="muted small">From {html.escape(m["sender_name"])} to {html.escape(m["recipient_name"])} • {html.escape(m["origin"])} • {m["created_at"]}</p>{gift_context}{dates}{season}<p>{html.escape(m["body"]).replace(chr(10),'<br>')}</p><div class="actions">{open_action}{coordination_profile_action}{reply}{save}{delete}</div></div></div></article>''')
    cards_html=''.join(cards) or '<div class="empty"><h3>No private conversations in this section yet</h3><p class="muted">Private messages will appear here.</p></div>'
    filters='<div class="chips"><a class="chip" href="'+url_for('inbox')+'">All</a>'+''.join(f'<a class="chip" href="{url_for("inbox",category=c)}">{c}</a>' for c in JOURNAL_CATEGORIES)+f'<a class="chip" href="{url_for("inbox",category="Business",view="saved")}">Saved Business Journal</a></div>'
    status=f'<article class="card"><span class="badge">NEW PRIVATE MESSAGES</span><h2>{unread} New Message{"s" if unread!=1 else ""}</h2><p class="muted">Open a new message to mark it read. Conversations stay filed below in Journal Inbox.</p></article>'
    request_notice=(f'''<article class="card paid"><span class="badge heart">CONSCIOUS COMMUNITY REQUEST</span><h2>{len(community_requests)} Community Request{'s' if len(community_requests)!=1 else ''}</h2><p class="muted">Review the sender, note and requested purpose, then accept or decline.</p><a class="btn" href="{url_for('conscious_community')}">Review Community Requests</a></article>''' if community_requests else '')
    invite_parts=[]
    for x in experience_invites:
        business_note=f'<p><b>Suggested Seasons Within business:</b> {html.escape(x["business_name"])}</p>' if x['business_name'] else ''
        personal_note=f'<p>{html.escape(x["note"])}</p>' if x['note'] else ''
        actions=''
        if x['status']=='Pending':
            yes=url_for('experience_invitation_respond',invitation_id=x['id'],decision='yes'); no=url_for('experience_invitation_respond',invitation_id=x['id'],decision='no')
            actions=f'<div class="actions"><form method="post" action="{yes}"><button class="btn">YES</button></form><form method="post" action="{no}"><button class="out">NO</button></form></div>'
        elif x['status']=='Accepted':
            calendar_link=f'<a class="out" href="{url_for("experience_invitation_calendar",invitation_id=x["id"])}">Add to Calendar</a>'
            virtual_link=f'<a class="out" href="{html.escape(x["virtual_link"],quote=True)}" target="_blank" rel="noopener">Open Virtual Meeting</a>' if x['virtual_link'] else ''
            plan_link=f'<a class="btn" href="{url_for("experience_invitation_plan",invitation_id=x["id"])}">Plan Our Experience</a>'
            actions=f'<div class="actions">{plan_link}{calendar_link}{virtual_link}</div>'
        invite_parts.append(f'''<article class="card paid"><span class="badge heart">WILL YOU GO OUT WITH ME?</span><h2>{html.escape(x['sender_name'])} would like to go out with you.</h2><p><b>Will you go out with me?</b></p><p><b>Experience:</b> {html.escape(x['activity'])}</p><p><b>When:</b> {html.escape(x['proposed_date'])} at {html.escape(x['proposed_time'])}</p><p><b>Format:</b> {html.escape(x['experience_mode'])}</p>{business_note}{personal_note}<p><b>Status:</b> {html.escape(x['status'])}</p>{actions}</article>''')
    invite_cards=''.join(invite_parts)
    host_link_cards=[]
    if category in {'All','Business'}:
        for business in hosted_businesses:
            app_path=url_for('business_app',business_id=business['id'])
            host_link=(APP_BASE_URL or request.url_root.rstrip('/'))+app_path
            safe_link=html.escape(host_link,quote=True)
            business_logo=(f'''<img src="{business_media_src(business['logo_name'])}" alt="{html.escape(business['name'],quote=True)} logo" style="display:block;width:120px;height:120px;object-fit:contain;margin:0 0 12px">''' if business['logo_name'] else '')
            host_link_cards.append(f'''<article class="card paid">{business_logo}<span class="badge gold">YOUR BUSINESS HOST LINK</span><h2>{html.escape(business['name'])}</h2><p>Your hosted app is ready to share.</p><div class="actions"><a class="btn" href="{app_path}">Open My Business App</a></div><label><b>Business Host Link:</b></label><input class="input" type="text" value="{safe_link}" readonly data-business-host-link aria-label="Business Host Link for {html.escape(business['name'],quote=True)}"><div class="actions"><button class="out" type="button" data-copy-business-host-link>Copy Link</button><span class="muted small" data-copy-business-host-status aria-live="polite"></span></div></article>''')
    host_links_html=''.join(host_link_cards)
    retreat_request_cards=''
    if category in {'All','Business'}:
        retreat_cards=[]
        for r in retreat_host_requests:
            details=_safe_json(r['details_json'] if 'details_json' in r.keys() else '{}',{})
            added_details=''.join(f'<br><b>{label}:</b> {html.escape(str(details.get(key)))}' for key,label in (
                ('season_choice','Which Season Speaks to You'),('shared_experience','Who Will Share This Experience'),('story','Share Your Story'),('desired_feeling','Desired Feeling'),
                ('energy','Energy'),('setting','Setting'),('duration','Retreat Length'),('budget','Accommodation Budget'),
                ('phone','Phone Number'),('joining_group','Who Will Be Joining')) if details.get(key))
            save=(f'''<form method="post" action="{url_for('retreat_inbox_manage',request_id=r['id'],action='save')}" style="display:inline"><button class="out" type="submit">Save</button></form>''' if not saved_view else '')
            delete=f'''<form method="post" action="{url_for('retreat_inbox_manage',request_id=r['id'],action='delete')}" style="display:inline" onsubmit="return confirm('Remove this Retreat Interest from your inbox?')"><button class="out danger" type="submit">Delete</button></form>'''
            retreat_cards.append(f'''<article class="card paid">{'<span class="badge gold">SAVED</span>' if saved_view else ''}<span class="badge heart">RETREAT INVITATION / RETREAT INTEREST</span><h2>{html.escape(r['business_name'])}</h2><p><b>{html.escape(r['requester_name'] or 'Someone')}</b> added this business to their Wellness Team and is interested in having it participate in a Retreat.</p><p><b>Retreat Experience:</b> {html.escape(r['retreat_type'])}{added_details}<br><b>Retreat Start Date:</b> {html.escape(r['start_date'])}<br><b>Retreat End Date:</b> {html.escape(r['end_date'])}<br><b>Retreat Time:</b> {html.escape(r['start_time'])} – {html.escape(r['end_time'])}<br><b>Number of Guests:</b> {html.escape(r['guests'] or 'Not provided')}<br><b>City:</b> {html.escape(r['city'] or 'Not provided')}<br><b>State:</b> {html.escape(r['state'] or 'Michigan')}<br><b>Selected Wellness Business / Hosted App:</b> {html.escape(r['business_name'])}</p>{f'<p><b>Requester Email:</b> {html.escape(r["requester_email"])}</p>' if r['requester_email'] and r['requester_email'].strip().lower()!=RETREAT_BUILDER_COPY_EMAIL.lower() else ''}<p class="muted small">Interest status: {html.escape(r['status'])} • This is a Retreat interest/invitation, not a confirmed booking.</p><div class="actions">{save}{delete}</div></article>''')
        retreat_request_cards=''.join(retreat_cards)
    copy_link_script='''<script>(()=>{document.querySelectorAll('[data-copy-business-host-link]').forEach(button=>{button.addEventListener('click',async()=>{const card=button.closest('article'),input=card&&card.querySelector('[data-business-host-link]'),status=card&&card.querySelector('[data-copy-business-host-status]');if(!input)return;let copied=false;try{await navigator.clipboard.writeText(input.value);copied=true}catch(error){input.focus();input.select();copied=document.execCommand('copy')}if(status)status.textContent=copied?'Link copied.':'Select and copy the link above.';});});})();</script>''' if host_link_cards else ''
    return page('Journal Inbox',f'''<div class="hero"><span class="badge">PRIVATE MESSAGES</span><h1>Journal Inbox</h1><p class="muted">Incoming private conversations, requests and invitations are kept here.</p></div>{host_links_html}{retreat_request_cards}{request_notice}{invite_cards}{status}{filters}{cards_html}{copy_link_script}''','more')

@app.route('/inbox/read/<int:message_id>')
@login_required
def inbox_read(message_id):
    u=current_user(); conn=db(); m=conn.execute('SELECT * FROM messages WHERE id=? AND (sender_id=? OR recipient_id=?)',(message_id,u['id'],u['id'])).fetchone()
    if not m: conn.close(); abort(404)
    if m['recipient_id']==u['id'] and not m['read_at']:
        conn.execute('UPDATE messages SET read_at=? WHERE id=?',(now(),message_id)); conn.commit()
    conn.close()
    return redirect(url_for('inbox',category=m['category'],message_id=message_id)+f'#message-{message_id}')

@app.route('/inbox/<int:message_id>/delete',methods=['POST'])
@login_required
def inbox_delete(message_id):
    u=current_user(); conn=db()
    # Inbox removal is recipient-scoped and never deletes another member's account
    # or a public/community source record.
    row=conn.execute('SELECT id FROM messages WHERE id=? AND recipient_id=?',(message_id,u['id'])).fetchone()
    if not row: conn.close(); abort(404)
    conn.execute('UPDATE messages SET recipient_deleted=1 WHERE id=? AND recipient_id=?',(message_id,u['id']))
    conn.commit(); conn.close(); flash('Inbox item removed.','success')
    return redirect(url_for('inbox'))

@app.route('/inbox/<int:message_id>/save',methods=['POST'])
@login_required
def inbox_save(message_id):
    u=current_user(); conn=db()
    row=conn.execute("SELECT id FROM messages WHERE id=? AND recipient_id=? AND category='Business'",(message_id,u['id'])).fetchone()
    if not row: conn.close(); abort(404)
    conn.execute('UPDATE messages SET recipient_saved=1 WHERE id=? AND recipient_id=?',(message_id,u['id']))
    conn.commit(); conn.close(); flash('Business Journal message saved.','success')
