@app.route('/member/<int:user_id>/report',methods=['GET','POST'])
@login_required
def report_member(user_id):
    me=current_user(); conn=db(); target=conn.execute('SELECT id,name FROM users WHERE id=?',(user_id,)).fetchone(); conn.close()
    if not target or user_id==me['id']: abort(404)
    if request.method=='POST':
        reason=request.form.get('reason','').strip()[:120]; details=request.form.get('details','').strip()[:5000]
        if not reason or not details:
            flash('Choose a reason and provide report details.','error')
        else:
            conn=db(); cur=conn.execute('INSERT INTO member_reports(reporter_id,reported_id,reason,details,created_at) VALUES(?,?,?,?,?)',(me['id'],user_id,reason,details,now())); report_id=cur.lastrowid; conn.commit(); conn.close()
            body=f'''Private member safety report #{report_id}\n\nReporter account ID: {me['id']}\nReported member: {target['name']} (ID {user_id})\nReason: {reason}\n\nDetails:\n{details}\n\nThis report is private and was not shown to the reported member.'''
            delivered=_send_account_email('e.reed81@gmail.com',f'Member safety report #{report_id}',body)
            flash('Your private report was submitted to moderation.' if delivered else 'Your private report was saved for moderation; email delivery is currently unavailable.','success')
            return redirect(url_for('connections'))
    options=''.join(f'<option>{html.escape(x)}</option>' for x in ('Harassment or bullying','Threats or safety concern','Spam or scam','Inappropriate content','Impersonation','Other'))
    return page('Report Member',f'''<div class="hero"><span class="badge">PRIVATE SAFETY REPORT</span><h1>Report {html.escape(target['name'])}</h1><p class="muted">This report is private and will not be shown to the reported member.</p></div><form class="card" method="post"><label><b>Reason</b></label><select class="input" name="reason" required><option value="">Choose a reason</option>{options}</select><label><b>Details</b></label><textarea class="input" name="details" maxlength="5000" required></textarea><div class="actions"><button class="btn">Submit Private Report</button><a class="out" href="{url_for('member_profile',user_id=user_id)}">Cancel</a></div></form>''','more')

@app.route('/message/<int:recipient_id>', methods=['GET','POST'])
@login_required
def message_member(recipient_id):
    u=current_user(); conn=db(); r=conn.execute('SELECT * FROM users WHERE id=?',(recipient_id,)).fetchone(); conn.close()
    if not r or not _personal_profile_available(r): abort(404)
    if _member_blocked(u['id'],recipient_id):
        flash('This member interaction is unavailable.','info'); return redirect(url_for('connections'))
    origin=request.args.get('origin','Profile'); post_id=request.args.get('post_id',type=int); gift_id=request.args.get('gift_id',type=int); subject=request.args.get('subject','')
    post=None; gift_context=None; category='Journal Entry'
    if post_id:
        conn=db(); post=conn.execute('SELECT * FROM community_posts WHERE id=?',(post_id,)).fetchone(); conn.close()
        if post:
            category=post['category']; subject=post['title']
    if gift_id:
        conn=db(); gift_context=conn.execute('''SELECT g.id,t.label,t.emoji FROM member_virtual_gifts g JOIN virtual_gift_types t ON t.id=g.gift_type_id WHERE g.id=? AND g.recipient_id=? AND g.public_shared_at IS NOT NULL''',(gift_id,recipient_id)).fetchone(); conn.close()
        if not gift_context: abort(404)
        subject=subject or f'''Public Gift — {gift_context['label']}'''
    show_schedule=origin in {'Retreat','Business','Business Inquiry','Retreat Inquiry'}
    if request.method=='POST':
        body=request.form.get('body','').strip(); origin=request.form.get('origin','Profile'); source_post_id=request.form.get('source_post_id',type=int); gift_id=request.form.get('gift_id',type=int)
        category=post['category'] if post else ('Conscious Coordination' if origin=='Conscious Coordination' else 'Journal Entry')
        subject=request.form.get('subject','').strip()
        preferred_start=request.form.get('preferred_start','').strip(); preferred_end=request.form.get('preferred_end','').strip(); season=request.form.get('season','').strip()
        preferred_dates=f'{preferred_start} to {preferred_end}' if preferred_start and preferred_end else (preferred_start or preferred_end)
        if gift_id:
            conn=db(); valid_gift=conn.execute('SELECT id FROM member_virtual_gifts WHERE id=? AND recipient_id=? AND public_shared_at IS NOT NULL',(gift_id,recipient_id)).fetchone(); conn.close()
            if not valid_gift: abort(404)
        if body and subject:
            conn=db(); cur=conn.execute('''INSERT INTO messages(sender_id,recipient_id,origin,subject,body,category,source_post_id,gift_id,preferred_dates,season,created_at,read_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,NULL)''',(u['id'],recipient_id,origin,subject,body,category,source_post_id,gift_id,preferred_dates,season,now())); message_id=cur.lastrowid; conn.commit(); conn.close()
            link=url_for('inbox_read',message_id=message_id)
            notify(recipient_id,'New Private Message',f'{u["name"]} sent you “{subject}”. Open your Journal Inbox to read it.',link)
            _clear_page_drafts(u['id'],request.path)
            flash(f'Message sent privately to {r["name"]}\'s Journal Inbox.','success')
            return redirect(url_for('inbox',message_id=message_id)+f'#message-{message_id}')
        flash('Please give your message a title and write your message.','info')
    schedule=''
    if show_schedule:
        schedule='''<div class="grid"><div><label><b>Choose Your Preferred Start Date</b></label><input class="input" type="date" name="preferred_start"></div><div><label><b>Choose Your Preferred End Date</b></label><input class="input" type="date" name="preferred_end"></div></div><label><b>Season</b></label><select class="input" name="season"><option value="">Choose a season</option><option>Spring Retreat</option><option>Summer Retreat</option><option>Autumn Retreat</option><option>Winter Retreat</option></select>'''
    locked_note=(f'<p><b>Public Journal post:</b> {html.escape(post["title"])} • {html.escape(post["category"])}</p>' if post else (f'''<p><b>Public gift:</b> {gift_context['emoji']} {html.escape(gift_context['label'])}</p>''' if gift_context else '<p class="muted">This private message will be filed automatically under <b>Journal Entry</b> in the recipient\'s Journal Inbox.</p>'))
    if origin=='Conscious Coordination':
        gift_action=f'''<a class="out" href="{url_for('member_gallery',user_id=recipient_id)}#send-gift">🎁 Send Gift</a>'''
        if has_full_access(u):
            additional_actions=f'''<a class="out" href="{url_for('video',user_id=recipient_id)}">🎥 Private Video</a><a class="out" href="{url_for('experience_invitation',user_id=recipient_id)}">💜 Will You Go Out With Me?</a>'''
        else:
            additional_actions=f'''<div class="locked"><p><b>🔒 Upgrade Membership</b></p><p class="muted">Upgrade to access Additional Private Interactions, including Private Video and Will You Go Out With Me.</p><a class="btn" href="{url_for('membership')}">Upgrade Membership</a></div>'''
        private_actions=f'''<article class="card"><h3>Additional Private Interactions</h3><div class="actions">{gift_action}{additional_actions}</div></article>'''
    else:
        private_actions=''
    return page('Private Message',f'''<div class="hero"><span class="badge">PRIVATE MESSAGE</span><h1>Send Private Journal Entry</h1><p class="muted">This entry will be delivered privately to {html.escape(r['name'])}'s Journal Inbox. It will not appear as a public comment.</p></div><form class="card" method="post"><input type="hidden" name="origin" value="{html.escape(origin,quote=True)}"><input type="hidden" name="source_post_id" value="{post_id or ''}"><input type="hidden" name="gift_id" value="{gift_id or ''}"><label><b>Give your message a title</b></label><input class="input" name="subject" value="{html.escape(subject or '',quote=True)}" placeholder="Enter your message title" required>{locked_note}{schedule}<label><b>Message</b></label><textarea class="input" name="body" placeholder="Write your private message..." required></textarea><button class="btn">Send Private Entry</button></form>{private_actions}''','more')

