@app.route('/conscious-community/request/<int:user_id>',methods=['GET','POST'])
@login_required
def conscious_community_request(user_id):
    u=current_user()
    if user_id==u['id']: abort(400)
    conn=db(); other=conn.execute('SELECT id,name FROM users WHERE id=?',(user_id,)).fetchone()
    connected=conn.execute('SELECT 1 FROM conscious_community_members WHERE user_id=? AND community_member_user_id=?',(u['id'],user_id)).fetchone()
    pending=conn.execute("SELECT 1 FROM conscious_community_requests WHERE ((sender_user_id=? AND receiver_user_id=?) OR (sender_user_id=? AND receiver_user_id=?)) AND status='Pending'",(u['id'],user_id,user_id,u['id'])).fetchone()
    if not other: conn.close(); abort(404)
    if connected or pending:
        conn.close(); flash('This community connection or request already exists.','info'); return redirect(url_for('connections'))
    if request.method=='POST':
        chosen=[x for x in request.form.getlist('purposes') if x in CONSCIOUS_COMMUNITY_PURPOSES]
        custom=request.form.get('other_purpose','').strip()
        purposes=[x for x in chosen if x!='Other']+([custom] if 'Other' in chosen and custom else [])
        note=request.form.get('note','').strip()[:500]
        cur=conn.execute('INSERT INTO conscious_community_requests(sender_user_id,receiver_user_id,note,purposes,status,created_at) VALUES(?,?,?,?,?,?)',(u['id'],user_id,note,', '.join(purposes) or 'Like-Minded Community','Pending',now()))
        request_id=cur.lastrowid
        conn.execute('INSERT INTO notifications(user_id,title,body,created_at,link) VALUES(?,?,?,?,?)',(user_id,'Conscious Community Request',f'{u["name"]} sent a request to connect in Conscious Community.',now(),url_for('conscious_community')+f'#request-{request_id}'))
        conn.commit(); conn.close(); flash('Conscious Community request sent.','success'); return redirect(url_for('connections'))
    conn.close(); choices=''.join(f'<label class="fact"><input type="checkbox" name="purposes" value="{x}"> {x}</label>' for x in CONSCIOUS_COMMUNITY_PURPOSES)
    return page('Request Conscious Community Connection',f'''<div class="hero"><span class="badge heart">CONSCIOUS COMMUNITY REQUEST</span><h1>Request to Add {html.escape(other['name'])}</h1></div><form class="card" method="post"><label><b>Short note (optional)</b><textarea class="input" name="note" maxlength="500" placeholder="I enjoyed our conversation and think we may align well..."></textarea></label><h3>Why would you like this member in your Conscious Community?</h3><div class="checkboxes">{choices}</div><label><b>If Other, add a short purpose</b><input class="input" name="other_purpose" maxlength="120"></label><button class="btn">Send Community Request</button></form>''','coordination')

@app.route('/conscious-community/request/<int:request_id>/<decision>',methods=['POST'])
@login_required
def conscious_community_respond(request_id,decision):
    if decision not in {'accept','decline'}: abort(404)
    u=current_user(); conn=db(); row=conn.execute("SELECT * FROM conscious_community_requests WHERE id=? AND receiver_user_id=? AND status='Pending'",(request_id,u['id'])).fetchone()
    if not row: conn.close(); abort(404)
    status='Accepted' if decision=='accept' else 'Declined'
    conn.execute('UPDATE conscious_community_requests SET status=?,responded_at=? WHERE id=?',(status,now(),request_id))
    if decision=='accept':
        conn.execute('INSERT INTO conscious_community_members(user_id,community_member_user_id,connection_purposes,note,created_at) VALUES(?,?,?,?,?) ON CONFLICT DO NOTHING',(u['id'],row['sender_user_id'],row['purposes'],row['note'],now()))
        conn.execute('INSERT INTO conscious_community_members(user_id,community_member_user_id,connection_purposes,note,created_at) VALUES(?,?,?,?,?) ON CONFLICT DO NOTHING',(row['sender_user_id'],u['id'],row['purposes'],row['note'],now()))
    conn.execute('INSERT INTO notifications(user_id,title,body,created_at,link) VALUES(?,?,?,?,?)',(row['sender_user_id'],f'Conscious Community Request {status}',f'{u["name"]} {status.lower()} your Conscious Community request.',now(),url_for('conscious_community')))
    conn.commit(); conn.close(); flash(f'Community request {status.lower()}.','success'); return redirect(url_for('conscious_community'))

@app.route('/conscious-community/remove/<int:user_id>',methods=['POST'])
@login_required
def conscious_community_remove(user_id):
    u=current_user(); conn=db(); conn.execute('DELETE FROM conscious_community_members WHERE user_id=? AND community_member_user_id=?',(u['id'],user_id)); conn.commit(); conn.close(); flash('Member removed from your Conscious Community only.','success'); return redirect(url_for('conscious_community'))

@app.route('/conscious-community/member/<int:user_id>/edit',methods=['GET','POST'])
@login_required
def conscious_community_member_edit(user_id):
    u=current_user(); conn=db()
    row=conn.execute('''SELECT c.*,m.name FROM conscious_community_members c JOIN users m ON m.id=c.community_member_user_id
                        WHERE c.user_id=? AND c.community_member_user_id=?''',(u['id'],user_id)).fetchone()
    if not row: conn.close(); abort(404)
    if request.method=='POST':
        purposes=request.form.get('connection_purposes','').strip()[:300]
        note=request.form.get('note','').strip()[:500]
        conn.execute('UPDATE conscious_community_members SET connection_purposes=?,note=? WHERE user_id=? AND community_member_user_id=?',(purposes,note,u['id'],user_id))
        conn.commit(); conn.close(); flash('Your community entry was updated.','success'); return redirect(url_for('conscious_community'))
    conn.close()
    return page('Edit My Community Entry',f'''<div class="hero"><span class="badge heart">MY CONSCIOUS COMMUNITY</span><h1>Edit My Entry for {html.escape(row['name'])}</h1><p class="muted">These changes apply only to the entry in your own Conscious Community.</p></div><form class="card" method="post"><label><b>Community Connection</b><input class="input" name="connection_purposes" maxlength="300" value="{html.escape(row['connection_purposes'] or '',quote=True)}"></label><label><b>My Note</b><textarea class="input" name="note" maxlength="500">{html.escape(row['note'] or '')}</textarea></label><div class="actions"><button class="btn">Save My Entry</button><a class="out" href="{url_for('conscious_community')}">Cancel</a></div></form>''','coordination')

def _can_create_coordination_post(user):
    if not user:
        return False
    return bool((user['name'] or '').strip().lower()=='galaxy eve' or user['is_admin'])


@app.route('/conscious-coordination')
@login_required


def connections():
    u=current_user()
    if not u:
        session.pop('user_id',None)
        return redirect(url_for('login',next=request.path))
    own_row=safe_connection_profile(u['id'])
    participating=conscious_coordination_ready(u,own_row)
    own=dict(own_row) if own_row else {}
    business=None
    try:
        conn=db()
        try:
            business=conn.execute('SELECT * FROM businesses WHERE owner_id=? ORDER BY active DESC,updated_at DESC,id DESC LIMIT 1',(u['id'],)).fetchone()
        finally:
            conn.close()
    except Exception:
        app.logger.exception('Could not load member business before Conscious Coordination join gate')

    if not participating:
        business_note=''
        if business:
            business_note=f'''<article class="card"><span class="badge gold">BUSINESS CONSCIOUS COORDINATION</span><h2>{html.escape(business['name'])}</h2><p class="muted">Your business tools remain available while you complete your profile.</p><div class="actions"><a class="out" href="{url_for('business_dashboard')}">Open My Business Dashboard</a></div></article>'''
        content=f'''<div class="hero"><span class="badge heart">JOIN THE COMMUNITY</span><h1>Join the Community</h1><p class="muted">Complete your one member profile to become part of The Seasons Within Community.</p><div class="actions"><a class="btn" href="{url_for('edit_profile')}">Join the Community</a><a class="out" href="{url_for('earn_while_you_grow')}">Earn While You Grow</a><a class="out" href="{url_for('profile')}">View My Journal</a></div></div>
        <article class="card"><span class="badge heart">COMPLETE YOUR PROFILE</span><h2>Complete Your Profile</h2><p class="muted">Your required birth information and connection answers are completed together in this setup. Once saved, Community access opens automatically.</p><p class="muted">Love / Relationship • Friendship • Business / Collaboration • Retreat / Activity • Shared Wellness</p></article>{business_note}'''
        return page('Conscious Coordination',content,'more')

    # Only load member-directory/feed data after the member has completed setup.
    try:
        conn=db()
        host=conn.execute("SELECT * FROM users WHERE lower(name)=lower('Galaxy Eve') ORDER BY is_admin DESC,id LIMIT 1").fetchone()
        members=conn.execute('''SELECT cp.*,u.name,u.city,u.birth_region,u.conscious_paid,u.age,u.dating_age_min,u.dating_age_max FROM connection_profiles cp JOIN users u ON u.id=cp.user_id WHERE cp.opted_in=1 AND cp.user_id<>? AND coalesce(u.dob,'')<>'' AND coalesce(u.birth_city,'')<>'' AND coalesce(u.birth_country,'')<>'' AND (coalesce(u.birth_time,'')<>'' OR coalesce(u.birth_time_unknown,0)=1) ORDER BY u.name''',(u['id'],)).fetchall()
        posts=conn.execute('''SELECT p.*,u.name author_name FROM coordination_posts p JOIN users u ON u.id=p.author_id ORDER BY p.id DESC LIMIT 40''').fetchall()
        conn.close()
    except Exception:
        app.logger.exception('Could not load Conscious Coordination directory/feed')
        host=None; members=[]; posts=[]

    ensure_free_coordination_notifications(u['id'])

    def splitv(v):
        return {x.strip() for x in (v or '').split(',') if x.strip()}

    default_types={'Love / Relationship','Friendship','Business / Collaboration','Retreat / Activity','Shared Wellness'}
    own_types=splitv(own.get('coordination_types','')) or default_types
    chosen=request.args.get('type','').strip()
    if chosen and chosen in own_types:
        members=[m for m in members if chosen in splitv(m['coordination_types'])]
    else:
        members=[m for m in members if splitv(m['coordination_types']) & own_types]

    # Dating ages are reciprocal: both members must fall inside the other's saved range.
    if 'Love / Relationship' in own_types and u['age']:
        own_min=u['dating_age_min'] or 18; own_max=u['dating_age_max'] or 120
        members=[m for m in members if m['age'] and own_min<=m['age']<=own_max and (m['dating_age_min'] or 18)<=u['age']<=(m['dating_age_max'] or 120)]

    pref_state=(own.get('preferred_state') or '').strip()
    pref_city=(own.get('preferred_city') or '').strip()
    distance=(own.get('distance_preference') or '').strip()
    if distance in {'10 miles','25 miles'} and pref_city:
        members=[m for m in members if (m['city'] or '').strip().lower()==pref_city.lower()]
    elif distance in {'50 miles','100 miles','Statewide'} and pref_state:
        members=[m for m in members if (m['birth_region'] or '').strip().lower()==pref_state.lower()]

    def preview(m):
        vals=[]
        for k in ('coordination_types','lifestyle','values_text','communication','affection'):
            aa=splitv(own.get(k,'')); bb=splitv(m[k])
            if aa and bb: vals.append(round(100*len(aa&bb)/max(1,len(aa|bb))))
        return round(sum(vals)/len(vals)) if vals else None

    cards=[]
    for m in members:
        score=preview(m)
        conn=db(); media=conn.execute("SELECT * FROM coordination_media WHERE user_id=? AND media_role='profile' AND media_type='image' ORDER BY id DESC LIMIT 1",(m['user_id'],)).fetchone(); connected=conn.execute('SELECT 1 FROM conscious_community_members WHERE user_id=? AND community_member_user_id=?',(u['id'],m['user_id'])).fetchone(); pending=conn.execute("SELECT sender_user_id,receiver_user_id FROM conscious_community_requests WHERE ((sender_user_id=? AND receiver_user_id=?) OR (sender_user_id=? AND receiver_user_id=?)) AND status='Pending' ORDER BY id DESC LIMIT 1",(u['id'],m['user_id'],m['user_id'],u['id'])).fetchone(); conn.close()
        photo=(f'<div class="discover-member-photo"><img src="{url_for("community_media",filename=media["file_name"])}" style="{_crop_css(media["crop_data"])}" alt="{html.escape(m["name"],quote=True)}"></div>' if media else f'<div class="discover-member-photo discover-member-photo-fallback" role="img" aria-label="{html.escape(m["name"],quote=True)} profile photo fallback">{initials(m["name"])}</div>')
        location=' • '.join(x for x in [(m['city'] or '').strip(),(m['birth_region'] or '').strip()] if x) or 'Location not shared'
        score_html=f'<div class="fact"><small>Basic Compatibility Preview</small><b>{score}%</b></div>' if score is not None else ''
        facts_html=_coordination_profile_facts_html(m)
        if connected: community_action='<span class="out">✓ In My Conscious Community</span>'
        elif pending and pending['sender_user_id']==u['id']: community_action='<span class="out">Request Sent</span>'
        elif pending: community_action=f'<a class="out" href="{url_for("conscious_community")}">Community Request Received</a>'
        else: community_action=f'<a class="out" href="{url_for("conscious_community_request",user_id=m["user_id"])}">Request to Add to Community</a>'
        cards.append(f'''<article class="card discover-swipe-card {'paid' if m['conscious_paid'] else ''}" data-member-card><span class="badge {'gold' if m['conscious_paid'] else ''}">{'★ FULL MEMBER' if m['conscious_paid'] else 'MEMBER'}</span><h3>{html.escape(m['name'])}</h3><p class="muted">{html.escape(location)} • {html.escape(m['coordination_types'] or 'Conscious Coordination')}</p>{photo}{score_html}{facts_html}<div class="actions"><form method="post" action="{url_for('coordination_like',user_id=m['user_id'])}" style="display:inline"><button class="out" type="submit">♡ Interested</button></form><a class="out" href="{url_for('message_member',recipient_id=m['user_id'],origin='Conscious Coordination')}">💬 Message</a><a class="out" href="{url_for('member_gallery',user_id=m['user_id'])}#send-gift">🎁 Send Gift</a>{community_action}<a class="btn" href="{url_for('connection_profile',user_id=m['user_id'])}">Conscious Coordination Profile</a></div></article>''')
    member_cards=''.join(cards) or '<div class="empty"><h3>No matching member profiles yet</h3><p class="muted">Compatible connections will appear as participating members match your selected intentions.</p><a class="out" href="'+url_for('connections')+'">Return to Discover Members</a></div>'
    filters='<a class="chip" href="'+url_for('connections')+'">All</a>'+''.join(f'<a class="chip" href="{url_for("connections",type=x)}">{x}</a>' for x in sorted(own_types))

    is_host=_can_create_coordination_post(u)
    host_form=''
    if is_host:
        poster_label='GALAXY EVE • CONSCIOUS COORDINATOR' if (u['name'] or '').strip().lower()=='galaxy eve' else 'THE SEASONS WITHIN • ADMIN'
        host_form=f'''<form class="card paid" method="post" enctype="multipart/form-data" action="{url_for('coordination_post_create')}"><span class="badge gold">{poster_label}</span><h2>Post to Conscious Coordination</h2><input class="input" name="title" placeholder="Post title" required><textarea class="input" name="body" placeholder="News, prompt, experience, event or Retreat invitation..." required></textarea><label><b>Optional Link</b></label><input class="input" type="url" name="link_url" placeholder="https://..."><label><b>Photo or Video</b></label><input class="input" type="file" name="media" accept="image/*,video/*"><button class="btn">Post as Conscious Coordinator</button></form>'''
    feed_cards=[]
    for p in posts:
        media=''
        if p['media_name']:
            src=url_for('community_media',filename=p['media_name'])
            media=f'<video controls playsinline style="width:100%;max-height:520px;border-radius:16px" src="{src}"></video>' if p['media_type']=='video' else f'<img src="{src}" style="width:100%;max-height:520px;object-fit:cover;border-radius:16px" alt="Conscious Coordination post media">'
        link=f'<p><a class="out" href="{html.escape(p["link_url"],quote=True)}" target="_blank" rel="noopener">Open Shared Link</a></p>' if p['link_url'] else ''
        conn=db(); comments=conn.execute('''SELECT c.*,usr.name,
            COALESCE(SUM(CASE WHEN v.vote=1 THEN 1 ELSE 0 END),0) likes,
            COALESCE(SUM(CASE WHEN v.vote=-1 THEN 1 ELSE 0 END),0) dislikes
            FROM coordination_post_comments c JOIN users usr ON usr.id=c.user_id
            LEFT JOIN coordination_comment_votes v ON v.comment_id=c.id
            WHERE c.post_id=? GROUP BY c.id,usr.name ORDER BY c.created_at,c.id''',(p['id'],)).fetchall(); conn.close()
        children={}
        for c in comments: children.setdefault(c['parent_comment_id'],[]).append(c)
        def comment_card(c,depth=0):
            replies=''.join(comment_card(x,depth+1) for x in children.get(c['id'],[])) if depth<3 else ''
            vote_buttons=''.join(f'''<form method="post" action="{url_for('coordination_comment_vote',comment_id=c['id'],vote=v)}" style="display:inline"><button class="out" type="submit">{label} {count}</button></form>''' for v,label,count in ((1,'👍 Like',c['likes']),(-1,'👎 Dislike',c['dislikes'])))
            reply=f'''<details><summary class="out">Reply</summary><form method="post" action="{url_for('coordination_post_comment',post_id=p['id'])}"><input type="hidden" name="parent_comment_id" value="{c['id']}"><textarea class="input" name="body" placeholder="Write a public reply..." required></textarea><button class="out">Post Reply</button></form></details>'''
            return f'''<div class="fact" style="margin-left:{min(depth,2)*18}px"><b>{html.escape(c['name'])}</b><p>{html.escape(c['body']).replace(chr(10),'<br>')}</p><div class="actions">{vote_buttons}{reply}</div>{replies}</div>'''
        discussion=''.join(comment_card(c) for c in children.get(None,[]))
        comment=f'''<div class="topspace"><h3>Join the Conversation</h3>{discussion}<form method="post" action="{url_for('coordination_post_comment',post_id=p['id'])}"><textarea class="input" name="body" placeholder="Write a public comment..." required></textarea><button class="out">Post Comment</button></form></div>'''
        author_label='GALAXY EVE • CONSCIOUS COORDINATOR' if (p['author_name'] or '').strip().lower()=='galaxy eve' else 'THE SEASONS WITHIN • ADMIN'
        management=(f'''<div class="actions"><a class="out" href="{url_for('coordination_post_edit',post_id=p['id'])}">Edit</a><form method="post" action="{url_for('coordination_post_delete',post_id=p['id'])}" onsubmit="return confirm('Delete this Conscious Coordination post?')"><button class="out danger" type="submit">Delete</button></form></div>''' if is_host else '')
        feed_cards.append(f'''<article class="card" id="coordination-post-{p['id']}"><span class="badge heart">{author_label}</span><h2>{html.escape(p['title'])}</h2><p class="muted small">{p['created_at']}</p><p>{html.escape(p['body']).replace(chr(10),'<br>')}</p>{media}{link}{management}{comment}</article>''')
    content=f'''<div class="hero"><span class="badge heart">♡ CONSCIOUS COORDINATION</span><h1>Conscious Coordination</h1><div class="actions"><a class="btn" href="{url_for('birth_chart',user_id=u['id'])}">♡ My Seasons Within</a><a class="out" href="{url_for('conscious_community')}">My Conscious Community</a><a class="out" href="{url_for('earn_while_you_grow')}">Earn While You Grow</a></div></div>
    <div class="topspace"><h2>Discover Members</h2><p class="muted small">Swipe horizontally to browse. Swiping browses only; use Interested when you want to express interest.</p></div><div class="chips">{filters}</div>
    <section class="discover-swipe" data-discover-swipe aria-label="Discover Members"><div class="discover-swipe-deck">{member_cards}</div>{f'<div class="discover-swipe-controls"><button class="out" type="button" data-swipe-prev aria-label="Previous member">Previous</button><span class="muted small" data-swipe-status aria-live="polite"></span><button class="out" type="button" data-swipe-next aria-label="Next member">Next</button></div>' if cards else ''}</section>
    {host_form}
    {''.join(feed_cards)}
    <style>.discover-swipe{{max-width:760px;margin:0 auto}}.discover-swipe-deck{{touch-action:pan-y}}.discover-swipe-card{{display:none;margin-top:18px}}.discover-swipe-card.is-active{{display:block}}.discover-member-photo{{width:100%;aspect-ratio:4/5;max-height:680px;margin:16px 0;border-radius:18px;overflow:hidden;background:linear-gradient(135deg,#d4b9e7,#f0c2cb)}}.discover-member-photo img{{display:block;width:100%;height:100%;object-fit:cover}}.discover-member-photo-fallback{{display:grid;place-items:center;color:#fff;font-size:clamp(52px,14vw,96px);font-weight:900}}.discover-swipe-controls{{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:12px}}.coordination-quick-facts{{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}}.coordination-quick-facts .chip{{font-size:.86rem}}@media(max-width:640px){{.discover-member-photo{{width:100%;max-height:none;border-radius:16px}}.discover-swipe-card .actions{{gap:7px}}.discover-swipe-card .actions .btn,.discover-swipe-card .actions .out{{font-size:.82rem;padding:9px 11px}}}}</style>
    <script>(()=>{{const root=document.querySelector('[data-discover-swipe]');if(!root)return;const cards=[...root.querySelectorAll('[data-member-card]')];if(!cards.length)return;let i=0,startX=0,startY=0,end=null;const deck=root.querySelector('.discover-swipe-deck'),status=root.querySelector('[data-swipe-status]');function show(next){{i=Math.max(0,Math.min(cards.length,next));cards.forEach((card,n)=>card.classList.toggle('is-active',n===i));if(i===cards.length){{if(!end){{end=document.createElement('div');end.className='empty';end.innerHTML='<h3>You’ve reached the end of members in this category.</h3><div class="actions"><button class="out" type="button" data-restart>Restart</button><a class="out" href="{url_for('connections')}">Change filter</a></div>';deck.appendChild(end);end.querySelector('[data-restart]').onclick=()=>show(0);}}end.hidden=false;}}else if(end)end.hidden=true;if(status)status.textContent=i<cards.length?`${{i+1}} of ${{cards.length}}`:'End of members';}}root.querySelector('[data-swipe-prev]').onclick=()=>show(Math.max(0,i-1));root.querySelector('[data-swipe-next]').onclick=()=>show(i+1);root.addEventListener('touchstart',e=>{{startX=e.changedTouches[0].clientX;startY=e.changedTouches[0].clientY}},{{passive:true}});root.addEventListener('touchend',e=>{{const dx=e.changedTouches[0].clientX-startX,dy=e.changedTouches[0].clientY-startY;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.25)show(dx<0?i+1:Math.max(0,i-1))}},{{passive:true}});show(0);}})();</script>'''
    return page('Conscious Coordination',content,'coordination')


@app.route('/conscious-coordination/host-post', methods=['POST'])
@login_required
def coordination_post_create():
    u=current_user()
    if not _can_create_coordination_post(u):
        abort(403)
    title=request.form.get('title','').strip(); body=request.form.get('body','').strip(); link_url=request.form.get('link_url','').strip()
    media_name,media_type=save_community_media(request.files.get('media'),u['id'])
    if title and body:
        conn=db(); conn.execute('INSERT INTO coordination_posts(author_id,title,body,link_url,media_name,media_type,created_at) VALUES(?,?,?,?,?,?,?)',(u['id'],title,body,link_url,media_name,media_type,now())); conn.commit(); conn.close()
        flash('Conscious Coordination post published.','success')
    return redirect(url_for('connections'))


@app.route('/conscious-coordination/post/<int:post_id>/edit',methods=['GET','POST'])
@login_required
def coordination_post_edit(post_id):
    u=current_user()
    if not _can_create_coordination_post(u): abort(403)
    conn=db(); post=conn.execute('SELECT * FROM coordination_posts WHERE id=?',(post_id,)).fetchone()
    if not post: conn.close(); abort(404)
    if request.method=='POST':
        title=request.form.get('title','').strip(); body=request.form.get('body','').strip(); link_url=request.form.get('link_url','').strip()
        if not title or not body:
            conn.close(); flash('A post title and message are required.','info'); return redirect(url_for('coordination_post_edit',post_id=post_id))
        media_name,media_type=post['media_name'],post['media_type']; upload=request.files.get('media'); old_media=''
        if upload and upload.filename:
            replacement_name,replacement_type=save_community_media(upload,u['id'])
            if replacement_name: old_media=media_name or ''; media_name,media_type=replacement_name,replacement_type
        conn.execute('UPDATE coordination_posts SET title=?,body=?,link_url=?,media_name=?,media_type=? WHERE id=?',(title,body,link_url,media_name,media_type,post_id)); conn.commit(); conn.close()
        if old_media and old_media!=media_name:
            try: (UPLOAD_DIR/old_media).unlink(missing_ok=True)
            except Exception: pass
        flash('Conscious Coordination post updated.','success'); return redirect(url_for('connections')+f'#coordination-post-{post_id}')
    conn.close()
    media_note=(f'<p class="muted small">The current photo/video remains unless you select a replacement.</p>' if post['media_name'] else '')
    return page('Edit Conscious Coordination Post',f'''<div class="hero"><span class="badge heart">CONSCIOUS COORDINATION</span><h1>Edit Post</h1></div><form class="card" method="post" enctype="multipart/form-data"><label><b>Post title</b><input class="input" name="title" value="{html.escape(post['title'],quote=True)}" required></label><label><b>Post/message</b><textarea class="input" name="body" required>{html.escape(post['body'])}</textarea></label><label><b>Optional Link</b><input class="input" type="url" name="link_url" value="{html.escape(post['link_url'] or '',quote=True)}"></label><label><b>Replace Photo or Video</b><input class="input" type="file" name="media" accept="image/*,video/*"></label>{media_note}<div class="actions"><button class="btn">Save Changes</button><a class="out" href="{url_for('connections')}#coordination-post-{post_id}">Cancel</a></div></form>''','coordination')


