ZODIAC_WHEEL_SIGNS = [
    ('♈','Aries'),('♉','Taurus'),('♊','Gemini'),('♋','Cancer'),
    ('♌','Leo'),('♍','Virgo'),('♎','Libra'),('♏','Scorpio'),
    ('♐','Sagittarius'),('♑','Capricorn'),('♒','Aquarius'),('♓','Pisces')
]
PLANET_GLYPHS = {'Sun':'☉','Moon':'☽','Mercury':'☿','Venus':'♀','Mars':'♂','Jupiter':'♃','Saturn':'♄','Uranus':'♅','Neptune':'♆','Pluto':'♇','Rising':'ASC'}
NATAL_WHEEL_PLANETS=('Sun','Moon','Mercury','Venus','Mars','Jupiter','Saturn','Uranus','Neptune','Pluto')
PLANETARY_COORDINATION_WHEEL_PLANETS=('Sun','Moon','Mercury','Venus','Mars','Jupiter','Saturn')
ZODIAC_SIGN_INDEX={name:index for index,(_,name) in enumerate(ZODIAC_WHEEL_SIGNS)}

def _planetary_coordination_longitude(placement):
    """Return the true longitude that agrees with the visible sign and degree."""
    placement=placement or {}; sign=str(placement.get('sign') or '')
    try: stored=float(placement.get('longitude'))%360.0
    except (TypeError,ValueError): stored=None
    try: within=float(placement.get('degree'))%30.0
    except (TypeError,ValueError): within=None
    sign_index=ZODIAC_SIGN_INDEX.get(sign)
    if stored is not None and (sign_index is None or int(stored//30)==sign_index):
        return stored
    if sign_index is not None and within is not None:
        return sign_index*30.0+within
    return stored

def _zodiac_wheel_html(chart, member_name='Member'):
    """Render one permanent natal chart from factual stored birth longitudes."""
    planets=(chart or {}).get('planets') or {}
    required={p:planets.get(p) for p in NATAL_WHEEL_PLANETS if planets.get(p)}
    if not (chart or {}).get('ready') or not required:
        return '<div class="empty"><h3>Natal wheel unavailable</h3><p class="muted">Complete birth information is needed for the calculated natal wheel.</p></div>'
    cx=240; cy=240; outer=198; inner=150; sign_r=175
    rising=(chart or {}).get('rising') or (chart or {}).get('ascendant') or {}
    try: asc_longitude=float(rising.get('longitude'))%360.0 if rising.get('longitude') is not None else None
    except (TypeError,ValueError): asc_longitude=None
    def point(radius,longitude):
        # With a reliable birth time, rotate the entire factual chart so the
        # Ascendant/first-house cusp is the left horizon (the start of house 1).
        # Without a reliable Ascendant, retain the fixed zodiac orientation and
        # do not invent houses. Signs, planets, cusps and ASC share this transform.
        value=float(longitude)%360.0
        angle=(180.0-(value-asc_longitude)) if asc_longitude is not None else -value
        angle=math.radians(angle)
        return cx+radius*math.cos(angle),cy+radius*math.sin(angle)
    orientation=('ascendant-house-one' if asc_longitude is not None else 'fixed-zodiac-no-houses')
    asc_data=(f'{asc_longitude:.4f}' if asc_longitude is not None else '')
    svg=[f'<svg viewBox="0 0 480 480" role="img" aria-label="{html.escape(member_name,quote=True)} accurate natal astrology wheel" data-chart-kind="natal" data-wheel-orientation="{orientation}" data-house-one-longitude="{asc_data}" style="width:100%;max-width:520px;height:auto;display:block;margin:0 auto">']
    svg.append(f'<circle cx="{cx}" cy="{cy}" r="{outer}" fill="none" stroke="currentColor" stroke-width="2.2" opacity=".62"/>')
    svg.append(f'<circle cx="{cx}" cy="{cy}" r="{inner}" fill="none" stroke="currentColor" stroke-width="1.2" opacity=".22"/>')
    svg.append(f'<circle cx="{cx}" cy="{cy}" r="76" fill="none" stroke="currentColor" stroke-width="1" opacity=".12"/>')
    for i,(glyph,name) in enumerate(ZODIAC_WHEEL_SIGNS):
        sector_start=i*30.0
        x1,y1=point(inner,sector_start); x2,y2=point(outer,sector_start); sx,sy=point(sign_r,sector_start+15.0)
        svg.append(f'<line x1="{x1:.1f}" y1="{y1:.1f}" x2="{x2:.1f}" y2="{y2:.1f}" stroke="currentColor" stroke-width="1" opacity=".30"/>')
        svg.append(f'<text x="{sx:.1f}" y="{sy:.1f}" text-anchor="middle" dominant-baseline="middle" font-size="24" aria-label="{html.escape(name,quote=True)}">{glyph}</text>')
    for degree in range(0,360,5):
        tick_inner=outer-(8 if degree%30==0 else 4); x1,y1=point(tick_inner,degree); x2,y2=point(outer,degree)
        svg.append(f'<line x1="{x1:.1f}" y1="{y1:.1f}" x2="{x2:.1f}" y2="{y2:.1f}" stroke="currentColor" stroke-width="{1.2 if degree%30==0 else .55}" opacity=".24"/>')
    # Reliable house cusps come directly from the birth calculation. Unknown or
    # unreliable birth time produces no invented houses or Ascendant.
    houses=(chart or {}).get('houses') or []
    if len(houses)>=12:
        for house_index,cusp in enumerate(houses[:12],1):
            try: longitude=float(cusp)%360.0
            except (TypeError,ValueError): continue
            x1,y1=point(76,longitude); x2,y2=point(inner,longitude); nx,ny=point(88,(longitude+4)%360)
            svg.append(f'<line x1="{x1:.1f}" y1="{y1:.1f}" x2="{x2:.1f}" y2="{y2:.1f}" stroke="var(--purple)" stroke-width="1" opacity=".28"/>')
            svg.append(f'<text x="{nx:.1f}" y="{ny:.1f}" text-anchor="middle" dominant-baseline="middle" font-size="9" fill="var(--purple)" opacity=".72">{house_index}</text>')
    # Keep the longitude anchor exact while placing crowded glyph labels into
    # collision-free radial/tangential lanes. A leader joins every displaced
    # label to its factual longitude, so visual spacing never changes the chart.
    placed=[]
    label_positions={}
    radius_candidates=(138,106,74,122,90)
    offset_candidates=(0.0,-7.0,7.0,-14.0,14.0,-21.0,21.0,-28.0,28.0,-35.0,35.0)
    for pname in NATAL_WHEEL_PLANETS:
        placement=planets.get(pname) or {}; longitude=_planetary_coordination_longitude(placement)
        if longitude is None: continue
        best=None
        for offset in offset_candidates:
            for radius in radius_candidates:
                px,py=point(radius,longitude+offset)
                nearest=min([math.hypot(px-ux,py-uy) for ux,uy in placed] or [999.0])
                collision=max(0.0,31.0-nearest)
                cost=collision*10000.0+abs(offset)*1.8+abs(radius-110)*0.08
                if best is None or cost<best[0]: best=(cost,px,py,radius,offset)
        _,px,py,radius,offset=best; placed.append((px,py)); label_positions[pname]=(px,py,radius,offset,longitude)
    for pname in NATAL_WHEEL_PLANETS:
        placement=planets.get(pname) or {}
        position=label_positions.get(pname)
        if not position: continue
        px,py,radius,offset,longitude=position; ex,ey=point(inner-4,longitude); ax,ay=point(78,longitude)
        glyph=PLANET_GLYPHS.get(pname,pname[:1]); display=pname
        sign=placement.get('sign',''); degree=placement.get('degree','')
        svg.append(f'<line x1="{ax:.1f}" y1="{ay:.1f}" x2="{ex:.1f}" y2="{ey:.1f}" stroke="currentColor" stroke-width=".7" opacity=".10"/>')
        if abs(offset)>0.01 or abs(radius-138)>0.01:
            anchor_x,anchor_y=point(radius,longitude)
            svg.append(f'<line x1="{anchor_x:.1f}" y1="{anchor_y:.1f}" x2="{px:.1f}" y2="{py:.1f}" stroke="currentColor" stroke-width=".8" opacity=".30"/>')
        svg.append(f'<circle cx="{px:.1f}" cy="{py:.1f}" r="14" fill="var(--card,#fff)" stroke="currentColor" stroke-width="1.5" opacity=".98" data-planet="{html.escape(display,quote=True)}" data-longitude="{longitude:.4f}" data-sign="{html.escape(str(sign),quote=True)}" data-degree="{html.escape(str(degree),quote=True)}"><title>{html.escape(display)} — {html.escape(str(sign))} {html.escape(str(degree))}°</title></circle>')
        svg.append(f'<text x="{px:.1f}" y="{py:.1f}" text-anchor="middle" dominant-baseline="middle" font-size="20" font-weight="700" aria-label="{html.escape(display,quote=True)} — {html.escape(str(sign),quote=True)} {html.escape(str(degree),quote=True)} degrees">{glyph}</text>')
    if rising.get('longitude') is not None:
        try: rx,ry=point(143,float(rising.get('longitude'))%360.0)
        except (TypeError,ValueError): rx=ry=None
        if rx is not None:
            svg.append(f'<circle cx="{rx:.1f}" cy="{ry:.1f}" r="13" fill="var(--lav)" stroke="var(--purple)" stroke-width="1.6"><title>Ascendant — {html.escape(str(rising.get("sign","")))} {html.escape(str(rising.get("degree","")))}°</title></circle>')
            svg.append(f'<text x="{rx:.1f}" y="{ry:.1f}" text-anchor="middle" dominant-baseline="middle" font-size="7" font-weight="800" fill="var(--purple)">ASC</text>')
    svg.append('</svg>')
    return ''.join(svg)


def _two_natal_wheels_html(chart_a,chart_b,name_a='You',name_b='Member'):
    """Keep two members' permanent natal charts separate and side-by-side."""
    return f'''<style>.coordination-wheel-pair{{display:grid!important;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px;align-items:start}}.coordination-wheel-pair>.card{{min-width:0;margin:0}}.coordination-wheel-pair svg{{width:100%!important;height:auto!important}}@media(max-width:520px){{.coordination-wheel-pair{{gap:7px}}.coordination-wheel-pair>.card{{padding:9px}}.coordination-wheel-pair h3{{font-size:.92rem;overflow-wrap:anywhere}}.coordination-wheel-pair .badge{{font-size:.62rem;padding:5px 7px}}}}</style><div class="grid coordination-wheel-pair" data-wheel-layout="side-by-side">
      <article class="card"><span class="badge">YOUR WHEEL</span><h3>{html.escape(name_a)}</h3>{_zodiac_wheel_html(chart_a,name_a)}</article>
      <article class="card"><span class="badge heart">{html.escape(name_b.upper())}'S WHEEL</span><h3>{html.escape(name_b)}</h3>{_zodiac_wheel_html(chart_b,name_b)}</article>
    </div>'''


def _saved_current_season(user_id):
    """Read an existing Season Within label without generating or exposing its private source."""
    conn=None
    try:
        conn=db()
        row=conn.execute("SELECT evidence_summary FROM coordination_reports WHERE user_id=? AND other_user_id=0 AND report_type='current_season_lunar_cycle' ORDER BY updated_at DESC,id DESC LIMIT 1",(user_id,)).fetchone()
        payload=json.loads(row['evidence_summary'] or '{}') if row else {}
        season=str(payload.get('season') or '')
        return season if season in LUNAR_SEASONS else ''
    except Exception:
        return ''
    finally:
        if conn:
            try: conn.close()
            except Exception: pass


NATAL_COORDINATION_INTERPRETATION_VERSION=1
NATAL_COORDINATION_SECTION_KEYS=('core_pattern','how_it_operates','strength_when_integrated','possible_tension','conscious_coordination','reflection_question')

def _natal_coordination_fallback(planet,placement,house,aspects):
    """Chart-specific permanent natal fallback; no transits or questionnaire copy."""
    sign=str((placement or {}).get('sign') or ''); tone=SIGN_BEHAVIORAL_TONES.get(sign) or {}
    strength=tone.get('strength','a distinctive way of approaching this function')
    watch=tone.get('watch','the familiar response can become automatic under pressure')
    question=tone.get('question','What would help this function become more deliberate?')
    house_focus={1:'personal initiative and the way life is approached',2:'values, resources, and what creates stability',3:'communication, learning, and everyday interpretation',4:'home, belonging, and emotional foundations',5:'creativity, visibility, and personal expression',6:'routines, responsibility, and practical wellbeing',7:'partnership, reciprocity, and direct relationship',8:'trust, shared responsibility, depth, and necessary change',9:'beliefs, learning, meaning, and wider perspective',10:'purpose, contribution, and public responsibility',11:'community, collaboration, and future direction',12:'rest, integration, privacy, and the inner life'}
    function_focus={
        'Sun':('identity and direction','turning self-understanding into choices that carry personal authorship','Notice which decision reflects what matters enough to receive your time, energy, and responsibility.'),
        'Moon':('emotional rhythm and internal safety','letting feelings become clear enough to guide care without making every feeling an instruction','When emotion rises, identify the need first; decide what the situation means after the feeling becomes more specific.'),
        'Mercury':('thinking, listening, and communication','organizing perception into language that leaves room for questions, correction, and real understanding','Before an important conversation, separate what you know, what you assume, and what you still need to ask.'),
        'Venus':('values, affection, and reciprocity','recognizing what is meaningful while allowing giving and receiving to remain mutual','Notice whether connection is reciprocal rather than measuring closeness only by how much you are willing to give.'),
        'Mars':('action, assertion, and boundaries','using motivation directly without requiring frustration to become the source of clarity','Express a limit while it is still a clear preference rather than waiting until it becomes accumulated frustration.'),
        'Jupiter':('growth, belief, and possibility','expanding toward meaning while keeping opportunity connected to capacity and follow-through','Choose the possibility that remains meaningful after you account for time, resources, and what it will require to sustain.'),
        'Saturn':('responsibility, limits, and endurance','making commitment specific enough to become sustainable rather than carrying pressure without definition','Make responsibility specific: decide what belongs to you before carrying what belongs to everyone else.'),
        'Uranus':('individuality, change, and experimentation','allowing necessary change without making disruption the only proof of freedom','Test one new approach while keeping enough structure to learn from what actually changes.'),
        'Neptune':('sensitivity, imagination, and intuition','making room for subtle information while maintaining enough clarity to distinguish intuition from uncertainty','Give an impression time to clarify, then pair it with one observable fact before treating it as direction.'),
        'Pluto':('depth, power, and transformation','recognizing when intensity is revealing something important and when attachment is resisting necessary renewal','Name what you are protecting, what it costs to keep protecting it, and what could change if control were no longer the only source of safety.'),
        'Rising':('outward approach and first response','coordinating the way situations are entered with the deeper pace and needs operating underneath','After the first response, pause long enough to ask whether your outward approach matches what you actually need from the situation.'),
    }
    focus,integrated,practice=function_focus.get(planet,('personal awareness','using this function with greater choice','Choose one grounded response that fits the facts in front of you.'))
    try: house_number=int(float(house)) if house not in (None,'') else None
    except (TypeError,ValueError): house_number=None
    house_text=house_focus.get(house_number,'the life area where this function becomes concrete')
    related=sorted({str(a.get('planet_b') if a.get('planet_a')==planet else a.get('planet_a')) for a in aspects})
    supportive=sum(1 for a in aspects if a.get('aspect') in {'trine','sextile'})
    friction=sum(1 for a in aspects if a.get('aspect') in {'square','opposition'})
    amplified=sum(1 for a in aspects if a.get('aspect')=='conjunction')
    relationship_text=(f" Its relationships with {', '.join(related)} make this function part of a wider internal conversation rather than an isolated trait." if related else '')
    nuance=''
    if amplified: nuance+=' Some linked functions may activate together, increasing both immediacy and the need to identify which one is leading.'
    if friction: nuance+=' Contrasting needs can create productive friction; integration comes from giving both sides a valid role instead of forcing one to win.'
    if supportive: nuance+=' Some responses may flow easily, although an available strength still becomes more useful when it is chosen deliberately.'
    return {
        'core_pattern':f"This {planet} function centers on {focus}. In this chart, it may develop through {strength}, especially in matters involving {house_text}.{relationship_text}",
        'how_it_operates':f"It may work best when {integrated}. The pattern is less about performing a fixed trait and more about noticing how this function organizes real choices, relationships, limits, or responses.",
        'strength_when_integrated':f"At its strongest, {strength} can become a usable capacity rather than only a familiar instinct.{nuance}",
        'possible_tension':f"Under pressure, {watch}. This is not a flaw or prediction; it is a place where pacing and conscious choice may matter more.",
        'conscious_coordination':practice+f' Pay particular attention when this choice affects {house_text}.',
        'reflection_question':f'What becomes clearer about {focus} when I notice how {strength} influences {house_text}?',
    }

def _natal_coordination_interpretations(user,chart,profile):
    """Generate and cache one structured permanent-natal interpretation packet."""
    planets=(chart or {}).get('planets') or {}; rising=(chart or {}).get('rising') or (chart or {}).get('ascendant') or {}
    names=[name for name in NATAL_WHEEL_PLANETS if planets.get(name)]
    if rising.get('sign'): names.append('Rising')
    if not names: return {}
    houses=(chart or {}).get('planet_houses') or {}; all_aspects=(chart or {}).get('aspects') or []
    profile_context=_profile_psychology_context(dict(profile) if profile else {})
    evidence={}
    for name in names:
        placement=(rising if name=='Rising' else planets.get(name)) or {}
        evidence[name]={
            'planet':name,'sign':placement.get('sign'),'degree':placement.get('degree'),
            'house':houses.get(name),
            'aspects':[a for a in all_aspects if name in {a.get('planet_a'),a.get('planet_b')}],
        }
    fingerprint=hashlib.sha256(json.dumps({'version':NATAL_COORDINATION_INTERPRETATION_VERSION,'natal':evidence,'profile_context':profile_context},sort_keys=True,default=str).encode()).hexdigest()
    period_key=f'natal:{fingerprint[:40]}|v{NATAL_COORDINATION_INTERPRETATION_VERSION}'
    try:
        conn=db(); row=conn.execute("SELECT written_report FROM coordination_reports WHERE user_id=? AND other_user_id=0 AND report_type='natal_planetary_coordination' AND period_key=?",(user['id'],period_key)).fetchone(); conn.close()
        cached=_cc_parse_json_object(row['written_report']) if row and row['written_report'] else None
        if cached and all(isinstance(cached.get(name),dict) and all(str(cached[name].get(k) or '').strip() for k in NATAL_COORDINATION_SECTION_KEYS) for name in names): return cached
    except Exception:
        pass
    section_schema={'type':'object','additionalProperties':False,'properties':{k:{'type':'string'} for k in NATAL_COORDINATION_SECTION_KEYS},'required':list(NATAL_COORDINATION_SECTION_KEYS)}
    schema={'type':'object','additionalProperties':False,'properties':{name:section_schema for name in names},'required':names}
    prompt='''Create the permanent Planetary Conscious Coordination interpretation packet for one natal chart. Astrology is the evidence; Conscious Coordination is the interpretation. For every supplied planet, synthesize its exact sign, degree phase, house, aspects, aspect types and orbs into lived human experience without teaching astrology or listing the evidence. Keep the named planet's human function at the center. Explain how it operates, what helps conscious use, an integrated strength, and nuanced possible tension. A conjunction may amplify linked functions; a square may create developmental friction; a trine may offer ease that can be underused; an opposition may require balancing two valid needs. Never call an aspect good, bad, lucky, or doomed. Use reflective possibility language and psychologically intelligent, grounded writing. Do not diagnose or make fixed personality claims. Do not mention current transits, the Moon today, current activation, seasons, lunar cycles, Journal material, algorithms, questionnaires, profile answers, degrees, houses, aspects, or orbs in the prose. Psychological context is secondary and may only subtly refine wording; never quote, repeat, identify, or obviously paraphrase it. Avoid generic spiritual filler. Every planet must have a different center of gravity. Each field must be specific to this chart and written in complete prose. core_pattern and how_it_operates should each be substantial short paragraphs; strength_when_integrated and possible_tension should each be focused paragraphs; conscious_coordination must be one concrete practice derived from this configuration; reflection_question must be one specific thoughtful question. Return only the required JSON.\nEVIDENCE:\n'''+json.dumps({'natal':evidence,'secondary_private_context':profile_context,'privacy':'Never expose or identify the secondary context. No Journal or current-sky evidence is included.'},default=str)
    generated=_openai_structured(prompt,'natal_planetary_coordination',schema)
    banned=('this month','right now','during this lunar cycle','today’s moon',"today's moon",'new moon','current activation','present sky','questionnaire','self-reported profile')
    valid=bool(generated)
    if valid:
        for name in names:
            section=generated.get(name) if isinstance(generated.get(name),dict) else {}
            combined=' '.join(str(section.get(k) or '') for k in NATAL_COORDINATION_SECTION_KEYS).lower()
            if any(not str(section.get(k) or '').strip() for k in NATAL_COORDINATION_SECTION_KEYS) or any(term in combined for term in banned): valid=False; break
    result=generated if valid else {name:_natal_coordination_fallback(name,(rising if name=='Rising' else planets.get(name)) or {},houses.get(name),evidence[name]['aspects']) for name in names}
    try:
        written=json.dumps(result,ensure_ascii=False,sort_keys=True); digest=hashlib.sha256(written.encode()).hexdigest(); conn=db()
        conn.execute('''INSERT INTO coordination_reports(user_id,other_user_id,report_type,period_key,report_version,written_report,spoken_script,audio_reference,evidence_summary,privacy_scope,context_fingerprint,normalized_text_hash,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(user_id,other_user_id,report_type,period_key) DO UPDATE SET written_report=excluded.written_report,evidence_summary=excluded.evidence_summary,context_fingerprint=excluded.context_fingerprint,normalized_text_hash=excluded.normalized_text_hash,updated_at=excluded.updated_at''',(user['id'],0,'natal_planetary_coordination',period_key,NATAL_COORDINATION_INTERPRETATION_VERSION,written,'','',json.dumps({'version':NATAL_COORDINATION_INTERPRETATION_VERSION,'planets':names,'ai_generated':bool(valid)},default=str),'permanent-natal-owner-profile-no-journal-no-transits',fingerprint,digest,now(),now()))
        conn.commit(); conn.close()
    except Exception:
        app.logger.exception('Could not cache permanent natal Conscious Coordination interpretations')
    return result


def _natal_positions_html(chart, owner_name='Member', profile=None, interpretations=None, self_view=False):
    """Translate one owner's factual natal placements into Conscious Coordination."""
    chart=chart or {}; planets=chart.get('planets') or {}; profile=dict(profile) if profile else {}; interpretations=interpretations or {}
    if not chart.get('ready') or not planets:
        return '<div class="empty"><h3>Planetary positions unavailable</h3><p class="muted">Complete saved birth information is needed to calculate these natal placements.</p></div>'
    def degree_label(value):
        if value in (None,''): return ''
        try: return f'{float(value):.2f}'.rstrip('0').rstrip('.')
        except (TypeError,ValueError): return str(value)
    planet_copy={
        'Sun':('Self & Purpose Coordination','sense of self, personal direction, confidence, identity, purpose, and returning to what feels authentic'),
        'Moon':('Emotional Coordination','emotional rhythm, processing, security, rest, restoration, and recognizing when a feeling needs attention rather than immediate action'),
        'Mercury':('Communication & Mental Coordination','communication, listening, thought processing, expressing needs, organizing decisions, and choosing the timing of important conversations'),
        'Venus':('Connection & Values Coordination','connection, affection, values, appreciation, receiving and giving, and recognizing what makes a relationship meaningful'),
        'Mars':('Action & Boundary Coordination','motivation, action, assertion, boundaries, frustration, conflict energy, and knowing when to move or pause'),
        'Jupiter':('Growth & Possibility Coordination','learning, opportunity, beliefs, meaning, confidence in growth, and distinguishing supportive expansion from excess'),
        'Saturn':('Structure & Responsibility Coordination','discipline, limits, responsibility, commitments, patience, long-term development, and sustainable structure'),
        'Uranus':('Change & Individuality Coordination','change, independence, originality, freedom, innovation, and adapting without losing grounding'),
        'Neptune':('Intuition & Sensitivity Coordination','sensitivity, imagination, intuition, ideals, compassion, rest, clear boundaries, and distinguishing inner knowing from uncertainty'),
        'Pluto':('Transformation & Depth Coordination','transformation, depth, personal power, release, regeneration, and recognizing patterns that no longer support the present season'),
        'Rising':('Outer Expression & Approach','first responses, outward expression, entering unfamiliar situations, and coordinating outward style with internal needs'),
    }
    chart_aspects=[a for a in (chart.get('aspects') or []) if a.get('planet_a') and a.get('planet_b') and a.get('aspect')]
    def aspect_label(aspect):
        orb=aspect.get('orb'); orb_text=(f' — orb {degree_label(orb)}°' if orb not in (None,'') else '')
        return f"{aspect.get('planet_a')} {aspect.get('aspect')} {aspect.get('planet_b')}{orb_text}"
    def placement_card(name,placement):
        title,_=planet_copy[name]; sign=str(placement.get('sign') or ''); degree_text=degree_label(placement.get('degree'))
        house=(chart.get('planet_houses') or {}).get(name); house_text=f' • House {html.escape(str(house))}' if house not in (None,'') else ''
        related=[a for a in chart_aspects if name in {a.get('planet_a'),a.get('planet_b')}]
        section=interpretations.get(name) if isinstance(interpretations.get(name),dict) else _natal_coordination_fallback(name,placement,house,related)
        glyph=PLANET_GLYPHS.get(name,'↑' if name=='Rising' else '')
        placement_text=f'''{html.escape(name)} in {html.escape(sign)}{(' '+html.escape(degree_text)+'°') if degree_text else ''}{house_text}'''
        paragraphs=''.join(f'<p>{html.escape(str(section.get(key) or ""))}</p>' for key in ('core_pattern','how_it_operates','strength_when_integrated','possible_tension') if str(section.get(key) or '').strip())
        coordination=html.escape(str(section.get('conscious_coordination') or ''))
        reflection=html.escape(str(section.get('reflection_question') or ''))
        return f'''<details class="card" data-natal-placement="{html.escape(name,quote=True)}"><summary style="cursor:pointer;font-weight:800;display:flex;justify-content:space-between;align-items:flex-start;gap:12px"><span><span style="display:block;font-size:1.08rem">{html.escape(glyph)} {html.escape(name)} — {html.escape(title)}</span><span class="muted small">{placement_text}</span></span><span class="muted small">Read interpretation ▾</span></summary><div class="planetary-interpretation"><p><b>{placement_text}</b></p>{paragraphs}<h4>Conscious Coordination</h4><p>{coordination}</p><h4>Reflection Question</h4><p>{reflection}</p></div></details>'''
    rows=[placement_card(name,planets[name]) for name in NATAL_WHEEL_PLANETS if planets.get(name)]
    rising=chart.get('rising') or chart.get('ascendant') or {}
    if rising and rising.get('sign'): rows.append(placement_card('Rising',rising))
    aspects=[f'<li>{html.escape(aspect_label(aspect))}</li>' for aspect in chart_aspects]
    breakdown=(f'''<details class="card" data-natal-breakdown><summary style="cursor:pointer;font-weight:800">▶ Natal Chart Breakdown</summary><div class="planetary-interpretation"><ul>{''.join(aspects)}</ul></div></details>''' if aspects else '')
    return f'''<style>
    .planetary-conscious-coordination{{display:block;width:100%;min-width:0;margin:24px 0 10px}}
    .planetary-conscious-coordination>h2{{margin-top:8px}}
    .planetary-conscious-coordination>.moregrid{{width:100%;align-items:start}}
    .planetary-conscious-coordination details[data-natal-placement][open]{{grid-column:1/-1}}
    .planetary-conscious-coordination .planetary-interpretation{{display:block;width:100%;min-width:0;margin-top:18px;line-height:1.7;overflow-wrap:anywhere}}
    .planetary-conscious-coordination .planetary-interpretation p,.planetary-conscious-coordination .planetary-interpretation h4,.planetary-conscious-coordination .planetary-interpretation ul{{display:block;width:100%;max-width:none;margin:12px 0}}
    .planetary-conscious-coordination details[data-natal-breakdown]{{width:100%;margin-top:14px}}
    @media(max-width:700px){{.planetary-conscious-coordination details[data-natal-placement][open]{{grid-column:1}}}}
    </style><section class="planetary-conscious-coordination" data-chart-owner="{html.escape(str(owner_name),quote=True)}"><span class="badge heart">THE SEASONS WITHIN</span><h2>Planetary Conscious Coordination</h2><div class="moregrid">{''.join(rows)}</div>{breakdown}</section>'''


def _preferred_connection_type(profile):
    raw=' '.join(str((profile or {}).get(k,'') or '') for k in ('seeking','coordination_types')).lower()
    candidates=[]
    for kind,terms in (
        ('love',('love','relationship','dating','romantic')),
        ('friendship',('friendship','friend')),
        ('business',('business','collaboration','collaborator')),
    ):
        positions=[raw.find(term) for term in terms if raw.find(term)>=0]
        if positions: candidates.append((min(positions),kind))
    if candidates: return min(candidates)[1]
    return 'friendship'


def _comparison_zodiac_wheel_html(chart_a,chart_b,name_a='You',name_b='Member'):
    """Overlay two factual natal wheels in a shared, fixed comparison orientation."""
    ap=(chart_a or {}).get('planets') or {}; bp=(chart_b or {}).get('planets') or {}
    if not (chart_a or {}).get('ready') or not (chart_b or {}).get('ready') or not ap or not bp:
        return '<div class="empty"><h3>Coordination wheel unavailable</h3><p class="muted">Both members need complete birth information for chart-to-chart coordination.</p></div>'
    cx=240; cy=240; outer=198; inner=150; sign_r=175
    def point(radius,longitude):
        # The comparison chart uses the same non-mirrored zodiac direction;
        # Aries is at the right in this legacy overlay renderer.
        angle=math.radians(-(float(longitude)%360.0))
        return cx+radius*math.cos(angle),cy+radius*math.sin(angle)
    svg=[f'<svg viewBox="0 0 480 520" role="img" aria-label="{html.escape(name_a,quote=True)} and {html.escape(name_b,quote=True)} Conscious Coordination comparison wheel" style="width:100%;max-width:560px;height:auto;display:block;margin:0 auto">']
    svg.append(f'<circle cx="{cx}" cy="{cy}" r="{outer}" fill="none" stroke="currentColor" stroke-width="2.2" opacity=".62"/>')
    svg.append(f'<circle cx="{cx}" cy="{cy}" r="{inner}" fill="none" stroke="currentColor" stroke-width="1.2" opacity=".22"/>')
    svg.append(f'<circle cx="{cx}" cy="{cy}" r="86" fill="none" stroke="currentColor" stroke-width="1" opacity=".12"/>')
    for i,(glyph,name) in enumerate(ZODIAC_WHEEL_SIGNS):
        longitude=i*30.0; x1,y1=point(inner,longitude); x2,y2=point(outer,longitude); sx,sy=point(sign_r,longitude+15.0)
        svg.append(f'<line x1="{x1:.1f}" y1="{y1:.1f}" x2="{x2:.1f}" y2="{y2:.1f}" stroke="currentColor" stroke-width="1" opacity=".28"/>')
        svg.append(f'<text x="{sx:.1f}" y="{sy:.1f}" text-anchor="middle" dominant-baseline="middle" font-size="24" aria-label="{html.escape(name,quote=True)}">{glyph}</text>')
    for degree in range(0,360,5):
        tick_inner=outer-(8 if degree%30==0 else 4); x1,y1=point(tick_inner,degree); x2,y2=point(outer,degree)
        svg.append(f'<line x1="{x1:.1f}" y1="{y1:.1f}" x2="{x2:.1f}" y2="{y2:.1f}" stroke="currentColor" stroke-width="{1.2 if degree%30==0 else .55}" opacity=".22"/>')
    # Reliable houses remain factual geometry.  Each member's cusps are drawn
    # in a separate ring without changing either person's zodiac longitudes.
    for houses,r1,r2,stroke,dash in [
        ((chart_a or {}).get('houses') or [],88,146,'var(--purple)',''),
        ((chart_b or {}).get('houses') or [],88,118,'var(--plum)','4 4'),
    ]:
        if len(houses)>=12:
            for cusp in houses[:12]:
                try: longitude=float(cusp)%360.0
                except (TypeError,ValueError): continue
                x1,y1=point(r1,longitude); x2,y2=point(r2,longitude)
                dash_attr=f' stroke-dasharray="{dash}"' if dash else ''
                svg.append(f'<line x1="{x1:.1f}" y1="{y1:.1f}" x2="{x2:.1f}" y2="{y2:.1f}" stroke="{stroke}" stroke-width="0.8" opacity=".18"{dash_attr}/>')
    # Cross-chart aspect lines use exact longitude relationships.
    contacts=[]
    for pa in PLANETARY_COORDINATION_WHEEL_PLANETS:
        for pb in PLANETARY_COORDINATION_WHEEL_PLANETS:
            alon=(ap.get(pa) or {}).get('longitude'); blon=(bp.get(pb) or {}).get('longitude')
            if alon is None or blon is None: continue
            aspect=_cc_detect_aspect(alon,blon)
            if aspect and aspect.get('strength',0)>=0.25:
                contacts.append((aspect.get('strength',0),pa,pb,float(alon),float(blon),aspect.get('aspect')))
    for strength,pa,pb,alon,blon,aspect_name in sorted(contacts,reverse=True)[:26]:
        ax,ay=point(122,alon); bx,by=point(98,blon)
        svg.append(f'<line x1="{ax:.1f}" y1="{ay:.1f}" x2="{bx:.1f}" y2="{by:.1f}" stroke="var(--purple)" stroke-width="{0.7+1.3*float(strength):.2f}" opacity="{0.10+0.28*float(strength):.2f}"/>')
    for radius,planets,fill,stroke,who in [(126,ap,'var(--lav)','var(--purple)',name_a),(98,bp,'#fff1ef','var(--plum)',name_b)]:
        for index,pname in enumerate([p for p in NATAL_WHEEL_PLANETS if planets.get(p)]):
            placement=planets[pname]
            try: longitude=float(placement.get('longitude'))%360.0
            except (TypeError,ValueError): continue
            px,py=point(radius+(index%3-1)*6,longitude); glyph=PLANET_GLYPHS.get(pname,pname[:1])
            svg.append(f'<circle cx="{px:.1f}" cy="{py:.1f}" r="13" fill="{fill}" stroke="{stroke}" stroke-width="1.5"/>')
            svg.append(f'<text x="{px:.1f}" y="{py:.1f}" text-anchor="middle" dominant-baseline="middle" font-size="18" font-weight="700" fill="{stroke}" aria-label="{html.escape(who+" "+pname,quote=True)}">{glyph}</text>')
    for rising,radius,fill,stroke,who in [
        (((chart_a or {}).get('rising') or (chart_a or {}).get('ascendant') or {}),136,'var(--lav)','var(--purple)',name_a),
        (((chart_b or {}).get('rising') or (chart_b or {}).get('ascendant') or {}),108,'#fff1ef','var(--plum)',name_b),
    ]:
        if rising.get('longitude') is None: continue
        try: rx,ry=point(radius,float(rising.get('longitude'))%360.0)
        except (TypeError,ValueError): continue
        svg.append(f'<circle cx="{rx:.1f}" cy="{ry:.1f}" r="10" fill="{fill}" stroke="{stroke}" stroke-width="1.2"/>')
        svg.append(f'<text x="{rx:.1f}" y="{ry:.1f}" text-anchor="middle" dominant-baseline="middle" font-size="7" font-weight="800" fill="{stroke}" aria-label="{html.escape(who+' Rising',quote=True)}">ASC</text>')
    svg.append(f'<text x="240" y="486" text-anchor="middle" font-size="12" fill="var(--purple)">● {html.escape(name_a)}</text>')
    svg.append(f'<text x="240" y="506" text-anchor="middle" font-size="12" fill="var(--plum)">● {html.escape(name_b)}</text>')
    svg.append('</svg>')
    return ''.join(svg)

COORDINATION_INDICATOR_LABELS = {
    'overall':'Overall Coordination',
    'social-emotional':'Social & Emotional Intelligence',
    'communication':'Communication',
    'conflict':'Conflict',
    'repair-accountability':'Repair & Accountability',
    'emotional-rhythm':'Emotional Rhythm',
    'love-affection':'Love Languages / Affection',
    'lifestyle-values':'Lifestyle & Values',
    'boundaries':'Boundaries',
    'business-collaboration':'Business Collaboration',
    'planetary':'Planetary Coordination',
}

def _coordination_indicator_slug(label):
    reverse={
        'Social & Emotional Intelligence':'social-emotional',
        'Communication':'communication',
        'Conflict':'conflict',
        'Repair & Accountability':'repair-accountability',
        'Emotional Rhythm':'emotional-rhythm',
        'Love Languages / Affection':'love-affection',
        'Lifestyle & Values':'lifestyle-values',
        'Boundaries':'boundaries',
        'Business Collaboration':'business-collaboration',
        'Planetary Coordination':'planetary',
    }
    return reverse.get(label,'')

def _coordination_indicator_description(label, user, cp_row):
    cp=dict(cp_row) if cp_row else {}
    insights=_behavioral_insights(cp)
    descriptions={
        'Overall Coordination':("This score is a whole-profile summary of how developed and internally supported your current Conscious Coordination patterns are. It is not a grade and it does not measure your worth or predict whether a relationship will succeed. It gives you a practical place to notice where your communication, regulation, repair, boundaries, values and collaboration habits are working together—and where one area may need more conscious attention."),
        'Social & Emotional Intelligence':(f"{insights.get('trust','Your social and emotional coordination grows through awareness of both your own state and the other person’s experience.')} A strong use of this area is noticing emotion without immediately assuming what it means, listening before fixing, and recognizing when another person needs presence, information, space or reassurance. The growth edge is staying responsive without becoming responsible for managing everyone else’s feelings."),
        'Communication':(f"{insights.get('communication','Clear communication improves when expectations are explicit instead of assumed.')} This area looks at how you organize your thoughts, how directly you express needs, and whether you can keep clarity when emotion rises. The goal is not constant talking; it is saying enough of the right thing that the other person does not have to guess what you mean."),
        'Conflict':("Conflict coordination is about what happens when two needs, interpretations or priorities no longer match. Useful conflict behavior separates the issue from the person, slows escalation, and identifies what actually needs a decision, boundary or clarification. A lower score here does not mean you are bad at conflict; it points to an area where stress can make your preferred communication style harder to access."),
        'Repair & Accountability':(f"{insights.get('repair','Repair becomes stronger when words and follow-through agree.')} This area reflects what happens after tension: whether responsibility can be named, whether impact can be heard without defensiveness, and whether the next behavior changes enough to rebuild trust. Repair is more than ending an argument; it is creating evidence that the same injury is less likely to repeat in the same way."),
        'Emotional Rhythm':(f"Emotional Rhythm describes the pace of activation, processing and recovery that feels most natural to you. Some people need conversation quickly; others need quiet, movement, sleep or time before they can speak clearly. {insights.get('practice','A deliberate regulation pause can help you respond from intention rather than urgency.')} Knowing your rhythm is useful because it lets you ask for space without disappearing and reconnect without forcing yourself to process on someone else’s timetable."),
        'Love Languages / Affection':(f"{insights.get('connection','Care is most useful when it is expressed in a form the other person can actually recognize and receive.')} This indicator is about how affection is shown, how closeness is recognized, and whether giving and receiving care feel reciprocal. The practical question is not only how you show love, but whether you can recognize care when it arrives differently than you would naturally express it."),
        'Lifestyle & Values':("Lifestyle & Values looks at whether the way you actually spend time, energy and resources supports what you say matters to you. Shared values do not require identical routines, but major differences around family, freedom, wellness, money, social life, spirituality, work or growth usually need explicit conversation. This area becomes stronger when values are translated into observable choices rather than remaining ideals."),
        'Boundaries':(f"{insights.get('boundaries','Boundaries work best when they are communicated before they have to become emergency limits.')} This area includes privacy, access, communication expectations, emotional responsibility and the ability to say yes or no without turning every limit into rejection. Healthy coordination allows closeness and autonomy to exist at the same time."),
        'Business Collaboration':(f"{insights.get('business','Collaboration improves when pace, ownership and decision rules are explicit before enthusiasm turns into commitment.')} This score focuses on how you work with another person around ideas, deadlines, responsibility, resources and follow-through. Good collaboration is not simply liking the same idea; it is knowing who owns what, how decisions are made, how disagreement is handled and what happens when circumstances change."),
        'Planetary Coordination':("Planetary Coordination uses your calculated planetary pattern as one reflective layer inside Conscious Coordination. The wheel shows the factual placements; the interpretation layer looks for useful patterns involving identity, emotion, communication, affection, action, growth and responsibility. It is used as reflective context—not as a diagnosis, prediction or substitute for the behavior you actually report and demonstrate."),
    }
    return descriptions.get(label,"This Conscious Coordination indicator is a reflective summary of the member’s current profile. It is not a diagnosis or prediction.")

@app.route('/conscious-coordination/profile/<int:user_id>/indicator/<category>')
@login_required
def coordination_indicator_detail(user_id,category):
    me=current_user()
    conn=db(); user=conn.execute('SELECT * FROM users WHERE id=?',(user_id,)).fetchone(); conn.close()
    if not user: abort(404)
    is_self=(me['id']==user_id)
    if not is_self and not has_full_access(me):
        flash('Upgrade to open the full Conscious Coordination descriptions for another member.','info')
