def _planet_profile_slice(profile,pname):
    p=profile or {}
    cfg=PLANET_BEHAVIORAL_LENSES.get(pname,{})
    return {k:p.get(k,'') for k in cfg.get('profile_keys',[]) if p.get(k,'')}

def _normalize_report_text(value):
    value=re.sub(r'[^a-z0-9\s]',' ',(value or '').lower())
    value=re.sub(r'\s+',' ',value).strip()
    return value

def _report_similarity(a,b):
    aa=set(_normalize_report_text(a).split())
    bb=set(_normalize_report_text(b).split())
    if not aa or not bb:
        return 0.0
    return len(aa & bb)/max(1,len(aa | bb))

def _planet_specific_practice(pname, practices):
    practice=(practices or [''])[0]
    if pname=='Sun':
        if practice=='meditation':
            return "Meditate before a choice that involves other people's expectations. Ask: If nobody approved or disapproved, what would I choose because it actually feels like mine?"
        if practice=='nature':
            return "Take a short walk alone before an important choice. Use the distance from other people's reactions to identify what you actually think and want."
        return "Before agreeing, name the choice that is actually yours to make and the part that belongs to other people."
    if pname=='Moon':
        if practice=='meditation':
            return "Use meditation to let the feeling exist without immediately turning it into action. Notice what the emotion is asking for—space, reassurance, rest, movement, or clarity—before deciding what to do."
        if practice=='nature':
            return "Use time outside to settle the body before changing plans, ending a conversation, spending money, or making a large decision for emotional relief."
        return "Regulate first, decide second. Give the emotional wave enough time to change before making a lasting choice."
    if pname=='Mercury':
        if practice=='meditation':
            return "Before a charged conversation, meditate for a few minutes and separate three things: what was actually said, what you observed, and what you are concluding from it."
        return "Write down: What do I know? What am I assuming? What question would give me the missing information?"
    if pname=='Venus':
        if practice=='meditation':
            return "Meditate on the difference between wanting comfort, wanting closeness, and wanting something that genuinely matches your values. Do not make them the same question."
        return "Before investing more time, money, affection or energy, ask whether the exchange feels mutual and whether it still fits your values."
    if pname=='Mars':
        if practice=='meditation':
            return "Use meditation to create a gap between activation and action. Notice the urge to push, defend or shut down, then choose the smallest clear action that protects the boundary without escalating the situation."
        if practice=='movement':
            return "Use movement to discharge activation before confrontation. Return to the issue once you can state the boundary without needing the other person to feel your intensity."
        return "Pause at the first sign of activation and decide whether the situation needs action, a boundary, a question, or simply more time."
    if pname=='Jupiter':
        if practice=='meditation':
            return "Use meditation to slow enthusiasm long enough to test the idea. Ask what evidence supports it, what resources it requires, and what would make the opportunity sustainable."
        return "Before saying yes to an opportunity, check capacity, cost, timing and follow-through—not just possibility."
    if pname=='Saturn':
        if practice=='meditation':
            return "Use meditation to sit with uncertainty without immediately trying to eliminate it. Ask whether the hesitation is useful caution or fear asking for perfect certainty."
        return "Break the responsibility into the next concrete step. Long-term structure is built more reliably through repeatable action than pressure."
    return "Use a short regulation pause before responding."

def _planet_fallback_guidance(pname,profile,practices,sky,relevant_aspects,placement=None,journal_context=None,lunar_cycle=None,user_id=None,variant=0,coordination_score=None,activation_score=None):
    placement=placement or {}
    journal_context=journal_context or {}
    lunar_cycle=lunar_cycle or {}
    sign=placement.get('sign','')
    try: degree=float(placement.get('degree',0) or 0)
    except (TypeError,ValueError): degree=0.0
    degree_phase=('an emerging, immediate expression' if degree<10 else 'an established, reinforced expression' if degree<20 else 'a mature, transitional expression')
    display_name='Lunar' if pname=='Moon' else pname
    tone=SIGN_BEHAVIORAL_TONES.get(sign,{})
    journal_themes=list((journal_context.get('theme_counts') or {}).keys())
    seed_raw='|'.join([
        str(user_id or ''),
        pname,
        sign,
        f'{degree:.3f}',
        str(coordination_score),
        str(activation_score),
        str(lunar_cycle.get('cycle_id','')),
        str(journal_context.get('history_fingerprint','')),
        str(variant),
    ])
    seed=int(hashlib.sha256(seed_raw.encode('utf-8')).hexdigest()[:12],16)

    planet_roles={
        'Sun':('self-direction and identity','own a choice without needing every outside reaction to settle first'),
        'Moon':('emotional safety and recovery','understand the feeling before turning it into a lasting decision'),
        'Mercury':('thinking and communication','separate observation, interpretation and assumption before responding'),
        'Venus':('affection, reciprocity and values','notice whether investment and care are moving in both directions'),
        'Mars':('action, assertion and boundaries','choose the clearest action without letting activation choose the method'),
        'Jupiter':('growth, opportunity and belief','test possibility against capacity, timing and follow-through'),
        'Saturn':('responsibility, limits and long-term structure','turn pressure into a repeatable next step rather than paralysis'),
    }
    role,action=planet_roles.get(pname,('personal coordination','respond deliberately to what is actually present'))

    sign_strength=tone.get('strength','a distinctive way of approaching this part of life')
    sign_watch=tone.get('watch','the familiar strength can become less useful when it is automatic')
    sign_question=tone.get('question','What response fits the present situation rather than the old pattern?')

    openings=[
        f"Your {display_name} pattern brings {sign_strength} into the area of {role}.",
        f"In the part of life connected with {role}, the {sign} quality here is expressed through {sign_strength}.",
        f"This {display_name} placement combines {role} with {sign_strength}, which changes how this part of your coordination tends to operate.",
        f"For {role}, this placement is less about a fixed trait and more about how {sign_strength} gets used under real pressure.",
    ]
    main=openings[seed%len(openings)]
    main+=f" At this part of the sign, it tends to operate as {degree_phase}. The useful task is to {action}."

    try: coordination_value=float(coordination_score)
    except (TypeError,ValueError): coordination_value=None
    try: activation_value=float(activation_score)
    except (TypeError,ValueError): activation_value=None
    score_context=''
    if coordination_value is not None:
        score_context=(' The calculated pattern suggests this function is currently easier to access deliberately.' if coordination_value>=80 else
                       ' The calculated pattern suggests this function is available, but benefits from conscious pacing.' if coordination_value>=65 else
                       ' The calculated pattern suggests this function may require more deliberate support in the present cycle.')
    if activation_value is not None and activation_value>=55:
        score_context+=' It is also strongly activated now, making real-time choices in this area especially noticeable.'
    elif activation_value is not None and activation_value<=20:
        score_context+=' Its activation is quieter now, so the pattern may appear more as background orientation than immediate pressure.'
    main+=score_context

    if journal_themes:
        primary=journal_themes[(seed//7)%len(journal_themes)].replace('/',' and ')
        second=journal_themes[(seed//13)%len(journal_themes)].replace('/',' and ') if len(journal_themes)>1 else ''
        journal_note=f"One pattern worth noticing is how {primary} is influencing this part of your coordination now."
        if second and second!=primary:
            journal_note+=f" Notice where {second} intersects with it rather than treating the two as separate concerns."
    else:
        journal_note="Notice how this part of your pattern changes when the situation asks for a response that is more deliberate than automatic."

    practice=_planet_specific_practice(pname,practices)
    if practices:
        rotations=[
            practice,
            practice.replace("Before","When possible, before",1) if "Before" in practice else practice,
            practice+" Keep the exercise short enough that it helps you return to the situation rather than avoid it.",
        ]
        practice=rotations[(seed//19)%len(rotations)]

    real_options=[
        f"In a real situation, notice the moment when {sign_watch}. That is the point to slow down enough to {action}.",
        f"The practical test is whether {sign_strength} is helping you handle the present facts or whether {sign_watch}. If the latter is happening, return to the simplest next action.",
        f"Use this placement as a decision lens: keep the strength of {sign_strength}, while refusing to let {sign_watch}.",
    ]
    real=real_options[(seed//23)%len(real_options)]

    cycle_note=''
    if relevant_aspects:
        cycle_note=" The current reflection cycle is activating this area strongly enough that it is worth observing in real time instead of treating it as a permanent personality statement."
    elif lunar_cycle.get('cycle_id'):
        cycle_note=" The current lunar reflection cycle provides the timing background, while the placement describes the personal function being worked with."

    watch_options=[
        sign_watch.capitalize()+".",
        f"Watch for the moment when {sign_watch}. The goal is not to suppress the strength, but to use it with more choice.",
        f"Be especially alert if {sign_watch}; that is where this placement can shift from useful instinct to automatic reaction.",
    ]
    watch=watch_options[(seed//29)%len(watch_options)]

    questions=[
        sign_question,
        f"What is changing in the way I need to use {role} now?",
        f"Where could I keep the strength of this placement without repeating the part that no longer fits?",
        f"What would a more deliberate use of {role} look like in the situation I am actually living today?",
    ]
    reflection=questions[(seed//31)%len(questions)]

    fallback_headings={
        'Sun':['Your Direction','Where You May Be Holding Back','What Supports Authentic Choice'],
        'Moon':['Your Emotional Rhythm','What Your System May Be Asking For','What Could Support Recovery'],
        'Mercury':['Your Communication Pattern','Where Meaning Can Get Lost','A Clearer Way to Respond'],
        'Venus':['Connection & Reciprocity','Where Your Energy Is Being Invested','What Mutuality Could Look Like'],
        'Mars':['Action & Boundaries','Where Frustration May Be Building','A Direct Next Step'],
        'Jupiter':['Growth & Opportunity','Where More Could Become Too Much','A Grounded Expansion'],
        'Saturn':['Responsibility & Structure','What Needs Clearer Limits','What Is Sustainable'],
    }.get(pname,['Your Current Pattern','What Deserves Attention','What May Support You'])
    return (
        f"{fallback_headings[0]}\n\n{main}{cycle_note}\n\n"
        f"{fallback_headings[1]}\n\n{journal_note} {watch}\n\n"
        f"{fallback_headings[2]}\n\n{real} {practice}\n\n"
        f"A Question to Carry With You\n\n{reflection}"
    )

CC_PLANET_REPORT_HEADINGS = {
    'Sun': [('core_theme','Your Direction'),('psychological_interpretation','Owning Your Position'),('emotional_interpretation','What May Be Under the Choice'),('current_coordination','Where Coordination May Be Available'),('potential_tension','Where You May Be Holding Back'),('supportive_response','What Supports Authentic Choice'),('coordination_practice','Coordination Practice'),('journal_question','A Question to Carry With You')],
    'Moon': [('core_theme','Your Emotional Rhythm'),('psychological_interpretation','How Your Regulation Pattern May Respond'),('emotional_interpretation','What Your System May Be Asking For'),('current_coordination','Where Emotional Coordination May Be Available'),('potential_tension','Where Recovery May Need More Space'),('supportive_response','What Could Support Recovery'),('coordination_practice','Regulation Practice'),('journal_question','A Question to Carry With You')],
    'Mercury': [('core_theme','Your Communication Pattern'),('psychological_interpretation','How You May Be Processing This'),('emotional_interpretation','What May Be Influencing Interpretation'),('current_coordination','Where Clarity May Be Available'),('potential_tension','Where Meaning Can Get Lost'),('supportive_response','A Clearer Way to Respond'),('coordination_practice','Communication Practice'),('journal_question','A Question to Carry With You')],
    'Venus': [('core_theme','Connection & Reciprocity'),('psychological_interpretation','How You May Be Investing in Connection'),('emotional_interpretation','What Closeness May Be Asking For'),('current_coordination','Where Mutuality May Be Available'),('potential_tension','Where Your Energy May Be Overextended'),('supportive_response','What Reciprocity Could Look Like'),('coordination_practice','Connection Practice'),('journal_question','A Question to Carry With You')],
    'Mars': [('core_theme','Action & Boundaries'),('psychological_interpretation','How You May Be Responding Under Pressure'),('emotional_interpretation','What Frustration May Be Signaling'),('current_coordination','Where Direct Action May Help'),('potential_tension','Where Frustration May Be Building'),('supportive_response','A Direct Next Step'),('coordination_practice','Boundary Practice'),('journal_question','A Question to Carry With You')],
    'Jupiter': [('core_theme','Growth & Opportunity'),('psychological_interpretation','How You May Be Meeting Possibility'),('emotional_interpretation','What Expansion May Be Stirring'),('current_coordination','Where Growth May Be Available'),('potential_tension','Where More Could Become Too Much'),('supportive_response','A Grounded Expansion'),('coordination_practice','Capacity Practice'),('journal_question','A Question to Carry With You')],
    'Saturn': [('core_theme','Responsibility & Structure'),('psychological_interpretation','How You May Be Carrying Responsibility'),('emotional_interpretation','What Pressure May Be Asking You to Notice'),('current_coordination','Where Structure May Support You'),('potential_tension','What Needs Clearer Limits'),('supportive_response','What Is Sustainable'),('coordination_practice','Sustainability Practice'),('journal_question','A Question to Carry With You')],
}

CC_GENERIC_REPORT_PHRASES = (
    'trust the universe','embrace your journey','everything happens for a reason',
    'you are entering a transformative time','focus on balance','the universe is telling you'
)

def _cc_planet_structured_text(pname,sections,other_view=False):
    other_headings={
        'core_theme':'How This May Operate in This Member',
        'psychological_interpretation':'How This May Show Up',
        'emotional_interpretation':'What May Shape Their Response',
        'current_coordination':'How to Connect With This Member',
        'potential_tension':'Where Coordination May Need Awareness',
        'supportive_response':'Ways to Consciously Coordinate',
        'coordination_practice':'Practical Connection Guidance',
        'journal_question':'Connection Consideration',
    }
    parts=[]
    for key,heading in CC_PLANET_REPORT_HEADINGS.get(pname,[]):
        value=str((sections or {}).get(key,'') or '').strip()
        if value:
            parts.append(f'{other_headings.get(key,heading) if other_view else heading}\n\n{value}')
    return '\n\n'.join(parts).strip()


def _cc_report_quality_ok(text, source_profile_text=''):
    low=(text or '').lower()
    if not text or len(text)<350:
        return False
    if sum(1 for phrase in CC_GENERIC_REPORT_PHRASES if phrase in low)>=2:
        return False
    # Guard against simply copying a member's questionnaire language into prose.
    source_words=set(_normalize_report_text(source_profile_text).split())
    report_words=set(_normalize_report_text(text).split())
    if source_words and report_words and len(source_words)>=12:
        overlap=len(source_words & report_words)/max(1,len(source_words))
        if overlap>0.72:
            return False
    return True


def _cc_generate_planet_structured_report(user_id,pname,context_key,instruction,data,fallback_factory,required_terms,other_view=False):
    journal_context=(data or {}).get('journal_history') or {}
    source_profile=' '.join(str(v or '') for v in ((data or {}).get('relevant_profile_only') or {}).values())
    schema='''Return ONLY valid JSON with these keys: core_theme, psychological_interpretation, emotional_interpretation, current_coordination, potential_tension, supportive_response, coordination_practice, journal_question, wellness_tags. wellness_tags must be a short JSON array of strings. Do not add markdown or commentary outside the JSON.'''
    for attempt in range(6):
        seed=_unique_generation_seed(user_id,'planet_'+pname.lower(),context_key,journal_context,attempt)
        prompt=instruction+'\n'+schema+f'''\nUNIQUENESS REQUIREMENT:
Compose this from the exact evidence packet. Do not reuse a sign template, another planet report, another member report, or a prior cycle report. Internal composition seed (never print): {seed}. Attempt {attempt+1}.\nINTERNAL FACTUAL DATA:
'''+json.dumps(data,default=str)
        structured=_openai_structured(prompt,'planetary_coordination',CC_REPORT_JSON_SCHEMA) or _cc_parse_json_object(_openai_text(prompt))
        if not structured:
            continue
        candidate=_cc_planet_structured_text(pname,structured,other_view)
        low=candidate.lower()
        if not _cc_report_quality_ok(candidate,source_profile) or not any(term in low for term in required_terms):
            continue
        duplicate,_=_reading_similarity_status(candidate)
        if duplicate:
            continue
        if _register_unique_reading(user_id,'planet_'+pname.lower(),context_key,candidate):
            return candidate,structured,True
    for variant in range(12):
        candidate=(fallback_factory(variant) or '').strip()
        low=candidate.lower()
        if not _cc_report_quality_ok(candidate,source_profile) or not any(term in low for term in required_terms):
            continue
        duplicate,_=_reading_similarity_status(candidate)
        if duplicate:
            continue
        if _register_unique_reading(user_id,'planet_'+pname.lower(),context_key,candidate):
            return candidate,{'fallback':True},False
    # Never leave a member-facing card empty merely because the uniqueness guard
    # exhausted every generated candidate. Use the evidence-bound deterministic
    # fallback as the last-resort communication layer and log that calibration is needed.
    candidate=(fallback_factory(99) or '').strip()
    if not candidate:
        candidate=f"This {pname} reflection is anchored to your current Lunar-cycle calculation. Notice what is most active in this function, give yourself enough space to respond deliberately, and choose one concrete practice that fits the situation in front of you."
    app.logger.warning('Planetary report uniqueness guard exhausted for user=%s planet=%s cycle=%s; serving evidence-bound fallback',user_id,pname,context_key)
    return candidate,{'fallback':True,'uniqueness_guard_exhausted':True},False


def _planet_reflection_payload(user_id,pname,viewer_id=None):
    canonical={x.lower():x for x in PLANET_NAMES}
    pname=canonical.get((pname or '').lower(),pname if pname in PLANET_NAMES else None)
    if not pname:
        return None
    display_name='Lunar' if pname=='Moon' else pname
    conn=db()
    member=conn.execute('SELECT * FROM users WHERE id=?',(user_id,)).fetchone()
    cp=conn.execute('SELECT * FROM connection_profiles WHERE user_id=?',(user_id,)).fetchone()
    conn.close()
    if not member:
        return None
    chart=member_chart_data(member)
    if not chart.get('ready'):
        return {'ready':False,'reason':'Birth information is needed before this reflection can be calculated.'}
    sky=current_sky_data(); lunar_cycle=_current_lunar_cycle_chart(sky)
    monthly_snapshot=_personal_monthly_coordination_snapshot(user_id)
    planet_snapshot=((monthly_snapshot.get('planetary') or {}).get(pname) or {}) if monthly_snapshot.get('ready') else {}
    relevant_aspects=[a for a in _chart_sky_aspects(chart,sky) if a.get('natal_planet')==pname or a.get('current_planet')==pname][:5]
    cycle_aspects=[a for a in (_chart_sky_aspects(chart,lunar_cycle) if lunar_cycle.get('planets') else []) if a.get('natal_planet')==pname or a.get('current_planet')==pname][:5]
    placement=(chart.get('planets') or {}).get(pname,{})
    sign_tone=SIGN_BEHAVIORAL_TONES.get(placement.get('sign',''),{})
    try: placement_degree=float(placement.get('degree',0) or 0)
    except (TypeError,ValueError): placement_degree=0.0
    placement_phase=('early-sign expression' if placement_degree<10 else 'middle-sign expression' if placement_degree<20 else 'late-sign expression')
    profile=dict(cp) if cp else {}; wellness=_member_wellness_practices(profile); lens=PLANET_BEHAVIORAL_LENSES.get(pname,{})
    profile_slice=_planet_profile_slice(profile,pname)
    use_private=(viewer_id is None or int(viewer_id)==int(user_id))
    other_view=not use_private
    journal_context=_cc_journal_evidence_packet(_all_journal_context(user_id)) if use_private else {
        'entry_count':0,'history_fingerprint':'private-not-shared','current_themes':[],'theme_strength':{},'theme_counts':{},
        'privacy':'Private Journal material is excluded from another member’s report.'}
    planet_fingerprint_packet={
        'member_id':user_id,
        'planet':pname,
        'lunar_cycle_id':lunar_cycle.get('cycle_id',''),
        'coordination_score':planet_snapshot.get('coordination_score'),
        'activation_score':planet_snapshot.get('activation_score'),
        'natal_planets':{k:{'longitude':v.get('longitude'),'sign':v.get('sign'),'house':v.get('house')} for k,v in (chart.get('planets') or {}).items()},
        'natal_aspects':chart.get('aspects',[]),
        'focus_placement':placement,
        'current_planets':{k:{'longitude':v.get('longitude'),'sign':v.get('sign')} for k,v in (sky.get('planets') or {}).items()},
        'relevant_current_aspects':relevant_aspects,
        'relevant_lunar_cycle_aspects':cycle_aspects,
        'lunar_cycle_id':lunar_cycle.get('cycle_id',''),
        'behavioral_profile':profile_slice,
        'wellness_practices':wellness,
        'journal_history_fingerprint':journal_context.get('history_fingerprint',''),
        'privacy_scope':'owner-private' if use_private else 'member-shared-no-private-journal',
        'writing_mode_version':2 if other_view else 1,
        'engine_version':REFLECTION_ENGINE_VERSION,
    }
    planet_context_fingerprint=hashlib.sha256(json.dumps(planet_fingerprint_packet,sort_keys=True,default=str).encode('utf-8')).hexdigest()
    scope_key='owner' if use_private else f'shared-{int(viewer_id or 0)}'
    context_key=f'{pname}|cycle:{lunar_cycle.get("cycle_id","")}|scope:{scope_key}|writing:{2 if other_view else 1}|v:{CC_ENGINE_VERSION}'
    reflection_type='planet_'+pname.lower()
    conn=db(); row=conn.execute('SELECT payload FROM astrology_reflections WHERE user_id=? AND reflection_type=? AND period_key=?',(user_id,reflection_type,context_key)).fetchone(); conn.close()
    if row:
        try: cached=json.loads(row['payload'])
        except Exception: cached={}
        if cached.get('engine_version')==REFLECTION_ENGINE_VERSION and cached.get('context_fingerprint')==planet_context_fingerprint and cached.get('text') and cached.get('spoken'):
            return cached

    data={
        'member':{'name':member['name'],'city':member['city']},'member_id':user_id,'focus_planet':pname,
        'focus_question':lens.get('question',''),'behavioral_focus':lens.get('focus',[]),'watch_for':lens.get('watch',''),
        'relevant_profile_only':profile_slice,'wellness_practices':wellness,'full_chart_internal':chart,
        'current_sky_internal':sky,'lunar_cycle_chart_internal':lunar_cycle,
        'relevant_current_to_natal_aspects_internal':relevant_aspects,
        'relevant_lunar_cycle_to_natal_aspects_internal':cycle_aspects,'placement_internal':placement,
        'sign_specific_behavioral_tone_internal':sign_tone,'placement_phase_internal':placement_phase,
        'calculated_monthly_coordination':{'coordination_score':planet_snapshot.get('coordination_score'),'activation_score':planet_snapshot.get('activation_score'),'evidence':planet_snapshot},
        'journal_history':journal_context}

    planet_headings={
        'Sun':['Your Direction','Where You May Be Holding Back','What Supports Authentic Choice','A Question to Carry With You'],
        'Moon':['Your Emotional Rhythm','What Your System May Be Asking For','What Could Support Recovery','A Question to Carry With You'],
        'Mercury':['Your Communication Pattern','Where Meaning Can Get Lost','A Clearer Way to Respond','A Question to Carry With You'],
        'Venus':['Connection & Reciprocity','Where Your Energy Is Being Invested','What Mutuality Could Look Like','A Question to Carry With You'],
        'Mars':['Action & Boundaries','Where Frustration May Be Building','A Direct Next Step','A Question to Carry With You'],
        'Jupiter':['Growth & Opportunity','Where More Could Become Too Much','A Grounded Expansion','A Question to Carry With You'],
        'Saturn':['Responsibility & Structure','What Needs Clearer Limits','What Is Sustainable','A Question to Carry With You'],
    }.get(pname,['Your Current Pattern','What Deserves Attention','What May Support You','A Question to Carry With You'])
    perspective_instruction=(f'''OTHER-MEMBER WRITING MODE: Write to the viewer about {member['name']}. Use “{member['name']}”, “this member”, “they” and “their”; never imply that the viewer owns this placement. Do not use private grounding, private reflection questions, private Journal themes or self-directed “you/your” language about the chart. The current_coordination, supportive_response and coordination_practice fields must tell the viewer how they may connect with this member using the supplied evidence. The journal_question field must instead be a concise relational Connection Consideration.''' if other_view else '''SELF WRITING MODE: Preserve the established self-facing “you/your” voice, personal grounding, practices and reflection-question structure.''')
    instruction=f'''Write a Conscious Coordination interpretation for the member’s {display_name} placement.

{perspective_instruction}

THIS PLACEMENT IS:
{display_name} in {placement.get('sign','')}

The actual sign must meaningfully change how this planet’s behavioral function is interpreted. The full chart, current planetary/lunar conditions, self-reported profile, wellness practices and permitted private context are evidence; this is never a reusable sign paragraph.

The final report must demonstrate the unique intersection of {display_name}'s human function with {placement.get('sign','')}'s specific strength, pressure pattern and reflective question. An interpretation that could be reused unchanged for the same planet in another sign is invalid. The early/middle/late position within the sign is also internal evidence and should subtly change emphasis without exposing degree mechanics.

This report’s behavioral question is: "{lens.get('question','')}"
Behavioral focus: {', '.join(lens.get('focus',[]))}
The deterministic engine calculated this lunar-cycle Coordination score before writing: {planet_snapshot.get('coordination_score','')}%.
The deterministic engine separately calculated Activation: {planet_snapshot.get('activation_score','')}%. A lower coordination score with high activation means this area is highly relevant and may require more conscious effort; it does not mean the member is "bad" at this planetary function.

PUBLIC LANGUAGE:
- Keep the experience under Conscious Coordination.
- If the internal focus is Moon, call it Lunar publicly.
- Never explain technical chart mechanics, degrees, aspect names/orbs, data fields or model process.
- Never quote Journal entries or say “Your Journal says.”
- Use possibility language, not diagnosis or deterministic horoscope language.

THIS PLANET HAS ITS OWN JOB:
Sun = self-direction, identity, confidence and owning choices.
Moon = emotional safety, stress, regulation and recovery.
Mercury = thinking, interpretation, communication and assumptions.
Venus = affection, reciprocity, values, attraction and investment.
Mars = action, assertion, frustration, anger and boundaries.
Jupiter = growth, opportunity, beliefs, risk and overextension.
Saturn = responsibility, fear, limits, patience, discipline and long-term structure.

Use this planet’s own member-facing section structure rather than a shared generic template:
{chr(10).join('- '+h for h in planet_headings)}

The section names and content must make this planetary function feel meaningfully different from every other planetary report. Make it practical, psychologically thoughtful, non-diagnostic and non-deterministic. Do not recycle another planet/member/day/cycle report.'''
    required_terms={'Sun':['choice','direction','own'],'Moon':['emotion','regulat','safety'],'Mercury':['communicat','assum','interpret'],'Venus':['reciproc','affection','invest'],'Mars':['action','boundar','frustrat'],'Jupiter':['opportun','expand','risk'],'Saturn':['responsib','limit','disciplin']}.get(pname,[])
    def fallback_factory(variant):
        base=_planet_fallback_guidance(pname,profile,wellness,sky,relevant_aspects,placement,journal_context,lunar_cycle,user_id,variant,planet_snapshot.get('coordination_score'),planet_snapshot.get('activation_score'))
        if not other_view:
            return base
        # The generator is normally used above; this evidence-bound fallback keeps
        # the public perspective correct even when the language service is offline.
        cleaned=base.replace('Your ',f'{member["name"]}’s ').replace('your ','their ').replace('You may','This member may').replace('you may','they may').replace(' you ',' they ')
        return f'''How This May Operate in This Member\n\n{cleaned}\n\nHow to Connect With This Member\n\nYou may find coordination easier when you allow this member’s {lens.get('question','behavioral rhythm').lower()} to become visible through direct questions, clear expectations and enough time for an honest response.\n\nConnection Consideration\n\nNotice what helps this connection stay reciprocal without assuming that a pause, boundary or different pace has only one possible meaning.'''
    text,structured_sections,_=_cc_generate_planet_structured_report(user_id,pname,context_key,instruction,data,fallback_factory,required_terms,other_view)

    spoken_instruction=f'''Create ONLY the spoken listening script for this exact {display_name} Conscious Coordination report.
Use the written report below as meaning to preserve, not wording to read verbatim.
Speak warmly, naturally and reflectively. Do not announce webpage headings. Do not discuss astrology mechanics, data sources, Journal history, degrees, aspects, algorithms, or diagnosis.
The spoken script must remain specifically about {display_name}'s human function and must not become a generic meditation.

WRITTEN REPORT FOR CONTEXT ONLY:
{text}'''
    spoken_data={'member_id':user_id,'focus_planet':pname,'written_report_for_context_only':text,'journal_history':journal_context,'placement_internal':placement,'current_sky_internal':sky}
    spoken=_cc_safe_spoken_script(user_id,reflection_type+'_spoken',context_key,spoken_instruction,spoken_data,text,display_name+' Conscious Coordination')
    conn=db(); existing_report=conn.execute('SELECT report_version,context_fingerprint FROM coordination_reports WHERE user_id=? AND other_user_id=? AND report_type=? AND period_key=?',(user_id,0,'planetary_'+pname.lower()+'_monthly',context_key)).fetchone(); conn.close()
    report_version=(int(existing_report['report_version'] or 1)+(1 if existing_report['context_fingerprint']!=planet_context_fingerprint else 0)) if existing_report else 1
    audio_key=hashlib.sha256((context_key+'|'+hashlib.sha256(text.encode()).hexdigest()).encode()).hexdigest()[:16]
    payload={'ready':True,'engine_version':REFLECTION_ENGINE_VERSION,'planet':pname,'display_name':display_name,'member':{'id':user_id,'name':member['name']},
        'placement':placement,'coordination_score':planet_snapshot.get('coordination_score'),'activation_score':planet_snapshot.get('activation_score'),'lunar_cycle_id':lunar_cycle.get('cycle_id',''),'text':text,'spoken':spoken,'structured_sections':structured_sections,'period_key':context_key,
        'report_version':report_version,'audio_key':audio_key,'context_fingerprint':planet_context_fingerprint,'report_type':'planetary_'+pname.lower()+'_monthly','other_storage_id':0,'period_key':context_key,
        'privacy_scope':'owner-private' if use_private else 'member-shared-no-private-journal'}
    evidence_summary={'coordination_score':planet_snapshot.get('coordination_score'),'activation_score':planet_snapshot.get('activation_score'),'lunar_cycle_id':lunar_cycle.get('cycle_id',''),'planet':pname,'structured_sections':structured_sections,'privacy_scope':payload['privacy_scope']}
    normalized=_normalize_report_text(text); digest=hashlib.sha256(normalized.encode()).hexdigest()
    conn=db()
    conn.execute('''INSERT INTO astrology_reflections(user_id,reflection_type,period_key,payload,created_at)
        VALUES(?,?,?,?,?) ON CONFLICT(user_id,reflection_type,period_key) DO UPDATE SET payload=excluded.payload,created_at=excluded.created_at''',
        (user_id,reflection_type,context_key,json.dumps(payload),now()))
    conn.execute('''INSERT INTO coordination_reports(user_id,other_user_id,report_type,period_key,report_version,written_report,spoken_script,audio_reference,evidence_summary,privacy_scope,context_fingerprint,normalized_text_hash,created_at,updated_at)
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(user_id,other_user_id,report_type,period_key) DO UPDATE SET report_version=excluded.report_version,written_report=excluded.written_report,spoken_script=excluded.spoken_script,audio_reference=excluded.audio_reference,evidence_summary=excluded.evidence_summary,privacy_scope=excluded.privacy_scope,context_fingerprint=excluded.context_fingerprint,normalized_text_hash=excluded.normalized_text_hash,updated_at=excluded.updated_at''',
        (user_id,0,'planetary_'+pname.lower()+'_monthly',context_key,report_version,text,spoken,'planet-audio:'+audio_key,json.dumps(evidence_summary,default=str),payload['privacy_scope'],planet_context_fingerprint,digest,now(),now()))
    conn.commit(); conn.close()
    return payload


