def _business_month_shift(year, month, delta):
    total=year*12+(month-1)+delta
    return total//12, total%12+1

def _booking_minutes(value, default):
    match=re.search(r'(\d+)',str(value or ''))
    return max(0,int(match.group(1))) if match else default

def _booking_clock(value):
    text=str(value or '').strip().upper().replace('.','')
    for fmt in ('%I:%M %p','%I %p','%H:%M'):
        try: return datetime.strptime(text,fmt).time()
        except ValueError: pass
    return None

def _sync_weekly_booking_slots(conn,business,settings,days_ahead=90):
    """Materialize owner rules into the same calendar used by public booking."""
    business_id=business['id']; conn.execute("DELETE FROM business_calendar WHERE business_id=? AND source='Weekly Availability'",(business_id,))
    day_names={x.strip().lower() for x in re.split(r'[,;/]+',settings.get('available_days','')) if x.strip()}
    times=re.split(r'\s*(?:–|—|-)\s*',settings.get('available_times',''),maxsplit=1)
    if len(times)!=2 or not day_names: return 0
    start_clock,end_clock=_booking_clock(times[0]),_booking_clock(times[1])
    if not start_clock or not end_clock: return 0
    duration=max(5,_booking_minutes(settings.get('duration'),60)); buffer_minutes=_booking_minutes(settings.get('buffer'),0)
    blocked={x.strip() for x in re.split(r'[,;]+',settings.get('blocked_dates','')) if re.fullmatch(r'\d{4}-\d{2}-\d{2}',x.strip())}
    existing=conn.execute("SELECT event_date,start_time,end_time FROM business_calendar WHERE business_id=? AND booking_status<>'Cancelled'",(business_id,)).fetchall()
    busy={}
    for row in existing: busy.setdefault(row['event_date'],[]).append((row['start_time'],row['end_time']))
    inserted=0; today=datetime.utcnow().date()
    for offset in range(days_ahead+1):
        day=today+timedelta(days=offset); ds=day.isoformat()
        if day.strftime('%A').lower() not in day_names or ds in blocked: continue
        cursor=datetime.combine(day,start_clock); end_day=datetime.combine(day,end_clock)
        while cursor+timedelta(minutes=duration)<=end_day:
            service_end=cursor+timedelta(minutes=duration); protected_end=service_end+timedelta(minutes=buffer_minutes)
            start_text=cursor.strftime('%H:%M'); end_text=service_end.strftime('%H:%M')
            collision=any(not (protected_end.strftime('%H:%M')<=a or start_text>=z) for a,z in busy.get(ds,[]))
            if not collision:
                conn.execute('''INSERT INTO business_calendar(business_id,title,event_type,event_date,start_time,end_time,location,capacity,booking_status,notes,source,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)''',(business_id,'Appointment','Appointment',ds,start_text,end_text,'','1','Open',f'{duration}-minute appointment; {buffer_minutes}-minute buffer; {settings.get("timezone") or "Business local time"}.','Weekly Availability',now(),now()))
                busy.setdefault(ds,[]).append((start_text,protected_end.strftime('%H:%M'))); inserted+=1
            cursor=service_end+timedelta(minutes=buffer_minutes)
    return inserted

def business_calendar_grid(events, business_id, selected_date='', month_value='', owner=False):
    today=datetime.utcnow().date()
    try:
        if month_value:
            year,month=[int(x) for x in month_value.split('-',1)]
            datetime(year,month,1)
        else:
            year,month=today.year,today.month
    except Exception:
        year,month=today.year,today.month
    by_date={}
    for e in events:
        by_date.setdefault(e['event_date'],[]).append(e)
    prev_y,prev_m=_business_month_shift(year,month,-1); next_y,next_m=_business_month_shift(year,month,1)
    if owner:
        prev_link=url_for('business_calendar_page',month=f'{prev_y:04d}-{prev_m:02d}')+'#business-calendar'
        next_link=url_for('business_calendar_page',month=f'{next_y:04d}-{next_m:02d}')+'#business-calendar'
    else:
        prev_link=url_for('business_app',business_id=business_id,month=f'{prev_y:04d}-{prev_m:02d}')+'#business-calendar'
        next_link=url_for('business_app',business_id=business_id,month=f'{next_y:04d}-{next_m:02d}')+'#business-calendar'
    headers=''.join(f'<div class="calendar-label" style="font-weight:800;padding:8px">{d}</div>' for d in ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'])
    cells=[]
    for week in pycalendar.Calendar(firstweekday=6).monthdayscalendar(year,month):
        for day in week:
            if not day:
                cells.append('<div class="calendar-cell" style="background:#faf7fc"></div>')
                continue
            ds=f'{year:04d}-{month:02d}-{day:02d}'; rows=by_date.get(ds,[])
            open_rows=[e for e in rows if e['booking_status']=='Open' and e['event_type']!='Blocked / Unavailable']
            blocked=[e for e in rows if e['event_type']=='Blocked / Unavailable' or e['booking_status'] in ('Private','Full')]
            selected='box-shadow:0 0 0 3px #a978c7 inset;' if selected_date==ds else ''
            if owner:
                href=url_for('business_calendar_page',month=f'{year:04d}-{month:02d}',date=ds)+'#calendar-day'
            elif open_rows:
                href=url_for('business_app',business_id=business_id,month=f'{year:04d}-{month:02d}',date=ds)+'#book-times'
            else:
                href=''
            badges=[]
            if open_rows: badges.append(f'<span class="badge" style="margin-top:5px">{len(open_rows)} open</span>')
            if blocked: badges.append('<span class="badge" style="margin-top:5px;background:#f8e9ef">busy</span>')
            inner=f'<b>{day}</b><div>{"".join(badges)}</div>'
            tag=f'<a href="{href}" style="display:block;color:inherit;height:100%">{inner}</a>' if href else inner
            cells.append(f'<div class="calendar-cell" style="{selected}">{tag}</div>')
    title=datetime(year,month,1).strftime('%B %Y')
    return f'''<div class="card calendar-card" id="business-calendar"><div class="calendar-head"><a class="out" href="{prev_link}">‹ Previous</a><h2>{title}</h2><a class="out" href="{next_link}">Next ›</a></div><div class="calendar-grid">{headers}{''.join(cells)}</div><p class="muted small">Open dates can be selected. Busy/blocked time is shown so the same calendar can protect classes, appointments, events and Retreats from collisions.</p></div>'''

def _hosted_app_render(b,media,events,preview=False,owner=False,draft=None):
    draft=draft or {}
    def get(key,default=''):
        if key in draft and draft.get(key) not in (None,''): return draft.get(key)
        try: return b[key] if key in b.keys() and b[key] is not None else default
        except Exception: return default
    business_id=get('id',0); name=html.escape(str(get('name','Your Business'))); logo_name=get('logo_name',''); cover_name=get('cover_name','')
    logo_html=(f'<img src="{business_media_src(logo_name)}" alt="{name} logo" style="{_logo_crop_css(get("logo_crop","{}"))}">' if logo_name else '<div class="branded-placeholder">LOGO</div>')
    if cover_name:
        src=business_media_src(cover_name)
        cover_html=(f'<video controls playsinline src="{src}"></video>' if get('cover_type')=='video' else f'<img src="{src}" alt="{name} cover" style="object-fit:contain;object-position:center;transform:none">')
    else: cover_html='<div class="branded-placeholder">The Seasons Within • Business Cover</div>'
    galleries=[m for m in media if m['media_kind']=='gallery']; videos=[m for m in media if m['media_kind']=='video']
    content=[]
    if business_id:
        conn=db()
        content=conn.execute('SELECT * FROM hosted_app_content WHERE business_id=? AND published=1 ORDER BY content_type,sort_order,id',(business_id,)).fetchall()
        conn.close()
    enabled=set((draft.get('enabled_modules') or get('enabled_modules','home,about,contact,booking')).split(','))
    draft_order=[x.strip() for x in (draft.get('section_order') or '').split(',') if x.strip()]
    order=(draft_order+[x for x in _module_order(b) if x not in draft_order]) if draft_order else _module_order(b)
    external=[]
    for label,key in [('Website','website'),('Instagram','instagram'),('TikTok','tiktok'),('YouTube','youtube'),('Facebook','facebook'),('Store','store_url'),('Podcast','podcast_url')]:
        if get(key): external.append(f'<a class="out" href="{html.escape(str(get(key)))}" target="_blank" rel="noopener">{label}</a>')
    ext_html='<div class="actions">'+''.join(external)+'</div>' if external else ''
    step_sections={1:'branding',2:'about',3:'services',4:'booking',5:'gallery',6:'contact'}
    edit=lambda step: (f'<a class="out" href="{url_for("hosted_app_edit_section",section=step_sections.get(step,"sections"))}">Edit</a>' if owner else '')
    sections={}
    description=html.escape(str(get('description',''))); story=html.escape(str(get('story',''))); offers=html.escape(str(get('offers','')))
    sections['home']=f'''<section id="home"><div class="crop-stage cover-crop">{cover_html}</div><article class="card"><div class="splitlabel"><span class="badge">HOME</span>{edit(1)}</div><div class="profilehero"><div><h1>{name}</h1><h3>{html.escape(str(get('owner_title') or get('category')))}</h3><p class="muted">{html.escape(str(get('location')))} • {html.escape(str(get('tagline')))}</p></div><div class="crop-stage logo-crop" style="width:110px;margin:0">{logo_html}</div></div>{ext_html}</article></section>'''
    if description or story:
        sections['about']=f'''<section id="about"><article class="card"><div class="splitlabel"><span class="badge">ABOUT</span>{edit(2)}</div><h2>About {name}</h2>{f'<p>{description}</p>' if description else ''}{f'<h3>Our Story</h3><p>{story}</p>' if story else ''}</article></section>'''
    content_by_type={k:[] for k,_ in HOSTED_APP_MODULES}
    for item in content: content_by_type.setdefault(item['content_type'],[]).append(item)
    def content_card(item,kind):
        detail=_safe_json(item['details'],{})
        image=f'<img src="{business_media_src(item["image_name"])}" alt="{html.escape(item["title"])}" style="width:100%;max-height:280px;object-fit:cover;border-radius:14px">' if item['image_name'] else ''
        facts=[]
        labels={'instructor':'Instructor','price':'Price','format':'Format','location':'Location','duration':'Duration','capacity':'Capacity','date':'Date','times':'Times','availability':'Availability','requirements':'Requirements'}
        for key,label in labels.items():
            if detail.get(key): facts.append(f'<p><b>{label}:</b> {html.escape(str(detail[key]))}</p>')
        lessons=''
        if kind=='courses' and detail.get('lessons'):
            lessons='<div class="card"><h4>Lessons / Modules</h4>'+''.join(f'''<div><b>{html.escape(str(x.get('title','Lesson')))}</b>{f'<p>{html.escape(str(x.get("content","")))}</p>' if x.get('content') else ''}{f'<p><a class="out" href="{html.escape(str(x.get("video_url")))}" target="_blank" rel="noopener">Watch lesson video</a></p>' if x.get('video_url') else ''}</div>''' for x in detail['lessons'] if isinstance(x,dict))+'</div>'
        video=f'<p><a class="out" href="{html.escape(item["video_url"])}" target="_blank" rel="noopener">Watch Video</a></p>' if item['video_url'] else ''
        action=detail.get('booking_url') or detail.get('registration_url') or detail.get('enrollment_url') or detail.get('link_url')
        button=f'<p><a class="btn" href="{html.escape(str(action))}" target="_blank" rel="noopener">{html.escape(str(detail.get("action_label") or "Book / Learn More"))}</a></p>' if action else ''
        return f'''<article class="card">{image}<h3>{html.escape(item['title'])}</h3>{f'<p>{html.escape(item["description"])}</p>' if item['description'] else ''}{''.join(facts)}{video}{lessons}{button}</article>'''
    service_cards=''.join(content_card(x,'services') for x in content_by_type.get('services',[]))
    if offers or service_cards: sections['services']=f'''<section id="services"><div class="splitlabel"><h2>Services</h2>{edit(3)}</div>{f'<article class="card"><p>{offers}</p></article>' if offers else ''}<div class="grid">{service_cards}</div></section>'''
    grouped={'classes':[],'courses':[],'events':[],'retreats':[]}
    for e in events:
        typ=(e['event_type'] or '').lower()
        if typ in {'class','program'}: grouped['classes'].append(e)
        elif typ=='course': grouped['courses'].append(e)
        elif typ=='retreat': grouped['retreats'].append(e)
        elif typ not in {'blocked / unavailable','availability','appointment'}: grouped['events'].append(e)
    for key,title in [('classes','Classes'),('courses','Courses'),('events','Events'),('retreats','Retreats')]:
        rows=grouped[key]
        saved=content_by_type.get(key,[])
        if rows or saved:
            cards=''.join(content_card(x,key) for x in saved)+''.join(f'<article class="card"><h3>{html.escape(e["title"])}</h3><p>{e["event_date"]} • {e["start_time"]}–{e["end_time"]}</p><p>{html.escape(e["location"] or "")}</p></article>' for e in rows[:8])
            sections[key]=f'<section id="{key}"><div class="splitlabel"><h2>{title}</h2>{edit(4)}</div><div class="grid">{cards}</div></section>'
    if videos:
        cards=''.join(f'''<article class="card"><video controls playsinline src="{business_media_src(m['file_name'])}"></video><h3>{html.escape(m['title'] or 'Business Video')}</h3>{f'<p>{html.escape(m["description"])}</p>' if m['description'] else ''}</article>''' for m in videos)
        sections['videos']=f'<section id="videos"><div class="splitlabel"><h2>Videos</h2>{edit(5)}</div><div class="grid">{cards}</div></section>'
    if galleries and int(get('gallery_enabled',1) or 0):
        cards=''.join(f'''<article class="card"><div class="crop-stage gallery-crop"><img src="{business_media_src(m['file_name'])}" alt="{html.escape(m['title'] or 'Business gallery photo')}" style="{_crop_css(m['crop_data'] if 'crop_data' in m.keys() else '{}')}"></div>{f'<h3>{html.escape(m["title"])}</h3>' if m['title'] else ''}{f'<p>{html.escape(m["description"])}</p>' if m['description'] else ''}</article>''' for m in galleries)
        sections['gallery']=f'<section id="gallery"><div class="splitlabel"><h2>Gallery</h2>{edit(5)}</div><div class="grid">{cards}</div></section>'
    for key,title in [('media_kit','Media Kit'),('affiliate','Affiliate Links')]:
        saved=content_by_type.get(key,[])
        if saved: sections[key]=f'<section id="{key}"><div class="splitlabel"><h2>{title}</h2>{edit(6)}</div><div class="grid">{"".join(content_card(x,key) for x in saved)}</div></section>'
    if get('contact_email') or get('contact_phone') or external:
        sections['contact']=f'''<section id="contact"><article class="card"><div class="splitlabel"><span class="badge">CONTACT</span>{edit(6)}</div><h2>Contact {name}</h2>{f'<p><b>Email:</b> {html.escape(str(get("contact_email")))}</p>' if get('contact_email') else ''}{f'<p><b>Phone:</b> {html.escape(str(get("contact_phone")))}</p>' if get('contact_phone') else ''}{ext_html}</article></section>'''
    open_events=[e for e in events if e['booking_status']=='Open' and e['event_type']!='Blocked / Unavailable']
    booking_method=get('booking_method','seasons_calendar') or 'seasons_calendar'
    if business_id and booking_method=='seasons_calendar':
        try: public_booking_settings=json.loads(get('booking_settings','{}') or '{}')
        except Exception: public_booking_settings={}
        timezone_label=public_booking_settings.get('timezone') or 'Business local time'
        month=request.args.get('month',''); selected=request.args.get('date',''); calendar_html=business_calendar_grid(events,business_id,selected,month,False)
        public_slots=([e for e in open_events if e['event_date']==selected] if selected else open_events[:8])
        slots=''.join(f'''<article class="card"><span class="badge">{e['event_type']}</span><h3>{html.escape(e['title'])}</h3><p><b>{e['event_date']}</b> • {e['start_time']}–{e['end_time']}</p><a class="btn" href="{url_for('business_book',business_id=business_id,calendar_id=e['id'])}">Choose This Time</a></article>''' for e in public_slots)
        sections['booking']=f'''<section id="booking"><div class="splitlabel"><h2>Book / Booking</h2>{edit(4)}</div><p class="muted small">Choose an available date and time. Times are shown in {html.escape(timezone_label)}.</p>{calendar_html}{f'<div class="grid">{slots}</div>' if slots else ''}</section>'''
    elif booking_method=='external' and get('booking_url'):
        sections['booking']=f'''<section id="booking"><article class="card"><div class="splitlabel"><span class="badge">BOOKING</span>{edit(4)}</div><h2>Book with {name}</h2><a class="btn" href="{html.escape(str(get('booking_url')))}" target="_blank" rel="noopener">Open Booking Website</a></article></section>'''
    elif booking_method!='none' and 'booking' in enabled:
        sections['booking']=f'''<section id="booking"><article class="card"><div class="splitlabel"><span class="badge">BOOKING</span>{edit(4)}</div><h2>Booking</h2><p class="muted">Booking will display here when availability or a booking link is added.</p></article></section>'''
    if get('affiliate_links'): sections['affiliate']=f'''<section id="affiliate"><article class="card"><div class="splitlabel"><span class="badge">AFFILIATE LINKS</span>{edit(6)}</div><p>{html.escape(str(get('affiliate_links')))}</p></article></section>'''
    # Every enabled module belongs on this app's dashboard immediately. Content
    # remains stored independently, so disabling a module hides rather than deletes it.
    module_labels=dict(HOSTED_APP_MODULES)
    content_editors=set(_HOSTED_CONTENT_FIELDS)
    for key in order:
        if key not in enabled or key in sections or key not in module_labels:
            continue
        owner_action=(f'<a class="out" href="{url_for("hosted_app_content_editor",kind=key)}">Add Content</a>' if owner and key in content_editors else '')
        sections[key]=f'''<section id="{key}"><article class="card"><div class="splitlabel"><span class="badge">{html.escape(module_labels[key].upper())}</span>{owner_action}</div><h2>{html.escape(module_labels[key])}</h2><p class="muted">This section is enabled. Published information will appear here.</p></article></section>'''
    visible=[key for key in order if key in sections and key in enabled]
    nav=''.join(f'<a class="chip" href="#{key}">{dict(HOSTED_APP_MODULES).get(key,key.title())}</a>' for key in visible)
    return f'''<div class="chips">{nav}</div>{''.join(sections[key] for key in visible)}'''

def _owner_business_bundle(user_id):
    conn=db(); b=conn.execute('SELECT * FROM businesses WHERE owner_id=? ORDER BY active DESC,updated_at DESC,id DESC LIMIT 1',(user_id,)).fetchone()
    if not b: conn.close(); return None,[],[]
    media=conn.execute('SELECT * FROM business_media WHERE business_id=? ORDER BY media_kind,sort_order,id',(b['id'],)).fetchall()
    events=conn.execute("SELECT * FROM business_calendar WHERE business_id=? AND booking_status<>'Cancelled' ORDER BY event_date,start_time",(b['id'],)).fetchall(); conn.close()
    return b,media,events

def _touch_crop_form(kind,title,current='',media_id=0,accept='image/*',crop_data='{}'):
    guide='logo-guide' if kind=='logo' else ('cover-guide' if kind=='cover' else 'gallery-guide')
    min_zoom='.25' if kind=='logo' else '1'
    crop=_safe_json(crop_data,{'x':50,'y':50,'zoom':1,'rotate':0})
    try:
        crop_x=max(0,min(100,float(crop.get('x',50) or 50))); crop_y=max(0,min(100,float(crop.get('y',50) or 50)))
        crop_zoom=max(float(min_zoom),min(3,float(crop.get('zoom',1) or 1)))
    except Exception:
        crop_x,crop_y,crop_zoom=50,50,1
    source=f'<img src="{current}" alt="Current {html.escape(title)}">' if current else '<img alt="Selected photo">'
    help_text=('Zoom out or reposition the logo until the complete design, text and edges are visible.' if kind=='logo' else 'Drag the actual photo with your finger. Pinch or use the one zoom control.')
    return f'''<form class="card touch-crop-form" method="post" enctype="multipart/form-data" action="{url_for('hosted_app_media_save')}"><h2>{html.escape(title)}</h2><input type="hidden" name="kind" value="{kind}"><input type="hidden" name="media_id" value="{media_id}"><input type="hidden" name="crop_x" value="{crop_x}"><input type="hidden" name="crop_y" value="{crop_y}"><input type="hidden" name="crop_zoom" value="{crop_zoom}"><input type="hidden" name="crop_rotate" value="0"><div class="touch-crop {guide}">{source}</div><label><b>Choose Photo</b><input class="input photo-input" type="file" name="media_file" accept="{accept}" {'required' if not current else ''}></label><label>Zoom<input class="input zoom-only" type="range" min="{min_zoom}" max="3" step=".05" value="{crop_zoom}"></label><p class="muted small">{help_text}</p><div class="actions"><a class="out" href="{url_for('hosted_app_editor')}">Cancel</a><button class="btn">Save Photo</button>{('<button class="out danger" name="remove" value="1">Remove</button>' if current else '')}</div></form>'''

_HOSTED_EDITOR_STYLE='''<style>.app-editor-card{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center;padding:17px;border:1px solid var(--line);border-radius:18px;background:#fff;box-shadow:var(--shadow);margin:12px 0}.editor-thumbs{display:flex;gap:8px;flex-wrap:wrap}.editor-thumb{width:72px;height:72px;border-radius:13px;object-fit:cover}.editor-cover{width:140px;height:78px;border-radius:13px;object-fit:cover}.touch-crop{position:relative;width:100%;overflow:hidden;background:#e9deef;touch-action:none;display:grid;place-items:center}.touch-crop.logo-guide{aspect-ratio:1}.touch-crop.cover-guide{aspect-ratio:16/9}.touch-crop.gallery-guide{aspect-ratio:4/3}.touch-crop img{position:absolute;width:100%;height:100%;object-fit:cover;transform-origin:center;user-select:none;pointer-events:none}.touch-crop.logo-guide img{object-fit:contain}.touch-crop.logo-guide:after{content:"";position:absolute;inset:8%;border:3px solid white;border-radius:50%;box-shadow:0 0 0 999px rgba(30,18,36,.25)}.touch-crop.cover-guide:after,.touch-crop.gallery-guide:after{content:"";position:absolute;inset:5%;border:3px solid white;border-radius:10px;box-shadow:0 0 0 999px rgba(30,18,36,.2)}.section-menu{position:relative}.section-menu summary{font-size:24px;cursor:pointer;list-style:none}.section-menu form{position:absolute;right:0;z-index:8;display:grid;min-width:145px;padding:8px;background:white;border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow)}.section-menu button{border:0;background:white;text-align:left;padding:9px;color:var(--plum)}</style>'''

_TOUCH_CROP_SCRIPT='''<script>(function(){document.querySelectorAll('.touch-crop-form').forEach(function(f){var box=f.querySelector('.touch-crop'),im=box.querySelector('img'),inp=f.querySelector('.photo-input'),zoom=f.querySelector('.zoom-only'),x=f.querySelector('[name=crop_x]'),y=f.querySelector('[name=crop_y]'),z=f.querySelector('[name=crop_zoom]'),drag=false,sx=0,sy=0,px=parseFloat(x.value)||50,py=parseFloat(y.value)||50;function draw(){im.style.objectPosition=px+'% '+py+'%';im.style.transform='scale('+zoom.value+')';x.value=px;y.value=py;z.value=zoom.value}inp.addEventListener('change',function(){var file=this.files&&this.files[0];if(file){im.src=URL.createObjectURL(file);draw()}});zoom.addEventListener('input',draw);box.addEventListener('pointerdown',function(e){drag=true;sx=e.clientX;sy=e.clientY;box.setPointerCapture(e.pointerId)});box.addEventListener('pointermove',function(e){if(!drag)return;px=Math.max(0,Math.min(100,px+(e.clientX-sx)/box.clientWidth*100));py=Math.max(0,Math.min(100,py+(e.clientY-sy)/box.clientHeight*100));sx=e.clientX;sy=e.clientY;draw()});box.addEventListener('pointerup',function(){drag=false});draw()})})();</script>'''

@app.route('/business/app/edit')
@login_required
def hosted_app_editor():
    u=current_user(); b,media,events=_owner_business_bundle(u['id'])
    if not b: return redirect(url_for('business_builder',step=1))
    galleries=[m for m in media if m['media_kind']=='gallery']; videos=[m for m in media if m['media_kind']=='video']
    thumbs=''.join(f'<img class="editor-thumb" src="{business_media_src(m["file_name"])}">' for m in galleries[:4])
    video_thumbs=''.join(f'<video class="editor-thumb" src="{business_media_src(m["file_name"])}"></video>' for m in videos[:3])
    logo=f'<img class="editor-thumb" src="{business_media_src(b["logo_name"])}">' if b['logo_name'] else '<span class="badge">Add logo</span>'
    cover=f'<video class="editor-cover" src="{business_media_src(b["cover_name"])}"></video>' if b['cover_name'] and b['cover_type']=='video' else (f'<img class="editor-cover" src="{business_media_src(b["cover_name"])}">' if b['cover_name'] else '<span class="badge">Add cover</span>')
    enabled=set(_module_list(b)); optional=[]
    for key,label in HOSTED_APP_MODULES:
        if key in {'home','about','services','gallery','videos','booking','contact'} or key not in enabled: continue
        optional.append(f'<div class="app-editor-card"><div><h3>{label}</h3><p class="muted">Visible in your app</p></div><a class="out" href="{url_for("hosted_app_content_editor",kind=key)}">Edit</a></div>')
    card=lambda title,summary,section,visual='': f'''<div class="app-editor-card"><div><h2>{title}</h2><p class="muted">{summary}</p><div class="editor-thumbs">{visual}</div></div><a class="out" href="{url_for('hosted_app_edit_section',section=section)}">Edit</a></div>'''
    body=f'''{_HOSTED_EDITOR_STYLE}<div class="hero"><span class="badge">HOSTED BUSINESS APP OWNER</span><h1>Edit My Hosted App</h1><p class="muted">Create once. Edit directly forever.</p><div class="actions"><a class="btn" href="{url_for('hosted_app_preview')}">Preview My App</a>{f'<a class="out" href="{url_for("business_app",business_id=b["id"])}">View Published App</a>' if b['active'] else ''}</div></div>{card('Header & Branding','Current logo and cover','branding',logo+cover)}{card('About',(b['description'] or 'Add your business description')[:180],'about')}{card('Services',(b['offers'] or 'Add individual services, pricing and booking details')[:180],'services')}{card('Gallery',f'{len(galleries)} photos','gallery',thumbs)}{card('Videos',f'{len(videos)} of 3 videos','videos',video_thumbs)}{card('Booking',{'seasons_calendar':'The Seasons Within Calendar','external':'Existing booking link','none':'No booking'}.get(b['booking_method'] or 'seasons_calendar'),'booking')}{card('Contact','Email, phone, website and social links','contact')}{card('Feature on Home Page','Choose which published sections appear as shortcuts on your Home Business App card','home_features')}{''.join(optional)}<a class="btn" href="{url_for('hosted_app_edit_section',section='sections')}">+ Add Section</a>'''
    return page('Edit My Hosted App',body,'business')

@app.route('/business/app/preview')
@login_required
def hosted_app_preview():
    u=current_user(); b,media,events=_owner_business_bundle(u['id'])
    if not b: return redirect(url_for('business_builder',step=1))
    return page('Preview My App',f'''{_HOSTED_EDITOR_STYLE}<div class="hero"><span class="badge">VIEW MODE</span><h1>Preview My App</h1><div class="actions"><a class="btn" href="{url_for('hosted_app_editor')}">Close Preview</a></div></div><div class="hosted-preview">{_hosted_app_render(b,media,events,preview=True)}</div>''','business')

@app.route('/business/app/edit/<section>',methods=['GET','POST'])
@login_required
def hosted_app_edit_section(section):
    u=current_user(); b,media,events=_owner_business_bundle(u['id'])
    if not b: return redirect(url_for('business_builder',step=1))
    if section not in {'branding','about','services','gallery','videos','booking','contact','sections','home_features'}: abort(404)
    if request.method=='POST':
        conn=db()
        if section=='about':
            business_name=request.form.get('name','').strip()
            if not business_name: conn.close(); flash('Business Name is required.','error'); return redirect(url_for('hosted_app_edit_section',section='about'))
            conn.execute('UPDATE businesses SET name=?,description=?,story=?,tagline=?,updated_at=? WHERE id=?',(business_name,request.form.get('description','').strip(),request.form.get('story','').strip(),request.form.get('tagline','').strip(),now(),b['id']))
        elif section=='services': conn.execute('UPDATE businesses SET offers=?,updated_at=? WHERE id=?',(request.form.get('offers','').strip(),now(),b['id']))
        elif section=='contact':
            fields=['contact_email','contact_phone','website','instagram','tiktok','youtube','facebook']; vals=[request.form.get(x,'').strip() for x in fields]
            conn.execute('UPDATE businesses SET contact_email=?,contact_phone=?,website=?,instagram=?,tiktok=?,youtube=?,facebook=?,updated_at=? WHERE id=?',(*vals,now(),b['id']))
        elif section=='booking':
            method=request.form.get('booking_method','seasons_calendar'); method=method if method in {'seasons_calendar','external','none'} else 'seasons_calendar'
            settings={k:request.form.get(k,'').strip() for k in ('available_days','available_times','duration','buffer','blocked_dates','timezone')}
            conn.execute('UPDATE businesses SET booking_method=?,booking_url=?,booking_settings=?,updated_at=? WHERE id=?',(method,request.form.get('booking_url','').strip(),json.dumps(settings),now(),b['id']))
            if method=='seasons_calendar':
                generated=_sync_weekly_booking_slots(conn,b,settings)
                flash(f'{generated} available appointment times were added to the live booking calendar.','success')
            else:
                conn.execute("DELETE FROM business_calendar WHERE business_id=? AND source='Weekly Availability'",(b['id'],))
        elif section=='sections':
            selected=[k for k,_ in HOSTED_APP_MODULES if request.form.get('module_'+k)]; selected=list(dict.fromkeys(['home','about','contact']+selected))
            conn.execute('UPDATE businesses SET enabled_modules=?,updated_at=? WHERE id=?',(','.join(selected),now(),b['id']))
            conn.commit(); conn.close(); flash('Sections saved.','success'); return redirect(url_for('hosted_app_edit_section',section='sections'))
        elif section=='home_features':
            enabled=set(_module_list(b)); allowed={'classes','services','media_kit','events','booking','contact','videos','courses','gallery','retreats','affiliate'}
            selected=[k for k,_ in HOSTED_APP_MODULES if k in allowed and k in enabled and request.form.get('feature_'+k)]
            conn.execute('UPDATE businesses SET home_feature_modules=?,updated_at=? WHERE id=?',(','.join(selected),now(),b['id']))
        conn.commit(); conn.close(); flash('Changes saved.','success'); return redirect(url_for('hosted_app_editor'))
    if section=='branding':
        logo=_touch_crop_form('logo','Business Logo / Profile Image',business_media_src(b['logo_name']) if b['logo_name'] else '',crop_data=b['logo_crop'] or '{}')
        cover=_touch_crop_form('cover','Cover Photo',business_media_src(b['cover_name']) if b['cover_name'] and b['cover_type']!='video' else '',crop_data=b['cover_crop'] or '{}')
        video=f'''<form class="card" method="post" enctype="multipart/form-data" action="{url_for('hosted_app_media_save')}"><h2>Cover Video</h2>{f'<video controls src="{business_media_src(b["cover_name"])}"></video>' if b['cover_name'] and b['cover_type']=='video' else ''}<input type="hidden" name="kind" value="cover_video"><input class="input" type="file" name="media_file" accept="video/mp4,video/quicktime,video/webm,video/x-m4v"><div class="actions"><a class="out" href="{url_for('hosted_app_editor')}">Cancel</a><button class="btn">Save Video</button></div></form>'''
        content=logo+cover+video+_TOUCH_CROP_SCRIPT
    elif section=='gallery':
        rows=[m for m in media if m['media_kind']=='gallery']; cards=''.join(f'''<article class="card"><img class="editor-cover" src="{business_media_src(m['file_name'])}"><form method="post" action="{url_for('hosted_app_media_save')}"><input type="hidden" name="kind" value="gallery"><input type="hidden" name="media_id" value="{m['id']}"><label>Caption title<input class="input" name="title" value="{html.escape(m['title'] or '')}"></label><label>Description<textarea class="input" name="description">{html.escape(m['description'] or '')}</textarea></label><div class="actions"><button class="btn">Save Caption</button><button class="out danger" name="remove" value="1">Remove</button></div></form></article>''' for m in rows)
        editors=''.join(_touch_crop_form('gallery','Edit / Replace Photo',business_media_src(m['file_name']),m['id']) for m in rows)
        content=f'<div class="grid">{cards}</div>{editors}'+_touch_crop_form('gallery','+ Add Photo')+_TOUCH_CROP_SCRIPT
    elif section=='videos':
        rows=[m for m in media if m['media_kind']=='video']; cards=''.join(f'''<article class="card"><video controls src="{business_media_src(m['file_name'])}"></video><form method="post" enctype="multipart/form-data" action="{url_for('hosted_app_media_save')}"><input type="hidden" name="kind" value="video"><input type="hidden" name="media_id" value="{m['id']}"><label>Title<input class="input" name="title" value="{html.escape(m['title'] or '')}"></label><label>Description<textarea class="input" name="description">{html.escape(m['description'] or '')}</textarea></label><label>Replace video<input class="input" type="file" name="media_file" accept="video/mp4,video/quicktime,video/webm,video/x-m4v"></label><div class="actions"><button class="btn">Save Changes</button><button class="out danger" name="remove" value="1">Remove</button></div></form></article>''' for m in rows)
        add='' if len(rows)>=3 else f'''<form class="card" method="post" enctype="multipart/form-data" action="{url_for('hosted_app_media_save')}"><h2>+ Add Video</h2><input type="hidden" name="kind" value="video"><input class="input" type="file" name="media_file" accept="video/mp4,video/quicktime,video/webm,video/x-m4v" required><input class="input" name="title" placeholder="Video title"><textarea class="input" name="description" placeholder="Description"></textarea><p class="muted small">Maximum 3 minutes.</p><button class="btn">Save Video</button></form>'''
        content=f'<p><b>{len(rows)} of 3 videos uploaded</b></p><div class="grid">{cards}</div>{add}'
    elif section=='about': content=f'''<form class="card" method="post"><label><b>Business Name</b><input class="input" name="name" value="{html.escape(b['name'] or '',quote=True)}" required></label><label>Tagline<input class="input" name="tagline" value="{html.escape(b['tagline'] or '')}"></label><label>About<textarea class="input" name="description">{html.escape(b['description'] or '')}</textarea></label><label>Our Story<textarea class="input" name="story">{html.escape(b['story'] or '')}</textarea></label><button class="btn">Save</button></form>'''
    elif section=='services': content=f'''<form class="card" method="post"><label>Services Overview<textarea class="input" name="offers">{html.escape(b['offers'] or '')}</textarea></label><button class="btn">Save Overview</button></form><p><a class="btn" href="{url_for('hosted_app_content_editor',kind='services')}">Add / Edit Individual Services</a></p>'''
    elif section=='contact': content='<form class="card" method="post">'+''.join(f'<label>{label}<input class="input" name="{key}" value="{html.escape(b[key] or "")}"></label>' for key,label in [('contact_email','Email'),('contact_phone','Phone'),('website','Website'),('instagram','Instagram'),('tiktok','TikTok'),('youtube','YouTube'),('facebook','Facebook')])+'<button class="btn">Save</button></form>'
    elif section=='booking':
        try: settings=json.loads(b['booking_settings'] or '{}')
        except Exception: settings={}
        radio=lambda value,label: f'<label class="booking-method-choice"><input type="radio" name="booking_method" value="{value}" {"checked" if (b["booking_method"] or "seasons_calendar")==value else ""}><span>{label}</span></label>'
        external_selected=(b['booking_method']=='external')
        content=f'''<style>.booking-method-list{{display:grid;gap:10px;margin:14px 0}}.booking-method-choice{{display:grid;grid-template-columns:22px minmax(0,1fr);align-items:start;gap:10px;width:100%;padding:13px;border:1px solid var(--line);border-radius:14px;background:#fff;line-height:1.35}}.booking-method-choice input{{width:18px;height:18px;margin:1px 0 0}}.booking-method-choice span{{min-width:0;overflow-wrap:anywhere}}@media(max-width:520px){{.booking-method-choice{{padding:12px 10px}}}}</style><form class="card" method="post" data-booking-settings><h2>Booking Method</h2><div class="booking-method-list">{radio('seasons_calendar','Use The Seasons Within Calendar')}{radio('external','Use My Existing Booking Link')}{radio('none','No Online Booking')}</div><label data-external-booking {'style="display:none"' if not external_selected else ''}><b>Existing Booking Link</b><input class="input" name="booking_url" value="{html.escape(b['booking_url'] or '')}"></label><label><b>Available Days</b><input class="input" name="available_days" value="{html.escape(settings.get('available_days',''))}" placeholder="Monday, Tuesday"></label><label><b>Available Times</b><input class="input" name="available_times" value="{html.escape(settings.get('available_times',''))}" placeholder="9:00 AM – 5:00 PM"></label><label><b>Business Time Zone</b><input class="input" name="timezone" value="{html.escape(settings.get('timezone','America/Detroit'))}" placeholder="America/Detroit"></label><label><b>Appointment Duration</b><input class="input" name="duration" value="{html.escape(settings.get('duration',''))}" placeholder="60 minutes"></label><label><b>Time Between Appointments</b><input class="input" name="buffer" value="{html.escape(settings.get('buffer',''))}" placeholder="15 minutes"></label><label><b>Blocked Dates</b><input class="input" name="blocked_dates" value="{html.escape(settings.get('blocked_dates',''))}" placeholder="2026-09-12, 2026-09-20"></label><p class="muted small">Use Manage Calendar to add specific availability, classes, events, vacations, personal appointments and blocked periods. Private block notes are never shown to members.</p><div class="actions"><button class="btn">Save</button><a class="out" href="{url_for('business_calendar_page')}">Manage Calendar</a></div></form><script>(()=>{{const form=document.querySelector('[data-booking-settings]'),field=form&&form.querySelector('[data-external-booking]');if(!form||!field)return;function update(){{const chosen=form.querySelector('[name=booking_method]:checked');field.style.display=chosen&&chosen.value==='external'?'block':'none';}}form.addEventListener('change',e=>{{if(e.target.name==='booking_method')update();}});update();}})();</script>'''
    elif section=='home_features':
        enabled=set(_module_list(b)); chosen=set(((b['home_feature_modules'] if 'home_feature_modules' in b.keys() else '') or '').split(',')); allowed={'classes','services','media_kit','events','booking','contact','videos','courses','gallery','retreats','affiliate'}
        choices=''.join(f'<label class="fact"><input type="checkbox" name="feature_{k}" {"checked" if k in chosen else ""}> {label}</label>' for k,label in HOSTED_APP_MODULES if k in allowed and k in enabled)
        content=f'''<form class="card" method="post"><h2>Feature on Home Page</h2><p class="muted">Choose shortcuts for your Home page Business App card. Only sections already enabled in your published Hosted App are available.</p>{choices or '<p class="muted">Enable and publish Hosted App sections before choosing Home page shortcuts.</p>'}<button class="btn">Save Home Page Features</button></form>'''
    else:
        enabled=set(_module_list(b))
        choices=''.join(f'<label class="hosted-section-choice"><input type="checkbox" name="module_{k}" {"checked" if k in enabled else ""}><span>{label}</span></label>' for k,label in HOSTED_APP_MODULES if k not in {'home','about','contact'})
        content=f'''<style>.hosted-section-options{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:14px 0 18px}}.hosted-section-choice{{display:grid;grid-template-columns:22px minmax(0,1fr);align-items:start;gap:10px;width:100%;min-width:0;padding:13px;border:1px solid var(--line);border-radius:14px;background:#fff;line-height:1.35}}.hosted-section-choice input{{width:18px;height:18px;margin:1px 0 0}}.hosted-section-choice span{{min-width:0;overflow-wrap:anywhere}}@media(max-width:520px){{.hosted-section-options{{grid-template-columns:1fr}}.hosted-section-choice{{padding:12px 10px}}}}</style><form class="card" method="post"><h2>+ Add Section</h2><div class="hosted-section-options">{choices}</div><button class="btn">Save Sections</button></form>'''
    return page('Edit '+section.title(),f'''{_HOSTED_EDITOR_STYLE}<div class="hero"><span class="badge">EDIT MY HOSTED APP</span><h1>{section.title()}</h1><a class="out" href="{url_for('hosted_app_editor')}">Back to Editor</a></div>{content}''','business')

_HOSTED_CONTENT_FIELDS={
    'services':[('price','Price'),('duration','Duration'),('format','Virtual or in-person'),('location','Location'),('availability','Availability'),('booking_url','Booking or inquiry link')],
    'classes':[('instructor','Instructor'),('price','Price / free'),('format','Virtual or in-person'),('location','Location or virtual details'),('date','Class date'),('times','Start and end time'),('duration','Duration'),('capacity','Capacity'),('requirements','Requirements / instructions'),('booking_url','Registration or booking link')],
    'courses':[('instructor','Instructor'),('price','Price / free'),('format','Delivery format'),('enrollment_url','Enrollment link')],
    'events':[('date','Event date'),('times','Start and end time'),('location','Location or virtual details'),('price','Price / free'),('capacity','Capacity'),('registration_url','Registration link')],
    'retreats':[('date','Retreat dates'),('times','Times'),('location','Location'),('price','Pricing'),('capacity','Capacity'),('requirements','Requirements / instructions'),('booking_url','Booking or inquiry link')],
    'media_kit':[('link_url','Media kit or download link'),('action_label','Button label')],
    'affiliate':[('link_url','Affiliate link'),('action_label','Button label')]
}

@app.route('/business/app/edit/content/<kind>',methods=['GET','POST'])
@login_required
def hosted_app_content_editor(kind):
    if kind not in _HOSTED_CONTENT_FIELDS: abort(404)
    u=current_user(); b,_,_= _owner_business_bundle(u['id'])
    if not b: return redirect(url_for('business_builder',step=1))
    conn=db(); item_id=request.values.get('id',type=int)
    item=conn.execute('SELECT * FROM hosted_app_content WHERE id=? AND business_id=?',(item_id,b['id'])).fetchone() if item_id else None
    if request.method=='POST':
        if request.form.get('delete') and item:
            old_detail=_safe_json(item['details'],{})
            if old_detail.get('calendar_id'):
                conn.execute('DELETE FROM business_calendar WHERE id=? AND business_id=?',(old_detail['calendar_id'],b['id']))
            conn.execute('DELETE FROM hosted_app_content WHERE id=?',(item['id'],)); conn.commit(); conn.close()
            if item['image_name']: (UPLOAD_DIR/item['image_name']).unlink(missing_ok=True)
            flash('Hosted App item removed.','success'); return redirect(url_for('hosted_app_content_editor',kind=kind))
        title=request.form.get('title','').strip(); description=request.form.get('description','').strip()
        if not title:
            conn.close(); flash('Add a title before saving.','error'); return redirect(request.url)
        old_details=_safe_json(item['details'],{}) if item else {}
        details={key:request.form.get(key,'').strip() for key,_ in _HOSTED_CONTENT_FIELDS[kind]}
        if kind=='courses':
            details['lessons']=[{'title':request.form.get(f'lesson_title_{n}','').strip(),'content':request.form.get(f'lesson_content_{n}','').strip(),'video_url':request.form.get(f'lesson_video_{n}','').strip()} for n in range(1,6) if request.form.get(f'lesson_title_{n}','').strip()]
        if kind in {'classes','events','retreats'} and re.fullmatch(r'\d{4}-\d{2}-\d{2}',details.get('date','')):
            time_parts=[x.strip() for x in re.split(r'\s*(?:–|—|\bto\b)\s*',details.get('times',''),maxsplit=1)]
            start=time_parts[0] if time_parts and time_parts[0] else '09:00'; end=time_parts[1] if len(time_parts)>1 and time_parts[1] else start
            calendar_id=old_details.get('calendar_id')
            event_type={'classes':'Class','events':'Event','retreats':'Retreat'}[kind]
            conn.execute("""DELETE FROM business_calendar WHERE business_id=? AND event_date=? AND source='Weekly Availability' AND NOT(end_time<=? OR start_time>=?)""",(b['id'],details['date'],start,end))
            if calendar_id:
                conn.execute('UPDATE business_calendar SET title=?,event_type=?,event_date=?,start_time=?,end_time=?,location=?,capacity=?,notes=?,updated_at=? WHERE id=? AND business_id=?',(title,event_type,details['date'],start,end,details.get('location',''),details.get('capacity',''),description,now(),calendar_id,b['id']))
            else:
                cur=conn.execute('INSERT INTO business_calendar(business_id,title,event_type,event_date,start_time,end_time,location,capacity,booking_status,notes,source,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',(b['id'],title,event_type,details['date'],start,end,details.get('location',''),details.get('capacity',''),'Open',description,'Hosted App Content',now(),now()))
                calendar_id=cur.lastrowid
            details['calendar_id']=calendar_id
        image_name=item['image_name'] if item else ''
        incoming=request.files.get('image_file')
        if incoming and incoming.filename:
            stored=_store_business_upload(incoming,b['id'],kind,BUSINESS_IMAGE_EXT)
            if stored: image_name=stored
        published=1 if request.form.get('published') else 0
        video_url=request.form.get('video_url','').strip()
        if item:
            conn.execute('UPDATE hosted_app_content SET title=?,description=?,image_name=?,video_url=?,details=?,published=?,updated_at=? WHERE id=?',(title,description,image_name,video_url,json.dumps(details),published,now(),item['id']))
        else:
            order=conn.execute('SELECT COALESCE(MAX(sort_order),-1)+1 n FROM hosted_app_content WHERE business_id=? AND content_type=?',(b['id'],kind)).fetchone()['n']
            conn.execute('INSERT INTO hosted_app_content(business_id,content_type,title,description,image_name,video_url,details,published,sort_order,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)',(b['id'],kind,title,description,image_name,video_url,json.dumps(details),published,order,now(),now()))
        conn.commit(); conn.close()
        if item and image_name!=item['image_name'] and item['image_name']: (UPLOAD_DIR/item['image_name']).unlink(missing_ok=True)
        flash('Hosted App content saved.','success'); return redirect(url_for('hosted_app_content_editor',kind=kind))
    rows=conn.execute('SELECT * FROM hosted_app_content WHERE business_id=? AND content_type=? ORDER BY sort_order,id',(b['id'],kind)).fetchall(); conn.close()
    label=dict(HOSTED_APP_MODULES).get(kind,kind.title()); details=_safe_json(item['details'],{}) if item else {}
    fields=''.join(f'<label>{html.escape(label_text)}<input class="input" name="{key}" value="{html.escape(str(details.get(key,"")))}"></label>' for key,label_text in _HOSTED_CONTENT_FIELDS[kind])
    lessons=''
    if kind=='courses':
        saved=details.get('lessons',[]) if isinstance(details.get('lessons',[]),list) else []
        blocks=[]
        for n in range(1,6):
            lesson=saved[n-1] if n<=len(saved) and isinstance(saved[n-1],dict) else {}
            blocks.append(f'''<fieldset class="card"><legend><b>Lesson / Module {n}</b></legend><label>Lesson title<input class="input" name="lesson_title_{n}" value="{html.escape(str(lesson.get('title','')))}"></label><label>Written lesson content<textarea class="input" name="lesson_content_{n}">{html.escape(str(lesson.get('content','')))}</textarea></label><label>Lesson video link<input class="input" name="lesson_video_{n}" value="{html.escape(str(lesson.get('video_url','')))}"></label></fieldset>''')
        lessons='<h3>Lessons / Modules</h3>'+''.join(blocks)
    current_image=f'<img class="editor-cover" src="{business_media_src(item["image_name"])}">' if item and item['image_name'] else ''
    form=f'''<form class="card" method="post" enctype="multipart/form-data">{f'<input type="hidden" name="id" value="{item["id"]}">' if item else ''}<h2>{'Edit' if item else 'Add'} {label.rstrip('s')}</h2>{current_image}<label>Title<input class="input" name="title" required value="{html.escape(item['title'] if item else '')}"></label><label>Description<textarea class="input" name="description">{html.escape(item['description'] if item else '')}</textarea></label><label>Photo / cover image<input class="input" type="file" name="image_file" accept="image/*"></label><label>Video link (optional)<input class="input" name="video_url" value="{html.escape(item['video_url'] if item else '')}"></label>{fields}{lessons}<label class="fact"><input type="checkbox" name="published" {'checked' if not item or item['published'] else ''}> Publish this item</label><div class="actions"><button class="btn">Save</button>{'<button class="out danger" name="delete" value="1">Delete</button>' if item else ''}<a class="out" href="{url_for('hosted_app_content_editor',kind=kind)}">Cancel</a></div></form>'''
    cards=''.join(f'''<article class="card"><span class="badge">{'PUBLISHED' if row['published'] else 'DRAFT'}</span><h3>{html.escape(row['title'])}</h3><p>{html.escape(row['description'] or '')}</p><a class="out" href="{url_for('hosted_app_content_editor',kind=kind,id=row['id'])}">Edit</a></article>''' for row in rows)
    return page('Edit '+label,f'''{_HOSTED_EDITOR_STYLE}<div class="hero"><span class="badge">EDIT MY HOSTED APP</span><h1>{label}</h1><div class="actions"><a class="out" href="{url_for('hosted_app_editor')}">Back to Editor</a><a class="out" href="{url_for('hosted_app_preview')}">Preview</a></div></div>{form}<h2>Saved {label}</h2><div class="grid">{cards}</div>''','business')

@app.route('/business/app/edit/media',methods=['POST'])
@login_required
def hosted_app_media_save():
    u=current_user(); b,media,_=_owner_business_bundle(u['id'])
    if not b: abort(404)
    kind=request.form.get('kind',''); media_id=request.form.get('media_id',type=int); remove=bool(request.form.get('remove')); incoming=request.files.get('media_file')
    conn=db()
    row=None
    if kind in {'gallery','video'} and media_id:
        row=conn.execute('SELECT * FROM business_media WHERE id=? AND business_id=?',(media_id,b['id'])).fetchone()
        if row and remove:
            conn.execute('DELETE FROM business_media WHERE id=?',(media_id,)); conn.commit(); conn.close(); (UPLOAD_DIR/row['file_name']).unlink(missing_ok=True); flash('Media removed.','success'); return redirect(url_for('hosted_app_edit_section',section='gallery' if kind=='gallery' else 'videos'))
    if remove and kind in {'logo','cover'}:
        old=b['logo_name'] if kind=='logo' else b['cover_name']; field='logo_name' if kind=='logo' else 'cover_name'
        conn.execute(f"UPDATE businesses SET {field}='',updated_at=? WHERE id=?",(now(),b['id'])); conn.commit(); conn.close();
        if old: (UPLOAD_DIR/old).unlink(missing_ok=True)
        flash('Media removed.','success'); return redirect(url_for('hosted_app_editor'))
    if not incoming or not incoming.filename:
        if kind in {'logo','cover'}:
            conn.execute(f'UPDATE businesses SET {kind}_crop=?,updated_at=? WHERE id=?',(_crop_payload(request.form),now(),b['id']))
        elif kind=='gallery' and row:
            crop=_crop_payload(request.form) if request.form.get('crop_x') else (row['crop_data'] if 'crop_data' in row.keys() else '{}')
            conn.execute('UPDATE business_media SET crop_data=?,title=?,description=? WHERE id=?',(crop,request.form.get('title',row['title'] or '').strip(),request.form.get('description',row['description'] or '').strip(),row['id']))
        elif kind=='video' and row:
            conn.execute('UPDATE business_media SET title=?,description=? WHERE id=?',(request.form.get('title','').strip(),request.form.get('description','').strip(),row['id']))
        else:
            conn.close(); flash('Choose a file to upload.','error'); return redirect(url_for('hosted_app_editor'))
        conn.commit(); conn.close(); flash('Changes saved.','success'); return redirect(url_for('hosted_app_edit_section',section='branding' if kind in {'logo','cover'} else ('gallery' if kind=='gallery' else 'videos')))
    allowed=BUSINESS_VIDEO_EXT if kind in {'video','cover_video'} else BUSINESS_IMAGE_EXT
    stored=_store_business_upload(incoming,b['id'],kind,allowed)
    if not stored: conn.close(); flash('We could not upload this file. Please choose a supported file and try again.','error'); return redirect(url_for('hosted_app_editor'))
    if kind in {'video','cover_video'}:
        seconds=_video_duration_seconds(UPLOAD_DIR/stored)
        if seconds and seconds>180: (UPLOAD_DIR/stored).unlink(missing_ok=True); conn.close(); flash('Video must be 3 minutes or shorter.','error'); return redirect(url_for('hosted_app_edit_section',section='videos' if kind=='video' else 'branding'))
    if kind=='logo':
        old=b['logo_name']; conn.execute('UPDATE businesses SET logo_name=?,logo_crop=?,updated_at=? WHERE id=?',(stored,_crop_payload(request.form),now(),b['id']))
    elif kind in {'cover','cover_video'}:
        old=b['cover_name']; conn.execute('UPDATE businesses SET cover_name=?,cover_type=?,cover_crop=?,updated_at=? WHERE id=?',(stored,'video' if kind=='cover_video' else 'image',_crop_payload(request.form),now(),b['id']))
    elif kind=='gallery':
        if row:
            old=row['file_name']; conn.execute('UPDATE business_media SET file_name=?,crop_data=? WHERE id=?',(stored,_crop_payload(request.form),row['id']))
        else:
            old=''; order=conn.execute("SELECT COALESCE(MAX(sort_order),-1)+1 n FROM business_media WHERE business_id=? AND media_kind='gallery'",(b['id'],)).fetchone()['n']; conn.execute('INSERT INTO business_media(business_id,media_kind,file_name,title,description,sort_order,crop_data,created_at) VALUES(?,?,?,?,?,?,?,?)',(b['id'],'gallery',stored,'','',order,_crop_payload(request.form),now()))
    elif kind=='video':
        old=row['file_name'] if row else ''; count=conn.execute("SELECT COUNT(*) n FROM business_media WHERE business_id=? AND media_kind='video'",(b['id'],)).fetchone()['n']
        if row:
            conn.execute('UPDATE business_media SET file_name=?,title=?,description=? WHERE id=?',(stored,request.form.get('title','').strip(),request.form.get('description','').strip(),row['id']))
        else:
            if count>=3: (UPLOAD_DIR/stored).unlink(missing_ok=True); conn.close(); flash('Maximum 3 videos.','error'); return redirect(url_for('hosted_app_edit_section',section='videos'))
            conn.execute('INSERT INTO business_media(business_id,media_kind,file_name,title,description,sort_order,crop_data,created_at) VALUES(?,?,?,?,?,?,?,?)',(b['id'],'video',stored,request.form.get('title','').strip(),request.form.get('description','').strip(),count,'{}',now()))
    conn.commit(); conn.close()
    if old and old!=stored: (UPLOAD_DIR/old).unlink(missing_ok=True)
    flash('Upload complete ✓','success'); return redirect(url_for('hosted_app_edit_section',section={'logo':'branding','cover':'branding','cover_video':'branding','gallery':'gallery','video':'videos'}[kind]))

@app.route('/business/app/<int:business_id>')
def business_app(business_id):
    conn=db(); b=conn.execute('SELECT * FROM businesses WHERE id=? AND active=1',(business_id,)).fetchone()
    if not b: conn.close(); abort(404)
    media=conn.execute('SELECT * FROM business_media WHERE business_id=? ORDER BY media_kind,sort_order,id',(business_id,)).fetchall()
    events=conn.execute("SELECT * FROM business_calendar WHERE business_id=? AND booking_status<>'Cancelled' ORDER BY event_date,start_time",(business_id,)).fetchall(); conn.close()
    viewer=current_user(); owner=bool(viewer and viewer['id']==b['owner_id'])
    owner_bar=(f'''<div class="actions"><a class="btn" href="{url_for('hosted_app_editor')}">Edit My Hosted App</a><a class="out" href="{url_for('hosted_app_preview')}">Preview My App</a><a class="out" href="{url_for('business_dashboard')}">Business Dashboard</a><a class="out" href="{url_for('inbox',category='Business')}">Business Inbox Journal</a></div>''' if owner else '')
    share_image=urllib.parse.urljoin(request.url_root,business_media_src(b['logo_name'])) if b['logo_name'] else ''
    return page(b['name'],f'''<div class="hero paid"><span class="badge gold">★ HOSTED BUSINESS APP</span><h1>{html.escape(b['name'])}</h1><p class="muted">{html.escape(b['category'] or b['owner_title'] or '')} • {html.escape(b['location'] or '')}</p>{owner_bar}</div>{_hosted_app_render(b,media,events,owner=owner)}''','business',share_image=share_image)
    logo=business_media_src(b['logo_name'])
    if b['cover_name']:
        src=business_media_src(b['cover_name']); cover_html=f'<video controls playsinline style="width:100%;height:100%;object-fit:cover" src="{src}"></video>' if b['cover_type']=='video' else f'<img src="{src}" alt="{b["name"]} cover" style="width:100%;height:100%;object-fit:cover">'
    else:
        cover_html=f'<div style="text-align:center"><img src="{logo}" style="width:140px;height:140px;object-fit:contain;border-radius:50%"><p class="muted">Business cover media can be added from Edit Hosted App.</p></div>'
    external=[]
    for label,key in [('Website','website'),('Instagram','instagram'),('TikTok','tiktok'),('YouTube','youtube'),('Facebook','facebook'),('Store','store_url'),('Podcast','podcast_url')]:
        if b[key]: external.append(f'<a class="out" href="{b[key]}" target="_blank" rel="noopener">{label}</a>')
    ext_html='<div class="actions">'+''.join(external)+'</div>' if external else ''
    gallery=[m for m in media if m['media_kind']=='gallery']; videos=[m for m in media if m['media_kind']=='video']
    gallery_html=''.join(f'<div class="media"><img src="{business_media_src(m["file_name"])}" alt="Business gallery photo"></div>' for m in gallery)
    video_html=''.join(f'''<article class="card"><video controls playsinline style="width:100%;border-radius:16px" src="{business_media_src(m['file_name'])}"></video><h3>{m['title'] or 'Business Video'}</h3><p class="muted">{m['description'] or ''}</p></article>''' for m in videos)

    month=request.args.get('month',''); selected_date=request.args.get('date','')
    calendar_html=business_calendar_grid(events,b['id'],selected_date,month,False)
    open_events=[e for e in events if e['booking_status']=='Open' and e['event_type']!='Blocked / Unavailable']
    if selected_date:
        shown=[e for e in open_events if e['event_date']==selected_date]
        heading=f'Available on {selected_date}'
    else:
        shown=open_events[:8]; heading='Upcoming Classes & Open Times'
    slots=''.join(f'''<article class="card"><span class="badge">{e['event_type']}</span><h3>{e['title']}</h3><p><b>{e['event_date']}</b> • {e['start_time']}–{e['end_time']}</p><p class="muted">{e['location']} • Capacity: {e['capacity'] or 'Not set'}</p><a class="btn" href="{url_for('business_book',business_id=b['id'],calendar_id=e['id'])}">Book / Request</a></article>''' for e in shown) or '<div class="empty"><h3>No open times on this date</h3><p class="muted">Choose another open date on the calendar.</p></div>'

    home_section=f'''<section id="home"><div class="media" style="height:380px">{cover_html}</div><article class="card"><span class="badge">HOME</span><h2>{b['tagline'] or b['name']}</h2><p>{b['description'] or 'Business description coming soon.'}</p>{ext_html}</article>{f'<div class="topspace"><h2>Business Photo Gallery</h2></div><div class="grid">{gallery_html}</div>' if b['gallery_enabled'] and gallery_html else ''}{f'<div class="topspace"><h2>Videos</h2></div><div class="grid">{video_html}</div>' if video_html else ''}</section>'''
    about_section=f'''<section id="about" class="topspace"><article class="card"><span class="badge">ABOUT</span><h2>About {b['name']}</h2><p>{b['description'] or 'Business description coming soon.'}</p><h3>Our Story</h3><p>{b['story'] or 'Business story coming soon.'}</p><h3>What We Offer</h3><p>{b['offers'] or 'Offers will appear here.'}</p></article></section>'''
    contact_section=f'''<section id="contact" class="topspace"><article class="card"><span class="badge">CONTACT</span><h2>Contact {b['name']}</h2>{f'<p><b>Email:</b> {b["contact_email"]}</p>' if b['contact_email'] else ''}{f'<p><b>Phone:</b> {b["contact_phone"]}</p>' if b['contact_phone'] else ''}{ext_html}</article></section>'''
    book_section=f'''<section id="book" class="topspace"><div class="hero"><span class="badge">BOOK</span><h2>Book with {b['name']}</h2><p class="muted">Classes, programs, appointments, events and Retreats all use this one Business Calendar so bookings do not collide.</p></div>{calendar_html}<div id="book-times" class="topspace"><h2>{heading}</h2></div><div class="grid">{slots}</div>{f'<p><a class="out" href="{b["booking_url"]}" target="_blank" rel="noopener">External Booking Website</a></p>' if b['booking_url'] else ''}</section>'''
    section_labels='<div class="card"><div class="chips"><span class="chip">Home</span><span class="chip">About</span><span class="chip">Contact</span><span class="chip">Book</span></div><p class="muted small">These are sections of this Hosted Business App. Scroll to view the business information and booking calendar.</p></div>'
    return page(b['name'],f'''<div class="hero paid"><span class="badge gold">★ HOSTED BUSINESS APP</span><div class="profilehero"><div><h1>{b['name']}</h1><h3>{b['owner_title'] or b['category']}</h3><p class="muted">{b['location']} • {b['tagline']}</p></div><img src="{logo}" style="width:110px;height:110px;object-fit:contain;border-radius:50%"></div></div>{section_labels}{home_section}{about_section}{contact_section}{book_section}''','business')

@app.route('/business/<int:business_id>/book/<int:calendar_id>', methods=['GET','POST'])
@login_required
def business_book(business_id,calendar_id):
    u=current_user(); conn=db(); b=conn.execute('SELECT * FROM businesses WHERE id=? AND active=1',(business_id,)).fetchone(); e=conn.execute("SELECT * FROM business_calendar WHERE id=? AND business_id=? AND booking_status='Open' AND event_type<>'Blocked / Unavailable'",(calendar_id,business_id)).fetchone()
    if not b or not e: conn.close(); abort(404)
    if request.method=='POST':
        # Serialize the final availability/capacity check. The browser calendar
        # is informative; this transaction is the authoritative booking gate.
        if USING_POSTGRES:
            conn.execute('SELECT id FROM business_calendar WHERE id=? FOR UPDATE',(calendar_id,))
        else:
            conn.execute('BEGIN IMMEDIATE')
        name=request.form.get('name','').strip() or u['name']; email=request.form.get('email','').strip() or u['email']; guests=request.form.get('guests','').strip() or '1'; notes=request.form.get('notes','').strip()
        current=conn.execute("SELECT * FROM business_calendar WHERE id=? AND booking_status='Open' AND event_type<>'Blocked / Unavailable'",(calendar_id,)).fetchone()
        if not current: conn.close(); flash('That time is no longer available.','error'); return redirect(url_for('business_app',business_id=business_id)+'#book')
        try: requested=max(1,int(guests))
        except Exception: requested=1
        try: capacity=int(current['capacity']) if current['capacity'] else 0
        except Exception: capacity=0
        prior=conn.execute("SELECT guests FROM business_bookings WHERE calendar_id=? AND status IN ('Requested','Confirmed')",(calendar_id,)).fetchall()
        used=sum(int(x['guests'] or 1) if str(x['guests'] or '1').isdigit() else 1 for x in prior)
        if capacity and used+requested>capacity:
            conn.rollback(); conn.close(); flash('That class/event does not have enough remaining capacity.','error'); return redirect(url_for('business_app',business_id=business_id)+'#book')
        conn.execute('''INSERT INTO business_bookings(business_id,calendar_id,booked_by_user_id,customer_name,customer_email,booking_type,title,event_date,start_time,end_time,guests,notes,status,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)''',(business_id,calendar_id,u['id'],name,email,e['event_type'],e['title'],e['event_date'],e['start_time'],e['end_time'],str(requested),notes,'Requested',now()))
        multi=e['event_type'] in ('Class','Program','Event') and capacity>1
        if multi:
            new_status='Full' if used+requested>=capacity else 'Open'; conn.execute("UPDATE business_calendar SET booking_status=?,source='Hosted App Booking',updated_at=? WHERE id=?",(new_status,now(),calendar_id))
        else:
            conn.execute("UPDATE business_calendar SET booking_status='Private',source='Hosted App Booking',booked_by_user_id=?,updated_at=? WHERE id=?",(u['id'],now(),calendar_id))
        conn.commit(); conn.close(); notify(b['owner_id'],'New Business Booking',f'{name} requested {e["title"]} for {e["event_date"]}.',url_for('business_calendar_page',date=e['event_date'])); flash('Booking request sent and recorded on the business calendar.','success'); return redirect(url_for('business_app',business_id=business_id,date=e['event_date'])+'#book')
    conn.close()
    return page('Book',f'''<div class="hero"><span class="badge">BOOK</span><h1>{b['name']}</h1><h2>{e['title']}</h2><p><b>{e['event_date']}</b> • {e['start_time']}–{e['end_time']}</p><p class="muted">This booking uses the same calendar as classes, appointments, events, Retreats and owner-blocked time.</p></div><form class="card" method="post"><label><b>Your Name</b></label><input class="input" name="name" value="{u['name']}" required><label><b>Your Email</b></label><input class="input" type="email" name="email" value="{u['email']}" required><label><b>Guests / Seats</b></label><input class="input" type="number" min="1" name="guests" value="1"><label><b>Booking Notes</b></label><textarea class="input" name="notes" placeholder="Anything the business should know?"></textarea><button class="btn">Request This Time</button></form>''','business')

