def _business_plan_answers(user_id):
    conn=db(); intake=None; plan=None
    try:
        try:
            intake=conn.execute('SELECT payload FROM business_plan_intake WHERE user_id=?',(user_id,)).fetchone()
        except Exception:
            app.logger.exception('Could not read saved business-plan intake for user %s',user_id)
            try: conn.rollback()
            except Exception: pass
        try:
            plan=conn.execute("SELECT payload FROM business_plans WHERE user_id=? AND status='Generated' ORDER BY version DESC LIMIT 1",(user_id,)).fetchone()
        except Exception:
            # Older production schemas may not yet have the status/version fields.
            try: conn.rollback()
            except Exception: pass
            try:
                plan=conn.execute('SELECT payload FROM business_plans WHERE user_id=? ORDER BY id DESC LIMIT 1',(user_id,)).fetchone()
            except Exception:
                app.logger.exception('Could not read saved business plan for user %s',user_id)
                try: conn.rollback()
                except Exception: pass
    finally:
        conn.close()
    row=plan or intake
    try: return json.loads(row['payload']) if row else {}
    except Exception: return {}

def _clean_text(value):
    if value is None: return ''
    if isinstance(value,(list,dict)): value=json.dumps(value)
    return html.unescape(re.sub(r'<[^>]+>',' ',str(value))).strip()

def _business_funding_facts(user_id):
    a=_business_plan_answers(user_id)
    conn=db(); b=None; certs=[]
    try:
        try:
            b=conn.execute('SELECT * FROM businesses WHERE owner_id=? ORDER BY active DESC,updated_at DESC,id DESC LIMIT 1',(user_id,)).fetchone()
        except Exception:
            # Production databases created before active/updated_at existed still
            # contain valid businesses. Read the newest row without those columns.
            try: conn.rollback()
            except Exception: pass
            try: b=conn.execute('SELECT * FROM businesses WHERE owner_id=? ORDER BY id DESC LIMIT 1',(user_id,)).fetchone()
            except Exception:
                app.logger.exception('Could not read business profile for funding user %s',user_id)
                try: conn.rollback()
                except Exception: pass
        try:
            certs=conn.execute("SELECT name FROM business_certifications WHERE user_id=? AND status IN ('Active','In Progress')",(user_id,)).fetchall()
        except Exception:
            try: conn.rollback()
            except Exception: pass
            try: certs=conn.execute('SELECT name FROM business_certifications WHERE user_id=?',(user_id,)).fetchall()
            except Exception:
                app.logger.exception('Could not read certifications for funding user %s',user_id)
                try: conn.rollback()
                except Exception: pass
    finally:
        conn.close()
    def row_value(row,key):
        if not row: return ''
        try: return row[key]
        except (KeyError,IndexError,TypeError): return ''
    def first(*keys):
        for key in keys:
            value=_clean_text(a.get(key,''))
            if value: return value
        return ''
    location=first('business_location','location','city','state') or _clean_text(row_value(b,'location'))
    state=first('state','business_state')
    if not state and re.search(r'\b(MI|Michigan)\b',location,re.I): state='Michigan'
    city=first('city','business_city')
    if not city and location: city=re.split(r'[,•]',location)[0].strip()
    county=first('county','business_county')
    if not county and city.lower()=='detroit': county='Wayne'
    return {'user_id':user_id,'business_name':first('business_name','name') or _clean_text(row_value(b,'name')),'city':city,'county':county,'state':state,'zip':first('zip','zip_code','postal_code'),'industry':first('industry','industry_sector','business_type') or _clean_text(row_value(b,'category')),'naics':first('naics','naics_code','industry_classification'),'business_type':first('business_type','legal_structure'),'stage':first('business_stage','stage'),'years':first('years_in_business','operating_history'),'purpose':first('funding_type','funding_purpose','financial_help','intended_use_of_funding'),'amount':first('budget','funding_amount','estimated_budget'),'revenue':first('revenue','current_revenue','projected_revenue','revenue_sources'),'employees':first('employees','employee_count'),'status':first('for_profit_status','organization_type'),'services':first('services','products_services','offerings'),'goals':first('short_goals','long_goals','goals','expansion_goals'),'certifications':[_clean_text(row_value(r,'name')) for r in certs if _clean_text(row_value(r,'name'))],'plan_complete':bool(a),'raw':a}

def _personalized_funding_keyword(facts):
    """Build a narrow official-source query from saved Business Plan facts."""
    parts=[facts.get('state'),facts.get('city'),facts.get('county'),facts.get('industry'),facts.get('naics'),facts.get('stage'),facts.get('services'),facts.get('purpose')]
    words=[]
    for value in parts:
        for word in re.findall(r'[A-Za-z0-9][A-Za-z0-9&/-]{2,}',_clean_text(value)):
            if word.lower() not in {'business','funding','grant','loan','county'} and word.lower() not in {x.lower() for x in words}:
                words.append(word)
    return ' '.join(words[:12]) or 'small business'

def _funding_geography_terms(facts,level='All',manual_location=''):
    city=_clean_text(facts.get('city')); county=_clean_text(facts.get('county')); state=_clean_text(facts.get('state')); manual=_clean_text(manual_location)
    if manual:
        parts=[x.strip() for x in manual.split(',') if x.strip()]
        if level=='City': city=parts[0] if parts else manual
        elif level=='County': county=(parts[0] if parts else manual).removesuffix(' County')
        elif level=='State': state=parts[-1] if parts else manual
    region=[]
    if city.lower()=='detroit' or county.lower()=='wayne': region=['Metro Detroit','Southeast Michigan']
    elif city: region=[f'{city} metropolitan area']
    elif county: region=[f'{county} County region']
    ordered=[('City',city),('County',(county+' County') if county else ''),('Regional',region[0] if region else ''),('Regional',region[1] if len(region)>1 else ''),('State',state),('Federal','United States federal'),('National/Private','national')]
    if level!='All': ordered=[x for x in ordered if x[0]==level or (level=='Federal' and x[0]=='National/Private')]
    seen=set(); out=[]
    for label,value in ordered:
        key=value.lower()
        if value and key not in seen: seen.add(key); out.append((label,value))
    return out

def _funding_search_profile(facts):
    """Split saved-plan evidence into focused funding categories without assuming eligibility."""
    raw=facts.get('raw') or {}
    combined=' '.join(_clean_text(x) for x in (facts.get('industry'),facts.get('services'),facts.get('purpose'),facts.get('goals'),raw)).lower()
    industry=_clean_text(facts.get('industry'))
    activities=[]
    for value in (facts.get('services'),raw.get('primary_business_activity'),raw.get('secondary_business_activities'),raw.get('products_services'),raw.get('offerings')):
        for part in re.split(r'[,;/|\n]+',_clean_text(value)):
            part=re.sub(r'\s+',' ',part).strip()
            if 2<len(part)<=60 and part.lower() not in {x.lower() for x in activities}: activities.append(part)
    need_map={
        'startup':('startup','start-up','pre-launch','launch'),
        'equipment':('equipment','machinery','tools'),
        'technology':('technology','software','digital','platform','website'),
        'marketing':('marketing','advertising','promotion'),
        'expansion':('expansion','expand','growth'),
        'working capital':('working capital','operating expenses','cash flow'),
        'property':('property','facility','real estate','commercial space','renovation'),
        'training':('training','workforce development','education'),
        'hiring':('hiring','employees','jobs','staffing'),
        'community development':('community development','community impact','neighborhood','underserved'),
        'creative business':('content creation','creator','creative','media','arts'),
        'tourism and hospitality':('tourism','hospitality','retreat','recreation','travel'),
        'wellness':('wellness','health','healing','fitness'),
        'rural business':('rural','agriculture','farm')}
    needs=[label for label,terms in need_map.items() if any(term in combined for term in terms)]
    explicit=_clean_text(facts.get('purpose'))
    for part in reversed([x.strip() for x in re.split(r'[,;/|]+|\s+and\s+|\s*&\s*',explicit,flags=re.I) if x.strip()]):
        if len(part)<=60 and part.lower() not in {x.lower() for x in needs}: needs.insert(0,part)
    eligibility=[]
    eligibility_fields={'women-owned':('women_owned','woman_owned'),'minority-owned':('minority_owned',),'veteran-owned':('veteran_owned',),'disadvantaged business':('disadvantaged_business','dbe'),'nonprofit':('nonprofit','organization_type')}
    for label,keys in eligibility_fields.items():
        values=[_clean_text(raw.get(k)).lower() for k in keys]
        if any(v in {'yes','true','1',label,'woman','women','minority','veteran','nonprofit'} or label in v for v in values if v): eligibility.append(label)
    return {'location':{'city':facts.get('city',''),'county':facts.get('county',''),'state':facts.get('state',''),'zip':facts.get('zip','')},'structure':_clean_text(facts.get('business_type') or facts.get('status')),'stage':_clean_text(facts.get('stage')),'industry':industry,'primary_activity':activities[0] if activities else industry,'secondary_activities':activities[1:5],'eligibility_categories':eligibility,'needs':needs[:8],'naics':_clean_text(facts.get('naics'))}

def _deep_funding_queries(facts,funding_type,level='All',manual_location=''):
    profile=_funding_search_profile(facts); geography=_funding_geography_terms(facts,level,manual_location)
    noun='grant' if funding_type=='Grant' else 'loan'
    local_product='small business grant program' if funding_type=='Grant' else 'small business loan microloan CDFI program'
    industry=profile['industry'] or profile['primary_activity'] or 'small business'
    needs=profile['needs'] or (['business growth'] if funding_type=='Grant' else ['working capital'])
    queries=[]
    def add(search_level,location,focus,pass_name):
        focus=re.sub(r'\s+',' ',_clean_text(focus)).strip()
        if focus: queries.append({'level':search_level,'location':location,'focus':focus,'pass':pass_name,'query':f'{location} {focus} official'.strip()})
    for geo_level,geo in geography:
        if geo_level in {'City','County'}: add(geo_level,geo,local_product,f'{geo_level.lower()} small-business programs')
        elif geo_level=='Regional': add(geo_level,geo,f'{industry} {noun} economic development program', 'regional industry programs')
        elif geo_level=='State':
            add(geo_level,geo,f'small business {noun} program','state small-business programs')
            add(geo_level,geo,f'{industry} business {noun}','state industry programs')
            for need in needs[:3]: add(geo_level,geo,f'{need} small business {noun}','state funding-purpose programs')
            for category in profile['eligibility_categories'][:2]: add(geo_level,geo,f'{category} small business {noun}','voluntarily supplied eligibility programs')
        elif geo_level=='Federal':
            if funding_type=='Grant': add(geo_level,'United States',f'{industry} federal grant opportunity site:grants.gov','federal industry programs')
            else: add(geo_level,'United States',f'{industry} SBA microloan lender financing','federal and SBA programs')
            if profile['naics']: add(geo_level,'United States',f'NAICS {profile["naics"]} {noun} site:.gov','federal NAICS programs')
        elif geo_level=='National/Private':
            add(geo_level,'United States',f'{industry} small business {noun} foundation corporate official application','national and private industry programs')
            for need in needs[:4]: add(geo_level,'United States',f'{need} small business {noun} official program','related funding fallback')
            if funding_type=='Loan': add(geo_level,'United States','startup microloan CDFI mission based lender official','national CDFI and microloan programs')
    unique=[]; seen=set()
    for item in queries:
        key=re.sub(r'\W+',' ',item['query'].lower()).strip()
        if key not in seen: seen.add(key); unique.append(item)
    return unique[:18]

def _trusted_funding_domain(url):
    try: host=(urllib.parse.urlparse(url).hostname or '').lower().strip('.')
    except Exception: return False
    if not host: return False
    if host.endswith('.gov') or host.endswith('.edu'): return True
    configured={x.strip().lower().strip('.') for x in os.environ.get('FUNDING_TRUSTED_DOMAINS','').split(',') if x.strip()}
    return any(host==domain or host.endswith('.'+domain) for domain in configured)

def _brave_web_search(query,count=10):
    token=os.environ.get('BRAVE_SEARCH_API_KEY','').strip()
    if not token: raise RuntimeError('Live web funding search is not configured. Set BRAVE_SEARCH_API_KEY.')
    endpoint=os.environ.get('BRAVE_SEARCH_API_URL','https://api.search.brave.com/res/v1/web/search').strip()
    params=urllib.parse.urlencode({'q':query,'count':max(1,min(int(count),20)),'country':'us','search_lang':'en','safesearch':'moderate','freshness':'py'})
    req=urllib.request.Request(endpoint+'?'+params,headers={'Accept':'application/json','X-Subscription-Token':token,'User-Agent':'The-Seasons-Within/1.0','Cache-Control':'no-cache'})
    with urllib.request.urlopen(req,timeout=20) as response: payload=json.loads(response.read().decode('utf-8'))
    return [x for x in ((payload.get('web') or {}).get('results') or []) if isinstance(x,dict)]

def _bing_web_search(query,count=10):
    token=os.environ.get('BING_SEARCH_API_KEY','').strip()
    if not token: raise RuntimeError('BING_SEARCH_API_KEY is not configured.')
    endpoint=os.environ.get('BING_SEARCH_API_URL','https://api.bing.microsoft.com/v7.0/search').strip()
    params=urllib.parse.urlencode({'q':query,'count':max(1,min(int(count),20)),'mkt':'en-US','safeSearch':'Moderate','responseFilter':'Webpages'})
    req=urllib.request.Request(endpoint+'?'+params,headers={'Accept':'application/json','Ocp-Apim-Subscription-Key':token,'User-Agent':'The-Seasons-Within/1.0'})
    with urllib.request.urlopen(req,timeout=20) as response: payload=json.loads(response.read().decode('utf-8'))
    return [{'title':x.get('name',''),'url':x.get('url',''),'description':x.get('snippet','')} for x in ((payload.get('webPages') or {}).get('value') or []) if isinstance(x,dict)]

def _google_cse_search(query,count=10):
    token=os.environ.get('GOOGLE_CSE_API_KEY','').strip(); cx=os.environ.get('GOOGLE_CSE_ID','').strip()
    if not token or not cx: raise RuntimeError('GOOGLE_CSE_API_KEY and GOOGLE_CSE_ID are not configured.')
    endpoint='https://www.googleapis.com/customsearch/v1'; wanted=max(1,min(int(count),10))
    params=urllib.parse.urlencode({'key':token,'cx':cx,'q':query,'num':wanted,'safe':'active'})
    req=urllib.request.Request(endpoint+'?'+params,headers={'Accept':'application/json','User-Agent':'The-Seasons-Within/1.0'})
    with urllib.request.urlopen(req,timeout=20) as response: payload=json.loads(response.read().decode('utf-8'))
    return [{'title':x.get('title',''),'url':x.get('link',''),'description':x.get('snippet','')} for x in (payload.get('items') or []) if isinstance(x,dict)]

def _openai_emergency_web_search(query,count=12):
    """Provider discovery using OpenAI web search; facts are verified again from each returned official page."""
    if not OPENAI_API_KEY: raise RuntimeError('OPENAI_API_KEY is not configured.')
    prompt=f'''Search the live web for actual local emergency-assistance providers matching the searches below.
Prioritize in this exact order: local nonprofit or shelter; church or faith-based direct provider; local government/county/state program; other community organization.
Exclude 211, Findhelp, Yelp, search-result pages, social media, and generic directories. Return only organizations that appear to provide assistance directly.
Return a JSON array with at most {max(1,min(int(count),15))} objects. Each object must contain only title, url, and description. URL must be the organization's official HTTPS website or official government program page, never a search URL. Do not guess a URL or contact detail.
SEARCHES:
{query[:9000]}'''
    payload={'model':ASTROLOGY_AI_MODEL,'input':prompt,'tools':[{'type':'web_search_preview','search_context_size':'high'}],'store':False}
    req=urllib.request.Request('https://api.openai.com/v1/responses',data=json.dumps(payload).encode('utf-8'),headers={'Authorization':'Bearer '+OPENAI_API_KEY,'Content-Type':'application/json'},method='POST')
    with urllib.request.urlopen(req,timeout=90) as response: raw=_responses_output_text(json.loads(response.read().decode('utf-8'))) or ''
    match=re.search(r'\[\s*\{.*\}\s*\]',raw,re.S)
    if not match: return []
    try: items=json.loads(match.group(0))
    except Exception: return []
    rows=[]
    for item in items if isinstance(items,list) else []:
        if not isinstance(item,dict): continue
        url=_clean_text(item.get('url')); title=_clean_text(item.get('title')); description=_clean_text(item.get('description'))
        if title and url.startswith('https://') and not _emergency_is_directory(url,title):
            rows.append({'title':title,'url':url,'description':description})
    return rows

def _bing_rss_emergency_search(query,count=10):
    """Keyless public-web fallback for emergency provider discovery."""
    params=urllib.parse.urlencode({'q':query,'format':'rss','setlang':'en-US'})
    req=urllib.request.Request('https://www.bing.com/search?'+params,headers={'User-Agent':'Mozilla/5.0 (compatible; TheSeasonsWithin/1.0)','Accept':'application/rss+xml,application/xml,text/xml'})
    with urllib.request.urlopen(req,timeout=20) as response: root=ET.fromstring(response.read())
    rows=[]
    for item in root.findall('.//item')[:max(1,min(int(count),20))]:
        title=_clean_text(item.findtext('title')); url=_clean_text(item.findtext('link')); description=_clean_text(re.sub(r'<[^>]+>',' ',item.findtext('description') or ''))
        if title and url.startswith('https://') and not _emergency_is_directory(url,title):
            rows.append({'title':title,'url':url,'description':description})
    return rows

class _EmergencySearchHTMLParser(HTMLParser):
    def __init__(self):
        super().__init__(); self.rows=[]; self.link=None; self.title=[]; self.snippet=[]; self.in_title=False; self.in_snippet=False
    def handle_starttag(self,tag,attrs):
        attrs=dict(attrs); classes=set((attrs.get('class') or '').split())
        if tag=='a' and classes.intersection({'result__a','result-link'}):
            self.link=attrs.get('href',''); self.title=[]; self.in_title=True
        if classes.intersection({'result__snippet','result-snippet'}):
            self.snippet=[]; self.in_snippet=True
    def handle_data(self,data):
        if self.in_title: self.title.append(data)
        if self.in_snippet: self.snippet.append(data)
    def handle_endtag(self,tag):
        if tag=='a' and self.in_title:
            href=html.unescape(self.link or '')
            if href.startswith('//'): href='https:'+href
            parsed=urllib.parse.urlparse(href)
            if parsed.hostname and parsed.hostname.endswith('duckduckgo.com'):
                href=(urllib.parse.parse_qs(parsed.query).get('uddg') or [''])[0]
            title=_clean_text(html.unescape(' '.join(self.title)))
            if title and href.startswith('https://'): self.rows.append({'title':title,'url':href,'description':''})
            self.in_title=False; self.link=None; self.title=[]
        if tag in {'div','td','span'} and self.in_snippet:
            if self.rows: self.rows[-1]['description']=_clean_text(html.unescape(' '.join(self.snippet)))
            self.in_snippet=False; self.snippet=[]

def _duckduckgo_emergency_search(query,count=10):
    """Keyless HTML search used only for local emergency-provider discovery."""
    errors=[]
    for endpoint in ('https://html.duckduckgo.com/html/','https://lite.duckduckgo.com/lite/'):
        try:
            data=urllib.parse.urlencode({'q':query,'kl':'us-en'}).encode()
            req=urllib.request.Request(endpoint,data=data,headers={'User-Agent':'Mozilla/5.0 (compatible; TheSeasonsWithin/1.0)','Accept':'text/html,application/xhtml+xml'},method='POST')
            with urllib.request.urlopen(req,timeout=25) as response: body=response.read(250000).decode('utf-8','ignore')
            parser=_EmergencySearchHTMLParser(); parser.feed(body)
            rows=[x for x in parser.rows if not _emergency_is_directory(x.get('url',''),x.get('title',''))]
            if rows: return rows[:max(1,min(int(count),15))]
        except Exception as exc: errors.append(type(exc).__name__)
    raise RuntimeError('DuckDuckGo provider search failed: '+', '.join(errors))

def _keyless_emergency_web_search(query,count=10):
    """Search without deployment API keys; official pages are still fetched and verified afterward."""
    rows=[]; providers=[]; failures=[]
    searches=(('DuckDuckGo',_duckduckgo_emergency_search),('Bing RSS',_bing_rss_emergency_search))
    with ThreadPoolExecutor(max_workers=len(searches)) as pool:
        futures={pool.submit(fn,query,count):name for name,fn in searches}
        for future in as_completed(futures):
            try: rows.extend(future.result()); providers.append(futures[future])
            except Exception as exc: failures.append(f'{futures[future]} {type(exc).__name__}')
    if not rows: raise RuntimeError('Public emergency-provider search failed: '+', '.join(failures))
    unique={}
    for row in rows:
        url=_clean_text(row.get('url')).lower().rstrip('/')
        if url: unique.setdefault(url,row)
    return list(unique.values()),' + '.join(providers)

def _configured_funding_web_search(query,count=10):
    """Search every configured provider independently and combine their discoveries."""
    providers=[]
    if os.environ.get('BRAVE_SEARCH_API_KEY','').strip(): providers.append(('Brave Search API',_brave_web_search))
    if os.environ.get('BING_SEARCH_API_KEY','').strip(): providers.append(('Bing Web Search API',_bing_web_search))
    if os.environ.get('GOOGLE_CSE_API_KEY','').strip() and os.environ.get('GOOGLE_CSE_ID','').strip(): providers.append(('Google Programmable Search',_google_cse_search))
    if not providers: raise RuntimeError('Configure BRAVE_SEARCH_API_KEY, BING_SEARCH_API_KEY, or GOOGLE_CSE_API_KEY plus GOOGLE_CSE_ID.')
    rows=[]; succeeded=[]; failures=[]
    with ThreadPoolExecutor(max_workers=len(providers)) as pool:
        futures={pool.submit(fn,query,count):name for name,fn in providers}
        for future in as_completed(futures):
            try: rows.extend(future.result()); succeeded.append(futures[future])
            except Exception as exc: failures.append(f'{futures[future]}: {type(exc).__name__}')
    if not succeeded: raise RuntimeError('All configured web-search providers failed: '+'; '.join(failures))
    unique={}
    for row in rows:
        url=_clean_text(row.get('url')).lower().rstrip('/')
        if url: unique.setdefault(url,row)
    return list(unique.values()),' + '.join(sorted(succeeded))

class _FundingPageText(HTMLParser):
    def __init__(self): super().__init__(); self.parts=[]; self.skip=0
    def handle_starttag(self,tag,attrs):
        if tag in {'script','style','svg','noscript'}: self.skip+=1
    def handle_endtag(self,tag):
        if tag in {'script','style','svg','noscript'} and self.skip: self.skip-=1
    def handle_data(self,data):
        if not self.skip and data.strip(): self.parts.append(data.strip())

def _safe_public_page_text(url):
    parsed=urllib.parse.urlparse(url)
    if parsed.scheme!='https' or not parsed.hostname: return ''
    try:
        for info in socket.getaddrinfo(parsed.hostname,443,type=socket.SOCK_STREAM):
            address=ipaddress.ip_address(info[4][0])
            if not address.is_global: return ''
    except Exception: return ''
    req=urllib.request.Request(url,headers={'User-Agent':'The-Seasons-Within/1.0','Accept':'text/html,application/xhtml+xml'})
    try:
        with urllib.request.urlopen(req,timeout=10) as response:
            if 'html' not in (response.headers.get('Content-Type') or '').lower(): return ''
            raw=response.read(350000).decode(response.headers.get_content_charset() or 'utf-8','replace')
        parser=_FundingPageText(); parser.feed(raw); return re.sub(r'\s+',' ',' '.join(parser.parts))[:120000]
    except Exception: return ''

def _published_field(text,patterns,default=''):
    for pattern in patterns:
        match=re.search(pattern,text,re.I)
        if match: return _clean_text(match.group(1))[:500]
    return default

def _web_result_to_opportunity(result,query_meta,funding_type,provider='Live web search'):
    url=_clean_text(result.get('url')); title=_clean_text(result.get('title')); snippet=_clean_text(result.get('description'))
    if not url or not title: return None
    host=(urllib.parse.urlparse(url).hostname or '').lower(); lower=' '.join((title,snippet,url)).lower()
    blocked=('best grants','top grants','grant list','loans you should','blog/','/blog','news article','lead generation')
    if any(x in lower for x in blocked): return None
    page=_safe_public_page_text(url)
    evidence=(title+' '+snippet+' '+page[:70000]).strip()
    required_word='grant' if funding_type=='Grant' else r'loan|lending|financing|microloan|line of credit'
    program_evidence=bool(page and re.search(rf'\b({required_word})\b',evidence,re.I) and re.search(r'\b(apply|application|eligib|qualif|deadline|rolling|amount|borrow|funds?|program)\w*\b',evidence,re.I))
    original_organization=not any(x in host for x in ('facebook.com','linkedin.com','youtube.com','instagram.com','reddit.com','medium.com','wikipedia.org'))
    official=bool(original_organization and (_trusted_funding_domain(url) or program_evidence))
    if not official: return None
    amount=_published_field(evidence,[r'((?:\$[\d,]+(?:\.\d{2})?)(?:\s*(?:-|–|to)\s*\$[\d,]+(?:\.\d{2})?)?)'])
    deadline=_published_field(evidence,[r'(?:deadline|due date|applications? due)\s*[:\-]?\s*((?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},?\s+20\d{2})',r'(?:deadline|due date)\s*[:\-]?\s*(20\d{2}-\d{2}-\d{2})'])
    if re.search(r'\brolling\b',evidence,re.I): deadline='Rolling'
    reported=''
    if re.search(r'\bapplications? (?:are )?open\b|\bnow accepting\b',evidence,re.I): reported='OPEN'
    if re.search(r'\bopening soon\b|\bopens? (?:on|in)\b',evidence,re.I): reported='OPENING SOON'
    if re.search(r'\brecurring\b|\bannual program\b',evidence,re.I): reported='RECURRING'
    if re.search(r'\bclosed\b',evidence,re.I): reported='CLOSED — EXPECTED TO RETURN' if re.search(r'\bannual|recurring|next round|return\b',evidence,re.I) else 'CLOSED'
    source_name=_clean_text(result.get('profile',{}).get('long_name') if isinstance(result.get('profile'),dict) else '') or host.removeprefix('www.')
    eligibility=_published_field(evidence,[r'(?:eligibility|eligible applicants?|who can apply)\s*[:\-]?\s*(.{30,700}?)(?=(?:deadline|award|funding|apply|application)\s*[:\-]|$)'])
    uses=_published_field(evidence,[r'(?:eligible uses|use of funds|funds may be used for|approved uses)\s*[:\-]?\s*(.{20,600}?)(?=(?:ineligible|deadline|application|required)\s*[:\-]|$)'])
    contact_email=_published_field(evidence,[r'([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})'])
    time_in_business=_published_field(evidence,[r'((?:at least|minimum of|minimum)\s+\d+\s+(?:months?|years?)\s+(?:in business|of operating history))'])
    revenue_requirement=_published_field(evidence,[r'((?:minimum|at least|annual|gross)\s+(?:annual\s+)?revenue[^.;]{0,100}\$[\d,]+)',r'(\$[\d,]+[^.;]{0,80}(?:annual revenue|in revenue))'])
    employee_requirement=_published_field(evidence,[r'((?:fewer than|no more than|between|at least)\s+\d+(?:\s+(?:and|to)\s+\d+)?\s+employees?)'])
    credit_requirement=_published_field(evidence,[r'((?:minimum|required)\s+(?:personal |business )?credit(?: score)?[^.;]{0,100})']) if funding_type=='Loan' else ''
    collateral_requirement=_published_field(evidence,[r'((?:collateral|security)\s+(?:is |may be |must be )?(?:required|not required|evaluated)[^.;]{0,100})']) if funding_type=='Loan' else ''
    personal_guarantee=_published_field(evidence,[r'((?:personal guarantee|personal guaranty)\s+(?:is |may be |must be )?(?:required|not required|evaluated)[^.;]{0,100})']) if funding_type=='Loan' else ''
    repayment_requirements=_published_field(evidence,[r'((?:repayment|monthly payments?|payment schedule)\s*[:\-]?\s*[^.;]{10,180})']) if funding_type=='Loan' else ''
    startup_eligibility='Startup eligible' if re.search(r'\bstartups?\b|\bnew businesses?\b',evidence,re.I) and not re.search(r'\bstartups? (?:are )?not eligible\b',evidence,re.I) else ''
    source_id=hashlib.sha256(url.encode()).hexdigest()[:24]
    interest_rate=_published_field(evidence,[r'((?:interest rate|rate|apr)\s*(?:of|is|:|-)?\s*(?:from|as low as|up to)?\s*\d+(?:\.\d+)?\s*%)']) if funding_type=='Loan' else ''
    term=_published_field(evidence,[r'((?:loan term|repayment term|term)\s*(?:of|is|:|-)?\s*(?:up to)?\s*\d+\s*(?:months?|years?))']) if funding_type=='Loan' else ''
    return {'source':source_name,'source_id':'web-'+source_id,'title':title,'agency':source_name,'opportunity_type':funding_type,'government_level':query_meta.get('level') or 'National/Private','service_area':query_meta.get('location') or 'Not published by funding source','amount_text':amount or 'Not published by funding source','deadline':deadline,'open_date':'','status':_opportunity_status(deadline,reported),'eligibility':eligibility or 'Not published by funding source','required_certifications':[],'required_documents':[],'eligible_industries':[],'eligible_business_stages':[startup_eligibility] if startup_eligibility else [],'funding_uses':[uses] if uses else [],'description':snippet,'source_url':url,'application_url':url,'eligibility_url':url,'contact_name':'','contact_email':contact_email,'contact_phone':'','time_in_business':time_in_business,'revenue_requirement':revenue_requirement,'employee_requirement':employee_requirement,'interest_rate':interest_rate or ('Rate determined by lender' if funding_type=='Loan' else ''),'term':term or ('Not published by lender' if funding_type=='Loan' else ''),'credit_requirements':credit_requirement,'collateral_requirements':collateral_requirement,'personal_guarantee':personal_guarantee,'repayment_requirements':repayment_requirements,'last_verified_at':now(),'official_source_verified':official,'discovered_via':provider,'search_query':query_meta.get('query',''),'search_focus':query_meta.get('focus',''),'search_pass':query_meta.get('pass','')}

def _deep_live_funding_search(facts,funding_type,level='All',manual_location=''):
    plan=_deep_funding_queries(facts,funding_type,level,manual_location); discovered=[]; errors=[]
    if not (os.environ.get('BRAVE_SEARCH_API_KEY','').strip() or os.environ.get('BING_SEARCH_API_KEY','').strip() or (os.environ.get('GOOGLE_CSE_API_KEY','').strip() and os.environ.get('GOOGLE_CSE_ID','').strip())): return [],plan,['Live web search is not configured. Configure Brave, Bing, or Google Programmable Search credentials.']
    with ThreadPoolExecutor(max_workers=4) as pool:
        futures={pool.submit(_configured_funding_web_search,item['query'],8):item for item in plan}
        for future in as_completed(futures):
            meta=futures[future]
            try:
                web_results,provider=future.result()
                for result in web_results:
                    item=_web_result_to_opportunity(result,meta,funding_type,provider)
                    if item: discovered.append(item)
            except Exception as exc: errors.append(f"{meta['location'] or meta['level']}: {type(exc).__name__}")
    merged=_merge_opportunities(discovered); merged.sort(key=lambda o:(_verification_state(o)['active_verified'],_funding_analysis(o,facts)['match_score'],_trusted_funding_domain(o.get('source_url',''))),reverse=True)
    return merged[:40],plan,errors

def _manual_loan_search_plan(facts,amount='',purpose='',stage='',level='All',manual_location='',keyword=''):
    """Build loan-only searches from the submitted form, from local to national."""
    local_facts=dict(facts); manual=_clean_text(manual_location)
    if manual:
        parts=[x.strip() for x in manual.split(',') if x.strip()]
        if level=='All':
            local_facts['city']=parts[0] if parts else manual
            local_facts['state']=parts[-1] if len(parts)>1 else _clean_text(facts.get('state'))
            local_facts['county']='Wayne' if local_facts['city'].lower()=='detroit' else ''
        elif level=='City': local_facts['city']=parts[0] if parts else manual
        elif level=='County': local_facts['county']=(parts[0] if parts else manual).removesuffix(' County')
        elif level=='State': local_facts['state']=parts[-1] if parts else manual
    geography=_funding_geography_terms(local_facts,level,'')
    member_terms=re.sub(r'\s+',' ',_clean_text(keyword)).strip()[:120]
    submitted=' '.join(x for x in (member_terms,_clean_text(stage),_clean_text(purpose),_clean_text(amount)) if x).strip()
    primary=member_terms or _clean_text(purpose) or 'small business financing'; purpose_term=_clean_text(purpose) or primary; stage_term=_clean_text(stage) or 'small business'; plan=[]
    def add(search_level,location,focus,pass_name):
        query=re.sub(r'\s+',' ',f'{location} {focus} official').strip()
        plan.append({'level':search_level,'location':location,'focus':focus,'pass':pass_name,'query':query})
    for geo_level,geo in geography:
        if geo_level=='City':
            add(geo_level,geo,f'{primary} business loan {stage_term} {amount}','member terms — city financing'); add(geo_level,geo,f'{primary} microloan CDFI community business lender','member terms — city community lenders')
        elif geo_level=='County':
            add(geo_level,geo,f'{primary} business loan economic development {submitted}','member terms — county financing'); add(geo_level,geo,f'{primary} CDFI microloan community development lender','member terms — county community lenders')
        elif geo_level=='Regional': add(geo_level,geo,f'{primary} financing CDFI community bank credit union {submitted}','member terms — regional lenders')
        elif geo_level=='State':
            add(geo_level,geo,f'{primary} state economic development business loan {submitted}','member terms — state financing'); add(geo_level,geo,f'{primary} {stage_term} microloan CDFI {amount}','member terms — state CDFI and microloan')
        elif geo_level=='Federal':
            add(geo_level,'United States',f'{primary} SBA {stage_term} business loan {amount}','member terms — SBA and federal'); add(geo_level,'United States',f'{primary} SBA microloan participating lender','member terms — SBA lenders')
        elif geo_level=='National/Private':
            add(geo_level,'United States',f'{primary} {stage_term} financing {amount} bank credit union','member terms — national lenders'); add(geo_level,'United States',f'{primary} microloan CDFI nonprofit lender','member terms — national mission lenders')
    unique=[]; seen=set()
    for item in plan:
        key=re.sub(r'\W+',' ',item['query'].lower()).strip()
        if key not in seen: seen.add(key); unique.append(item)
    return unique[:18]

def _deep_live_manual_loan_search(facts,amount='',purpose='',stage='',level='All',manual_location='',keyword=''):
    plan=_manual_loan_search_plan(facts,amount,purpose,stage,level,manual_location,keyword); discovered=[]; errors=[]
    configured=(os.environ.get('BRAVE_SEARCH_API_KEY','').strip() or os.environ.get('BING_SEARCH_API_KEY','').strip() or (os.environ.get('GOOGLE_CSE_API_KEY','').strip() and os.environ.get('GOOGLE_CSE_ID','').strip()))
    if not configured: return [],plan,['Live web search is not configured. Configure Brave, Bing, or Google Programmable Search credentials.']
    with ThreadPoolExecutor(max_workers=4) as pool:
        futures={pool.submit(_configured_funding_web_search,item['query'],8):item for item in plan}
        for future in as_completed(futures):
            meta=futures[future]
            try:
                web_results,provider=future.result()
                for result in web_results:
                    item=_web_result_to_opportunity(result,meta,'Loan',provider)
                    if item: discovered.append(item)
            except Exception as exc: errors.append(f"{meta['location'] or meta['level']}: {type(exc).__name__}")
    merged=_merge_opportunities(discovered); merged.sort(key=lambda o:(_verification_state(o)['active_verified'],_funding_analysis(o,facts)['match_score'],_trusted_funding_domain(o.get('source_url',''))),reverse=True)
    return merged[:40],plan,errors

def _manual_grant_variations(keyword):
    """Keep manual discovery centered on the member's words, never their plan categories."""
    phrase=re.sub(r'\s+',' ',_clean_text(keyword)).strip()[:120]
    if not phrase: return []
    topic=re.sub(r'\s+(?:grants?|grant funding|funding)$','',phrase,flags=re.I).strip() or phrase
    variations=[topic,f'{topic} grant',f'{topic} small business grant',f'{topic} entrepreneur funding',f'{topic} program funding']
    lower=topic.lower()
    related={
        'wellness':['well-being grant','health and wellness funding','community wellness grant'],
        'technology':['technology innovation grant','small business technology funding'],
        'community garden':['community gardening grant','urban agriculture funding'],
        'mental wellness':['mental wellness funding','community mental health and wellness grant']}
    for key,items in related.items():
        if key in lower: variations.extend(items)
    out=[]; seen=set()
    for value in variations:
        normalized=re.sub(r'\W+',' ',value.lower()).strip()
        if normalized and normalized not in seen: seen.add(normalized); out.append(value)
    return out[:8]

def _manual_grant_search_plan(facts,keyword,level='All',manual_location='',stage='',purpose=''):
    local_facts=dict(facts); manual=_clean_text(manual_location)
    if manual and level=='All':
        parts=[x.strip() for x in manual.split(',') if x.strip()]
        local_facts['city']=parts[0] if parts else manual; local_facts['state']=parts[-1] if len(parts)>1 else facts.get('state',''); local_facts['county']='Wayne' if local_facts['city'].lower()=='detroit' else ''
    geography=_funding_geography_terms(local_facts,level,manual); variations=_manual_grant_variations(keyword); plan=[]; filters=' '.join(x for x in (_clean_text(stage),_clean_text(purpose)) if x)
    primary=variations[0] if variations else _clean_text(keyword)
    for geo_level,geo in geography:
        plan.append({'level':geo_level,'location':geo,'focus':primary,'pass':'manual keyword','query':f'{geo} {primary} grant official'})
        if geo_level in {'City','County','Regional','State'}: plan.append({'level':geo_level,'location':geo,'focus':primary,'pass':'manual keyword funding programs','query':f'{geo} {primary} funding program official'})
        if geo_level=='State' and filters: plan.append({'level':'State','location':geo,'focus':primary,'pass':'member-selected filters','query':f'{geo} {primary} grant {filters} official'})
    for variation in variations[1:5]: plan.append({'level':'National/Private','location':'United States','focus':variation,'pass':'closely related manual-keyword variation','query':f'{variation} official application'})
    unique=[]; seen=set()
    for item in plan:
        key=re.sub(r'\W+',' ',item['query'].lower()).strip()
        if key not in seen: seen.add(key); unique.append(item)
    return unique[:18]

def _manual_grants_gov_search(keyword):
    terms=_manual_grant_variations(keyword)[:6]; found=[]; errors=[]
    with ThreadPoolExecutor(max_workers=3) as pool:
        futures={pool.submit(_grants_gov_search,term):f'Grants.gov — {term}' for term in terms}
        if os.environ.get('SIMPLER_GRANTS_API_KEY','').strip():
            futures.update({pool.submit(_simpler_grants_search,term):f'Simpler.Grants.gov — {term}' for term in terms})
        for future in as_completed(futures):
            try: found.extend(future.result())
            except Exception as exc: errors.append(f'{futures[future]}: {type(exc).__name__}')
    return _merge_opportunities(found),errors

def _deep_live_manual_grant_search(facts,keyword,level='All',manual_location='',stage='',purpose=''):
    plan=_manual_grant_search_plan(facts,keyword,level,manual_location,stage,purpose); discovered=[]; errors=[]
    configured=bool(os.environ.get('BRAVE_SEARCH_API_KEY','').strip() or os.environ.get('BING_SEARCH_API_KEY','').strip() or (os.environ.get('GOOGLE_CSE_API_KEY','').strip() and os.environ.get('GOOGLE_CSE_ID','').strip()))
    if not configured: return [],plan,['Live web search is not configured. Configure Brave, Bing, or Google Programmable Search credentials.']
    with ThreadPoolExecutor(max_workers=4) as pool:
        futures={pool.submit(_configured_funding_web_search,item['query'],8):item for item in plan}
        for future in as_completed(futures):
            meta=futures[future]
            try:
                web_results,provider=future.result()
                for result in web_results:
                    item=_web_result_to_opportunity(result,meta,'Grant',provider)
                    if item: discovered.append(item)
            except Exception as exc: errors.append(f"{meta['location'] or meta['level']}: {type(exc).__name__}")
    return _merge_opportunities(discovered)[:40],plan,errors

def _expanded_grants_gov_search(facts,manual_keyword=''):
    profile=_funding_search_profile(facts)
    terms=[manual_keyword,profile['industry'],profile['primary_activity'],profile['naics']]+profile['needs'][:4]+profile['secondary_activities'][:2]
    terms=[x for x in terms if x]; unique=[]
    for term in terms:
        cleaned=' '.join(re.findall(r'[A-Za-z0-9&/-]{3,}',term)[:6])[:80]
        if cleaned and cleaned.lower() not in {x.lower() for x in unique}: unique.append(cleaned)
    if not unique: unique=['small business']
    found=[]; errors=[]
    with ThreadPoolExecutor(max_workers=3) as pool:
        futures={pool.submit(_grants_gov_search,term):f'Grants.gov — {term}' for term in unique[:8]}
        if os.environ.get('SIMPLER_GRANTS_API_KEY','').strip():
            futures.update({pool.submit(_simpler_grants_search,term):f'Simpler.Grants.gov — {term}' for term in unique[:8]})
        for future in as_completed(futures):
            try: found.extend(future.result())
            except Exception as exc: errors.append(f'{futures[future]}: {type(exc).__name__}')
    return _merge_opportunities(found),errors

def _tokens(*values):
    return {w for w in re.findall(r'[a-z0-9]{3,}', ' '.join(_clean_text(v).lower() for v in values)) if w not in {'business','funding','grant','loan','small','with','from','that','this','your','program'}}

def _opportunity_status(deadline,reported=''):
    status=_clean_text(reported).upper()
    if status in {'OPEN','OPENING SOON','UPCOMING','ROLLING','RECURRING','CLOSING SOON','CLOSED','CLOSED — EXPECTED TO RETURN','DEADLINE PASSED','UNVERIFIED','NEEDS VERIFICATION'}: return status
    if not deadline: return 'NEEDS VERIFICATION'
    if 'rolling' in deadline.lower(): return 'ROLLING'
    try:
        raw=deadline.strip().replace(',',''); dt=None
        try: dt=datetime.fromisoformat(raw[:10]).date()
        except Exception:
            for fmt in ('%B %d %Y','%b %d %Y'):
                try: dt=datetime.strptime(raw,fmt).date(); break
                except Exception: pass
        if not dt: return 'NEEDS VERIFICATION'
        days=(dt-datetime.now(timezone.utc).date()).days
        if days<0: return 'DEADLINE PASSED'
        if days<=14: return 'CLOSING SOON'
        return 'OPEN'
    except Exception: return 'NEEDS VERIFICATION'

def _official_funding_url(value):
    """Accept only traceable official program/lender URLs; never blog or lead-list URLs."""
    try:
        parsed=urllib.parse.urlparse(_clean_text(value))
        host=(parsed.hostname or '').lower().strip('.')
    except Exception:
        return False
    if parsed.scheme != 'https' or not host:
        return False
    if host.endswith('.gov') or host in {'grants.gov','www.grants.gov','sam.gov','www.sam.gov'}:
        return True
    # Non-government opportunities may be added only from a specifically
    # reviewed official organization/lender record. This flag is never inferred
    # from a third-party URL.
    return False

def _verification_state(opp):
    official_url=opp.get('source_url') or opp.get('official_url')
    application_url=opp.get('application_url') or official_url
    checked=_clean_text(opp.get('last_verified_at') or opp.get('last_checked_at'))
    status=_opportunity_status(opp.get('deadline',''),opp.get('status',''))
    reasons=[]
    server_vetted=bool(opp.get('official_source_verified'))
    if opp.get('discovered_via') and not server_vetted: reasons.append('the official page could not be retrieved for verification')
    if not (_official_funding_url(official_url) or server_vetted): reasons.append('official opportunity source is not confirmed')
    if not (_official_funding_url(application_url) or server_vetted): reasons.append('official application page is not confirmed')
    if status in {'NEEDS VERIFICATION','UNVERIFIED'}: reasons.append('current opening status or deadline is not confirmed')
    if status in {'CLOSED','CLOSED — EXPECTED TO RETURN','DEADLINE PASSED'}: reasons.append('the published deadline has passed or the source reports closed')
    if not checked: reasons.append('last checked date is missing')
    elif checked:
        try:
            age=(datetime.now(timezone.utc)-datetime.fromisoformat(checked.replace('Z','+00:00'))).days
            if age>14: reasons.append('official-source check is more than 14 days old')
        except Exception: reasons.append('last checked date needs confirmation')
    active=status in {'OPEN','OPENING SOON','UPCOMING','ROLLING','RECURRING','CLOSING SOON'} and not reasons
    label='VERIFIED ACTIVE OPPORTUNITY' if active else ('POTENTIAL OPPORTUNITY — VERIFICATION REQUIRED' if status not in {'CLOSED','CLOSED — EXPECTED TO RETURN','DEADLINE PASSED'} else status)
    return {'active_verified':active,'label':label,'status':status,'reasons':reasons,'last_checked':checked or 'Not checked'}

def _funding_analysis(opp,facts):
    profile=_funding_search_profile(facts)
    hay=' '.join(_clean_text(opp.get(k,'')) for k in ('title','agency','description','eligibility','eligible_industries','eligible_business_stages','funding_uses','service_area','state','time_in_business','revenue_requirement','employee_requirement','required_certifications')).lower()
    checks=[]; score=0; possible=0
    def add(label,weight,met=None,detail=''):
        nonlocal score,possible
        possible+=weight
        if met is True: score+=weight; state='✓ Appears Met'
        elif met is False: state='✕ Does Not Appear Eligible'
        elif met is None: state='○ Not Recorded'
        else: state='! Needs Verification'
        checks.append({'label':label,'state':state,'detail':detail})
    level=opp.get('government_level','Federal'); geo=_clean_text(opp.get('city') or opp.get('county') or opp.get('state') or opp.get('service_area'))
    if level=='Federal' and ('united states' in geo.lower() or not geo): geo_met=True
    elif level=='City': geo_met=(facts['city'].lower() in geo.lower()) if facts['city'] and geo else None
    elif level=='County': geo_met=(facts['county'].lower() in geo.lower()) if facts['county'] and geo else None
    elif level=='State': geo_met=(facts['state'].lower() in geo.lower()) if facts['state'] and geo else None
    elif geo and facts['state']: geo_met=(facts['state'].lower() in geo.lower() or 'united states' in geo.lower())
    else: geo_met='verify'
    add('Business location requirement',25,geo_met,geo or level)
    ft=_tokens(facts['industry'],facts['services']); ot=_tokens(opp.get('eligible_industries',''),opp.get('description',''),opp.get('title',''))
    add('Industry alignment',15,bool(ft & ot) if ft and ot else 'verify',', '.join(sorted(ft & ot)[:5]) or 'Published industry scope needs review')
    member_terms=_tokens(facts.get('member_search_terms','')); result_terms=_tokens(opp.get('title',''),opp.get('description',''),opp.get('eligibility',''),opp.get('funding_uses',''))
    if member_terms: add('Member search-term alignment',25,bool(member_terms & result_terms),', '.join(sorted(member_terms & result_terms)[:6]) or 'The discovered page does not clearly reflect the member-entered terms')
    stages=_clean_text(opp.get('eligible_business_stages',''))
    add('Business stage requirement',10,(facts['stage'].lower() in stages.lower() or ('startup' in facts['stage'].lower() and 'startup eligible' in stages.lower())) if facts['stage'] and stages else ('verify' if facts['stage'] else None),stages or 'Not provided by official source')
    uses=_tokens(facts['purpose'],facts['goals']); opp_uses=_tokens(opp.get('funding_uses',''),opp.get('description',''))
    add('Use of funds alignment',15,bool(uses & opp_uses) if uses and opp_uses else ('verify' if facts['purpose'] else None),', '.join(sorted(uses & opp_uses)[:5]) or 'Published uses need review')
    structure=profile['structure'].lower(); add('Business structure requirement',5,(structure in hay) if structure and any(x in hay for x in ('llc','corporation','sole proprietor','nonprofit','for-profit')) else ('verify' if structure else None),_clean_text(opp.get('eligibility')) or 'Not provided by official source')
    add('Funding amount within program range',10,'verify' if facts['amount'] else None,opp.get('amount_text') or 'Not provided by official source')
    add('Time in business requirement',5,'verify' if facts['years'] and opp.get('time_in_business') else None,opp.get('time_in_business') or 'Not published by funding source')
    add('Revenue requirement',5,'verify' if facts['revenue'] and opp.get('revenue_requirement') else None,opp.get('revenue_requirement') or 'Not published by funding source')
    add('Employee or business-size requirement',5,'verify' if facts['employees'] and opp.get('employee_requirement') else None,opp.get('employee_requirement') or 'Not published by funding source')
    published_certs=_tokens(opp.get('required_certifications',''),opp.get('eligibility','')); member_certs=_tokens(facts.get('certifications',''))
    add('Required certifications or registrations',5,bool(published_certs & member_certs) if published_certs and member_certs else ('verify' if published_certs else None),_clean_text(opp.get('required_certifications')) or 'None published')
    ownership_terms=[x for x in profile['eligibility_categories'] if x in hay]
    if any(x in hay for x in ('women-owned','woman-owned','minority-owned','veteran-owned','disadvantaged business')): add('Ownership eligibility',5,bool(ownership_terms),', '.join(ownership_terms) or 'Published ownership condition is not recorded in the member profile')
    status=_opportunity_status(opp.get('deadline',''),opp.get('status','')); active=status in {'OPEN','OPENING SOON','UPCOMING','ROLLING','RECURRING','CLOSING SOON'}
    add('Current program status',10,active if status not in {'NEEDS VERIFICATION','UNVERIFIED'} else 'verify',status)
    match=max(0,min(100,round(score*100/possible)))
    if geo_met is False: match=min(match,25)
    if status in {'CLOSED','DEADLINE PASSED'}: match=min(match,20)
    elif status=='CLOSED — EXPECTED TO RETURN': match=min(match,40)
    readiness_items=[('Business Plan completed',facts['plan_complete']),('Business location recorded',bool(facts['city'] or facts['state'])),('Funding purpose recorded',bool(facts['purpose'])),('Funding amount recorded',bool(facts['amount'])),('Financial information available',bool(facts['revenue'])),('Licenses/certifications recorded',bool(facts['certifications']))]
    required_docs=opp.get('required_documents') or []
    if isinstance(required_docs,str):
        try: required_docs=json.loads(required_docs)
        except Exception: required_docs=[required_docs] if required_docs else []
    readiness=round(100*sum(1 for _,v in readiness_items if v)/(len(readiness_items) or 1))
    strengths=[c['label'] for c in checks if c['state']=='✓ Appears Met']
    conflicts=[c['label'] for c in checks if c['state']=='✕ Does Not Appear Eligible']
    gaps=[c['label'] for c in checks if c['state'] not in {'✓ Appears Met','✕ Does Not Appear Eligible'}]
    known=[c for c in checks if c['state'] in {'✓ Appears Met','✕ Does Not Appear Eligible'}]; met=sum(1 for c in known if c['state']=='✓ Appears Met'); eligibility_percent=round(100*met/len(known)) if known else 0
    eligibility_confidence='Known Conflict' if conflicts else ('Strong' if len(known)>=5 and eligibility_percent>=80 else ('Moderate' if len(known)>=3 and eligibility_percent>=60 else 'Limited Published Evidence'))
    rank='Not Currently Eligible' if conflicts else ('Best Match' if match>=80 and len(gaps)<=2 else ('Good Match' if match>=60 else 'Possible Match'))
    reason=(f"This {str(opp.get('opportunity_type','funding')).lower()} appears relevant to {facts['business_name'] or 'your business'} because " + (', '.join(x.lower() for x in strengths[:3]) if strengths else 'its official requirements overlap parts of your saved business information') + '. ' + (f"Before applying, verify {', '.join(x.lower() for x in gaps[:2])}." if gaps else 'Review the official notice before applying.'))
    return {'match_score':match,'readiness_score':readiness,'eligibility_confidence':eligibility_confidence,'eligibility_requirements_met':met,'eligibility_requirements_known':len(known),'checks':checks,'strengths':strengths,'gaps':gaps,'conflicts':conflicts,'rank':rank,'match_reason':reason,'readiness_items':readiness_items,'required_documents':required_docs}

def _grants_gov_detail(opportunity_id):
    """Retrieve published detail for one Grants.gov result; no API key is required."""
    req=urllib.request.Request('https://api.grants.gov/v1/api/fetchOpportunity',data=json.dumps({'opportunityId':int(opportunity_id)}).encode(),headers={'Content-Type':'application/json','User-Agent':'The-Seasons-Within/1.0'},method='POST')
    with urllib.request.urlopen(req,timeout=20) as resp: payload=json.loads(resp.read().decode('utf-8'))
    return payload.get('data',payload) if isinstance(payload,dict) else {}

def _published_amount(floor,ceiling,estimated=''):
    def money(value):
        raw=_clean_text(value).replace('$','').replace(',','')
        try: return '${:,.0f}'.format(float(raw))
        except Exception: return ''
    low=money(floor); high=money(ceiling)
    if low and high: return low if low==high else f'{low}–{high}'
    return high or low or money(estimated) or ''

def _grants_gov_search(keyword):
    body={'keyword':keyword or 'small business','oppStatuses':'posted|forecasted','rows':25}
    req=urllib.request.Request('https://api.grants.gov/v1/api/search2',data=json.dumps(body).encode(),headers={'Content-Type':'application/json','User-Agent':'The-Seasons-Within/1.0'},method='POST')
    with urllib.request.urlopen(req,timeout=25) as resp: data=json.loads(resp.read().decode('utf-8'))
    root=data.get('data',data) if isinstance(data,dict) else {}; hits=root.get('oppHits') or root.get('opportunities') or root.get('results') or []
    out=[]
    for index,item in enumerate(hits[:25]):
        if not isinstance(item,dict): continue
        oid=str(item.get('id') or item.get('opportunityId') or item.get('number') or item.get('opportunityNumber') or '')
        detail={}
        if index<5 and oid.isdigit():
            try: detail=_grants_gov_detail(oid)
            except Exception: detail={}
        synopsis=detail.get('synopsis') if isinstance(detail.get('synopsis'),dict) else {}
        title=_clean_text(detail.get('opportunityTitle') or item.get('title') or item.get('opportunityTitle') or 'Federal funding opportunity'); agency=_clean_text(synopsis.get('agencyName') or item.get('agencyName') or item.get('agency') or '')
        description=_clean_text(synopsis.get('synopsisDesc') or item.get('synopsis') or item.get('description') or '')
        applicants=synopsis.get('applicantTypes') or item.get('eligibilities') or item.get('eligibleApplicants') or ''
        eligibility=', '.join(_clean_text(x.get('description')) for x in applicants if isinstance(x,dict)) if isinstance(applicants,list) else _clean_text(applicants)
        # Exclude clearly international/diplomatic and defense/research notices from ordinary small-business results.
        excluded=' '.join((title,agency,description)).lower()
        if any(x in excluded for x in ('embassy ','department of defense','dod ','foreign assistance','international development','latvia','tunisia','indonesia')): continue
        deadline=_clean_text(synopsis.get('responseDate') or detail.get('originalDueDateDesc') or item.get('closeDate') or item.get('closeDateDesc') or item.get('deadline') or '')
        contact_name=_clean_text(synopsis.get('agencyContactName')); contact_email=_clean_text(synopsis.get('agencyContactEmail')); contact_phone=_clean_text(synopsis.get('agencyContactPhone'))
        amount=_published_amount(synopsis.get('awardFloor') or synopsis.get('awardFloorFormatted'),synopsis.get('awardCeiling') or synopsis.get('awardCeilingFormatted'),item.get('estimatedFunding'))
        funding_uses=[_clean_text(x.get('description')) for x in (synopsis.get('fundingActivityCategories') or []) if isinstance(x,dict) and _clean_text(x.get('description'))]
        official=('https://www.grants.gov/search-results-detail/'+urllib.parse.quote(oid)) if oid else 'https://www.grants.gov/search-results'
        out.append({'source':'Grants.gov','source_id':oid or hashlib.sha256(title.encode()).hexdigest()[:20],'title':title,'agency':agency,'opportunity_type':'Grant','government_level':'Federal','service_area':'United States / see official notice','amount_text':amount or 'Not published by funding source','deadline':deadline,'open_date':_clean_text(synopsis.get('postingDate') or item.get('openDate') or item.get('postDate') or ''),'status':_opportunity_status(deadline,item.get('oppStatus') or item.get('status','')),'eligibility':eligibility or 'Not published by funding source','required_certifications':[],'required_documents':[],'eligible_industries':[],'eligible_business_stages':[],'funding_uses':funding_uses,'description':description,'source_url':official,'application_url':official,'eligibility_url':official,'contact_name':contact_name,'contact_email':contact_email,'contact_phone':contact_phone,'matching_funds':'Required' if synopsis.get('costSharing') is True else ('Not required' if synopsis.get('costSharing') is False else ''),'last_verified_at':now(),'official_source_verified':True})
    return out

def _simpler_grants_search(keyword):
    """Optional official federal search. Configure SIMPLER_GRANTS_API_KEY server-side."""
    token=os.environ.get('SIMPLER_GRANTS_API_KEY','').strip()
    if not token: return []
    endpoint=os.environ.get('SIMPLER_GRANTS_API_URL','https://api.simpler.grants.gov/v1/opportunities/search').strip()
    body={'query':keyword or 'small business','filters':{'opportunity_status':{'one_of':['posted','forecasted']}},'pagination':{'page_offset':1,'page_size':25,'sort_order':[{'order_by':'relevancy','sort_direction':'descending'}]}}
    req=urllib.request.Request(endpoint,data=json.dumps(body).encode(),headers={'Accept':'application/json','Content-Type':'application/json','X-API-Key':token,'User-Agent':'The-Seasons-Within/1.0'},method='POST')
    with urllib.request.urlopen(req,timeout=25) as resp: payload=json.loads(resp.read().decode('utf-8'))
    root=payload.get('data',payload) if isinstance(payload,dict) else {}; hits=root.get('opportunities') or root.get('results') or root.get('items') or []
    out=[]
    for raw in hits[:25]:
        if not isinstance(raw,dict): continue
        item=raw.get('opportunity') if isinstance(raw.get('opportunity'),dict) else raw
        oid=_clean_text(item.get('opportunity_id') or item.get('id') or item.get('opportunity_number'))
        title=_clean_text(item.get('opportunity_title') or item.get('title')); agency_value=item.get('agency') or item.get('agency_name') or ''
        agency=_clean_text(agency_value.get('agency_name') if isinstance(agency_value,dict) else agency_value)
        if not title or not oid: continue
        summary=item.get('summary') if isinstance(item.get('summary'),dict) else {}
        deadline=_clean_text(summary.get('close_date') or item.get('close_date')); status=_clean_text(item.get('opportunity_status') or item.get('status'))
        award_floor=summary.get('award_floor') or item.get('award_floor'); award_ceiling=summary.get('award_ceiling') or item.get('award_ceiling')
        applicants=item.get('applicant_types') or summary.get('applicant_types') or []
        eligibility=', '.join(_clean_text(x.get('description') if isinstance(x,dict) else x) for x in applicants) if isinstance(applicants,list) else _clean_text(applicants)
        official='https://simpler.grants.gov/opportunity/'+urllib.parse.quote(oid)
        out.append({'source':'Simpler.Grants.gov','source_id':oid,'title':title,'agency':agency or 'Federal agency — see official notice','opportunity_type':'Grant','government_level':'Federal','service_area':'United States / see official notice','amount_text':_published_amount(award_floor,award_ceiling) or 'Not published by funding source','deadline':deadline,'open_date':_clean_text(summary.get('post_date') or item.get('post_date')),'status':_opportunity_status(deadline,status),'eligibility':eligibility or 'Not published by funding source','required_certifications':[],'required_documents':[],'eligible_industries':[],'eligible_business_stages':[],'funding_uses':[],'description':_clean_text(summary.get('summary_description') or item.get('description')),'source_url':official,'application_url':official,'eligibility_url':official,'contact_name':'','contact_email':'','contact_phone':'','last_verified_at':now(),'official_source_verified':True})
    return out

def _official_loan_programs():
    # These descriptions were reviewed against the linked SBA program pages on
    # this build date. They become Needs Verification after the freshness window.
    stamp='2026-08-27T00:00:00+00:00'
