def _store_funding_opportunity(opp):
    conn=db()
    try:
        fields=('source','source_id','opportunity_type','title','agency','government_level','city','county','state','service_area','source_url','application_url','contact_name','contact_email','contact_phone','funding_min','funding_max','amount_text','deadline','open_date','status','eligibility','required_certifications','required_documents','eligible_industries','eligible_business_stages','funding_uses','description')
        vals={k:opp.get(k,'') for k in fields}; vals['source_name']=vals.pop('source'); vals['agency_name']=vals.pop('agency'); vals['official_url']=vals.pop('source_url')
        for key in ('required_certifications','required_documents','eligible_industries','eligible_business_stages','funding_uses'):
            if not isinstance(vals[key],str): vals[key]=json.dumps(vals[key] or [])
        vals['status']=_opportunity_status(str(vals['deadline'] or ''),str(vals['status'] or ''))
        columns=['source_name','source_id','opportunity_type','title','agency_name','government_level','city','county','state','service_area','official_url','application_url','contact_name','contact_email','contact_phone','funding_min','funding_max','amount_text','deadline','open_date','status','eligibility','required_certifications','required_documents','eligible_industries','eligible_business_stages','funding_uses','description']
        values=[vals.get(k) for k in columns]
        conn.execute(f'''INSERT INTO funding_opportunities({','.join(columns)},raw_payload,retrieved_at,last_verified_at) VALUES({','.join('?' for _ in columns)},?,?,?) ON CONFLICT(source_name,source_id) DO UPDATE SET title=excluded.title,agency_name=excluded.agency_name,amount_text=excluded.amount_text,deadline=excluded.deadline,status=excluded.status,eligibility=excluded.eligibility,description=excluded.description,raw_payload=excluded.raw_payload,retrieved_at=excluded.retrieved_at,last_verified_at=excluded.last_verified_at''',tuple(values+[json.dumps(opp),now(),opp.get('last_verified_at') or now()]))
        row=conn.execute('SELECT id FROM funding_opportunities WHERE source_name=? AND source_id=?',(vals['source_name'],vals['source_id'])).fetchone()
        conn.commit()
        return row['id'] if row else None
    except Exception:
        try: conn.rollback()
        except Exception: pass
        raise
    finally:
        conn.close()

def _cache_funding_opportunity(opp):
    """A cache outage must not turn a valid funding search into a 500 page."""
    try:
        return _store_funding_opportunity(opp)
    except Exception:
        app.logger.exception('Funding cache write failed for %s/%s',opp.get('source'),opp.get('source_id'))
        return None

def _stored_funding_opportunities(opportunity_type=''):
    conn=db(); rows=conn.execute('SELECT * FROM funding_opportunities WHERE opportunity_type=? ORDER BY last_verified_at DESC',(opportunity_type,)).fetchall() if opportunity_type else conn.execute('SELECT * FROM funding_opportunities ORDER BY last_verified_at DESC').fetchall(); conn.close(); out=[]
    for r in rows:
        item=dict(r); item.update({'source':item.pop('source_name'),'agency':item.pop('agency_name'),'source_url':item.pop('official_url')})
        try:
            raw=json.loads(item.get('raw_payload') or '{}')
            if isinstance(raw,dict):
                for key,value in raw.items():
                    if key not in item or item.get(key) in (None,'',[]): item[key]=value
        except Exception: pass
        for key in ('required_certifications','required_documents','eligible_industries','eligible_business_stages','funding_uses'):
            try: item[key]=json.loads(item.get(key) or '[]')
            except Exception: item[key]=[item.get(key)] if item.get(key) else []
        out.append(item)
    return out

def _merge_opportunities(*groups):
    merged={}
    def key(item):
        url=_clean_text(item.get('source_url') or item.get('application_url')).lower().rstrip('/')
        if url:
            parsed=urllib.parse.urlsplit(url); return ('url',(parsed.hostname or '').removeprefix('www.')+(parsed.path.rstrip('/') or '/'))
        title=re.sub(r'\W+',' ',_clean_text(item.get('title')).lower()).strip(); agency=re.sub(r'\W+',' ',_clean_text(item.get('agency') or item.get('source')).lower()).strip()
        return ('name',title,agency)
    def quality(item):
        status=_opportunity_status(item.get('deadline',''),item.get('status',''))
        return (5 if item.get('official_source_verified') else 0)+(4 if _trusted_funding_domain(item.get('source_url','')) else 0)+(3 if item.get('source') in {'Grants.gov','SBA.gov'} else 0)+(2 if status in {'OPEN','ROLLING','RECURRING','OPENING SOON','UPCOMING','CLOSING SOON'} else 0)+(1 if item.get('last_verified_at') else 0)
    for group in groups:
        for item in group:
            item_key=key(item)
            if item_key not in merged or quality(item)>quality(merged[item_key]): merged[item_key]=item
    return list(merged.values())

def _funding_card(opp,facts):
    analysis=_funding_analysis(opp,facts); verification=_verification_state(opp); opp=dict(opp); opp.update(analysis); opp['verification']=verification
    level=_clean_text(opp.get('government_level')) or 'Federal'; typ=_clean_text(opp.get('opportunity_type')) or 'Funding'; deadline=_clean_text(opp.get('deadline')) or 'Not provided by official source'; amount=_clean_text(opp.get('amount_text')) or 'Not provided by official source'
    def official(value): return html.escape(_clean_text(value) or 'Not provided by official source')
    checklist=''.join(f'''<li><b>{html.escape(c['label'])}</b> — {html.escape(c['state'])}<br><small>{html.escape(c['detail'] or '')}</small></li>''' for c in analysis['checks'])
    requirement_total=analysis['eligibility_requirements_known']; requirement_met=analysis['eligibility_requirements_met']; eligibility_strength=analysis['eligibility_confidence']
    packed=html.escape(json.dumps(opp),quote=True)
    tool_label='Build Cash-Flow Statement' if typ.lower()=='loan' else ('Start Government Proposal' if typ.lower() in {'contract','government contract'} else 'Create Grant Budget')
    verification_notes=''.join(f'<li>{html.escape(x)}</li>' for x in verification['reasons'])
    calendar_label='Add Follow-Up to Funding Calendar' if typ.lower()=='loan' else 'Add Deadline to Funding Calendar'
    eligibility_label='Check My Qualifications' if typ.lower()=='loan' else 'Check My Eligibility'
    proposal_label='Start Loan Application Package' if typ.lower()=='loan' else 'Start Grant Proposal'
    saved_record=None
    if facts.get('user_id'):
        conn=db()
        try: saved_record=conn.execute('SELECT id FROM saved_funding_opportunities WHERE user_id=? AND source=? AND source_id=?',(facts['user_id'],opp.get('source',''),opp.get('source_id',''))).fetchone()
        finally: conn.close()
    if not verification['active_verified']:
        actions='''<p class="muted"><b>This record cannot be treated as an active match yet.</b> Use the official source to confirm the opening status, requirements and application page.</p>'''
    elif saved_record:
        actions=f'''<div class="actions"><span class="badge">SAVED</span><a class="btn" href="{url_for('saved_opportunity_view',opportunity_id=saved_record['id'])}">View Saved Item</a><a class="out" href="{url_for('business_plan')}#{'loans' if typ.lower()=='loan' else 'grants'}">View in Business Journal</a><form method="post" action="{url_for('delete_saved_opportunity',opportunity_id=saved_record['id'])}" onsubmit="return confirm('Remove this opportunity from your Business Journal?')"><button class="out danger">Unsave / Delete</button></form></div>'''
    else:
        actions=f'''<div class="actions"><form method="post" action="{url_for('save_funding_opportunity')}"><input type="hidden" name="opportunity" value="{packed}"><button class="btn">Save to Business Journal</button></form><form method="post" action="{url_for('save_funding_opportunity')}"><input type="hidden" name="opportunity" value="{packed}"><input type="hidden" name="next_action" value="eligibility"><button class="out">{eligibility_label}</button></form><form method="post" action="{url_for('save_funding_opportunity')}"><input type="hidden" name="opportunity" value="{packed}"><input type="hidden" name="next_action" value="financial"><button class="out">{tool_label}</button></form><form method="post" action="{url_for('save_funding_opportunity')}"><input type="hidden" name="opportunity" value="{packed}"><input type="hidden" name="next_action" value="proposal"><button class="out">{proposal_label}</button></form><form method="post" action="{url_for('save_funding_opportunity')}"><input type="hidden" name="opportunity" value="{packed}"><input type="hidden" name="next_action" value="calendar"><button class="out">{calendar_label}</button></form></div>'''
    source_url=html.escape(opp.get('source_url') or '#',quote=True); application_url=html.escape(opp.get('application_url') or opp.get('source_url') or '#',quote=True); eligibility_url=html.escape(opp.get('eligibility_url') or opp.get('source_url') or '#',quote=True)
    loan_details=f'''<br><b>Published rate / structure:</b> {official(opp.get('interest_rate') or opp.get('rate_structure'))}<br><b>Term:</b> {official(opp.get('term'))}<br><b>Repayment requirements:</b> {official(opp.get('repayment_requirements'))}<br><b>Fees:</b> {official(opp.get('fees'))}<br><b>Credit requirements:</b> {official(opp.get('credit_requirements'))}<br><b>Collateral requirements:</b> {official(opp.get('collateral_requirements'))}<br><b>Personal guarantee:</b> {official(opp.get('personal_guarantee'))}<br><b>Business-age requirement:</b> {official(opp.get('time_in_business'))}<br><b>Revenue requirement:</b> {official(opp.get('revenue_requirement'))}''' if typ.lower()=='loan' else f'''<br><b>Prohibited uses:</b> {official(opp.get('prohibited_uses'))}<br><b>Reporting requirements:</b> {official(opp.get('reporting_requirements'))}<br><b>Matching-fund requirement:</b> {official(opp.get('matching_funds'))}<br><b>Recurring / renewal status:</b> {official(opp.get('recurring_status'))}'''
    visit_label='Visit Official Loan Program' if typ.lower()=='loan' else 'Visit Official Grant'
    if typ.lower()=='loan':
        search_strength='Strong' if analysis['match_score']>=75 else ('Moderate' if analysis['match_score']>=50 else 'Possible')
        evidence_score=(f'''<b>Evidence-based match: {analysis['match_score']}%</b><br><small>Calculated only from published criteria; this is not approval likelihood.</small>''' if verification['active_verified'] and requirement_total>=5 else '''<b>Match score unavailable</b><br><small>Additional lender underwriting information is required.</small>''')
        score_panel=f'''<div class="grid"><div><b>Search Match: {search_strength}</b><br><small>Amount, purpose, stage, location and published program fit.</small></div><div>{evidence_score}</div><div><b>Approval likelihood: Information not available</b><br><small>Cannot be reliably calculated from the lender's published information.</small></div></div>'''
    else:
        score_panel=f'''<div class="grid"><div><b>Business Plan Match: {analysis['match_score']}%</b><br><small>Published-rule alignment, not approval odds.</small></div><div><b>Application Readiness: {analysis['readiness_score']}%</b><br><small>Preparation completed, not approval odds.</small></div><div><b>Eligibility Confidence: {html.escape(eligibility_strength)}</b><br><small>Known requirements met: {requirement_met} of {requirement_total}; unknown items are not counted as met.</small></div></div>'''
    return f'''<article class="card funding-card"><div class="actions"><span class="badge">{html.escape(typ.upper())}</span><span class="badge">{html.escape(level.upper())}</span><span class="badge">{html.escape(verification['label'])}</span><span class="badge">{html.escape(verification['status'])}</span><span class="badge">{html.escape(analysis['rank'])}</span></div><h3>{html.escape(_clean_text(opp.get('title')))}</h3><p><b>Source:</b> {official(opp.get('agency') or opp.get('source'))}</p><p><b>Funding:</b> {html.escape(amount)}<br><b>Open date:</b> {official(opp.get('open_date'))}<br><b>Deadline:</b> {html.escape(deadline)}</p>{score_panel}<details><summary class="out">View Requirements</summary><h3>Why We Matched This to Your Business</h3><p>{html.escape(analysis['match_reason'])}</p><h3>Your Business vs. Requirements</h3><ul>{checklist}</ul>{('<h3>Before You Apply</h3><ul>'+verification_notes+'</ul>') if verification_notes else ''}<p><b>Location / Service Area:</b> {official(opp.get('service_area'))}<br><b>Industry eligibility:</b> {official(opp.get('eligible_industries'))}<br><b>Applicant type / eligibility:</b> {official(opp.get('eligibility'))}<br><b>Business Stage Eligible:</b> {official(opp.get('eligible_business_stages'))}<br><b>Approved Uses:</b> {official(opp.get('funding_uses'))}{loan_details}<br><b>Required Certifications / Registrations:</b> {official(opp.get('required_certifications'))}<br><b>Application requirements / documents:</b> {official(opp.get('required_documents'))}<br><b>Official Contact:</b> {official(opp.get('contact_name'))}<br><b>Email:</b> {official(opp.get('contact_email'))}<br><b>Phone:</b> {official(opp.get('contact_phone'))}<br><b>Last Checked:</b> {html.escape(verification['last_checked'])}</p><div class="actions"><a class="out" target="_blank" rel="noopener" href="{source_url}">{visit_label}</a><a class="out" target="_blank" rel="noopener" href="{eligibility_url}">Eligibility Requirements</a><a class="out" target="_blank" rel="noopener" href="{application_url}">Official Application</a></div></details>{actions}</article>'''

def _financial_number(value):
    """Convert member/imported numeric text without inventing a value."""
    try:
        cleaned=re.sub(r'[^0-9.\-]','',str(value or ''))
        return round(float(cleaned),2) if cleaned not in {'','-','.'} else 0.0
    except (TypeError,ValueError):
        return 0.0

def _financial_plan_seed(user_id):
    """Prefill only values that are explicitly present in the saved Business Plan."""
    answers=_business_plan_answers(user_id)
    def value(*keys):
        for key in keys:
            if answers.get(key) not in (None,''): return answers.get(key)
        return ''
    return {
        'business_name':value('business_name','name'),
        'service_name':value('primary_service','services','products_services'),
        'service_price':_financial_number(value('service_price','price','pricing')),
        'service_sales':_financial_number(value('expected_monthly_clients','expected_sales','customers_per_month')),
        'product_price':_financial_number(value('product_price')),
        'product_sales':_financial_number(value('product_sales','products_per_month')),
        'recurring_revenue':_financial_number(value('monthly_recurring_revenue','membership_revenue')),
        'startup_costs':_financial_number(value('startup_costs','startup_budget')),
        'rent':_financial_number(value('monthly_rent','rent')),
        'utilities':_financial_number(value('monthly_utilities','utilities')),
        'supplies':_financial_number(value('monthly_supplies','supplies')),
        'payroll':_financial_number(value('monthly_payroll','payroll')),
        'contractors':_financial_number(value('monthly_contractors','contractors')),
        'marketing':_financial_number(value('monthly_marketing','marketing_budget')),
        'insurance':_financial_number(value('monthly_insurance','insurance')),
        'technology':_financial_number(value('monthly_technology','software','technology_budget')),
        'professional_services':_financial_number(value('professional_services')),
        'transportation':_financial_number(value('transportation')),
        'taxes_fees':_financial_number(value('taxes_fees')),
        'other_fixed':_financial_number(value('other_fixed_expenses')),
        'variable_cost_percent':_financial_number(value('variable_cost_percent')),
        'monthly_growth_percent':_financial_number(value('monthly_growth_percent','growth_rate')),
        'source_type':'PROJECTED',
        'source_note':'Prefilled from saved Professional Business Plan; review every assumption.'
    }

def _calculate_financial_forecast(assumptions):
    """Rules-based forecast. AI never supplies or changes these calculations."""
    a={k:_financial_number(v) for k,v in assumptions.items() if k not in {'business_name','service_name','source_type','source_note'}}
    service_revenue=a.get('service_price',0)*a.get('service_sales',0)
    product_revenue=a.get('product_price',0)*a.get('product_sales',0)
    base_revenue=round(service_revenue+product_revenue+a.get('recurring_revenue',0),2)
    fixed_keys=('rent','utilities','supplies','payroll','contractors','marketing','insurance','technology','professional_services','transportation','taxes_fees','other_fixed')
    fixed=round(sum(a.get(k,0) for k in fixed_keys),2)
    variable_rate=max(0,min(a.get('variable_cost_percent',0),100))/100
    variable=round(base_revenue*variable_rate,2)
    expenses=round(fixed+variable,2)
    gross=round(base_revenue-variable,2)
    operating=round(base_revenue-expenses,2)
    margin=1-variable_rate
    break_even=round(fixed/margin,2) if margin>0 else 0
    average_sale=a.get('service_price',0) or a.get('product_price',0)
    sales_to_break_even=math.ceil(break_even/average_sale) if average_sale>0 else 0
    growth=max(-100,a.get('monthly_growth_percent',0))/100
    startup_costs=max(0,a.get('startup_costs',0))
    months=[]
    for index in range(36):
        revenue=round(base_revenue*((1+growth)**index),2)
        month_variable=round(revenue*variable_rate,2)
        total=round(fixed+month_variable,2)
        profit_loss=round(revenue-total,2)
        cash_flow=round(profit_loss-(startup_costs if index==0 else 0),2)
        months.append({'month':index+1,'revenue':revenue,'expenses':total,'profit_loss':profit_loss,'cash_flow':cash_flow})
    horizons={}
    for count,label in ((12,'12_month'),(24,'24_month'),(36,'3_year')):
        selected=months[:count]
        horizons[label]={
            'revenue':round(sum(x['revenue'] for x in selected),2),
            'expenses':round(sum(x['expenses'] for x in selected),2),
            'profit_loss':round(sum(x['profit_loss'] for x in selected),2),
            'cash_flow':round(sum(x['cash_flow'] for x in selected),2),
        }
    return {'monthly_revenue':base_revenue,'monthly_fixed_expenses':fixed,'monthly_variable_expenses':variable,'monthly_expenses':expenses,'gross_profit':gross,'operating_profit_loss':operating,'cash_flow':round(operating-startup_costs,2),'break_even_revenue':break_even,'sales_to_break_even':sales_to_break_even,'startup_costs':startup_costs,'months':months,'horizons':horizons,'formula_version':'financial-forecast-v2'}

def _latest_financial_forecast(user_id):
    conn=db(); row=conn.execute('SELECT * FROM financial_forecasts WHERE user_id=? ORDER BY version DESC,id DESC LIMIT 1',(user_id,)).fetchone(); conn.close()
    if not row: return None
    item=dict(row)
    for key in ('assumptions','calculations'):
        try: item[key]=json.loads(item[key] or '{}')
        except Exception: item[key]={}
    return item

def _money(value):
    return '${:,.2f}'.format(_financial_number(value))

