def _business_protection_review(facts):
    """Personalized education only; labels never assert coverage or legal sufficiency."""
    raw=facts.get('raw') or {}; text=' '.join(_clean_text(x) for x in (facts.get('industry'),facts.get('services'),facts.get('goals'),facts.get('purpose'),raw)).lower(); activity=_clean_text(facts.get('services') or facts.get('industry')) or 'the activities in the saved Business Plan'; place=', '.join(x for x in (facts.get('city'),facts.get('state')) if x) or 'the saved business location'
    employees=bool(_clean_text(facts.get('employees')) and _clean_text(facts.get('employees')).lower() not in {'0','none','no'}); physical=any(x in text for x in ('studio','store','office','facility','property','venue','class','retreat','event','in person')); services=any(x in text for x in ('service','consult','coach','teach','instructor','wellness','reiki','therapy','beauty','technology','design','content')); products=any(x in text for x in ('product','sell','retail','inventory','food','cater','online shop')); online=any(x in text for x in ('online','website','platform','app','technology','ecommerce','customer data','member data','digital')); equipment=any(x in text for x in ('equipment','machinery','computer','camera','inventory')); vehicle=any(x in text for x in ('delivery','vehicle','transport','mobile service','travel to clients')); food=any(x in text for x in ('food','cater','restaurant','bakery','meal','beverage','kitchen')); event=any(x in text for x in ('retreat','event','class','workshop','participant','venue','yoga'))
    cards=[]
    def add(key,name,label,plain,protects,example,why,local,questions,source='https://www.sba.gov/counseling/launch-your-business/'):
        cards.append({'key':key,'name':name,'classification':label,'what_it_is':plain,'protects':protects,'example':example,'why':why,'state_considerations':local,'questions':questions,'source_url':source,'last_checked':'2026-08-28'})
    if physical or event or products: add('general-liability','General Liability','Recommended','Coverage commonly considered for certain third-party bodily-injury or property-damage claims.','Certain covered defense, settlement, judgment, medical, or property-damage costs.','A customer, participant, or visitor alleges injury or property damage during a business activity.',f'Your plan describes {activity}, which may involve participants, venues, products, or physical interactions.',f'Ask whether {place} or a landlord, venue, client, lender, or contract requires proof of coverage.',['Which activities and locations are covered?','Are participants, rented premises, and events included?','What exclusions, limits, and deductibles apply?'])
    if services: add('professional-liability','Professional Liability / Errors & Omissions','Recommended','Coverage designed for certain claims alleging mistakes, negligence, or failure in professional services.','Certain covered defense and claim costs connected to professional services.','A client alleges that guidance, instruction, technology work, or another paid service caused a loss.',f'Your Business Plan describes service work: {activity}.','Client, venue, licensing, and professional contracts may request specific coverage.',['Does it cover every service I provide?','Are contractors or instructors covered?','Does it cover prior work and online services?'])
    if products: add('product-liability','Product Liability','Recommended','Coverage commonly considered for claims that a product caused bodily injury or property damage.','Certain covered product claims involving goods made, distributed, prepared, or sold.','A customer alleges that a sold or prepared product caused injury or property damage.',f'Your plan indicates products, inventory, food, or retail activity connected to {activity}.','Product, labeling, recall, and health rules vary by product and location.',['Which products and sales channels are covered?','Are completed products and vendors addressed?','What recall and product exclusions apply?'])
    if physical or equipment or products: add('property-bop','Commercial Property / Business Owner’s Policy (BOP)','Recommended','Commercial property covers certain business-property losses; a BOP may combine property and liability coverage.','Covered equipment, inventory, furnishings, and business property subject to policy terms.','A covered fire, theft, or weather event damages equipment or inventory.',f'Your plan references {"a physical operation" if physical else "equipment, inventory, or business property"}.',f'Property values, leases, home-based operations, and local hazards around {place} affect the review.',['Is replacement cost or actual cash value used?','Are off-site property and equipment covered?','Which liability coverage is included?'])
    if employees:
        add('workers-compensation','Workers’ Compensation','May Be Required','State-regulated coverage for qualifying work-related employee injuries or illnesses.','Benefits and employer duties defined by the applicable workers’ compensation system.','An employee is injured while performing assigned work and seeks benefits.','Employee information appears in your saved Business Plan.','State law controls private-employer workers’ compensation. Confirm with the official state agency before hiring or classifying workers.',['Which workers must be covered?','How are owners, contractors, and part-time workers treated?','What payroll classifications are required?'],'https://www.dol.gov/agencies/owcp/wc')
        add('epli','Employment Practices Liability','Recommended','Coverage commonly considered for certain employment-related claims.','Certain covered employment-practice claims and defense costs.','An applicant or worker alleges a covered hiring, discrimination, retaliation, or termination issue.','Your Business Plan records employees or hiring activity.','Employment duties vary by workforce size, location, and circumstances.',['Which claims and workers are covered?','Are wage-and-hour matters excluded?','What prevention steps are required?'])
    if vehicle: add('commercial-auto','Commercial Auto','May Be Required','Vehicle coverage designed for covered business driving and vehicles.','Covered liability or physical-damage risks involving scheduled vehicles and uses.','A delivery or client-service vehicle is involved in a collision during business activity.','Your plan refers to delivery, transportation, mobile service, or business travel.','Vehicle ownership, drivers, use, and state law affect requirements.',['Are owned, hired, and non-owned vehicles covered?','Which drivers and uses are permitted?','Are delivery and equipment included?'])
    if online: add('cyber-liability','Cyber Liability / Data Breach','Recommended','Coverage that may address certain cyber incidents, privacy claims, breach response, and recovery expenses.','Specific first-party and third-party cyber costs defined by the policy.','Customer or member information is exposed after unauthorized system access.',f'Your plan describes online, platform, ecommerce, technology, or customer-data activity related to {activity}.','Privacy and notification duties vary by information held and affected jurisdiction.',['What data and systems are covered?','Are response, notification, ransomware, and vendors included?','What security controls are required?'],'https://www.ftc.gov/business-guidance/small-businesses/cybersecurity')
    if physical or equipment or event: add('interruption-equipment','Business Interruption / Equipment Coverage','Recommended','Coverage that may address certain lost income, continuing expenses, breakdown, or equipment loss after a covered event.','Only losses, causes, waiting periods, and property described by the policy.','A covered event closes a venue or disables equipment needed to operate.',f'Your plan indicates reliance on {"a venue or physical operation" if physical or event else "business equipment"}.','Business-income coverage is usually tied to a covered cause of loss.',['Which events trigger coverage?','How is income calculated?','Are rented, portable, or specialized equipment covered?'])
    if food: add('food-related','Food-Related Liability','Recommended','A review of coverage for food preparation, products, premises, delivery, equipment, and events.','Covered food-product, premises, spoilage, equipment, delivery, or event risks.','A customer alleges illness from prepared food, or refrigeration failure damages stock.','Your plan identifies food, catering, meal, beverage, kitchen, or hospitality activity.','Food permits stay in Licenses & Certifications; coverage depends on preparation, venue, delivery, alcohol, employees, and products.',['Does coverage include foodborne-illness claims?','Are catering, delivery, spoilage, and equipment included?','Is liquor liability relevant?'])
    if not cards: add('basic-review','General Business Insurance Review','Optional','A professional review of the business’s activities, property, contracts, customers, and location.','Only risks and events included in policies selected after professional review.','A loss or contract reveals a risk that was not considered during startup.',f'Your saved plan currently provides limited operational-risk detail for {activity}.','No legal requirement is assumed; confirm circumstances with a licensed professional.',['Which risks are most important?','What is excluded?','Which contracts require proof of coverage?'])
    return cards

def _business_legal_checklist(facts):
    text=' '.join(_clean_text(x) for x in (facts.get('industry'),facts.get('services'),facts.get('raw'))).lower(); employees=bool(_clean_text(facts.get('employees')) and _clean_text(facts.get('employees')).lower() not in {'0','none','no'}); online=any(x in text for x in ('online','website','platform','app','customer data','member data','ecommerce'))
    items=[{'key':'registration','title':'Business registration and entity standing','classification':'Needs Professional Review','source_url':'https://www.sba.gov/business-guide/launch-your-business/register-your-business','note':'Structure, assumed-name, filing, and renewal duties depend on the business and jurisdiction.'},{'key':'licenses-link','title':'Licenses, permits, and professional requirements','classification':'Needs Professional Review','source_url':url_for('business_certifications'),'note':'Managed in the existing Licenses & Certifications section; records are not duplicated here.'},{'key':'insurance','title':'Insurance and proof-of-coverage review','classification':'Recommended Protection','source_url':'https://www.sba.gov/counseling/launch-your-business/','note':'Compare recommendations, contracts, venue rules, lender terms, and state requirements.'},{'key':'contracts','title':'Contracts, waivers, and service terms','classification':'Needs Professional Review','source_url':'https://www.sba.gov/business-guide/manage-your-business','note':'Written agreements should fit the actual services, products, participants, venues, and governing law.'},{'key':'renewals','title':'Renewal and expiration dates','classification':'Recommended Protection','source_url':url_for('funding_calendar'),'note':'Track saved insurance renewal dates in the existing calendar view.'}]
    if employees: items.append({'key':'workers','title':'Employee and independent-contractor review','classification':'May Be Required','source_url':'https://www.dol.gov/general/audience/aud-employers','note':'Classification, payroll, workplace, insurance, tax, and employment duties require jurisdiction-specific review.'})
    if online: items.append({'key':'privacy','title':'Privacy, data protection, and online terms','classification':'Needs Professional Review','source_url':'https://www.ftc.gov/business-guidance/privacy-security/data-security','note':'Review customer information, security, privacy notices, online terms, and breach-response duties.'})
    items.append({'key':'industry','title':'Industry-specific legal review','classification':'Needs Professional Review','source_url':url_for('business_certifications'),'note':'Use the existing licensing roadmap and official agencies for regulated activities.'}); return items

def _insurance_search_profile(facts,coverage='',location=''):
    """Translate Business Plan facts into compact insurance-search evidence."""
    raw=facts.get('raw') or {}; text=' '.join(_clean_text(x) for x in (facts.get('industry'),facts.get('services'),facts.get('goals'),facts.get('purpose'),raw)).lower()
    place=_clean_text(location) or ', '.join(x for x in (facts.get('city'),facts.get('state')) if x)
    state=_clean_text(facts.get('state')); industry=_clean_text(facts.get('industry'))
    operations=[]; classifications=[]
    groups=[
        (('yoga','wellness','reiki','retreat','meditation','class','participant'), 'wellness classes retreats', '713940'),
        (('restaurant','food','cater','bakery','meal','beverage','kitchen'), 'food service catering', '722320'),
        (('consult','coach','professional service'), 'consulting professional services', '541611'),
        (('technology','software','platform','app','customer data','member data'), 'technology software data services', '541511'),
        (('retail','product','ecommerce','online shop','inventory'), 'retail product sales', '454110'),
        (('beauty','salon','esthetic','cosmet'), 'beauty personal care services', '812112')]
    for words,label,naics in groups:
        if any(word in text for word in words): operations.append(label); classifications.append(naics)
    if not operations: operations.append(_clean_text(facts.get('services') or industry) or 'small business')
    employees=bool(_clean_text(facts.get('employees')) and _clean_text(facts.get('employees')).lower() not in {'0','none','no'})
    return {'coverage':_clean_text(coverage) or 'business insurance','place':place,'state':state,'industry':industry or operations[0],'operations':operations[:4],'naics':classifications[:3],'employees':employees}

def _insurance_search_queries(profile):
    """Progressive query plan; kept separate so a future quote API can reuse the profile."""
    coverage=profile['coverage']; place=profile['place']; state=profile['state']; queries=[]
    for operation in profile['operations'][:3]:
        queries.append(f'{coverage} insurance {operation} {place} official provider quote')
    queries.append(f'{coverage} insurance {profile["industry"]} {state} official provider')
    for naics in profile['naics']: queries.append(f'{coverage} insurance NAICS {naics} {state} official provider')
    for operation in profile['operations'][:2]: queries.append(f'specialty {coverage} insurance {operation} {state} official')
    queries.extend([f'commercial insurance carrier {coverage} small business {state} official quote',f'licensed commercial insurance broker {coverage} {state} official'])
    unique=[]; seen=set()
    for query in queries:
        key=re.sub(r'\W+',' ',query.lower()).strip()
        if key not in seen: seen.add(key); unique.append(query)
    return unique[:12]

def _insurance_result(row,profile,provider):
    url=_clean_text(row.get('url')); title=_clean_text(row.get('title')); snippet=_clean_text(row.get('description'))
    if not url.startswith('https://') or not title: return None
    lower=' '.join((title,snippet,url)).lower()
    if any(x in lower for x in ('best insurance','top insurance','affiliate','blog/','/blog','news article','press release','review of')): return None
    coverage=profile['coverage']; coverage_words=[x for x in re.findall(r'[a-z]{4,}',coverage.lower()) if x not in {'insurance','coverage','business'}]
    page_text=_safe_public_page_text(url); evidence=' '.join((title,snippet,page_text[:70000])).lower()
    commercial=bool(re.search(r'\b(business|commercial|small business)\b',evidence))
    coverage_supported=not coverage_words or any(word in evidence for word in coverage_words)
    provider_supported=bool(re.search(r'\b(insurance|insurer|carrier|broker|agency|coverage|policy|quote)\b',evidence))
    if not (commercial and coverage_supported and provider_supported): return None
    host=(urllib.parse.urlparse(url).hostname or '').lower().removeprefix('www.')
    state_terms=[profile['state'].lower(),profile['place'].lower()]
    state_verified=any(term and term in evidence for term in state_terms)
    operation_verified=[x for x in profile['operations'] if any(w in evidence for w in x.split() if len(w)>4)]
    if state_verified and operation_verified: fit='Strong Business Fit'
    elif operation_verified or state_verified: fit='Possible Business Fit'
    elif 'specialty' in evidence: fit='Specialty Provider'
    else: fit='Eligibility Requires Confirmation'
    displayed_name=re.sub(r'\s*[|\-–—].*$','',title).strip() or host
    why=f'This provider page references {coverage} for business or commercial customers.'
    if operation_verified: why+=f' Its published information is relevant to {operation_verified[0]} identified in your Business Plan.'
    if state_verified: why+=f' The page also references {profile["state"] or profile["place"]}.'
    else: why+=' Availability for your exact location requires provider confirmation.'
    return {'key':hashlib.sha256(url.encode()).hexdigest()[:24],'name':displayed_name[:180],'provider_name':host,'classification':fit,'coverage_types':[coverage],'what_it_is':f'Coverage available: {coverage}. '+(snippet or 'Official provider page located during the insurance search.'),'why':why,'protects':'Coverage depends on the policy offered and purchased. Contact provider for quote; no premium, deductible, limit, or eligibility is assumed.','example':'Review the provider page, request written terms, and compare exclusions, limits, deductibles, and endorsements.','state_considerations':f'{"Published information references the saved location." if state_verified else "Eligibility and state availability require provider confirmation."}','questions':['Does this provider serve my exact location and business operations?','Which exclusions, limits, deductibles, and endorsements apply?','Can I receive a written quote and specimen policy?'],'source_url':url,'quote_url':url,'last_checked':now(),'discovered_via':provider,'page_verified':bool(page_text)}

def _insurance_search(facts,coverage='',location=''):
    configured=bool(os.environ.get('BRAVE_SEARCH_API_KEY','').strip() or os.environ.get('BING_SEARCH_API_KEY','').strip() or (os.environ.get('GOOGLE_CSE_API_KEY','').strip() and os.environ.get('GOOGLE_CSE_ID','').strip()))
    if not configured: return [],['The existing approved web-search provider is not configured.']
    profile=_insurance_search_profile(facts,coverage,location); queries=_insurance_search_queries(profile); found=[]; errors=[]
    with ThreadPoolExecutor(max_workers=min(6,len(queries))) as pool:
        futures={pool.submit(_configured_funding_web_search,q,10):q for q in queries}
        for future in as_completed(futures):
            try:
                rows,provider=future.result()
                for row in rows:
                    item=_insurance_result(row,profile,provider)
                    if item: found.append(item)
            except Exception as exc: errors.append({'query':futures[future],'error':type(exc).__name__})
    rank={'Strong Business Fit':0,'Possible Business Fit':1,'Specialty Provider':2,'Eligibility Requires Confirmation':3}; unique={}
    for item in found:
        old=unique.get(item['provider_name'])
        if not old or rank[item['classification']]<rank[old['classification']]: unique[item['provider_name']]=item
    return sorted(unique.values(),key=lambda x:(rank[x['classification']],x['provider_name'].lower()))[:12],errors

