    conn=db(); conn.execute('''INSERT INTO business_protection_records(user_id,record_kind,item_key,title,classification,provider_name,coverage_types,what_it_is,why_matched,protects,example_situation,state_considerations,questions_json,source_url,quote_url,status,raw_payload,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(user_id,record_kind,item_key) DO UPDATE SET title=excluded.title,classification=excluded.classification,provider_name=excluded.provider_name,coverage_types=excluded.coverage_types,what_it_is=excluded.what_it_is,why_matched=excluded.why_matched,protects=excluded.protects,example_situation=excluded.example_situation,state_considerations=excluded.state_considerations,questions_json=excluded.questions_json,source_url=excluded.source_url,quote_url=excluded.quote_url,raw_payload=excluded.raw_payload,updated_at=excluded.updated_at''',values); conn.commit(); conn.close(); flash('Saved to Business Journal → Business Insurance & Legal Protection.','success'); return redirect(url_for('business_protection'))

