@app.route('/business-development/protection/<int:record_id>/document/<path:file_name>')
@login_required
def business_protection_document(record_id,file_name):
    u=current_user(); conn=db(); record=conn.execute('SELECT document_notes FROM business_protection_records WHERE id=? AND user_id=?',(record_id,u['id'])).fetchone()
    try: documents=json.loads(record['document_notes'] or '[]') if record else []
    except Exception: documents=[]
    allowed={x.get('file_name') for x in documents if isinstance(x,dict)}
    if file_name not in allowed: conn.close(); abort(404)
    stored=conn.execute('SELECT content_type,file_data FROM stored_files WHERE file_name=? AND user_id=?',(file_name,u['id'])).fetchone(); conn.close()
    if not stored: abort(404)
    raw=stored['file_data']; raw=raw.tobytes() if isinstance(raw,memoryview) else bytes(raw); return send_file(io.BytesIO(raw),mimetype=stored['content_type'] or 'application/octet-stream',download_name=file_name,as_attachment=True)

@app.route('/business-development/protection/<int:record_id>/delete',methods=['POST'])
@login_required
def business_protection_delete(record_id):
    u=current_user(); conn=db(); row=conn.execute('SELECT document_notes FROM business_protection_records WHERE id=? AND user_id=?',(record_id,u['id'])).fetchone()
    try: documents=json.loads(row['document_notes'] or '[]') if row else []
    except Exception: documents=[]
    for item in documents:
        if isinstance(item,dict) and item.get('file_name'): conn.execute('DELETE FROM stored_files WHERE file_name=? AND user_id=?',(item['file_name'],u['id']))
    conn.execute('DELETE FROM business_protection_records WHERE id=? AND user_id=?',(record_id,u['id'])); conn.commit(); conn.close(); flash('Removed from Business Journal → Business Insurance & Legal Protection.','success'); return redirect(url_for('business_plan')+'#protection')

