    protection_cards=''.join(f'''<article class="card"><span class="badge">{html.escape(r['status'])}</span><h3>{html.escape(r['title'])}</h3><p>{html.escape(r['provider_name'] or r['classification'] or '')}</p><div class="actions"><a class="out" href="{url_for('business_protection_edit',record_id=r['id'])}">View / Edit</a><form method="post" action="{url_for('business_protection_delete',record_id=r['id'])}" onsubmit="return confirm('Delete this saved protection record?')"><button class="out danger">Delete</button></form></div></article>''' for r in protection_rows); protection_cards+=''.join(f'''<article class="card"><span class="badge">{html.escape(r['status'])}</span><h3>{html.escape(r['title'])}</h3><a class="out" href="{url_for('business_protection')}#legal-checklist">View / Edit Checklist</a></article>''' for r in checklist_rows); protection_cards=protection_cards or '<div class="empty">No saved insurance or legal-protection records.</div>'
