@app.route('/business-development/funding')
@login_required
def funding_opportunities():
    u=current_user(); facts=_business_funding_facts(u['id']); kind=request.args.get('type','all').lower(); level=request.args.get('level','all').title()
    keyword=_personalized_funding_keyword(facts); grants=[]; warning=''
    try:
        grants,official_errors=_expanded_grants_gov_search(facts)
        if official_errors: warning='One official federal source could not be reached. Matching continued through the other available sources.'
    except Exception: warning='The official federal grant services could not be reached just now. Saved and official loan programs remain available.'
    opportunities=grants+_official_loan_programs()
    for opp in opportunities: _cache_funding_opportunity(opp)
    if kind in {'grant','loan'}: opportunities=[o for o in opportunities if o.get('opportunity_type','').lower()==kind]
    if level!='All': opportunities=[o for o in opportunities if o.get('government_level')==level]
    # The personalized dashboard never presents stale, closed or unverified
    # records as active matches, and it excludes records with no reasonable fit.
    opportunities=[o for o in opportunities if _verification_state(o)['active_verified'] and _funding_analysis(o,facts)['match_score']>=35 and not _funding_analysis(o,facts)['conflicts']]
    opportunities.sort(key=lambda o:_funding_analysis(o,facts)['match_score'],reverse=True)
    tabs=f'''<div class="actions"><a class="out" href="{url_for('funding_opportunities',type='all',level=request.args.get('level','all'))}">All Matches</a><a class="out" href="{url_for('funding_opportunities',type='grant',level=request.args.get('level','all'))}">Grants</a><a class="out" href="{url_for('funding_opportunities',type='loan',level=request.args.get('level','all'))}">Loans</a></div><div class="actions">'''+''.join(f'<a class="out" href="{url_for("funding_opportunities",type=kind,level=x.lower())}">{x}</a>' for x in ('All','City','County','State','Federal'))+'</div>'
    grant_cards=''.join(_funding_card(o,facts) for o in opportunities if (o.get('opportunity_type') or '').lower()=='grant') or '<div class="empty">No active verified grant matches were found for these filters.</div>'
    loan_cards=''.join(_funding_card(o,facts) for o in opportunities if (o.get('opportunity_type') or '').lower()=='loan') or '<div class="empty">No active verified loan matches were found for these filters.</div>'
    contracts='''<article class="card"><h3>Government Contract Opportunities</h3><p>Search verified federal solicitations by your services, industry and NAICS information. State and local procurement sources should be selected from the member's saved business location.</p><a class="btn" target="_blank" rel="noopener" href="https://sam.gov/content/opportunities">Search SAM.gov Contract Opportunities</a><p class="muted">The Seasons Within does not invent solicitations. Save only an official notice after confirming its location, NAICS, deadline, set-aside and submission requirements.</p></article>'''
    sections=f'''<section><h2>Recommended Grants</h2><div class="funding-results">{grant_cards}</div></section><section><h2>Recommended Loans</h2><div class="funding-results">{loan_cards}</div></section><section><h2>Government Contract Opportunities</h2>{contracts}</section>'''
    return page('Funding Matches',f'''<div class="hero"><span class="badge">BUSINESS DEVELOPMENT</span><h1>Funding Matches</h1><p class="muted">Verified grants, loans and contracting pathways ranked against your saved Business Plan. Business Match and Application Readiness are rules-based guidance—not approval predictions.</p></div>{tabs}{('<div class="notice">'+html.escape(warning)+'</div>') if warning else ''}{sections}''','business')

@app.route('/business-development/funding/search',methods=['GET','POST'])
@login_required
def funding_search():
    u=current_user(); facts=_business_funding_facts(u['id']); keyword=(request.form.get('keyword','') if request.method=='POST' else request.args.get('keyword','')).strip()[:180]
    level=request.values.get('level','All'); location=request.values.get('location',', '.join(x for x in (facts['city'],facts['county'],facts['state']) if x)); stage=request.values.get('stage',facts['stage']); purpose=request.values.get('purpose',facts['purpose']); status_filter=request.values.get('status','Open'); sort=request.values.get('sort','Best Match'); search_facts=dict(facts); search_facts.update({'stage':stage,'purpose':purpose,'member_search_terms':keyword})
    if location.strip():
        if level=='City': search_facts['city']=location.strip()
        elif level=='County': search_facts['county']=location.strip().removesuffix(' County')
        elif level=='State': search_facts['state']=location.strip()
    live=[]; warning=''; search_plan=[]; search_errors=[]
    if request.method=='POST':
        if not keyword: warning='Enter what you want to search for, such as Wellness, Technology grants, or Community garden grants.'
        else:
            federal,federal_errors=_manual_grants_gov_search(keyword)
            web_live,search_plan,web_errors=_deep_live_manual_grant_search(search_facts,keyword,level,location,stage,purpose)
            live=_merge_opportunities(federal,web_live); search_errors=federal_errors+web_errors
            for o in live:
                if o.get('source')=='Grants.gov' or _verification_state(o)['active_verified']: _cache_funding_opportunity(o)
            if search_errors: warning='Some live sources could not be reached. The search continued through the remaining available sources.'
    try: stored=_stored_funding_opportunities('Grant')
    except Exception:
        app.logger.exception('Stored grant cache could not be read')
        stored=[]
    manual_terms=_tokens(keyword); relevant_cache=[o for o in stored if manual_terms and manual_terms & _tokens(o.get('title',''),o.get('description',''),o.get('eligibility',''),o.get('funding_uses',''))]
    results=_merge_opportunities(live,relevant_cache if request.method=='POST' else [])
    if level!='All': results=[o for o in results if o.get('government_level')==level]
    if status_filter!='All':
        allowed={'Open':{'OPEN','CLOSING SOON','ROLLING','RECURRING'},'Upcoming':{'UPCOMING','OPENING SOON'},'Rolling':{'ROLLING'},'Closed':{'CLOSED','CLOSED — EXPECTED TO RETURN','DEADLINE PASSED'}}.get(status_filter,{status_filter.upper()}); results=[o for o in results if _opportunity_status(o.get('deadline',''),o.get('status','')) in allowed]
    if sort=='Deadline Soonest': results.sort(key=lambda o:o.get('deadline') or '9999')
    elif sort=='Newly Added': results=list(reversed(results))
    elif sort=='Local First': results.sort(key=lambda o:{'City':0,'County':1,'Regional':2,'State':3,'Federal':4,'National/Private':5}.get(o.get('government_level'),6))
    else: results.sort(key=lambda o:(_verification_state(o)['active_verified'],_funding_analysis(o,search_facts)['match_score'],_trusted_funding_domain(o.get('source_url',''))),reverse=True)
    # Search history is useful, but an older/mid-migration history table must
    # never prevent the member from seeing live official grant results.
    conn=db()
    try:
        conn.execute('INSERT INTO funding_searches(user_id,keyword,funding_type,state,industry,amount,result_count,created_at) VALUES(?,?,?,?,?,?,?,?)',(u['id'],keyword,'Grant',facts['state'],facts['industry'],facts['amount'],len(results),now()))
        conn.commit()
    except Exception:
        try: conn.rollback()
        except Exception: pass
        app.logger.exception('Funding search history could not be saved for user %s',u['id'])
    finally:
        conn.close()
    options=lambda values,current: ''.join(f'<option{" selected" if x==current else ""}>{html.escape(x)}</option>' for x in values)
    progress='''<div id="funding-search-progress" class="card" style="display:none"><h2>Searching for grant opportunities…</h2><p id="funding-progress-text">Preparing searches centered on your keyword…</p><div class="progress"><span id="funding-progress-bar" style="width:8%"></span></div></div><script>function beginFundingSearch(){const box=document.getElementById('funding-search-progress'),text=document.getElementById('funding-progress-text'),bar=document.getElementById('funding-progress-bar');box.style.display='block';const steps=['Searching city programs…','Searching county programs…','Searching regional programs…','Searching state programs…','Searching federal programs…','Searching foundation and corporate programs…','Checking official eligibility requirements…','Comparing discovered grants with your Business Plan…'];let i=0;text.textContent=steps[0];bar.style.width='12%';window.fundingProgressTimer=setInterval(()=>{i=Math.min(i+1,steps.length-1);text.textContent=steps[i];bar.style.width=(12+Math.round(84*i/(steps.length-1)))+'%'},900);box.scrollIntoView({behavior:'smooth',block:'center'});return true}</script>'''
    form=f'''<form class="card" method="post" onsubmit="return beginFundingSearch()"><h2>Search Grants Inside The Seasons Within</h2><p class="muted">Enter what you want to find. Your words control discovery; your Business Plan is used afterward to explain and rank the grants found.</p><label><b>Search grants</b></label><input class="input" name="keyword" value="{html.escape(keyword,quote=True)}" placeholder="Examples: Wellness, Technology grants, Community garden grants" required><div class="grid"><div><label>Geographic level</label><select class="input" name="level">{options(['All','City','County','Regional','State','Federal','National/Private'],level)}</select></div><div><label>City, county or state</label><input class="input" name="location" value="{html.escape(location,quote=True)}"></div><div><label>Business Stage</label><select class="input" name="stage">{options(['','Idea/Pre-launch','Startup','Operating','Growth'],stage)}</select></div><div><label>Funding Purpose</label><select class="input" name="purpose">{options(['','Startup','Equipment','Technology','Marketing','Hiring','Expansion','Working Capital','Property','Training','Research','Other'],purpose)}</select></div><div><label>Status</label><select class="input" name="status">{options(['Open','Upcoming','Rolling','Closed','All'],status_filter)}</select></div><div><label>Sort</label><select class="input" name="sort">{options(['Best Match','Deadline Soonest','Newly Added','Local First','Funding Amount'],sort)}</select></div></div><button class="btn">Search Grants</button></form>{progress}'''
    # Search may retain a traceable record that needs rechecking, but it is
    # visibly separated from current verified results and cannot be saved as active.
    verified=[o for o in results if _verification_state(o)['active_verified']]
    verify=[o for o in results if not _verification_state(o)['active_verified'] and _opportunity_status(o.get('deadline',''),o.get('status',''))!='CLOSED']
    if request.method!='POST': body='<div class="empty">Enter a grant topic above. Manual search follows your keyword; automatic Business Plan matching remains available in Funding Matches.</div>'
    else:
        broaden=f'''<form method="post"><input type="hidden" name="keyword" value="{html.escape(keyword,quote=True)}"><input type="hidden" name="level" value="All"><input type="hidden" name="location" value="{html.escape(facts['state'],quote=True)}"><input type="hidden" name="stage" value="{html.escape(stage,quote=True)}"><input type="hidden" name="purpose" value="{html.escape(purpose,quote=True)}"><input type="hidden" name="status" value="All"><button class="out">Broaden My Search</button></form>'''
        body=(''.join(_funding_card(o,search_facts) for o in verified[:20]) or f'<div class="empty"><b>No verified matching opportunities were located after the full search.</b><p>Potentially useful unverified or recurring programs appear below. You can broaden the geography and status while keeping “{html.escape(keyword)}” as the primary topic.</p>{broaden}</div>')
    if verify: body+='<section><h2>Needs Verification</h2><p class="muted">These traceable official-source records are not active matches until their current status is confirmed.</p>'+''.join(_funding_card(o,search_facts) for o in verify[:8])+'</section>'
    if request.method=='POST' and search_plan:
        coverage=[]
        for item in search_plan:
            label=item['location'] or item['level']
            if label and label not in coverage: coverage.append(label)
        body+=f'''<details class="card"><summary>Search coverage</summary><p><b>{' → '.join(html.escape(x) for x in coverage)}</b></p><p class="muted">Every level remained centered on “{html.escape(keyword)}.” Internal search-engine phrases are intentionally not displayed.</p></details>'''
    education='''<article class="card"><h2>What Is a Grant?</h2><p>Grants are financial support from governments, corporations, foundations and other organizations that generally does not have to be repaid when every award requirement is followed.</p><div class="grid"><details><summary><b>Eligibility</b></summary><p>You must meet the program's published requirements before applying.</p></details><details><summary><b>Approved Uses</b></summary><p>Funds may be used only for the expenses and activities authorized by the award.</p></details><details><summary><b>Deadlines</b></summary><p>Application and spending deadlines must be followed.</p></details><details><summary><b>Reporting Rules</b></summary><p>Receipts, financial accounting, progress or performance reports may be required.</p></details><details><summary><b>Consequences</b></summary><p>Failure to follow an award can cause loss of funding, repayment, disqualification or a clawback.</p></details></div><a class="out" target="_blank" rel="noopener" href="https://www.grants.gov/search-grants">Search Federal Grants on Grants.gov</a></article>'''
    return page('Grant Search',f'''<div class="hero"><span class="badge">BUSINESS DEVELOPMENT</span><h1>Grant Search</h1><p class="muted">Manual search follows the words you enter across live federal and web sources. After discovery and source verification, your saved Business Plan helps explain and rank results; it does not replace your keyword.</p></div>{education}{form}{('<div class="notice">'+html.escape(warning)+'</div>') if warning else ''}{body}''','business')

@app.route('/business-development/loans',methods=['GET','POST'])
@login_required
def loan_search():
    u=current_user(); facts=_business_funding_facts(u['id']); keyword=request.values.get('keyword','').strip()[:180]; amount=request.values.get('amount',facts['amount']); purpose=request.values.get('purpose',facts['purpose']); stage=request.values.get('stage',facts['stage']); level=request.values.get('level','All'); location=request.values.get('location',', '.join(x for x in (facts['city'],facts['county'],facts['state']) if x)); search_facts=dict(facts); search_facts.update({'amount':amount,'purpose':purpose,'stage':stage,'member_search_terms':keyword}); official=_official_loan_programs()
    if location.strip():
        if level=='City': search_facts['city']=location.strip()
        elif level=='County': search_facts['county']=location.strip().removesuffix(' County')
        elif level=='State': search_facts['state']=location.strip()
    live=[]; search_plan=[]; search_errors=[]; warning=''
    if request.method=='POST':
        web_live,search_plan,search_errors=_deep_live_manual_loan_search(search_facts,amount,purpose,stage,level,location,keyword)
        live=_merge_opportunities(official,web_live)
        for o in live:
            if o.get('source')=='SBA.gov' or _verification_state(o)['active_verified']: _cache_funding_opportunity(o)
        if search_errors: warning='Some live sources could not be reached. The results below include the official sources that responded.'
    try: stored=_stored_funding_opportunities('Loan')
    except Exception:
        app.logger.exception('Stored loan cache could not be read')
        stored=[]
    programs=_merge_opportunities(live,stored if request.method=='POST' else [])
    purpose_tokens=_tokens(purpose)
    if purpose_tokens: programs=[o for o in programs if purpose_tokens & _tokens(o.get('funding_uses',''),o.get('description',''),o.get('title',''))] or programs
    if level!='All': programs=[o for o in programs if o.get('government_level')==level]
    programs.sort(key=lambda o:(_verification_state(o)['active_verified'],_funding_analysis(o,search_facts)['match_score'],_trusted_funding_domain(o.get('source_url',''))),reverse=True)
    opts=lambda values,current: ''.join(f'<option{" selected" if x==current else ""}>{html.escape(x)}</option>' for x in values)
    progress='''<div id="funding-search-progress" class="card" style="display:none"><h2>Searching for financing opportunities…</h2><p id="funding-progress-text">Building searches from your Business Plan…</p><div class="progress"><span id="funding-progress-bar" style="width:8%"></span></div></div><script>function beginFundingSearch(){const box=document.getElementById('funding-search-progress'),text=document.getElementById('funding-progress-text'),bar=document.getElementById('funding-progress-bar');box.style.display='block';const steps=['Searching city loan programs…','Searching county financing programs…','Searching regional and CDFI programs…','Searching state loan programs…','Searching SBA and federal programs…','Searching microloan and mission-based lenders…','Checking official qualification requirements…','Comparing financing with your Business Plan…'];let i=0;text.textContent=steps[0];bar.style.width='12%';window.fundingProgressTimer=setInterval(()=>{i=Math.min(i+1,steps.length-1);text.textContent=steps[i];bar.style.width=(12+Math.round(84*i/(steps.length-1)))+'%'},900);box.scrollIntoView({behavior:'smooth',block:'center'});return true}</script>'''
    form=f'''<form class="card" method="post" onsubmit="return beginFundingSearch()"><h2>Search Loans Inside The Seasons Within</h2><p class="muted">Enter what you want to find. Your words control discovery; your Business Plan is used afterward to explain and rank financing found across city-to-national sources.</p><label><b>Search loans or financing</b></label><input class="input" name="keyword" value="{html.escape(keyword,quote=True)}" placeholder="Examples: wellness startup loans, equipment financing, working-capital microloan"><div class="grid"><div><label>Funding amount</label><input class="input" name="amount" value="{html.escape(amount,quote=True)}"></div><div><label>Purpose</label><select class="input" name="purpose">{opts(['','Startup','Equipment','Technology','Marketing','Hiring','Expansion','Working Capital','Property','Training','Other'],purpose)}</select></div><div><label>Business stage</label><select class="input" name="stage">{opts(['','Idea/Pre-launch','Startup','Operating','Growth'],stage)}</select></div><div><label>Geographic level</label><select class="input" name="level">{opts(['All','City','County','Regional','State','Federal','National/Private'],level)}</select></div><div><label>City, county or state</label><input class="input" name="location" value="{html.escape(location,quote=True)}"></div></div><button class="btn">Search Loans</button></form>{progress}'''
    verified=[o for o in programs if _verification_state(o)['active_verified']]
    verify=[o for o in programs if not _verification_state(o)['active_verified']]
    if request.method!='POST': cards='<div class="empty">Press Search Loans to perform a new live search using your Business Plan and the fields above.</div>'
    else:
        broaden=f'''<form method="post"><input type="hidden" name="keyword" value="{html.escape(keyword,quote=True)}"><input type="hidden" name="amount" value="{html.escape(amount,quote=True)}"><input type="hidden" name="purpose" value="{html.escape(purpose,quote=True)}"><input type="hidden" name="stage" value="{html.escape(stage,quote=True)}"><input type="hidden" name="level" value="All"><input type="hidden" name="location" value="{html.escape(facts['state'],quote=True)}"><button class="out">Broaden My Search</button></form>'''
        cards=''.join(_funding_card(o,search_facts) for o in verified[:20]) or f'<div class="empty"><b>No verified matching financing was located after the full search.</b><p>Potentially useful programs that still need verification appear below. Broaden the geography while keeping your member-entered financing terms primary.</p>{broaden}</div>'
    if verify: cards+='<section><h2>Needs Verification</h2>'+''.join(_funding_card(o,search_facts) for o in verify[:8])+'</section>'
    if request.method=='POST' and search_plan:
        coverage=[]
        for item in search_plan:
            label=item['location'] or item['level']
            if label and label not in coverage: coverage.append(label)
        cards+=f'''<details class="card"><summary>Search coverage</summary><p><b>{' → '.join(html.escape(x) for x in coverage)}</b></p><p class="muted">The submitted amount, purpose, stage and location controlled this search across local programs, economic-development lenders, CDFIs, banks, credit unions, SBA programs and national mission-based lenders. Internal search queries are intentionally not displayed.</p></details>'''
    education=f'''<article class="card"><h2>What Is a Business Loan?</h2><p>A business loan is money borrowed by a company and repaid under the lender's terms, usually with interest or financing costs.</p><div class="grid"><details><summary><b>Term Loans</b></summary><p>Traditional financing repaid on a defined schedule.</p></details><details><summary><b>SBA Loans</b></summary><p>Loans through participating lenders supported by SBA programs.</p></details><details><summary><b>Lines of Credit</b></summary><p>Revolving financing that may be borrowed, repaid and borrowed again under lender terms.</p></details><details><summary><b>Equipment Financing</b></summary><p>Financing for machinery or equipment, sometimes secured by the purchased asset.</p></details></div><h3>What lenders may review</h3><p>Time in business, revenue and cash flow, personal or business credit, collateral, financing purpose and ability to repay.</p><div class="actions"><a class="out" target="_blank" rel="noopener" href="https://www.sba.gov/funding-programs/loans">Explore SBA Loan Programs</a><a class="out" href="{url_for('business_credit')}">Build My Business Credit</a></div></article>'''
    return page('Loan Search',f'''<div class="hero"><span class="badge">BUSINESS DEVELOPMENT</span><h1>Business Loan Search</h1><p class="muted">Each submitted search checks live web sources, verifies original lender/program pages, and ranks actual financing against the saved Business Plan. The database is used only as a cache.</p></div>{education}{form}{('<div class="notice">'+html.escape(warning)+'</div>') if warning else ''}{cards}''','business')

@app.route('/business-development/funding/save',methods=['POST'])
@login_required
def save_funding_opportunity():
    u=current_user()
    try: submitted=json.loads(request.form.get('opportunity','{}'))
    except Exception: abort(400)
    conn=db(); canonical=conn.execute('SELECT * FROM funding_opportunities WHERE source_name=? AND source_id=?',(submitted.get('source',''),submitted.get('source_id',''))).fetchone(); conn.close()
    if not canonical: abort(400)
    o=dict(canonical); o.update({'source':o.pop('source_name'),'agency':o.pop('agency_name'),'source_url':o.pop('official_url')})
    try:
        raw=json.loads(o.get('raw_payload') or '{}')
        if isinstance(raw,dict): o.update(raw)
    except Exception: pass
    if not _verification_state(o)['active_verified']: abort(400)
    facts=_business_funding_facts(u['id']); analysis=_funding_analysis(o,facts); record_id=_store_funding_opportunity(o)
    conn=db(); conn.execute('''INSERT INTO saved_funding_opportunities(user_id,source,source_id,title,agency,opportunity_type,amount_text,deadline,eligibility,description,source_url,match_reason,raw_payload,status,opportunity_record_id,match_score,readiness_score,eligibility_results,application_status,member_notes,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(user_id,source,source_id) DO UPDATE SET title=excluded.title,deadline=excluded.deadline,raw_payload=excluded.raw_payload,match_score=excluded.match_score,readiness_score=excluded.readiness_score,eligibility_results=excluded.eligibility_results,updated_at=excluded.updated_at''',(u['id'],o.get('source',''),o.get('source_id',''),o.get('title',''),o.get('agency',''),o.get('opportunity_type',''),o.get('amount_text',''),o.get('deadline',''),o.get('eligibility',''),o.get('description',''),o.get('source_url') or o.get('application_url',''),analysis['match_reason'],json.dumps(o),'Saved',record_id,analysis['match_score'],analysis['readiness_score'],json.dumps(analysis['checks']),'Researching','',now(),now())); saved=conn.execute('SELECT id,deadline FROM saved_funding_opportunities WHERE user_id=? AND source=? AND source_id=?',(u['id'],o.get('source',''),o.get('source_id',''))).fetchone()
    if saved and saved['deadline']:
        conn.execute('''INSERT INTO funding_deadlines(user_id,saved_opportunity_id,deadline_type,due_date,status,reminder_note,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(user_id,saved_opportunity_id,deadline_type) DO UPDATE SET due_date=excluded.due_date,updated_at=excluded.updated_at''',(u['id'],saved['id'],'Application deadline',saved['deadline'],'Upcoming','',now(),now()))
    conn.commit(); conn.close(); destination='Loans & Financing' if (o.get('opportunity_type') or '').lower()=='loan' else 'Grants'; flash(f'Saved to Business Journal → {destination}.','success')
    action=request.form.get('next_action','')
    if saved and action=='eligibility': return redirect(url_for('funding_eligibility',opportunity_id=saved['id']))
    if saved and action=='proposal': return redirect(url_for('proposal_new',opportunity_id=saved['id']))
    if saved and action=='calendar': return redirect(url_for('funding_calendar',saved_opportunity_id=saved['id']))
    if saved and action=='financial':
        return redirect(url_for('loan_cash_flow',opportunity_id=saved['id'])) if (o.get('opportunity_type') or '').lower()=='loan' else redirect(url_for('grant_budget',opportunity_id=saved['id']))
    return redirect(url_for('saved_opportunities'))

@app.route('/business-development/funding/saved/<int:opportunity_id>/eligibility')
@login_required
def funding_eligibility(opportunity_id):
    u=current_user(); conn=db(); row=conn.execute('SELECT * FROM saved_funding_opportunities WHERE id=? AND user_id=?',(opportunity_id,u['id'])).fetchone()
    if not row: conn.close(); abort(404)
    try: checks=json.loads(row['eligibility_results'] or '[]')
    except Exception: checks=[]
    met=sum(1 for x in checks if x.get('state')=='✓ Appears Met'); failed=sum(1 for x in checks if x.get('state')=='✕ Does Not Appear Eligible')
    conclusion='Currently Does Not Meet Requirements' if failed else ('Likely Eligible' if checks and met==len(checks) else 'May Be Eligible — Information Needed')
    conn.execute('''INSERT INTO funding_eligibility_reviews(user_id,saved_opportunity_id,result,checks_json,notes,created_at,updated_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(user_id,saved_opportunity_id) DO UPDATE SET result=excluded.result,checks_json=excluded.checks_json,updated_at=excluded.updated_at''',(u['id'],opportunity_id,conclusion,json.dumps(checks),'',now(),now())); conn.commit(); conn.close()
    items=''.join(f'''<li><b>{html.escape(x.get('state',''))}</b> {html.escape(x.get('label',''))}<br><small>{html.escape(x.get('detail',''))}</small></li>''' for x in checks)
    return page('Eligibility Review',f'''<div class="hero"><span class="badge">CHECK MY ELIGIBILITY</span><h1>{html.escape(row['title'])}</h1><h2>{html.escape(conclusion)}</h2><p class="muted">This review compares published requirements with your saved Business Plan. It is not an approval decision.</p></div><article class="card"><h2>Your Eligibility Review</h2><ul>{items}</ul><div class="actions"><a class="out" target="_blank" rel="noopener" href="{html.escape(row['source_url'] or '#',quote=True)}">Official Requirements</a><a class="btn" href="{url_for('proposal_new',opportunity_id=opportunity_id)}">Start Proposal</a></div></article>''','business')

