@login_required
def saved_opportunities():
    u=current_user(); tab=request.args.get('type','All'); conn=db(); rows=conn.execute('SELECT * FROM saved_funding_opportunities WHERE user_id=? ORDER BY updated_at DESC',(u['id'],)).fetchall(); conn.close()
