    cards=''.join(f'''<article class="card"><div class="actions"><span class="badge">{html.escape(r['opportunity_type'] or 'Funding')}</span><span class="badge">{html.escape(r['application_status'] or 'Saved')}</span></div><h3>{html.escape(r['title'])}</h3><p><b>Deadline:</b> {html.escape(r['deadline'] or 'Rolling / not published')}</p><p><b>Business Match: {r['match_score']}%</b><br><b>Application Readiness: {r['readiness_score']}%</b></p><p>{html.escape(r['match_reason'] or '')}</p><div class="actions"><a class="out" href="{url_for('saved_opportunity_view',opportunity_id=r['id'])}">View / Edit</a>{actions(r)}<form method="post" action="{url_for('delete_saved_opportunity',opportunity_id=r['id'])}" onsubmit="return confirm('Delete this saved opportunity and its connected deadlines and preparation records?')"><button class="out danger">Delete</button></form></div></article>''' for r in rows) or '<div class="empty">No saved opportunities in this category yet.</div>'
    tabs='<div class="actions">'+''.join(f'<a class="out" href="{url_for("saved_opportunities",type=x)}">{x}</a>' for x in ('All','Grants','Loans','Government Contracts'))+'</div>'
    return page('Saved Opportunities',f'''<div class="hero"><span class="badge">BUSINESS DEVELOPMENT</span><h1>Saved Opportunities</h1><p class="muted">Track verified grants, loans and government solicitations without mixing one member's records with another's.</p></div>{tabs}<div class="grid">{cards}</div>''','business')

