    return page('Saved Opportunity',f'''<div class="hero"><span class="badge">BUSINESS JOURNAL • {html.escape(row['opportunity_type'] or 'FUNDING')}</span><h1>{html.escape(row['title'])}</h1><p>{html.escape(row['agency'] or '')}</p><div class="actions"><a class="out" href="{url_for('business_plan')}#{'loans' if (row['opportunity_type'] or '').lower()=='loan' else 'grants'}">View in Business Journal</a><a class="out" target="_blank" rel="noopener" href="{html.escape(source or '#',quote=True)}">Official Source</a><a class="out" target="_blank" rel="noopener" href="{html.escape(eligibility or '#',quote=True)}">Eligibility</a><a class="btn" target="_blank" rel="noopener" href="{html.escape(application or '#',quote=True)}">Official Application</a></div></div><article class="card"><p><b>Amount:</b> {html.escape(row['amount_text'] or 'Not published by funding source')}<br><b>Eligibility:</b> {html.escape(row['eligibility'] or 'Not published by funding source')}<br><b>Business Plan Match:</b> {row['match_score']}%<br><b>Application Readiness:</b> {row['readiness_score']}%</p><p>{html.escape(row['description'] or '')}</p></article><form class="card" method="post"><label>Application progress<select class="input" name="application_status">{option_html}</select></label><label>Deadline<input class="input" name="deadline" value="{html.escape(row['deadline'] or '',quote=True)}"></label><label>Private notes<textarea class="input" name="member_notes">{html.escape(row['member_notes'] or '')}</textarea></label><button class="btn">Save Changes</button></form><div class="actions"><a class="out" href="{url_for('proposal_new',opportunity_id=opportunity_id)}">Start Proposal</a><a class="out" href="{url_for('funding_calendar',saved_opportunity_id=opportunity_id)}">Funding Calendar</a><form method="post" action="{url_for('delete_saved_opportunity',opportunity_id=opportunity_id)}" onsubmit="return confirm('Delete this saved opportunity and its connected preparation records?')"><button class="out danger">Delete</button></form></div>''','business')

